window.CRIM_GAKRON_CONCEPT = [["개인001", "사람의 시기와 종기", "<div class=\"cs-h\">Ⅰ. 사람의 시기</div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①진통설(통설)</div><div class=\"cs-li\" style=\"margin-left:16px\">②일부노출설</div><div class=\"cs-li\" style=\"margin-left:16px\">③전부노출설</div><div class=\"cs-li\" style=\"margin-left:16px\">④독립호흡설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[①진통설]</span> 규칙적 진통 동반 분만개시 시(=분만개시설) = 사람의 시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 모체 노출 전 생명도 보호 필요 → 진통설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[의료과실로 태아 사망]</span> 임산부에 대한 상해<span class=\"cs-x\"><strong>(X)</strong></span> — 신체 일부 훼손·생리기능 침해 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[조산원이 분만 중 태아를 질식사에 이르게 한 경우]</span> 업무상과실치사죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[제왕절개 수술]</span> 분만개시시점 기준<span class=\"cs-x\"><strong>(X)</strong></span> — 수술 가능·필요 시기가 판단주체·상황마다 다름<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-h\">Ⅱ. 사람의 종기</div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①호흡종지설</div><div class=\"cs-li\" style=\"margin-left:16px\">②심장사설(맥박종지설)</div><div class=\"cs-li\" style=\"margin-left:16px\">③뇌사설</div></div><div class=\"cs-h\">Ⅲ. 낙태죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: 자연분만기 전 인위적으로 모체 밖 배출 or 모체 안 살해 → 태아 사망여부 불문</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[산부인과 의사가 유도분만으로 낙태 시도, 미숙아로 생존출생하자 염화칼륨 주입 살해]</span> 살인죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변18】</span></div>", [], 1, "gak_생명신체"], ["개인002", "상습범", "<div class=\"cs-h\">Ⅰ. 상습성</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">의의: 동종 범행 반복 습벽, 고의의 인식대상 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">인정자료: 제한 X (소년법상 보호처분도 O) <span class=\"cs-fact-tag\">[도박습벽]</span> 전과·횟수 중요자료이나 전과 없어도 습벽 인정 시 상습성 O <span class=\"cs-fact-tag\">[심신미약 등 정신장애]</span> 상습성 당연부정 사유 X, 여러 판단자료 중 하나일 뿐</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-crime\">상해·폭행 상습범</span>(<span class=\"cs-stat\"><strong>§264</strong></span>)의 '상습' = 열거된 습벽만, 타 유형범죄 고려 X <span class=\"cs-neg-tag\">[재물손괴·주거침입 전과 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[단순폭행·존속폭행이 동일습벽 발현으로 인정되는 경우]</span> 법정형 더 중한 상습존속폭행죄 포괄일죄만<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26, 변기19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상습절도범이 절도습벽 발현으로 자동차등불법사용을 추가로 한 경우]</span> 상습절도죄만 성립, 별죄 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[단순절도·야간주거침입절도를 상습적으로 범한 경우]</span> 상습야간주거침입절도죄 포괄일죄만<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[도박습벽자가 도박+도박방조를 한 경우]</span> 무거운 상습도박죄에 포괄하여 1죄로 처단</div>", ["§264"], 1, "gak_생명신체"], ["개인003", "업무상과실치사상죄", "<div class=\"cs-h\">Ⅰ. 업무상과실치상</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 업무 = 사회생활상 지위로서 계속 종사하는 사무 = 안전배려의무업무 + 생명·신체위험방지의무업무 모두 포함, 적법성 불요</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[골프장 캐디]</span> 업무<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[무허가 골재채취업무]</span> 업무<span class=\"cs-o\"><strong>(O)</strong></span> — 허가받은 적법한 업무일 필요 X</div><div class=\"cs-h\">Ⅱ. 임대인(건물소유자)·임차인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[비정기 수리·일부임대만 한 경우]</span> 업무<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[3층건물 임대인의 낙하사고방지를 위한 관리의무 소홀, 안전바 미설치 낙하사고]</span> 업무<span class=\"cs-x\"><strong>(X)</strong></span> → 후단무죄, <span class=\"cs-crime\">과실치상죄</span>는 별도<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[분전반을 통해 합선 화재사고로 상해]</span> 임대인: 업무<span class=\"cs-x\"><strong>(X)</strong></span> — <span class=\"cs-crime\">과실치상죄</span><span class=\"cs-o\"><strong>(O)</strong></span>는 인정취지 / 임차인: 과실<span class=\"cs-x\"><strong>(X)</strong></span> — 안전이상 인지하고 있었어도 업무상 주의의무위반 X<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-h\">Ⅲ. 도급인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 도급인의 수급인업무 관련 안전조치 취할 주의의무 원칙 : <span class=\"cs-o\"><strong>(X)</strong></span> 예외 : <span class=\"cs-x\"><strong>(O)</strong></span> —</div><div class=\"cs-li\" style=\"margin-left:16px\">①법령상 관리·감독의무가 있거나</div><div class=\"cs-li\" style=\"margin-left:16px\">②도급인이 구체적으로 지시·감독한 특별한 사정이 있는 경우<span class=\"cs-exam\">【변18·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[타워크레인 설치작업을 도급, 현장대리인에게 실질적 지휘·감독권한 X]</span> 업무상 주의의무 위반 과실<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span></div>", [], 2, "gak_생명신체"], ["개인004", "흉기 또는 위험한 물건", "<div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[흉기와 위험한 물건 규정 구분]</span> 흉기만 규정: <span class=\"cs-stat\"><strong>§331</strong></span>②(특수절도)·<span class=\"cs-stat\"><strong>§334</strong></span>②(특수강도) 위험한 물건만 규정: 특수절도·강도 제외 형법 나머지 전부 흉기나 그 밖의 위험한 물건: 성폭법 특수강간(<span class=\"cs-stat\"><strong>§4</strong></span>①)·폭처법 우범자(<span class=\"cs-stat\"><strong>§7</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[합동범]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①특수절도(<span class=\"cs-stat\"><strong>§331</strong></span>②)</div><div class=\"cs-li\" style=\"margin-left:16px\">②특수강도(<span class=\"cs-stat\"><strong>§334</strong></span>②)</div><div class=\"cs-li\" style=\"margin-left:16px\">③특수도주(<span class=\"cs-stat\"><strong>§146</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:16px\">④성폭법 특수강간등(<span class=\"cs-stat\"><strong>§4</strong></span>①)</div><div class=\"cs-h\">Ⅰ. 위험한 물건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">① 흉기 아니어도 사람의 생명·신체에 해를 가할 수 있는 일체의 물건 →</div><div class=\"cs-li\" style=\"margin-left:16px\">② 본래 살상용·파괴용이 아니라 다른 목적으로 만들어진 물건도 사용목적에 따라 포함 (칼·가위·유리병·공구·자동차·화학약품·사주된 동물 등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 사회통념상 그 물건 사용시 상대방·제3자가 생명·신체 위험을 느낄 수 있는지 여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[자동차]</span> <span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[승용차로 견인료 요구 직원을 들이받은 경우]</span><span class=\"cs-exam\">【변13】</span>, <span class=\"cs-fact-tag\">[겁을 주기 위해 정차 후 후진하여 피해자의 자동차와 충돌한 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[이혼분쟁 중 아들을 승낙없이 태우고 떠나려는 상대방 급히 추격제지 중 소형차로 중형차 저속 충격, 손괴 경미한 경우]</span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[먼저 들고 있던 식칼 저지하려 뺏은 후 훈계하며 칼자루로 머리를 가볍게 친 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[당구공으로 머리를 툭툭 건드린 정도]</span> <span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공기총, 실탄 미장전 상태로 소지]</span> <span class=\"cs-o\"><strong>(O)</strong></span> — 언제든 장전 가능<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[빈 2리터 페트병으로 피해자 눈 부위 수회 가격한 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 흉기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념 (判例) : 본래 살상·파괴용으로 만들어졌거나 이에 준하는 위험성을 가진 것 (↔위험한 물건과는 분명히 구분)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 본래 용도·크기와 모양·개조 여부·구체적 사용방법 등 사회통념상 객관적 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[절도 중 택시 운전석 창문 파손에 사용한 드라이버]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[전기충격기]</span> <span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변사17】</span></div><div class=\"cs-h\">Ⅲ. 휴대하여 (<span class=\"cs-crime\">성폭법</span> 특수강간 '지닌 채')</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념 (判例) : 범행현장에서 그 범행에 사용하려는 의도로 소지·몸에 지니는 것 → 그 범행과 전혀 무관한 우연한 소지는 제외, 행위자의 휴대사실에 대한 인식 필요(고의 대상)<span class=\"cs-exam\">【변18·17, 변기23】</span> 사실상 지배하며 언제든 사용가능한 상태에 두면 충분 (물리적 부착 불요) 소지뿐 아니라 널리 이용한다는 뜻도 포함 <span class=\"cs-fact-tag\">[자동차]</span> 피해자의 인식여부·실제 범행사용 및 결과 불문 — 위해를 입지 않았어도 휴대<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[마약사범이 비닐봉지에 담아 버리려고 칼을 소지한 채 나섰다가 체포된 경우]</span> <span class=\"cs-crime\">폭처법 우범자죄(§7)</span>의 '위험한 물건 휴대' <span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변기15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[과도·라이터를 피해자 현관문 앞에 놓아두고 피해자가 이를 발견한 때 이미 범행현장을 이탈한 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[장검을 집에 보관만 한 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[승용차로 들이받은 경우]</span> <span class=\"cs-o\"><strong>(O)</strong></span></div>", ["§331", "§334", "§4", "§7", "§146"], 3, "gak_생명신체"], ["개인005", "상해의 개념", "<details class=\"cs-case\"><summary><u><strong>[CASE] 졸피뎀 수면제·간음 사례</strong></u> <span class=\"cs-exam\">[법무사21]</span> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 과거 연인 乙(女)에게 권장용량의 2배에 해당하는 졸피뎀 성분 수면제를 섞은 커피를 마시게 해 잠들자 간음. 乙은 마신 직후 정신을 잃고 깊이 잠들었다가 약 4시간 뒤 깨어났는데, 잠든 이후 상황을 제대로 기억 못했고 정신이 희미하게 든 때도 자기 의지대로 생각·행동하지 못한 채 곧바로 기절하다시피 다시 깊은 잠에 빠짐. 이후 자연적으로 의식 회복, 특별한 치료는 받지 않음.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [강간죄의 폭행]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 강간죄(<span class=\"cs-stat\"><strong>제297조</strong></span>)의 폭행 = 피해자의 항거를 불가능하게 하거나 현저히 곤란하게 할 정도</div><div class=\"cs-li\" style=\"margin-left:0px\">② 졸피뎀 성분 수면제 섞은 커피를 마시게 해 정신을 잃고 깊이 잠들게 함 → 항거불가능 정도 → 강간죄의 폭행(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [강간치상죄의 상해]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 강간치상죄(<span class=\"cs-stat\"><strong>제301조</strong></span>)의 상해 = 신체의 완전성 훼손 또는 생리적 기능 장애 초래</div><div class=\"cs-li\" style=\"margin-left:0px\">② 수면제 등 약물로 일시적 수면·의식불명 상태에 이르게 한 경우 자연적 의식회복·외상 없어도 상해에 해당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙이 4시간 후 깨어났고 그 사이 상황 기억 못한 채 곧바로 다시 깊이 잠든 점, 졸피뎀이 중추신경계 작용 향정신성의약품인 점 → 생리적 기능훼손 인정</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 강간치상죄</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 상해의 개념</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념 (判例) : <span class=\"cs-fact-tag\">[생리적 기능훼손설]</span> 상해 = 신체의 완전성 훼손 또는 생리적 기능에 장애 초래 (건강상태 불량화+생활기능장애), 육체적+정신적 기능 모두 포함 → 경미하여 치료 불요·일상생활 지장 없고 자연치유되는 정도는 X <span class=\"cs-fact-tag\">[</span><span class=\"cs-crime\">강간치상죄·강제추행치상죄·강도상해죄·체포치상죄</span><span class=\"cs-fact-tag\"> 등에도 동일 적용]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당 <span class=\"cs-o\"><strong>(O)</strong></span>:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[8세 </span><span class=\"cs-crime\">미성년자의제강제추행</span><span class=\"cs-fact-tag\">, 외음부에 경도의 염증이 발생한 경우]</span> <span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[폭행으로 보행불능·수면장애·식욕감퇴 등 기능장해를 일으킨 경우]</span> <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당 <span class=\"cs-x\"><strong>(X)</strong></span>:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[동전크기 멍]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[음모를 자른 경우]</span> 외모변화만으로는 생리적 기능 장애 X → <span class=\"cs-x\"><strong>(X)</strong></span>, <span class=\"cs-crime\">폭행</span> O</div><div class=\"cs-h\">Ⅱ. 일시적 수면 또는 의식불명 상태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[협박·폭행으로 실신, 구급차 안에서 정신 차린 경우]</span> <span class=\"cs-o\"><strong>(O)</strong></span> — 외상 없어도 생리적 기능훼손</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수면제 등 향정신성의약품인 약물로 일시적 수면·의식불명 상태에 이르게 한 경우]</span> <span class=\"cs-o\"><strong>(O)</strong></span> — 자연회복·외상 없어도 <span class=\"cs-crime\">강간치상·강제추행치상</span>의 상해<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[약물(약품명 미상) 탄 음료로 정신혼미·기억상실된 경우]</span> <span class=\"cs-x\"><strong>(X)</strong></span> — <span class=\"cs-crime\">강도죄</span> 항거불능 사유는 될 수 있으나 상해 인정자료로는 부족</div><div class=\"cs-h\">Ⅲ. 중상해</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 중상해죄 = 부진정결과적 가중범, 미수범 처벌규정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[실명 / 코 절단 / 혀 절단]</span> 모두 불구 <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[3주간 치료 요하는 우측흉부자상]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div>", ["제297조", "제301조"], 1, "gak_생명신체"], ["개인006", "독립행위 경합과 상해 동시범 특례", "<details class=\"cs-case\"><summary><u><strong>[CASE] 이시(異時)의 폭행 경합·사망 원인불명</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A에 대한 <span class=\"cs-crime\">성폭법상 주거침입강간치상죄</span>를 범한 직후 현장에 도착한 A의 아버지 B에게 잡히자 B를 때려 눕히고 발로 복부를 수 회 걷어찬 뒤 도주. 약 2시간 후 甲의 친구 乙이 평소 감정이 좋지 않던 B가 쓰러진 것을 우연히 발견하고 화가 나 발로 복부를 수 회 걷어참. 며칠 후 B는 장 파열로 사망, 부검결과 甲과 乙 중 누구의 행위로 사망했는지 판명되지 않음.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲과 乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [문제점]</strong> <span class=\"cs-stat\"><strong>제19조</strong></span>, <span class=\"cs-stat\"><strong>제263조</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [이시의 독립행위]</strong> 이시의 독립행위에도 상해의 동시범 특례가 적용되는지 — 부정설/긍정설, 판례 = 긍정설. 이시의 독립행위를 제외할 이유(X) → 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [상해·폭행치사죄 적용여부]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 동시범 특례가 상해치사죄(<span class=\"cs-stat\"><strong>제259조</strong></span> 제1항)·폭행치사죄(<span class=\"cs-stat\"><strong>제262조</strong></span>)에도 적용되는지 — 부정설/긍정설, 판례 = \"상해행위나 폭행행위가 경합하여 사망의 결과가 일어난 경우에도 적용된다\" 긍정설. 모두 동시범 특례와 같은 '상해와 폭행의 죄'의 장에 규정 → 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲과 乙의 이시의 독립행위(폭행 또는 상해)가 경합해 B 사망, 그러나 원인행위 판명(X) → <span class=\"cs-stat\"><strong>제263조</strong></span> 상해의 동시범특례 적용</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲과 乙 = 상해치사죄(또는 폭행치사죄)의 공동정범의 예에 의해 처벌</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제19조(독립행위의 경합)</strong></span> 동시 또는 이시의 독립행위가 경합한 경우에 그 결과발생의 원인된 행위가 판명되지 아니한 때에는 각 행위를 미수범으로 처벌한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제263조(동시범)</strong></span> 독립행위가 경합하여 상해의 결과를 발생하게 한 경우에 있어서 원인된 행위가 판명되지 아니한 때에는 공동정범의 예에 의한다.</div></div><div class=\"cs-h\">Ⅰ. 독립행위 경합 (<span class=\"cs-stat\">§19</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">의의: 2인 이상 상호 의사연락 없이 동일객체에 행위 → 결과 원인행위 판명 X → 각 미수 처벌</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[구조]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 독립행위 경합 → 원인불명 시 각 미수</div><div class=\"cs-li\" style=\"margin-left:16px\">② 상해결과·원인불명 시 공동정범의 例 (상해 동시범특례)</div><div class=\"cs-li\" style=\"margin-left:16px\">③ 공동가공의사 있으면 동시범 문제 여지 X (공동정범)<span class=\"cs-exam\">【변20·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[가해행위 자체가 불분명한 자]</span> 상해죄 동시범<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변25·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[A가 甲에게 폭행당한 후 함께 폭행하자는 연락받고 온 乙에게 다시 폭행당해 사망·원인불명]</span> 甲·乙 폭행치사 공동정범<span class=\"cs-o\"><strong>(O)</strong></span> — 동시범특례 적용 X</div><div class=\"cs-h\">Ⅱ. 원인행위가 판명되지 아니한 때</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">원칙 : 원인 판명 시 → 각자 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[실화죄, 공동과실 경합 화재·각 과실이 하나의 조건]</span> 각자 실화죄<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[원인행위 판명됨]</span><span class=\"cs-exam\">【변26·25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[甲 폭행 후 乙이 의사연락 없이 폭행, A가 무단횡단 중 차량에 치여 사망]</span> <span class=\"cs-stat\"><strong>§263</strong></span> 적용<span class=\"cs-x\"><strong>(X)</strong></span> — 乙 폭행과 사망 간 인과관계 판명 → 甲 폭행죄 · 乙 폭행치사죄<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅲ. 상해의 동시범 특례 (<span class=\"cs-stat\">§263</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>상해의 결과 발생</strong> 적용범위: '상해와 폭행의 죄'章 규정 → 상해행위든 폭행행위든 불문 <span class=\"cs-fact-tag\">[상해·폭행치상]</span> <span class=\"cs-issue\">《상해·폭행치사죄에도 적용되는지 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(사망도 포함)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(유추해석금지 위반)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 시차 있는 독립 상해·폭행 경합 → 사망·원인불명 시 공동정범의 例<span class=\"cs-exam\">【변26·20·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 상해치사(<span class=\"cs-stat\"><strong>§259</strong></span>)·폭행치사(<span class=\"cs-stat\"><strong>§262</strong></span>) 모두 같은 章 → 긍정설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>동시 또는 이시의 독립행위</strong> <span class=\"cs-issue\">《'이시'의 독립행위에도 적용되는지 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(동시 한정)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(<span class=\"cs-stat\"><strong>§263</strong></span>은 <span class=\"cs-stat\"><strong>§19</strong></span> 특칙, 이시 제외 이유 X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 시차 있는 독립 상해·폭행 경합 → '사망'·원인불명 시 공동정범의 例<span class=\"cs-exam\">【변26·20·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 긍정설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>강간상해·치상죄, 과실치상죄 등</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[강간치상]</span> <span class=\"cs-stat\"><strong>§263</strong></span> 적용<span class=\"cs-x\"><strong>(X)</strong></span> — '상해·폭행죄 특별규정'이므로 보호법익 다른 <span class=\"cs-crime\">강간치상죄</span>엔 부적용 <span class=\"cs-neg-tag\">[각자 강간죄]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[과실치사]</span> 선·후 교통사고 중 사망원인 불명 — 후행 운전자 과실·사망 인과관계는 검사 증명책임<span class=\"cs-exam\">【변21·20】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>동시범 특례의 효과</strong> 효과: 공동정범의 例(<span class=\"cs-stat\"><strong>§263</strong></span>) → 경합 독립행위·결과 간 인과관계 있으면 전원 기수 처벌<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25】</span> 일부 특례 부적용 시 전부 <span class=\"cs-stat\"><strong>§19</strong></span>로 미수 <span class=\"cs-fact-tag\">[예: 일반상해·폭행치상·강도상해 경합→상해미수·폭행·강도상해미수만]</span><span class=\"cs-exam\">【모사16】</span></div><div class=\"cs-h\">Ⅳ. 동시범 특례와 증명책임 전환</div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>: <span class=\"cs-fact-tag\">[증명책임전환설]</span> <span class=\"cs-stat\"><strong>§263</strong></span>은 <span class=\"cs-stat\"><strong>§19</strong></span> 예외 = 증명책임 전환 규정(통설) → 피고인이 자기 행위·결과 간 인과관계 부존재 입증해야</div></div>", ["§19", "§263", "§259", "§262", "제19조", "제263조", "제259조", "제262조"], 3, "gak_생명신체"], ["개인007", "폭행의 개념", "<details class=\"cs-case\"><summary><u><strong>[CASE] 자동차로 부딪칠 듯 조금씩 전진 반복 → 특수폭행</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">층간소음으로 다툼 있던 아랫층 A가 항의하러 甲 차 앞을 가로막음 → 甲이 부딪힐 듯</div><div class=\"cs-li\" style=\"margin-left:0px\">차를 조금씩 전진, A가 물러나면 다시 전진 반복. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [폭행]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 폭행죄(<span class=\"cs-stat\"><strong>제260조</strong></span> 제1항) = 사람의 신체에 대한 유형력 행사, 신체 직접 접촉 不要</div><div class=\"cs-li\" style=\"margin-left:0px\">② 차 가로막은 A에게 부딪칠 듯 조금씩 전진 반복 = 위법한 유형력 행사 → 폭행(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [위험한 물건을 휴대하여]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [위험한 물건]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 특수폭행죄(<span class=\"cs-stat\"><strong>제261조</strong></span>)의 '위험한 물건' = 흉기 아니어도 생명·신체에 해를 가하는 데 쓸 수 있는 일체의 물건 판단기준 = 사회통념상 그 물건 사용 시 상대방·제3자가 생명·신체에 위험을 느낄 수 있는지</div><div class=\"cs-li\" style=\"margin-left:0px\">② 폭행에 사용한 자동차 → 위험한 물건(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [휴대하여]</div><div class=\"cs-li\" style=\"margin-left:0px\">① '휴대' = 소지뿐 아니라 널리 이용하는 것도 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자동차 이용 → 휴대(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = A에 대한 특수폭행죄</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 최협의 폭행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[준강도]</span> 반항 억압 정도 要 (일반강도와의 균형) — 체포·재물탈환 의사 제압할 정도 현실적 반항억압 不要 — 일반적·객관적으로 가능하다 인정될 정도면 족</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강간]</span> 항거 불가능/현저 곤란 정도 要 <span class=\"cs-fact-tag\">[유사강간 동일]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[절도범이 피해자의 심한 폭력 피하려 엉겁결에 솥뚜껑 들어 막다 스쳐 상처]</span> 준강도 폭행<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[새벽4시 방문 부술 기세로 두드리고 창문·베란다로 침입 시도]</span> 강간 수단 폭행 착수<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 협의 폭행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[폭행]</span> 신체에 대한 유형력 행사 = 신체적 고통 주는 물리력 작용 신체 접촉 不要. 다만 폭행죄는 신체 완전성 보호 목적이지 심리적 불안감 보호 목적 X <span class=\"cs-fact-tag\">[강제추행(判例 변경)]</span> 폭행·협박 = 불법 유형력 행사(폭행) or 공포심 일으킬 해악 고지(협박) <span class=\"cs-fact-tag\">[폭행·협박선행형 강제추행도 폭행죄·협박죄와 동일하게 변경, 성폭법도 적용]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-o\"><strong>(O)</strong></span> : <span class=\"cs-fact-tag\">[어린애 업은 사람 넘어뜨림]</span> 어린애에 대해서도 폭행<span class=\"cs-o\"><strong>(O)</strong></span> → 폭행치사죄<span class=\"cs-exam\">【변16】</span> <span class=\"cs-fact-tag\">[고성 폭언·욕설하며 손발·물건 휘두르거나 던지는 행위]</span> 폭행<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변18】</span><span class=\"cs-exam\">【모사17】</span> <span class=\"cs-fact-tag\">[자동차로 부딪칠 듯 조금씩 전진 반복]</span> 위법 유형력 행사<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[특수폭행죄]</span><span class=\"cs-exam\">【변26·23】</span><span class=\"cs-exam\">【모사20】</span> <span class=\"cs-fact-tag\">[운행중 자동차 운전자 폭행하여 상해]</span> <span class=\"cs-crime\">특가법 §5의10②</span> 충족<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[교통사고 없이 직접 운전자 상해만 발생시켜도 특가법위반(운전자폭행등)죄 성립]</span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-x\"><strong>(X)</strong></span> : <span class=\"cs-neg-tag\">[욕설만/대문 발로 참]</span> 신체 유형력 행사<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[죽여버린다 폭언하며 시정된 방문 수회 발로 참]</span> 신체 유형력 행사<span class=\"cs-x\"><strong>(X)</strong></span> → 폭행죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[음향]</span> <span class=\"cs-o\"><strong>(O)</strong></span> : 청각기관 직접 자극 음향 → 유형력 포함 가능 <span class=\"cs-x\"><strong>(X)</strong></span> : 멀리 떨어진 자에게 전화 고성·녹음 청취 → 특별한 사정 없는 한 유형력 X</div><div class=\"cs-h\">Ⅲ. 광의 폭행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 사람에 대한 직·간접 유형력 행사 <span class=\"cs-fact-tag\">[특수도주죄 등]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강요죄]</span> 직접뿐 아니라 간접 유형력 포함, 신체에 한정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공무집행방해죄]</span> 공무원에 직·간접 유형력 <span class=\"cs-fact-tag\">[파출소 바닥에 인분 던진 경우]</span></div><div class=\"cs-h\">Ⅳ. 최광의 폭행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[내란죄·소요죄]</span> 일체의 유형력 행사</div><div class=\"cs-h\">Ⅴ. 특수폭행치상죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[다중]</span> 단체 못 이룬 다수인 집합 = 집단적 위력 보일/압력 느껴 불안 줄 정도 다수 <span class=\"cs-fact-tag\">[3인은 다중 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">'위력' = 사람 의사 제압할 세력. 현실적 제압 不要, 제압할 세력 인식시킬 정도는 要</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상해의 例]</span> 특수폭행치상은 <span class=\"cs-stat\"><strong>§258의2</strong></span>(특수상해) 신설에도 종전대로 <span class=\"cs-stat\"><strong>§257</strong></span>①(상해죄)의 例로 처벌 <span class=\"cs-fact-tag\">[자동차로 충격하여 상해]</span><span class=\"cs-exam\">【변26·22】</span></div>", ["§5", "§258", "§257", "제260조", "제261조"], 3, "gak_생명신체"], ["개인008", "유기죄와 학대죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제271조(유기, 존속유기)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 나이가 많거나 어림, 질병 그 밖의 사정으로 도움이 필요한 사람을 법률상 또는 계약상 보호할 의무가 있는 자가 유기한 경우에는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 또는 배우자의 직계존속에 대하여 제1항의 죄를 지은 경우에는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 제1항의 죄를 지어 사람의 생명에 위험을 발생하게 한 경우에는 7년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 제2항의 죄를 지어 사람의 생명에 위험을 발생하게 한 경우에는 2년 이상의 유기징역에 처한다. [중유기·존속중유기]</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제273조(학대, 존속학대)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 자기의 보호 또는 감독을 받는 사람을 학대한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 또는 배우자의 직계존속에 대하여 전항의 죄를 범한 때에는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제275조(유기등 치사상)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 제271조 또는 제273조의 죄를 범하여 사람을 상해에 이르게 한 때에는 7년 이하의 징역에 처한다. 사망에 이르게 한 때에는 3년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 또는 배우자의 직계존속에 대하여 제271조 또는 제273조의 죄를 범하여 상해에 이르게 한 때에는 3년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년이상의 징역에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 유기죄 (<span class=\"cs-stat\">§271</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>주체 – 법률상 또는 계약상 보호할 의무가 있는 자 (진정신분범)</strong> 가. <strong>보호의무의 발생근거<span class=\"cs-exam\">【변사17·16, 모사22·14】</span></strong> <span class=\"cs-issue\">《법률상·계약상 보호의무 외 사회상규상 보호의무 인정 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(예시설, <span class=\"cs-stat\"><strong>§271</strong></span>①을 예시적으로 봄)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(제한적 열거설, 법률·계약상 의무로 한정 → 선행행위·사무관리·관습·조리 근거로는 인정 X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[부정설]</span> 현행 형법은 법률·계약상 의무자만 유기죄 주체로 규정 → 사회상규상 보호책임 관념 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 죄형법정주의 → 부정설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\">[일정거리 동행 사실만으론]</span> 법률·계약상 보호의무<span class=\"cs-x\"><strong>(X)</strong></span> → 유기죄 주체<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">나. <strong>법률상 보호의무</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[사실혼 O]</span> 부부간 부양의무(민<span class=\"cs-stat\"><strong>§826</strong></span>①) 포함 → 사실혼도 보호의무<span class=\"cs-o\"><strong>(O)</strong></span> 단 사실혼은 단순 동거·간헐적 정교만으론 부족 — 주관적 혼인의사 + 객관적 혼인생활 실체 要<span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[11세 딸 수혈거부 사망]</span> 종교신념·환자 본인 거부에도 유기치사죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\">[강간치상 후 실신 피해자 방치]</span> 포괄하여 단일 <span class=\"cs-crime\">강간치상죄</span>만 성립 → 별도 유기죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">다. <strong>계약상 보호의무</strong> 판단기준 (判例) : '계약상 의무'는 주된 급부의무가 부조인 경우(간호사·보모)에 한정 X → 계약 해석상 부수적 의무로 부조하는 경우도 포함 단, 부수의무로서 민사적 부조·보호의무가 인정된다 하여 '계약상 의무'가 당연 긍정되는 것<span class=\"cs-x\"><strong>(X)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[주점운영자, 만취 손님 방치 저체온증 사망]</span> 계약상 부조의무<span class=\"cs-o\"><strong>(O)</strong></span> — 내실 이동·여관·지인·경찰 연락 등 조치 要 <span class=\"cs-fact-tag\">[유기치사죄 O]</span><span class=\"cs-exam\">【변사17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>행위 – 유기</strong> 개념: 유기 = 장소적 이전·유기 + 장소적 격리 없이 생존 필요 보호 안 하는 경우도 포함 <span class=\"cs-fact-tag\">[추상적 위험범]</span> 생명·신체 위험 발생 가능성 있으면 유기행위 충족 — 보호가능성 전무일 것 不要<span class=\"cs-exam\">【변25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[청산가리 음독 후 흡수되어 치료불가 상태 방치]</span> 유기행위와 사망 간 상당인과관계<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[유기죄만 성립]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>고의</strong> 개념: 유기죄 고의 = 보호책임 발생원인 사실 인식 + 이에 기한 부조의무 해태 의식 要 유기시 요부조자 사망 미필적 고의 있으면 <span class=\"cs-crime\">살인죄</span>에 흡수 → 살인죄만 성립</div><div class=\"cs-h\">Ⅱ. 학대죄 (<span class=\"cs-stat\">§273</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[상태범·즉시범]</span> 학대(육체적 고통·정신적 차별대우) 행위 있음과 동시 완성<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수십회 계속 폭행 중]</span> 친권자 징계권 범위로 위법성 조각되는 부분 → 따로 떼어 무죄 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[성년후견 개시·별도 성년후견인 있어도]</span> 부양의무 지는 직계비속의 직계존속 학대 → 존속학대죄(<span class=\"cs-stat\"><strong>§273</strong></span>②)<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["§271", "§826", "§273", "제271조", "제273조", "제275조"], 3, "gak_생명신체"], ["개인009", "협박죄 등", "<details class=\"cs-case\"><summary><u><strong>[CASE] 회사 내부비리 고발 협박·제3자(법인)에 대한 해악 고지</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">X회사 직원 甲, 자기 횡령 추궁당하자 상무이사 A에게 전화 \"문제 삼으면 회사 내부비리를 금융감독원 등 관계기관에 고발하겠다\" → X회사·A는 겁먹지 않았으나 고소. 이후 甲이 경찰서</div><div class=\"cs-li\" style=\"margin-left:0px\">조사 중 담당경찰관 P에게 불만 품고 \"처벌받으면 A의 집에 불 지르겠다\". 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [협박죄의 협박]</strong> 협박죄(<span class=\"cs-stat\"><strong>제283조</strong></span> 제1항)의 '협박' = 일반적으로 보아 사람에게 공포심을 일으킬 수 있는 정도의 해악 고지</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [A에게 X회사에 대한 해악을 고지한 행위]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [협박죄의 객체]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 보호법익 = 의사결정의 자유 → 법인은 협박죄의 객체(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② X회사에 대한 협박죄(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [제3자에 대한 법익 침해를 내용으로 하는 해악의 고지]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 피해자 본인과 제3자가 '밀접한 관계' + 그 해악이 본인에게 공포심 일으킬 정도 → 협박죄(O). 제3자에 법인 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">② A = X회사 상무이사로 밀접한 관계 → 협박죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [협박죄의 기수시기]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 상대방이 고지된 해악의 의미를 인식한 이상 현실적 공포심 여부 무관 → 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲 = A에 대한 협박기수</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [경찰관 P에게 A에 대한 해악을 고지한 행위]</strong> P가 공포심 일으킬 만큼 A와 밀접한 관계(X) → P에 대한 협박죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = A에 대한 협박기수죄</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 협박죄 (<span class=\"cs-stat\">§283</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>협박죄의 협박</strong> 개념 (判例) : '협박' = 일반적으로 사람에게 공포심 일으킬 정도의 해악 고지 성립하려면 고지 해악이 일반적으로 공포심 일으키기에 충분해야 고의 = 그 정도 해악을 고지한다는 것을 인식·용인 거동으로도 해악 고지 가능 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[말다툼 중 회칼 들고 나와 요구 불응시 자해하려 함]</span> 단순 자해시늉 아닌 해악 가할 위세 → 협박<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">단순 감정적 욕설·일시적 분노 표시로 가해의사 없음 객관적 명백 → 협박(의사)<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>협박죄의 객체 (상대방)</strong> 적용범위: <span class=\"cs-neg-tag\">[법인 X]</span> 의사결정 자유 보호법익, 자연인만 대상 → 법인은 협박죄 객체<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15·14】</span><span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>해악의 고지</strong> 가. <strong>제3자에 '의한' 해악</strong> 원칙 : 직접 해악뿐 아니라 제3자로 하여금 해악 가하도록 하겠다는 방식도 가능 판단기준 (判例) : 고지자가 제3자 행위를 사실상 지배/영향 미칠 지위임을 믿게 하는 언동 或 제3자 행위가 고지자 의사에 좌우된다고 상대방이 인식한 경우에 한해 협박<span class=\"cs-o\"><strong>(O)</strong></span> 그런 언동·인식 없으면 상대방이 외포심 느껴도 협박<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[고지자가 사실상 지배해야 X]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\">[조상천도제 안 지내면 좋지 않은 일]</span> 길흉화복·천재지변 예고로 좌우 불가 → 협박<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">나. <strong>제3자에 '대한' 법익침해 해악의 고지</strong> 판단기준 (判例) : 피해자 본인·친족뿐 아니라 제3자에 대한 법익침해 해악 고지라도 '본인과 제3자 밀접관계'로 본인에게 공포심 일으킬 정도면 협박<span class=\"cs-o\"><strong>(O)</strong></span> 이때 제3자에 자연인뿐 아니라 법인도 포함<span class=\"cs-exam\">【변22·13·12】</span><span class=\"cs-exam\">【변기17, 모사25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[횡령 추궁당한 지사장이 회사 본사·상무이사에 '내부비리 금감원 고발' 고지]</span> 상무이사에 대한 협박죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모사25·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-neg-tag\">[술 취해 경찰서에 A정당 당사 폭파하겠다 전화]</span> 경찰관 개인과 A정당의 밀접관계<span class=\"cs-x\"><strong>(X)</strong></span> → 협박죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변기17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>권리행사와 해악의 고지</strong> 판단기준 (判例) : 권리행사·직무집행 일환 해악 고지가 사회상규에 반하지 않으면 협박<span class=\"cs-x\"><strong>(X)</strong></span> 외관상 권리행사여도 실질 남용으로 사회상규 반하면 협박<span class=\"cs-o\"><strong>(O)</strong></span> 정당한 목적 위한 상당한 수단이면 위법성 조각, 관련성 없으면 조각<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변12】</span> 권리행사 일환 해악 고지도</div><div class=\"cs-li\" style=\"margin-left:16px\">①사회통념상 용인 정도 或</div><div class=\"cs-li\" style=\"margin-left:16px\">②정당목적 상당수단 등 사회상규 반하지 않으면 협박<span class=\"cs-x\"><strong>(X)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[경영위기 회사 직원들이 협의 거쳐 '사임제안서' 대표이사 전달]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①공포심 일으킬 정도 아니라 협박<span class=\"cs-x\"><strong>(X)</strong></span> — 구성요건 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②협박 해당해도 사회상규 반하지 않음 — 위법성 X</div><div class=\"cs-li\" style=\"margin-left:0px\">5. <strong>착수 및 기수 시기<span class=\"cs-exam\">【모사25】</span></strong> 개념: <span class=\"cs-fact-tag\">[위험범]</span> 의사결정 자유 보호법익 — 공포심 일으키기 충분해야 하나 현실적 공포심 일으킬 것까진 不要 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[기수-의미 인식]</span> 충분한 해악 고지로 상대방이 그 '의미를 인식'한 이상 기수<span class=\"cs-o\"><strong>(O)</strong></span> — 현실적 공포심 여부 무관 <span class=\"cs-neg-tag\">[도달하면 기수 X]</span><span class=\"cs-exam\">【변22·20·15·13·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[미수]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①해악 고지 미도달</div><div class=\"cs-li\" style=\"margin-left:48px\">②도달했으나 미지각</div><div class=\"cs-li\" style=\"margin-left:48px\">③고지 해악 의미 미인식 시 적용</div><div class=\"cs-h\">Ⅱ. 스토킹처벌법위반죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 스토킹범죄 = 의사결정 자유·생활형성 자유와 평온 침해 방지 보호법익 위험범</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 객관적·일반적으로 상대방 인식시 불안·공포 일으키기 충분하면 현실적 불안·공포 여부 관계없이 '스토킹행위'<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[전화 걸어 벨소리·부재중 표시되게 함]</span> 실제 통화 여부 관계없이 스토킹행위<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-h\">Ⅲ. 정통망법위반죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[반복성]</span> <span class=\"cs-crime\">정통망법 §74①iii, §44의7①iii</span> 위반이려면 각 행위 간 일시·장소 근접 · 방법 유사 · 기회 동일 · 범의 계속 등 밀접관계로 전체적 반복행위 평가 가능해야 일회성·비연속 단발성 여러 번 → 협박죄·경범죄처벌법상 별개 범죄는 별론, 위 법 위반<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[예: 하루 간격 2번 문자 X]</span><span class=\"cs-exam\">【변18】</span></div>", ["§283", "§74", "§44", "제283조"], 3, "gak_자유"], ["개인010", "강요죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제324조(강요)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 폭행 또는 협박으로 사람의 권리행사를 방해하거나 의무없는 일을 하게 한 자는 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제1항의 죄를 범한 자는 10년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 강요죄의 폭행과 협박 (<span class=\"cs-stat\">§324</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>강요죄의 폭행</strong> 적용범위: <span class=\"cs-fact-tag\">[간접 유형력 O]</span> 폭행 = '사람에 대한' 직접 유형력 + 간접 유형력 행사도 포함 신체에 한정 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[차량을 피해자 주택 대문 앞 주차하여 피해자 차 출입 못하게 함]</span> 강요죄<span class=\"cs-x\"><strong>(X)</strong></span> —</div><div class=\"cs-li\" style=\"margin-left:48px\">①물리적 접촉·유형력 행사 없음(폭행 X)</div><div class=\"cs-li\" style=\"margin-left:48px\">②피해자 차량 정상 사용 가능(권리행사방해 X)</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>강요죄의 협박</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[객관적]</span> 의사결정 자유 제한/의사실행 자유 방해할 정도로 겁먹게 할 해악 고지 <span class=\"cs-fact-tag\">[구체적]</span> 발생 가능한 것으로 생각할 수 있는 정도의 구체적 해악 고지 要 <span class=\"cs-fact-tag\">[묵시적 O]</span> 명시적 아니어도 말·행동으로 상대방이 해악 인식 갖게 하면 족 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[골프시설 운영자가 불리하게 변경된 회칙 동의 등록신청서 미제출시 회원 대우 안 함 통지]</span> 협박<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[직무·지위상 영향 줄 수 있는 자의 요구]</span> 곧바로 해악 고지로 단정<span class=\"cs-x\"><strong>(X)</strong></span> 특히 공무원이 직무 관련 상대방에 이익 제공 요구 + 상대방이 직무상 이익 기대·대가로 응함 → 특별한 사정 없으면 해악 고지로 단정 곤란<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[상관이 부하에게 직무수행 일지 형식 보고 명령]</span> 강요죄<span class=\"cs-x\"><strong>(X)</strong></span> — 직무권한 내 정당한 명령으로 실행 법률상 의무 有, 불이행시 징계·얼차려 부과되어도 무관</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[직장상사가 범죄 저지른 부하에게 사직 단순 권유]</span> 협박<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 권리행사를 방해하거나 의무없는 일을 하게 하는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '의무 없는 일' = 법령·계약 등에 기한 법률상 의무 없는 일 폭행·협박으로 법률상 의무 있는 일 하게 함 → <span class=\"cs-crime\">폭행·협박죄</span>만 성립, 강요죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22】</span></div><div class=\"cs-h\">Ⅲ. 강요죄의 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[현실적 방해]</span> 폭력에 의한 권리행사방해죄는 폭행·협박으로 권리행사가 '현실적'으로 방해되어야 협박 자체가 미수에 그침 或 현실적으로 권리행사 방해 X → 강요미수죄(<span class=\"cs-stat\"><strong>§324의5</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[해외도피 방지 위해 협박하여 여권 강제 회수]</span> 기수<span class=\"cs-o\"><strong>(O)</strong></span> — 해외여행 권리 사실상 침해</div>", ["§324", "제324조"], 2, "gak_자유"], ["개인011", "체포·감금죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제276조(체포, 감금, 존속체포, 존속감금)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 체포 또는 감금한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 또는 배우자의 직계존속 [이하 생략]</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제277조(중체포, 중감금, 존속중체포, 존속중감금)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 체포 또는 감금하여 가혹한 행위를 가한 자는 7년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 또는 배우자의 직계존속 [이하 생략]</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제278조(특수체포, 특수감금)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 전 2조의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다. [제281조 체포감금치사상죄 생략]</div></div><div class=\"cs-h\">Ⅰ. 체포죄 (<span class=\"cs-stat\">§276</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '체포' = 신체에 직접적·현실적 구속 가하여 신체활동 자유 박탈, 수단·방법 불문 <span class=\"cs-neg-tag\">[체포·감금·약취·유인은 폭행·협박으로 제한 X]</span> <span class=\"cs-fact-tag\">[착수]</span> 체포 고의로 타인 신체활동 자유 현실적으로 침해하는 행위 개시한 때 <span class=\"cs-fact-tag\">[기수]</span> 계속범 → 신체 자유 구속 인정할 정도의 시간적 계속 要, 일시적으로 그치면 미수<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강간미수 후 나가려는 피해자 세 번 밀치고 엘리베이터서 팔 잡고 끌어내리려 하며 닫히는 문 막고 들어오려 함]</span> 일시적으로나마 신체 구속 <span class=\"cs-fact-tag\">[체포미수죄 O]</span></div><div class=\"cs-h\">Ⅱ. 감금죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>감금죄의 객체</strong> 적용범위: 정신병자도 감금죄 객체<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>감금의 수단과 방법</strong> 개념: 감금 = 일정 장소 밖 못 나가게 신체 자유 제한 물리적·유형적 장애 + 심리적·무형적 장애에 의하는 경우도 포함 행동 자유 박탈은 전면적일 必要 X → 감금 특정구역 내 일정 생활 자유 허용되어도 감금죄<span class=\"cs-o\"><strong>(O)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[경찰서 대기실, 여닫이문만 열면 나갈 수 있는 구조여도]</span> 감금<span class=\"cs-o\"><strong>(O)</strong></span> — 밖으로 못 나가게 유·무형 억압 有<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[도박빚 갚아야 떠날 수 있다는 위협에 사무실 밖 못 나감]</span> 감금<span class=\"cs-o\"><strong>(O)</strong></span> — 심리적·무형적 장애로 감금상태 30여 차례 전화통화·연락받은 사람이 찾아옴 사정으로 감금죄 부정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자의 입원 환자 퇴원요구에도 퇴원절차 안 밟고 방치]</span> 위법한 감금행위<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>'감금죄'와 다른 범죄의 죄수관계</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">감금 수단으로 행사된 단순 협박 → 감금죄에 흡수, 별도 <span class=\"cs-crime\">협박죄</span><span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">감금이 <span class=\"cs-crime\">강간죄</span>·<span class=\"cs-crime\">강도죄</span> '수단'이어도 흡수 X → 상상적 경합<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">감금이 강도상해 수단에 그치지 않고 범행 후에도 계속 → 감금죄와 <span class=\"cs-crime\">강도상해죄</span> 실체적 경합 <span class=\"cs-fact-tag\">[승용차에 태우고 가다 폭행·반항억압·강취 후 15km 계속 진행하다 사고로 발각]</span><span class=\"cs-exam\">【변18·17·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">미성년자 유인 후 계속 불법 감금 → <span class=\"cs-crime\">미성년자유인죄</span> 외 감금죄 별도 성립</div>", ["§276", "제276조", "제277조", "제278조", "제281조"], 3, "gak_자유"], ["개인012", "약취·유인죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제287조(미성년자의 약취, 유인)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">미성년자를 약취 또는 유인한 사람은 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제295조의2(형의 감경)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">제287조부터 제290조까지, 제292조와 제294조의 죄를 범한 사람이 약취, 유인, 매매 또는 이송된 사람을 안전한 장소로 풀어준 때에는 그 형을 감경할 수 있다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제296조의2(세계주의)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">제287조부터 제292조까지 및 제294조는 대한민국 영역 밖에서 죄를 범한 외국인에게도 적용한다.</div></div><div class=\"cs-h\">Ⅰ. 약취</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>약취의 의미</strong> 개념: '약취' =</div><div class=\"cs-li\" style=\"margin-left:16px\">①폭행·협박 또는 불법적 사실상의 힘 수단</div><div class=\"cs-li\" style=\"margin-left:16px\">②피해자 의사에 반해 자유로운 생활관계·보호관계에서 이탈</div><div class=\"cs-li\" style=\"margin-left:16px\">③자기·제3자 사실상 지배하로 옮김 적용범위: <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§288</span><span class=\"cs-fact-tag\"> 약취]</span> 폭행·협박 정도는 실력적 지배하 둘 수 있을 정도면 족, 반항억압 정도 不要 미성년자 자유 외 보호감독자 감호권도 보호법익 → 아버지 감호권 침해하여 사실상 지배하로 옮기면 미성년자약취죄<span class=\"cs-o\"><strong>(O)</strong></span> '미성년자 동의' 있어도 성립 변함 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>약취와 장소적 이전</strong> 적용범위: 장소적 이전 + 이전 없이 기존 생활관계·부모와의 보호관계에서 이탈시켜 사실상 지배하 두는 경우도 포함 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[미성년자 혼자 주거 침입 감금 후 폭행·협박으로 부모 출입 봉쇄 或 부모만 강제 퇴거시켜 독자 생활관계 형성]</span> 미성년자약취죄<span class=\"cs-o\"><strong>(O)</strong></span> — 장소적 이전 없어도<span class=\"cs-exam\">【변18·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[강도 과정 일시적 보호관계 침해]</span> 약취 범의 인정 곤란·완전 이탈 평가 곤란 — 의도가 이탈 아닌 금품 강취 위한 반항 제압 / 해악 대상이 거주 미성년자였던 것에 불과</div><div class=\"cs-h\">Ⅱ. 유인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '유인' =</div><div class=\"cs-li\" style=\"margin-left:16px\">①기망·유혹 수단으로 사람 꾀어</div><div class=\"cs-li\" style=\"margin-left:16px\">②하자 있는 의사로</div><div class=\"cs-li\" style=\"margin-left:16px\">③자유로운 생활관계·보호관계 이탈</div><div class=\"cs-li\" style=\"margin-left:16px\">④자기·제3자 사실적 지배하로 옮김 유혹 내용이 허위일 것 不要 피해자가 하자있는 의사로 자유롭게 승낙했어도 성립 지장 X 사실적 지배 = 물리적·실력적 지배관계</div><div class=\"cs-h\">Ⅲ. 약취유인의 상대방</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 폭행·협박 또는 기망·유혹의 상대방은 피인취자·보호감독자 불문 <span class=\"cs-fact-tag\">[보호자를 폭행하여 떠나게 하고 유아에 대한 실력적 지배]</span></div><div class=\"cs-h\">Ⅳ. 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 미성년자유인죄 범의 = 피해자가 미성년자임을 알면서 유인행위 인식이면 족 피해자 의사에 반함까지 인식 不要</div><div class=\"cs-h\">Ⅴ. '부모'의 미성년자 약취 관련 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>미성년자에 대한 약취죄의 주체</strong> 판단기준 (判例) : 보호·감독자라도 다른 보호감독자 보호·양육권 침해 或 자기 보호·양육권 남용하여 미성년자 본인 이익 침해 → 약취죄 주체<span class=\"cs-o\"><strong>(O)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[외조부에 양육 맡긴 부가 배상금 분쟁 후 귀가하는 미성년자를 의사 반해 강제로 차에 태워 데려감]</span> 미성년자약취죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>약취에 해당하는 경우</strong> 판단기준 (判例) : 이혼·별거 상황 일방이 평온 보호·양육 중, 상대방 부모가 '폭행·협박 또는 불법적 사실상의 힘' 행사하여 양육상태 깨고 사실상 지배하로 옮김 → 미성년자약취죄<span class=\"cs-o\"><strong>(O)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[이혼소송 중 면접교섭 위해 프랑스서 5세 자녀 인계받은 부가 기간 종료 후 연락두절·유아인도명령 불응]</span> 약취<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">['부작위'에 의한 약취, 부진정부작위범]</span> — 불법적 사실상의 힘으로 의사·복리 반해 생활·보호관계 이탈·지배하로 옮긴 적극적 행위와 같은 정도<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>약취에 해당하지 않는 경우</strong> 판단기준 (判例) : 동거 보호·양육 중 일방이 상대방·자녀에 '어떠한 폭행·협박·불법적 사실상 힘 없이' 자녀 데리고 종전 거소 벗어나 양육 계속 → 양육권 남용 등 특별한 사정 없으면 법원 결정·상대방 동의 없어도 미성년자약취죄<span class=\"cs-x\"><strong>(X)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[베트남 여성이 남편 의사 반해 13개월 아들 데리고 베트남行]</span> 약취<span class=\"cs-x\"><strong>(X)</strong></span> — 실력 행사로 이탈시킨 것 아니라 친권자로 줄곧 맡아온 양육 계속 <span class=\"cs-crime\">국외이송약취죄</span>·<span class=\"cs-crime\">피약취자국외이송죄</span><span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사15】</span></div>", ["§288", "제287조", "제295조", "제290조", "제292조", "제294조", "제296조"], 2, "gak_자유"], ["개인013", "강간·유사강간죄", "<div class=\"cs-h\">Ⅰ. 보호법익</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '성적 자유' = 적극적 성행위 자유 아닌 소극적으로 원치 않는 성행위 안 할 자유 '성적 자기결정권' = 성행위 여부·상대방·방법 등을 스스로 결정할 권리</div><div class=\"cs-h\">Ⅱ. 요건</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>강간죄의 객체</strong> 적용범위: <span class=\"cs-fact-tag\">[부부 O]</span> 민법상 동거의무 있어도 강요된 성관계 감내의무 X 강간죄 객체인 사람에 법률상 처 포함 → 혼인관계 파탄뿐 아니라 실질적으로 유지되는 경우에도 성립<span class=\"cs-exam\">【모사15】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>폭행·협박 – 최협의</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[강간]</span> 폭행·협박은 항거 불가능/현저 곤란 정도 要 <span class=\"cs-fact-tag\">[유사강간]</span> 동일</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>폭행·협박과 간음 사이 인과관계</strong> 판단기준 (判例) : 협박과 간음·추행 사이 시간적 간격 있어도 협박에 의한 간음·추행 인정되면 강간·강제추행죄 협박 해당<span class=\"cs-o\"><strong>(O)</strong></span> 폭행·협박과 간음 사이 인과관계 要, 단 폭행·협박이 반드시 간음보다 선행 不要<span class=\"cs-exam\">【변25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[기습적 성기 삽입 후 벗어나려 하자 팔·몸통 끌어안고 등 눌러 반항 억압 후 간음 계속]</span> 강간죄<span class=\"cs-o\"><strong>(O)</strong></span> — 시작시 폭행·협박 없어도 간음과 거의 동시/직후 폭행하여 간음한 것으로 평가</div><div class=\"cs-h\">Ⅲ. 착수와 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[착수]</span> 간음 위해 항거 불능/현저 곤란 정도의 폭행·협박 개시한 때<span class=\"cs-exam\">【모사24】</span> 실제 그 폭행·협박으로 항거 불능/현저 곤란 되어야만 착수 있는 것 X 실제 간음행위 시작되어야만 착수 있는 것 X <span class=\"cs-fact-tag\">[유사강간 동일]</span> <span class=\"cs-fact-tag\">[기수]</span> 간음행위 한 때 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강간 목적 집 침입, 자는 피해자 가슴·엉덩이 만지며 간음 기도]</span> 준강간죄 착수<span class=\"cs-o\"><strong>(O)</strong></span> — 강간 수단 폭행·협박 개시 X</div><div class=\"cs-h\">Ⅳ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[1회 강간 상해 후 약 1시간 뒤 장소 옮겨 다시 1회 강간]</span> 실체적 경합 — 범행 시간·장소 다르고 각 별개 범의</div><div class=\"cs-h\">Ⅴ. 강간치상죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 강간치상죄 상해 결과는 강간 수단 폭행에서 발생한 경우뿐 아니라 간음행위 그 자체/강간에 수반하는 행위에서 발생한 경우도 포함</div><div class=\"cs-h\">Ⅵ. 예비·음모죄 처벌규정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①형법은 강간·유사강간죄 예비·음모 처벌규정 有, 강제추행죄는 無(<span class=\"cs-stat\"><strong>§305의3</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:16px\">②성폭법은 특수강간·특수강제추행(특수유사강간 포함) 모두 예비음모 처벌규정 有(<span class=\"cs-stat\"><strong>§15의2</strong></span>)<span class=\"cs-exam\">【변23】</span></div>", ["§305", "§15"], 2, "gak_성범죄"], ["개인014", "강제추행죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 사진유포 협박으로 피해자 자기추행 강요</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 평소 좋아하던 A(여, 20세)로부터 은밀한 신체 부위 사진을 전송받은 적 있음. 영상통화 중 \"시키는 대로 안 하면 사진 유포하겠다\" 협박 → 겁먹은 A가 가슴·음부를 스스로</div><div class=\"cs-li\" style=\"margin-left:0px\">만지게 함. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [강제추행죄의 성립여부]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [강제추행죄의 폭행]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 폭행·협박 선행형 — 종전 판례는 항거곤란 정도를 요구했으나 변경 → 폭행 = 신체에 대한 불법한 유형력 행사 / 협박 = 일반적으로 보아 공포심 일으킬 수 있는 정도의 해악 고지</div><div class=\"cs-li\" style=\"margin-left:0px\">② 사진 유포 협박 = 공포심 일으킬 정도 → 강제추행죄의 협박(O) (본 사례 = 폭행·협박 선행형)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [강제추행죄의 추행]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 추행 = 객관적으로 성적 수치심·혐오감을 일으키고 선량한 성적 도덕관념에 반해 피해자의 성적 자유를 침해하는 행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 강제추행죄는 자수범(X) → 처벌되지 않는 타인을 도구로 한 간접정범 가능, 도구인 타인에 피해자도 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">③ A가 스스로 만지게 함 → 피해자를 도구로 이용한 강제추행죄(<span class=\"cs-stat\"><strong>제298조</strong></span>) 간접정범(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [소결] 甲 = 강제추행죄의 간접정범</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [성폭법위반(촬영물등이용강요)죄의 성립여부]</strong> 사진 유포 협박으로 의무 없는 일을 하게 함 → 성폭법위반(촬영물등이용강요)죄(성폭법 <span class=\"cs-stat\"><strong>제14조의3</strong></span> 제2항, 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 강제추행죄 간접정범 + 성폭법위반(촬영물등이용강요)죄 = 1개 행위 → 상상적 경합</div></div></details></div></details><details class=\"cs-case\"><summary><u><strong>[CASE] 마스크 쓰고 뒤따라가 껴안으려다 미수</strong></u> [법무사21 유사] <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 술 마시고 배회 중 버스에서 내린 丙(여, 17세)의 용모에 반해 마스크 착용한 채 뒤따라가 인적 없는 외진 곳에서 접근, 양팔을 높이 들어 껴안으려 함 → 丙이 뒤돌아보며</div><div class=\"cs-li\" style=\"margin-left:0px\">소리치자 몇 초 쳐다보다 되돌아감. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [아청법 적용]</strong> 丙 = 범행 당시 만 17세 → 아청법상 아동·청소년(아청법 <span class=\"cs-stat\"><strong>제2조</strong></span> 제1호)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [강제추행의 고의]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 추행 = 객관적으로 성적 수치심·혐오감을 일으키고 선량한 성적 도덕관념에 반해 피해자의 성적 자유를 침해하는 행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙에게 접근해 갑자기 뒤에서 껴안으려 함 → 추행 해당 → 추행의 고의(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [강제추행의 폭행]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 기습추행형의 폭행 = 의사 억압 정도 不要, 의사에 반하는 유형력 행사가 있는 이상 힘의 대소강약 불문</div><div class=\"cs-li\" style=\"margin-left:0px\">② 마스크 쓰고 뒤따라가 외진 곳에서 접근·양팔 들어 껴안으려 함 → 기습추행형 폭행(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 폭행 개시로 실행의 착수(O), 丙이 소리쳐 추행에는 이르지 못함 → 아청법위반(강제추행)죄의 장애미수(아청법 <span class=\"cs-stat\"><strong>제7조</strong></span> 제6항, 제3항, 형법 <span class=\"cs-stat\"><strong>제298조</strong></span>, <span class=\"cs-stat\"><strong>제25조</strong></span>)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 폭행 또는 협박 (<span class=\"cs-stat\">§298</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[폭행·협박 선행형]</span> '폭행·협박'은 폭행죄·협박죄와 동일 = 신체에 불법한 유형력 행사(폭행) or 공포심 일으킬 정도의 해악 고지(협박)<span class=\"cs-exam\">【변사21】</span> <span class=\"cs-fact-tag\">[기습추행형]</span> 폭행행위 자체가 추행 → 폭행은 의사 억압 정도 불요 의사에 반하는 유형력이면 힘의 대소강약 불문<span class=\"cs-exam\">【변23·18·15】</span><span class=\"cs-exam\">【모사23·19】</span></div><div class=\"cs-h\">Ⅱ. 추행</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>추행의 개념</strong> 개념: 추행 = 객관적으로 일반인에게 성적 수치심·혐오감 일으키고 선량한 성적 도덕관념에 반하여 '피해자의 성적 자유'를 침해 <span class=\"cs-fact-tag\">[성범죄의 '추행' 의미 동일]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[엘리베이터 폐쇄공간 칼로 위협 후 자위행위 관람 강요]</span> 추행<span class=\"cs-o\"><strong>(O)</strong></span> — 실력적 지배하에 외면·회피 못하게 함 <span class=\"cs-fact-tag\">[성폭법(특수강제추행)]</span><span class=\"cs-exam\">【모사21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[비교: 엘리베이터 13세미만과 단둘, 성기 노출·접근(신체접촉 X)]</span> '위력'에 의한 추행<span class=\"cs-o\"><strong>(O)</strong></span> — 도피 불가한 협소·폐쇄 상황 조성 <span class=\"cs-fact-tag\">[성폭법(13세미만위계등추행)]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[회식 후 노래방 분위기서 즉시 거부의사 안 밝힘]</span> 동의·의사에 반하지 않았다고 쉽게 단정 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>추행 대상 신체 부분</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대표가 회식 중 직원 머리 헤드락·머리카락 잡고 흔듦]</span> 추행<span class=\"cs-o\"><strong>(O)</strong></span>·고의<span class=\"cs-o\"><strong>(O)</strong></span> — 공개장소·동석자는 중요 고려요소 X, 여성 추행은 신체부위별 본질적 차이 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[회식 후 단둘, 거절에도 모텔 가자며 손목 잡아끎]</span> 성적 수치심·혐오감 일으키는 추행<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>성적 자기결정의 자유 침해</strong> 판단기준 (判例) : 성적 수치심·혐오감 일으키고 도덕관념에 반해도 피해자의 성적 자기결정 자유 침해 아니면 추행<span class=\"cs-x\"><strong>(X)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[공개도로서 욕설하며 바지 벗어 성기 노출·신체접촉 X]</span> 폭행·협박으로 추행<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>대상자의 성적수치심 또는 혐오감</strong> 판단기준 (判例) : 추행행위 실행으로 충분 → 대상자가 실제로 성적 수치심·혐오감 느껴야 하는 것 X <span class=\"cs-fact-tag\">[공중밀집장소추행죄도 동일]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[뒤에서 접근해 성기 노출, 피해자 등에 소변]</span> 추행<span class=\"cs-o\"><strong>(O)</strong></span> — 행위 당시 피해자가 인식 못했어도</div><div class=\"cs-h\">Ⅲ. 착수와 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 추행 고의로 의사에 반하는 유형력 행사(폭행)해 착수했으나 추행 결과 미도달 → 강제추행미수; 기습추행도 동일<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[밤에 마스크 쓰고 17세女 뒤따라가 뒤에서 껴안으려다 소리쳐 실패, 팔 안 닿음]</span> 아청법위반(강제추행) 미수 — 껴안으려는 행위가 의사에 반하는 폭행=기습추행 착수, 추행 결과 미도달<span class=\"cs-exam\">【변25·19】</span><span class=\"cs-exam\">【모사23·19】</span></div><div class=\"cs-h\">Ⅳ. 죄수관계 및 주관적 구성요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 강제추행죄는 특별한 사정 없는 한 행위마다 1개 범죄 성립 행위마다 폭행·협박 외에 추행행위 및 그에 대한 범의가 인정되어야 성립 주관적 구성요건은 고의로 충분 → 성욕 자극·흥분·만족의 동기·목적 불요<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅴ. 강제추행치상죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 상해 결과는 강제추행 수단인 폭행·추행 그 자체 또는 이에 수반하는 행위로부터 발생해야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[폭행 당시 강제추행 범의 없었음]</span> 그 폭행은 강제추행 수단 X → 폭행 상해와 이후 강제추행 간 인과관계<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[폭행으로 비골골절 상해 후 강제추행, 폭행이 추행수단 아님]</span> 강제추행치상 상해로 인정<span class=\"cs-o\"><strong>(X)</strong></span> — 인과관계 X → <span class=\"cs-crime\">상해죄</span>·<span class=\"cs-crime\">강제추행죄</span> 실체적 경합<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">◎ 피해자 연령에 따른 성범죄 처벌규정 (원문 정리표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[폭행·협박·준범죄·위계·위력]</span> 13세미만: 성폭법 <span class=\"cs-stat\"><strong>제7조</strong></span> (형법·아청법 <span class=\"cs-stat\"><strong>제7조</strong></span> 적용X, 특별법 관계) 13세 이상 19세 미만(13~16세, 16~19세 공통): 아청법 <span class=\"cs-stat\"><strong>제7조</strong></span> (형법 적용X) 위 나이 범죄와 성폭법상 특수범죄는 상상적 경합으로 의율:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 주거침입절도강간등<span class=\"cs-exam\">【모사23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">② 특수강도강간 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">③ 특수강간 등과 아청법 <span class=\"cs-stat\"><strong>제7조</strong></span><span class=\"cs-exam\">【변기19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">④ 아청법위반(위계등유사성행위)와 성폭법위반(업무상위력등에의한추행)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[기타 유형 – 주체]</span> 13세미만: 주체 제한 없음 13세 이상 19세 미만: 주체 19세 이상의 사람</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[장애]</span> 13세미만: 형법 <span class=\"cs-stat\"><strong>제305조</strong></span> 제1항 / 13세 이상 19세 미만: 아청법 <span class=\"cs-stat\"><strong>제8조</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[궁박]</span> 13세미만: 형법 <span class=\"cs-stat\"><strong>제305조</strong></span> 제1항 / 13~16세: 아청법 <span class=\"cs-stat\"><strong>제8조의2</strong></span> <span class=\"cs-fact-tag\">[장애 아동청소년 제외]</span> / 16~19세: X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[동의]</span> 13세미만: 형법 <span class=\"cs-stat\"><strong>제305조</strong></span> 제1항 / 13~16세: 형법 <span class=\"cs-stat\"><strong>제305조</strong></span> 제2항<span class=\"cs-exam\">【변26·25】</span> / 16~19세: X</div>", ["§298", "제298조", "제14조", "제2조", "제7조", "제25조", "제305조", "제8조"], 3, "gak_성범죄"], ["개인015", "준강간·준강제추행", "<div class=\"cs-h\">Ⅰ. 심신상실 또는 항거불능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 준강간죄 보호법익 = 성적 자기방어 못하는 사람의 성적 자기결정권 (원치 않는 성적관계 거부라는 소극적 측면) '항거불능' = 심신상실 이외의 원인으로 심리적·물리적 반항이 절대적 불가능 or 현저히 곤란</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[잠깨어 피고인을 애인으로 착각, 빨리하라며 성교에 응함]</span> 준강간<span class=\"cs-o\"><strong>(X)</strong></span> — 간음 당시 심신상실 X<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-h\">Ⅱ. 블랙아웃과 패싱아웃</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[알코올 블랙아웃(기억형성 실패만)]</span> 인지기능·의식상태 장애 인정 곤란</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[패싱아웃(수면 등 의식상실)]</span> 심신상실<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[의식상실 아니나 알코올로 의사형성능력·저항력 현저 저하]</span> '항거불능'<span class=\"cs-o\"><strong>(O)</strong></span> → 준강간·준강제추행 성립 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[깊은 잠·술·약물로 일시 의식상실 또는 정상 판단·대응·조절 능력 행사 불가]</span> 준강제추행죄 심신상실 or 항거불능<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅲ. 준강간의 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 준강간 고의 = 피해자가 심신상실·항거불능 상태라는 것 +<span> </span>이를 이용해 간음한다는 결과발생 가능성 인식하고 위험 용인하는 내심의 의사<span class=\"cs-exam\">【변23】</span></div>", [], 2, "gak_성범죄"], ["개인016", "성폭법 – 주거침입강간 등", "<details class=\"cs-case\"><summary><u><strong>[CASE] 엘리베이터 폭행 후 계단 강간 중지·저항 중 상해</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(25)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A를 강간하기로 마음먹고 A 거주 아파트 1층 현관에 숨어 있다 귀가하는 A를 따라 엘리베이터 탑승 → 주먹으로 얼굴 2회 폭행, 5층에서 내려 계단으로 끌고 가 청테이프로 양손 묶어 반항 억압 후 간음하려 했으나 A가 애원하자 뉘우치고 단념. A는 끌려가는 과정에서 甲의</div><div class=\"cs-li\" style=\"margin-left:0px\">손을 뿌리치다 넘어져 3주 발목 골절. 甲의 죄책은? (25점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [성폭법위반(주거침입강간)죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [결합범] 주거침입죄 + 강간죄의 결합범</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [주거침입죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공동주택 내부 공용부분도 '주거'(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② '침입' 여부 = 출입 당시 객관적·외형적으로 드러난 행위태양 기준이 원칙</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 사실상 평온상태를 해치는 태양으로 침입(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 주거침입죄(<span class=\"cs-stat\"><strong>제319조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [중지미수의 인정여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① <span class=\"cs-stat\"><strong>제26조</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">② 자의성 — 학설 및 판례(절충설)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 폭행으로 강간 실행 착수 후 A의 애원에 뉘우치고 간음 포기 → 어느 견해에 의해도 자의성(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 성폭법위반(주거침입강간)죄의 중지미수(성폭법 <span class=\"cs-stat\"><strong>제15조</strong></span>, <span class=\"cs-stat\"><strong>제3조</strong></span> 제1항, 형법 <span class=\"cs-stat\"><strong>제319조</strong></span> 제1항, <span class=\"cs-stat\"><strong>제297조</strong></span>, <span class=\"cs-stat\"><strong>제26조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [성폭법위반(강간등치상)죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [기본범죄의 미수] 주거침입강간이 미수여도 상해 발생 시 성폭법위반(강간등치상)죄(O)(성폭법 <span class=\"cs-stat\"><strong>제8조</strong></span> 제1항, <span class=\"cs-stat\"><strong>제3조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [강간미수행위와 상해의 인과관계 및 예견가능성]</div><div class=\"cs-li\" style=\"margin-left:0px\">① <span class=\"cs-stat\"><strong>제15조</strong></span> 제1항 — 결과적 가중범은 기본범죄와 중한 결과 사이 상당인과관계 + 예견가능성 要</div><div class=\"cs-li\" style=\"margin-left:0px\">② 저항하며 손 뿌리치다 넘어져 골절 = 통상 예견 가능 → 상당인과관계·예견가능성(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [결과적 가중범의 미수 인정여부] 긍정설(미수설)/부정설(기수설), 판례는 특수강간치상죄에서 \"특수강간이 미수에 그쳐도 상해 입었으면 치상죄의 기수범 성립, 미수범(X)\" → 부정설. 결과 발생으로 불법 실현된 이상 미수로 볼 수 없고 기본범죄 미수는 양형 고려로 족 → 부정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 성폭법위반(강간등치상)죄의 기수범. 주거침입죄는 별도 성립(X)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 결합범 (일종의 신분범)<span class=\"cs-exam\">【변사21, 모사24·23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[결합범]</span> 성폭법위반(주거침입강간)죄 = 주거침입죄·건조물침입죄 + 강간죄의 결합범 <span class=\"cs-fact-tag\">[주거침입+(준)강제추행은 단순위헌]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[일종의 신분범]</span> 주거침입 후 강간해야 성립 선후가 바뀌어 강간 후 피해자 주거에 침입 → 해당 X, <span class=\"cs-crime\">강간죄</span>+<span class=\"cs-crime\">주거침입죄</span> 실체적 경합 <span class=\"cs-fact-tag\">[실제 '결합범'이므로 후행가담자는 승계적 공동정범 논점]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[남자화장실서 반항 억압해 여자화장실로 끌고가 유사강간 미수]</span> 성폭법(주거침입유사강간)<span class=\"cs-x\"><strong>(X)</strong></span> — 끌고 갈 때 이미 유사강간 착수 → 여자화장실 침입 전 착수, 주거침입 범한 자 아님 → <span class=\"cs-crime\">유사강간미수죄</span>(<span class=\"cs-stat\"><strong>제300조</strong></span>, <span class=\"cs-stat\"><strong>제297조의2</strong></span>)+<span class=\"cs-crime\">건조물침입죄</span> 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공중화장실 용변칸 노크→남편으로 오인한 피해자가 문 열자 강간의도로 들어감]</span> 주거침입<span class=\"cs-o\"><strong>(O)</strong></span> — 승낙 없음 → <span class=\"cs-crime\">강간등치상죄</span>+<span class=\"cs-crime\">감금죄</span> 상상적 경합<span class=\"cs-exam\">【변17·12】</span></div><div class=\"cs-h\">Ⅱ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[주거침입 강간미수 + 수사단서 제공 보복목적 폭행]</span> <span class=\"cs-crime\">특가법위반(보복폭행등)죄</span>·성폭법위반(주거침입강간)죄 상상적 경합</div>", ["제319조", "제26조", "제15조", "제3조", "제297조", "제8조", "제300조"], 2, "gak_성범죄"], ["개인017", "아청법 및 성폭법상 위계 등 간음", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\">(아청법) <span class=\"cs-crime\"><strong>제2조(정의)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">이 법에서 사용하는 용어의 뜻은 다음과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\">1<span>.</span> \"아동·청소년\"이란 19세 미만의 사람을 말한다.</div></div><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\">(성폭법) <span class=\"cs-crime\"><strong>제14조의3(촬영물과 편집물 등을 이용한 협박·강요)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 성적 욕망 또는 수치심을 유발할 수 있는 촬영물 또는 복제물(복제물의 복제물을 포함한다), 제14조의2 제2항에 따른 편집물등 또는 복제물(복제물의 복제물을 포함한다)을 이용하여 사람을 협박한 자는 1년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항에 따른 협박으로 사람의 권리행사를 방해하거나 의무 없는 일을 하게 한 자는 3년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 상습으로 제1항 및 제2항의 죄를 범한 경우에는 그 죄에 정한 형의 2분의 1까지 가중한다.</div></div><div class=\"cs-h\">Ⅰ. 위력</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '위력' = 강제추행죄의 '폭행·협박'에 해당하지 않는 폭행·협박은 물론, 상대방의 자유의사를 제압·혼란하게 할 사회적·경제적·정치적 지위·권세 이용 포함<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅱ. 위계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 오인·착각·부지의 대상 =</div><div class=\"cs-li\" style=\"margin-left:16px\">①간음행위 자체</div><div class=\"cs-li\" style=\"margin-left:16px\">②간음에 이르게 된 동기</div><div class=\"cs-li\" style=\"margin-left:16px\">③간음과 결부된 금전적·비금전적 대가<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 위계적 언동이 존재한 사정만으로 성립 X → 성행위를 결심하게 된 중요 동기가 포함되어 자발적 성적 자기결정권 행사 없었다 평가돼야 아동·청소년이 동의로 보이는 언동을 해도 기망·왜곡된 신뢰관계 이용에 의한 것이면 온전한 성적 자기결정권 행사 아님<span class=\"cs-exam\">【변25】</span> 간음 목적으로 오인·착각·부지 일으키고 이용해 간음 목적 달성 → 위계와 간음 간 인과관계 인정, 위계에 의한 간음죄 성립<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[36세가 '고2 A' 사칭, 스토킹녀 떼려면 A 선배와 성관계해야 한다며 14세 간음]</span> 위계<span class=\"cs-o\"><strong>(O)</strong></span> — 성행위 결심의 중요 동기 형성, 자발적·진지한 자기결정권 행사 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[매니저·사진작가 1인2역, 성관계하면 모델 시켜준다며 15세 간음]</span> 위계<span class=\"cs-o\"><strong>(O)</strong></span> — '간음에 이르게 된 동기' 내지 '비금전적 대가'에 관한 위계 <span class=\"cs-fact-tag\">[촬영으로 성폭법(카메라등이용촬영)죄도 성립]</span></div><div class=\"cs-h\">Ⅲ. 성폭법위반(업무상위력등에의한추행)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: '보호·감독을 받는 사람'에는 직장 안 보호·감독자뿐 아니라 채용 절차에서 영향력 범위 안에 있는 사람도 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[편의점 업주가 구인광고 보고 연락한 자를 채용 빌미로 유인 추행]</span> 업무상위력등에의한추행<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26·25】</span></div><div class=\"cs-h\">◎ 성폭법위반 결합범 정리표 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">표제: 성폭법위반<span class=\"cs-fact-tag\">[(주거침입, 절도)(강간, 유사강간, 강제추행, 준강간, 준유사강간, 준강제추행)]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">신분('결합범'): 주거침입(미수X), 단순절도 X, 야주절(야간주거침입절도)(미수O), 특수절도(미수O)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">착수/미수·기수: 강간(준강간), 유사강간(준유사강간), 강제추행(준강제추행)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">형량: 동일 — 무기징역 또는 7년 이상의 징역</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">단순위헌: 주거침입+(준)강제추행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">&lt;!-- 아래 조문박스는 원문 p233(017 말미)에 실려 있으나 내용상 <span class=\"cs-fact-tag\">[개인018]</span> 촬영물이용범죄의 핵심조문임. 018 파일에도 동일 조문박스가 수록되어 있으며, 누락 방지를 위해 여기에도 보존함. --&gt;</div>", ["제2조", "제14조"], 2, "gak_성범죄"], ["개인018", "촬영물이용범죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 합의촬영 성관계 동영상 캡처로 채무변제 협박</strong></u> <span class=\"cs-exam\">【변사22】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">丙, 유흥비 마련 위해 메신저로 옛 여자친구 B에게 \"내일까지 빌려간 100만 원 갚아라. 안 그러면 네 가족·친구들이 이 동영상을 보게 될 것\" + 과거 합의하에 촬영한 성관계 동영상</div><div class=\"cs-li\" style=\"margin-left:0px\">캡처 사진 첨부 → B는 겁먹고 경찰 신고. 丙의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [성폭법위반(카메라등이용촬영)]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 성폭법 <span class=\"cs-stat\"><strong>제14조</strong></span> 제1항의 '사람의 신체' = 신체 그 자체를 직접 촬영하는 것만 의미, 신체 이미지가 담긴 영상 촬영은 해당(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 성관계 동영상 캡처 → 본죄 구성(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [성폭법위반(카메라등이용촬영물반포등)]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 합의 촬영이라 촬영 당시엔 B 의사에 반하지 않았으나, 캡처 사진은 '촬영물 또는 복제물'(O) → B 의사에 반해 제공하면 본죄 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">② 본죄는 유포 방지로 피해자를 보호하는 규정 → 피해자 본인은 <span class=\"cs-stat\"><strong>제14조</strong></span> 제2항의 제공 상대방인 '특정한 1인 또는 소수의 사람'에 포함(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ B 본인에게 전송 → '제공'으로 인한 본죄 구성(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [공갈죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 권리행사 수단으로 해악 고지 시 공갈죄 성부 — 긍정설(갈취의 불법)/ 부정설(영득의 불법), 판례 = \"정당한 권리 실현 수단이어도 수단·방법이 사회통념상 허용 범위를 넘으면 공갈죄 실행의 착수\" → 긍정설. 사회통념상 용인 곤란한 협박이면 불법영득의사 인정 가능 → 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 협박했으나 돈 못 받음 → 공갈미수죄(<span class=\"cs-stat\"><strong>제352조</strong></span>, <span class=\"cs-stat\"><strong>제350조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [성폭법위반(촬영물등이용협박)죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 촬영물·복제물(동영상 및 캡처 사진)로 협박 → 성폭법위반(촬영물등이용협박)죄(성폭법 <span class=\"cs-stat\"><strong>제14조의3</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② <span class=\"cs-stat\"><strong>제14조의3</strong></span> 제2항의 '의무 없는 일' = 법률상 의무 없는 일 → 빌려준 돈 변제 요구는 법률상 의무 있는 일 → 성폭법위반(촬영물등이용강요)죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(5) [결론]</strong> 丙 = 공갈미수죄 + 성폭법위반(촬영물등이용협박)죄, 양죄는 상상적 경합</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\">(성폭법) <span class=\"cs-crime\"><strong>제14조(카메라 등을 이용한 촬영)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 카메라나 그 밖에 이와 유사한 기능을 갖춘 기계장치를 이용하여 성적 욕망 또는 수치심을 유발할 수 있는 사람의 신체를 촬영대상자의 의사에 반하여 촬영한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항에 따른 촬영물 또는 복제물(복제물의 복제물을 포함한다. 이하 이 조에서 같다)을 반포·판매·임대·제공 또는 공공연하게 전시·상영(이하 \"반포등\"이라 한다)한 자 또는 제1항의 촬영이 촬영 당시에는 촬영대상자의 의사에 반하지 아니한 경우(자신의 신체를 직접 촬영한 경우를 포함한다)에도 사후에 그 촬영물 또는 복제물을 촬영대상자의 의사에 반하여 반포등을 한 자는 7년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\">(성폭법) <span class=\"cs-crime\"><strong>제14조의3(촬영물과 편집물 등을 이용한 협박·강요)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 성적 욕망 또는 수치심을 유발할 수 있는 촬영물 또는 복제물(복제물의 복제물을 포함한다), 제14조의2 제2항에 따른 편집물등 또는 복제물(복제물의 복제물을 포함한다)을 이용하여 사람을 협박한 자는 1년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항에 따른 협박으로 사람의 권리행사를 방해하거나 의무 없는 일을 하게 한 자는 3년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 상습으로 제1항 및 제2항의 죄를 범한 경우에는 그 죄에 정한 형의 2분의 1까지 가중한다.</div></div><div class=\"cs-h\">Ⅰ. 성폭법위반(카메라등이용촬영) – <span class=\"cs-stat\">제14조</span> 제1항 '촬영'</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>성적 욕망 또는 수치심을 유발할 수 있는</strong> 판단기준 (判例) : 촬영 부위 해당 여부는 피해자와 같은 성별·연령대 일반인 입장에서 촬영장소·각도·거리, 원판 이미지, 특정 신체부위 부각 여부 등 종합 고려해 구체적·개별적·상대적으로 결정 <span class=\"cs-neg-tag\">[피해자가 실제 성적 수치심을 느껴야 하는 것 X]</span> 적용범위: 성적 욕망·수치심 유발 신체 해당 여부는 촬영 대상 신체부분만으로 결정되는 것 X 노출 부분에 한정 X, 밀착 의복으로 엉덩이·허벅지 굴곡이 드러나도 해당 가능 <span class=\"cs-fact-tag\">[버스 레깅스]</span> 공개장소서 자의로 드러낸 신체라도 촬영시 수치심 유발 가능 → 대상 안 된다고 단정 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[청바지 여성 계단 오르는 모습 엉덩이 부각 촬영]</span> <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[부각 없이 뒷모습 전신을 원거리 촬영]</span> <span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>사람의 신체</strong> 개념: '사람의 신체' = 신체 그 자체 직접 촬영만 해당, 신체 이미지가 담긴 영상 촬영은 X<span class=\"cs-exam\">【모기25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[모니터 화면(화상카메라 수신 영상) 촬영]</span> <span class=\"cs-x\"><strong>(X)</strong></span> — 신체 자체 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[영상통화 수신 신체 이미지를 녹화·저장]</span> <span class=\"cs-x\"><strong>(X)</strong></span> — 신체 자체 아님<span class=\"cs-exam\">【변21】</span><span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>의사에 반하여</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[매니저·사진작가 1인2역 거짓말에 속아 나체촬영·성관계 응함]</span> 의사에 반함<span class=\"cs-o\"><strong>(O)</strong></span> — 자유의사에 기초한 승낙 아님 <span class=\"cs-fact-tag\">[하자 있는 동의에 기해 촬영해도 본죄 성립]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>촬영죄의 착수·기수</strong> 개념: 촬영 = 필름·저장장치에 피사체 영상정보를 입력하는 행위 <span class=\"cs-neg-tag\">[착수X]</span> 육안·줌 기능으로 피해자 있는지 탐색하다 미발견해 포기 → 준비행위, 착수 X <span class=\"cs-fact-tag\">[착수O]</span> 휴대폰을 치마 밑/화장실칸 밑으로 들이밀어 대상을 피해자로 특정하고 초점 맞추는 등 밀접행위 개시 → 착수 O<span class=\"cs-exam\">【변26】</span> <span class=\"cs-fact-tag\">[기수]</span> 영상정보가 주기억장치 등에 입력되면 기수 저장버튼 안 눌러 강제종료돼 영구저장 안 됐어도 미수 X<span class=\"cs-exam\">【변26·24】</span></div><div class=\"cs-h\">Ⅱ. 성폭법위반(카메라등이용촬영물반포등) – <span class=\"cs-stat\">제14조</span> 제2항 '반포 등'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[제2항 전단]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①사람의 신체 자체를</div><div class=\"cs-li\" style=\"margin-left:16px\">②의사에 반하여 촬영한</div><div class=\"cs-li\" style=\"margin-left:16px\">③촬영물·복제물을</div><div class=\"cs-li\" style=\"margin-left:16px\">④의사에 반하여 반포등 <span class=\"cs-fact-tag\">[제2항 후단]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①타인 또는 '자신'의 신체를</div><div class=\"cs-li\" style=\"margin-left:16px\">②의사에 반하지 않고 촬영한 경우</div><div class=\"cs-li\" style=\"margin-left:16px\">③촬영물·복제물을</div><div class=\"cs-li\" style=\"margin-left:16px\">④의사에 반하여 반포등</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 반포자 ≠ 촬영자여도 무방, 촬영물을 누가 촬영했는지 불문<span class=\"cs-exam\">【변21】</span> <span class=\"cs-fact-tag\">[반포등 기준]</span> 반포등 행위 시를 기준으로 의사에 반하면 성립 촬영이 의사에 반하지 않았어도 성립에 지장 X<span class=\"cs-exam\">【변25·21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 반포 = 불특정·다수인에 무상 교부 반복 전달로 불특정·다수인 반포 의사 있으면 1인·소수 교부도 반포 가능 제공 = 반포에 이르지 않는 무상교부, 반포 의사 없이 특정 1인·소수에 무상 교부 <span class=\"cs-fact-tag\">[전시]</span> '공공연한 전시' = 불특정·다수인 인식 가능 상태에 두는 것, 실제 인식 못했어도 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[영상통화서 자기 신체 직접 촬영·전송한 영상]</span> 전단 촬영물 X, 후단 '자신 신체 직접 촬영' 촬영물 O 상대방이 녹화·저장한 동영상은 후단 촬영물의 '복제물'</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">피해자 본인은 제2항 '제공의 상대방(특정 1인·소수)'에 포함 X<span class=\"cs-exam\">【변24·21】</span><span class=\"cs-exam\">【변사22·21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상영]</span> 지인 2명에게 성관계 동영상을 휴대폰으로 시청하게 함 → '공공연한 상영'<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. <span class=\"cs-stat\">제14조의3</span> 성폭법위반(촬영물등이용협박·강요)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>촬영물 또는 복제물</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[만들어진 바 있는 촬영물]</span> 실제 만들어진 촬영물 등을 방편으로 유포가능성 등 공포심 일으킬 해악 고지하면 성립 직접 제시·소지·유포 가능 상태 불요 <span class=\"cs-fact-tag\">[유포 의사 있어야 하는 것 X]</span><span class=\"cs-exam\">【변25】</span> 적용범위: <span class=\"cs-fact-tag\">[피해자를 대상으로 한 촬영물]</span> '촬영물등' = 피해자 신체를 촬영했거나 피해자로 오인할 편집물로 제한 → 무관한 타인 사진을 피해자처럼 오인시켜 협박은 성폭법위반(촬영물등이용협박)죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>죄수관계</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[촬영물 협박으로 '돈' 요구 미수]</span> <span class=\"cs-crime\">공갈미수죄</span> + 성폭법위반(촬영물등이용강요)죄 미수범 상상적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[촬영물 협박으로 '변제' 받음]</span> <span class=\"cs-crime\">공갈죄</span> + 촬영물등이용'협박'죄 상상적 경합 <span class=\"cs-fact-tag\">[변제는 피해자의 의무 → 촬영물이용강요 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[촬영물로 피해자 스스로 자기 신체 추행 강요]</span> 촬영물등이용강요죄 + 간접정범 <span class=\"cs-crime\">강제추행죄</span> 상상적 경합 (하급심)</div>", ["제14조", "제352조", "제350조"], 3, "gak_성범죄"], ["개인019", "아동·청소년성착취물", "<div class=\"cs-h\">Ⅰ. 제작·수입·수출 (<span class=\"cs-stat\">제11조</span> 제1항) – 아청법위반(성착취물제작등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 일상생활 중 신체노출을 몰래 촬영하는 등 성적 대상화하면 적극적 성적 행위 아니어도 성착취물<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[기숙사 여학생 옷 갈아입는 모습 망원렌즈 몰래 촬영]</span> 아청이 제작에 '동의'했거나 개인적 소지·보관을 1차 목적으로 제작해도 성착취물 제작<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25·19】</span><span class=\"cs-exam\">【모기25】</span> 직접 촬영 안 해도 기획하거나 촬영 지시하면 '제작' 재생 가능 형태로 저장된 때 기수 (재생 가능 상태 도달 不要) 아청 스스로 촬영하게 한 경우도 동일<span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-h\">Ⅱ. 구입·소지·시청 (<span class=\"cs-stat\">제11조</span> 제5항) – 아청법위반(성착취물소지등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 구입해 시청·접근 가능 상태만으로 소지로 보는 것은 문언 해석 한계 넘어 허용 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[클라우드 URL로 접속했으나 다운로드 등 지배 가능 상태로 안 나아감]</span> 소지<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">제작자가 성착취물 소지 → 소지죄는 제작죄에 흡수</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">다만 제작 수반 소지 벗어나 사회통념상 새로운 소지 개시 → 제작죄와 별개의 소지죄</div>", ["제11조"], 2, "gak_성범죄"], ["개인020", "명예훼손죄 기본 법리", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제307조(명예훼손)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공연히 사실을 적시하여 사람의 명예를 훼손한 자는 2년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공연히 허위의 사실을 적시하여 사람의 명예를 훼손한 자는 5년 이하의 징역, 10년 이하의 자격정지 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제308조(사자의 명예훼손)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">공연히 허위의 사실을 적시하여 사자의 명예를 훼손한 자는 2년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제309조(출판물 등에 의한 명예훼손)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 비방할 목적으로 신문, 잡지 또는 라디오 기타 출판물에 의하여 제307조 제1항의 죄를 범한 자는 3년 이하의 징역이나 금고 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 방법으로 제307조 제2항의 죄를 범한 자는 7년 이하의 징역, 10년 이하의 자격정지 또는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">(정통망법) <span class=\"cs-crime\"><strong>제70조(벌칙)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 비방할 목적으로 정보통신망을 통하여 공공연하게 사실을 드러내어 다른 사람의 명예를 훼손한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 사람을 비방할 목적으로 정보통신망을 통하여 공공연하게 거짓의 사실을 드러내어 다른 사람의 명예를 훼손한 자는 7년 이하의 징역, 10년 이하의 자격정지 또는 7천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 제1항과 제2항의 죄는 피해자가 구체적으로 밝힌 의사에 반하여 공소를 제기할 수 없다.</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 제2항의 죄를 지은 자가 해당 위반행위와 관련하여 취득한 금품이나 그 밖의 이익은 몰수한다. 그 금품이나 그 밖의 이익을 몰수하기 불가능하거나 재산상의 이익을 취득한 때에는 그 가액을 추징한다.</div></div><div class=\"cs-h\">Ⅰ. 집합명칭에 의한 명예훼손</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 집합적 명사라도 어떤 범위의 특정인을 가리킴이 명백하면 각자의 명예훼손<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[집단표시]</span> 비난 정도가 희석되어 개개인의 사회적 평가에 영향 못 미침 → 개개인 명예훼손<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[서울시민 X]</span> 희석되지 않아 개개인 평가 저하 → 개개인 명예훼손<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[모욕죄에도 동일]</span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-h\">Ⅱ. 명예훼손의 피해자</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 특정 사람 또는 인격 보유 단체에 대해 성립 <span class=\"cs-fact-tag\">[피해자에 자연인·법인·법인격 없는 단체 포함]</span><span class=\"cs-exam\">【변24·14】</span> 국가·지방자치단체는 기본권 수범자일 뿐 → 외부적 명예 주체 X, 명예훼손·모욕 피해자<span class=\"cs-o\"><strong>(X)</strong></span> 정부·국가기관도 명예훼손죄 피해자<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 공적 인물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 기자회견 등 공개 발언은 공적 인물의 공적 관심사안 vs 사적 영역 사이에 심사기준 차이 두어야 공공적·사회적 의미 표현은 표현의 자유 제한 완화 공적 인물의 공적 관심사 의혹 제기는 암시에 의한 사실 적시로 평가함에 신중 정부·국가기관 정책·업무 관련 발언은 공직자 개인에 대한 악의적이거나 심히 경솔한 공격으로 현저히 상당성 잃지 않는 한 공직자 개인에 대한 명예훼손<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅳ. 공연성 (전파가능성)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>전파가능성</strong> 개념: 공연성 = 불특정·다수인이 인식할 수 있는 상태 소수에게 적시했어도 상대방이 불특정·다수인에게 전파할 가능성 있으면 공연성<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25】</span> 적용범위: 정통망 명예훼손·공직선거법상 후보자비방죄 공연성 판단에도 동일 적용<span class=\"cs-exam\">【변26】</span> 판단기준 (判例) : 전파가능성 인정에는 막연한 가능성으로 부족, 고도의 가능성 내지 개연성 要 실제 전파 여부는 소극적 사정으로만 고려 <span class=\"cs-neg-tag\">[상대방이 배우자·친척·친구 등 친밀관계 or 비밀유지 직무자]</span> 비밀 보장 기대 → 공연성<span class=\"cs-x\"><strong>(X)</strong></span> 인정하려면 그럼에도 전파될 특별한 사정 要 인정자료: 전파가능성은 검사의 엄격한 증명 要</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공연성에 대한 고의</strong> 개념: 전파가능성으로 공연성 인정시 미필적 고의 要 = 전파가능성 인식 + 위험 용인 내심의 의사 판단기준 (判例) : 전파가능성 용인 여부는 '행위자의 입장'에서 심리상태 추인 사실 확인·규명, 상대방 가해에 대응, 수사·소송 등 공적 절차 공방 중 발언 → 전파가능성 인식·용인 인정 신중</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>공연성에 관한 구체적 판례</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[병문안 4명 자리서 \"피해자에게 정신병 있었다더라\"]</span> 공연성<span class=\"cs-x\"><strong>(X)</strong></span> — 참석자 관계상 전파가능성 X<span class=\"cs-exam\">【변15·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[블로그 비공개 1:1 대화, 비밀 지키겠다는 말 들음]</span> 공연성 인정 가능 — 전파가능성 X 아님<span class=\"cs-exam\">【변23·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[친척 B 앞 \"전과자다\" 큰소리]</span> 전파가능성 부정 X — B가 전과 처음 들을 정도로 가깝지 않고 회자 가능성 큰 개인사</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[귀엣말로 '그 사람 본인'만 들리게 본인 관련 사실 이야기]</span> 공연성<span class=\"cs-x\"><strong>(X)</strong></span> — 전파가능성 X (그가 스스로 전파해도 결론 동일)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[진정서·고소장 사본을 특정인 200여 명에게 개별 우송]</span> 공연성<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅴ. 구체적 사실의 적시</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>사실의 적시</strong> 개념: 사실의 적시 = 의견표현에 대치되는 개념 시공간적으로 구체적인 과거·현재 사실관계의 보고·진술, 증거에 의한 증명 가능한 것 적용범위: <span class=\"cs-stat\"><strong>제307조</strong></span>①의 '사실' =</div><div class=\"cs-li\" style=\"margin-left:16px\">②의 '허위사실'과 반대되는 '진실한 사실' 아니라 '의견'에 대치되는 개념 →</div><div class=\"cs-li\" style=\"margin-left:16px\">①죄는 진실·허위 불문 성립 허위라도 허위성 인식 없으면</div><div class=\"cs-li\" style=\"margin-left:16px\">②죄 아니라</div><div class=\"cs-li\" style=\"margin-left:16px\">①죄<span class=\"cs-exam\">【변21】</span><span class=\"cs-exam\">【모사24】</span> 적시 사실 = 현실 발생·증명 가능한 과거·현재 사실 장래 일이라도 과거·현재 사실을 기초·주장으로 포함하면 성립<span class=\"cs-exam\">【변16】</span> 판단기준 (判例) : 사실 적시는 직접 표현에 한정 X 간접·우회 표현도 전취지상 사실 존재 암시하고 구체성 있으면 족 사회적 평가 저하 발언이 전문·추측 형태여도 전취지상 사실 존재 암시하면 사실 적시<span class=\"cs-o\"><strong>(O)</strong></span> 비유적·상상적·다의적이고 구체 내용 불특정해 입장 표명이 결정적이면 사실 적시<span class=\"cs-x\"><strong>(X)</strong></span> 비평 중 사실관계 서술 형태여도 실제로는 주관적 의견 강조 수단이면 사실 적시<span class=\"cs-x\"><strong>(X)</strong></span> 학문적 표현의 배후를 섣불리 단정해 암시 사실 적시 인정 X 학문 자유 영역 아님은 검사가 증명 <span class=\"cs-fact-tag\">[제국의 위안부]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[내사종결됐음에도 \"그 경찰관이 내일 검찰청서 구속영장 떨어진다\"]</span> 사실 적시<span class=\"cs-o\"><strong>(O)</strong></span> — 현재 사실 기초로 장래 적시<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[연예인이 재벌 아이 낳았다는 댓글에 \"모 재벌님과의 관계는 끝났나?\" 추가 댓글]</span> 허위사실 적시 → 정통망 명예훼손<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[피해자를 '사칭'해 직접 작성한 글처럼 게시]</span> 정통망 <span class=\"cs-stat\"><strong>제70조</strong></span>② 명예훼손<span class=\"cs-x\"><strong>(X)</strong></span> — 피해자에 대한 사실 드러냄 아님<span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>허위 사실</strong> 판단기준 (判例) : 중요 부분이 객관적 사실과 합치하면 세부 차이·다소 과장 있어도 허위사실<span class=\"cs-x\"><strong>(X)</strong></span> 민사판결로 사실인정 있었다는 이유만으로 반대되는 주장을 '허위 적시' 구성요건 해당한다 단정 X 허위라도 허위성에 대한 인식 없으면</div><div class=\"cs-li\" style=\"margin-left:16px\">②죄 아니라</div><div class=\"cs-li\" style=\"margin-left:16px\">①죄 <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">제15조</span><span class=\"cs-fact-tag\">①]</span><span class=\"cs-exam\">【변15】</span> 인정자료: 정통망</div><div class=\"cs-li\" style=\"margin-left:16px\">②허위 명예훼손은 허위 인식 要, 허위성 인식(범의) 입증책임은 검사 허위 명예훼손도 미필적 고의로 성립; 사자명예훼손 판단도 동일<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>특정인의 사회적 가치나 평가가 침해될 가능성</strong> 판단기준 (判例) : 명예훼손 여부는 사회통념에 따른 객관적 평가로 판단 사실 드러냄 = 사회적 가치·평가 침해 가능성 있을 정도의 구체성 직접 명시 不要하나 곧바로 유추될 정도는 되어야 피해자 특정은 누구를 지목하는지 알아차릴 정도여야 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[상태메시지에 '학교폭력범' 사용]</span> 사회적 가치 저하할 구체적 사실 드러냄<span class=\"cs-x\"><strong>(X)</strong></span> — A 지목 단정 X, 조치 알려진 증거 없음<span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【모기22】</span></div><div class=\"cs-h\">Ⅵ. 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 명예훼손 고의 갖고 사회적 평가 저하에 충분한 구체적 사실 적시해야 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상급자 추궁 질문에 답하다 명예훼손적 사실 발설]</span> 고의 인정 어려움 — 단순 확인 취지 소극적 답변은 사실 적시라 단정 X <span class=\"cs-fact-tag\">[과태료 책임 추궁받자 \"A가 성추행 사건 보고한 사실 없다\" 발언]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[불미스러운 소문 진위 확인차 질문 과정에서 명예훼손 발언]</span> 동기상 고의 인정 어려움 <span class=\"cs-fact-tag\">[입점비 관련 뒷조사 언급]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[목사가 전임목사 소문 진위 확인차 집사들에게 물어봄]</span> 사실 적시<span class=\"cs-o\"><strong>(X)</strong></span> — 고의 없는 단순 확인</div><div class=\"cs-h\">Ⅶ. 명예훼손의 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span> 사회적 평가 침해 '위험' 발생으로 족, 침해 '결과' 不要<span class=\"cs-exam\">【변23】</span> 불특정·다수인이 실제 인식 못했어도 인식할 수 있는 상태면 명예 훼손된 것<span class=\"cs-exam\">【변23·15】</span> 발언 상대방이 직접 인식해야 하는 것 X 서적·신문 게시로 범행 종료 (회수 안 해도 계속 X) 정통망 명예훼손도 게시시 기수·공소시효 기산 (삭제시 X)<span class=\"cs-exam\">【변26·21】</span><span class=\"cs-exam\">【변기24】</span></div><div class=\"cs-h\">Ⅷ. 명예훼손의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[인스타그램으로 계속 A 명예훼손]</span> 정통망 명예훼손 포괄일죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[A·B 동시 지칭해 훼손]</span> 상상적 경합 <span class=\"cs-fact-tag\">[모욕죄도 동일]</span><span class=\"cs-exam\">【모기19】</span></div><div class=\"cs-h\">◎ 명예훼손죄와 모욕죄 정리표 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">처벌규정별 구성요건 / <span class=\"cs-stat\"><strong>제310조</strong></span>(위법성 조각) / 소추조건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">정통망법 명예훼손 (<span class=\"cs-stat\"><strong>제70조</strong></span>): 비방할 목적 + 수단(정통망) + 공연성(전파가능성) <span class=\"cs-stat\"><strong>제310조</strong></span> 적용 X. 소추조건 = 반의사불벌죄(<span class=\"cs-stat\"><strong>제312조</strong></span>).</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">출판물 명예훼손 (<span class=\"cs-stat\"><strong>제309조</strong></span>): 비방할 목적 + 수단(출판물, A4 X) + 공연성(전파가능성) <span class=\"cs-stat\"><strong>제310조</strong></span> 적용 X. 소추조건 = 반의사불벌죄(<span class=\"cs-stat\"><strong>제312조</strong></span>).</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">명예훼손 (<span class=\"cs-stat\"><strong>제307조</strong></span>): 공연성(전파가능성) + 구체적 사실의 적시 <span class=\"cs-fact-tag\">[제1항]</span> '사실' 적시:</div><div class=\"cs-li\" style=\"margin-left:16px\">① 진실 적시,</div><div class=\"cs-li\" style=\"margin-left:16px\">② 허위 적시+허위성 인식 X(<span class=\"cs-stat\"><strong>제15조</strong></span>①) → <span class=\"cs-stat\"><strong>제310조</strong></span> 위법성 조각 O(<span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">제307조</span><span class=\"cs-fact-tag\">①]</span> O) :</div><div class=\"cs-li\" style=\"margin-left:16px\">① 위전착 견해,</div><div class=\"cs-li\" style=\"margin-left:16px\">② 상당한 이유(판례),</div><div class=\"cs-li\" style=\"margin-left:16px\">③ 허용된 위험설 <span class=\"cs-fact-tag\">[제2항]</span> 허위사실 적시: 허위 적시+허위성 인식 → <span class=\"cs-stat\"><strong>제310조</strong></span> 적용 X(<span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">제307조</span><span class=\"cs-fact-tag\">②]</span> X) 소추조건 = 반의사불벌죄(<span class=\"cs-stat\"><strong>제312조</strong></span>).</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">사자 명예훼손 (<span class=\"cs-stat\"><strong>제308조</strong></span>): <span class=\"cs-fact-tag\">[허위사실 적시]</span> 허위사실 적시+허위성 인식</div><div class=\"cs-li\" style=\"margin-left:16px\">① 사실 적시 처벌 X,</div><div class=\"cs-li\" style=\"margin-left:16px\">② 허위 적시+허위성 인식 X ⇒ 무죄(<span class=\"cs-stat\"><strong>제13조</strong></span> 고의 조각) <span class=\"cs-stat\"><strong>제310조</strong></span> 적용 X. 소추조건 = 친고죄(<span class=\"cs-stat\"><strong>제312조</strong></span>).</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">모욕 (<span class=\"cs-stat\"><strong>제311조</strong></span>): 모욕(사실 적시 X) <span class=\"cs-stat\"><strong>제310조</strong></span> 적용 X (단, 형법 <span class=\"cs-stat\"><strong>제20조</strong></span> 정당행위 적용 O). 소추조건 = 친고죄(<span class=\"cs-stat\"><strong>제312조</strong></span>).</div>", ["제307조", "제308조", "제309조", "제70조", "제15조", "제310조", "제312조", "제13조"], 3, "gak_명예주거"], ["개인021", "출판물 및 정통망법", "<details class=\"cs-case\"><summary><u><strong>[CASE] 인터넷 카페 게시판 허위사실 게시 + B 명의 허위 사실확인서 첨부</strong></u> <span class=\"cs-exam\">【변사23】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">X회사 개발팀장 甲, 입주 상가 관리소장 A와 주차 문제로 언쟁 후 A를 비방할 목적으로 입주자 약 200명이 회원인 Y상가 번영회 인터넷 카페 게시판에 'A에게 혼외자가 있다'는 허위사실 게시 + 신빙성 높이려 직원 B에게 부탁해 받은 허위 내용의 B 명의 사실확인서 첨부.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [정통망법위반(명예훼손)]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 인터넷 카페 게시판 = 정보통신망(O)(정통망법 <span class=\"cs-stat\"><strong>제2조</strong></span> 제1항 제1호)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공연성 = 불특정 또는 다수인이 인식할 수 있는 상태 → 회원 약 200명 게시판 → 공연성(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 비방 목적 + 정보통신망에 공공연히 거짓 사실 게시 → 정통망법위반(명예훼손)죄(정통망법 <span class=\"cs-stat\"><strong>제70조</strong></span> 제2항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [사문서위조죄와 무형위조]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사문서는 무형위조 불벌 → B에게 사문서위조죄(X), 무형위조를 교사한 甲에게도 교사죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 위조가 없으니 첨부해도 위조사문서행사죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 정통망법위반(명예훼손)죄(정통망법 <span class=\"cs-stat\"><strong>제70조</strong></span> 제2항)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 비방의 목적 – 출판물 및 정통망법위반</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 비방의 목적은 <span class=\"cs-crime\">출판물에의한명예훼손죄</span>·<span class=\"cs-crime\">정통망법위반(명예훼손)죄</span>의 구성요건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '사람을 비방할 목적' = 가해의 의사 내지 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : '사회적 평가 저하 사실'인지와 별개 구성요건 → 저하 사실이라 하여 당연 인정 X. 모든 구성요건 증명책임은 검사 '거짓'인지와 별개 구성요건 → 거짓이라 하여 당연 인정 X 공익 목적과는 주관적 의도 방향에서 상반 → 적시 사실이 공공의 이익에 관한 것이면 특별한 사정 없는 한 비방목적 부인<span class=\"cs-exam\">【모사25】</span> '적시 사실이 공공의 이익에 관한 경우' = 객관적으로 공익 관련 + 행위자도 주관적으로 공익 위해 적시 주요 동기·목적이 공익이면 부수적 사익 목적·동기 있어도 비방목적 인정 어려움 공공의 이익 = 국가·사회·일반 다수인 이익 + 특정 사회집단·구성원 전체의 관심·이익 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[동창 단체채팅방 사기꾼 글]</span> 정통망법위반(명예훼손)<span class=\"cs-x\"><strong>(X)</strong></span> — 동창 사회집단 이익 관련·주된 목적 공익(주의 당부), 비방목적 증명 부족<span class=\"cs-exam\">【모기23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[포털 지식검색 성형시술 불만 한 줄 댓글]</span> 사실적시<span class=\"cs-o\"><strong>(O)</strong></span>·비방목적<span class=\"cs-x\"><strong>(X)</strong></span> — 다수 이용자 의사결정 도움 공익<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배드파더스 양육비 미지급 신상공개]</span> 비방목적<span class=\"cs-o\"><strong>(O)</strong></span> — 공적 관심사 여론형성 기여하나 개별 채무자 압박·사적 제재 수단에 가까움</div><div class=\"cs-h\">Ⅱ. 출판물에 의한 명예훼손죄 (정통망법도 동일 법리)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>출판물</strong> 판단기준 (判例) : '기타 출판물'(<span class=\"cs-stat\"><strong>§309</strong></span>①) = 등록·출판 제본인쇄물 아니어도 그와 같은 정도의 효용·기능 갖고 사실상 출판물로 유통·통용될 외관 가진 인쇄물이어야 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[A4 7쪽 인쇄물 X]</span> <span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span><span class=\"cs-exam\">【변기19】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>출판물에 의한 명예훼손죄의 간접정범<span class=\"cs-exam\">【모사25·24·20, 모기18】</span></strong> 적용범위: 출판물 명예훼손죄는 간접정범으로도 가능 → 비방 목적으로 허위 기사재료를 정 모르는 기자에게 제공·보도되게 한 경우 성립<span class=\"cs-exam\">【변22】</span> 판단기준 (判例) : <span class=\"cs-fact-tag\">[공연성 구별]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①보통사람에 적시 → 즉시 외부 공표, 그때부터 전파가능성으로 공연성 판단</div><div class=\"cs-li\" style=\"margin-left:16px\">②기자 통한 적시 → 기사화·보도돼야 공표, 취재만 하고 미보도면 전파가능성 X → 공연성<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23】</span> 제보자가 기사 취재·작성과 직접 연관 없는 자에게 허위사실만 알린 경우 → 기사화 특별 부탁·기사화 고도 예상 등 특별한 사정 없으면, 피제보자가 언론공개·취재로 게재·배포되더라도 제보자에게 출판물 명예훼손죄 책임 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사례: 기자에게 허위 제보]</span> (1) <span class=\"cs-fact-tag\">[기자]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①비방목적 없어 <span class=\"cs-stat\"><strong>§309</strong></span> 출판물 명예훼손죄 불성립</div><div class=\"cs-li\" style=\"margin-left:48px\">②허위 인식 없어 <span class=\"cs-stat\"><strong>§15</strong></span>①에 따라 <span class=\"cs-stat\"><strong>§307</strong></span>②이 아닌 <span class=\"cs-stat\"><strong>§307</strong></span>① 적용</div><div class=\"cs-li\" style=\"margin-left:48px\">③<span class=\"cs-stat\"><strong>§307</strong></span>① 명예훼손죄는 <span class=\"cs-stat\"><strong>§310</strong></span> 진실성 착오 학설·판례에 따라 위법성 조각 가능 (2) <span class=\"cs-fact-tag\">[제보자]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①기자에게 직접 기사재료 제공 → 공연성(전파가능성) 인정되면 <span class=\"cs-stat\"><strong>§307</strong></span>② 명예훼손죄 성립</div><div class=\"cs-li\" style=\"margin-left:48px\">②판례에 따라 <span class=\"cs-stat\"><strong>§309</strong></span>② 출판물 명예훼손죄의 간접정범 성립</div><div class=\"cs-li\" style=\"margin-left:48px\">③간접정범 성립하는 이상 <span class=\"cs-stat\"><strong>§307</strong></span>② 명예훼손죄는 별도 성립 X <span class=\"cs-fact-tag\">[정통망법위반(명예훼손)죄 간접정범에도 동일 법리 적용(예: 인터넷 기사).]</span></div>", ["§309", "§15", "§307", "§310", "제2조", "제70조"], 3, "gak_명예주거"], ["개인022", "형법 제310조 위법성조각사유", "<details class=\"cs-case\"><summary><u><strong>[CASE] 기자 프로포폴 불법투여 특종 보도·진실성 착오</strong></u> <span class=\"cs-exam\">【변사16】 </span><span class=\"cs-o\">(25)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">참소식신문사 사회부 기자 甲·乙은 의사들의 프로포폴 불법투여 실태를 취재 중, 다나아 종합병원 원장 A가 연예인들에게 프로포폴을 불법 투여한다는 풍문을 듣고 취재차 병원을 찾아갔다(대표이사 김참말은 포상금 지급을 약속하며 격려). 甲·乙은 연예인 B가 진료실에서 A로부터 프로포폴을 투여받는 것을 열린 문틈으로 우연히 목격하고 불법투여를 사실이라 믿었다. A(환자 비밀)·B(사생활)가 인터뷰를 거절하자, 추가 확인 없이 \"A가 거액을 받고 상습적으로 프로포폴을 주사하고, B도 상습적으로 불법투여받은 것으로 보인다\"는 기사를 작성해 1면 특종으로 게재하였다. 甲·乙은 사실이라 굳게 믿었고 비방 의도 없이 오·남용 근절 목적이었으나, 실은 B는 성형수술 목적이었고 A 관련 내용도 경쟁병원 의사 C의 헛소문(허위)이었다. (1) 甲·乙의 죄책? (25점) (2) 甲·乙 행위에 대해 대표이사 김참말에게 방조범 성립을 긍정하는 견해? (5점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲·乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [구성요건 확정]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 비방목적 ↔ 공익목적은 주관적 의도가 상반 → 드러낸 사실이 공공의 이익에 관한 것이면 특별한 사정 없는 한 비방목적(X). 甲·乙 = 비방 의도 없는 공익 목적 → <span class=\"cs-stat\"><strong>§309</strong></span>(X), <span class=\"cs-stat\"><strong>§307</strong></span> 적용</div><div class=\"cs-li\" style=\"margin-left:0px\">② 적시 사실이 허위여도 행위자에게 허위성 인식이 없으면 <span class=\"cs-stat\"><strong>§307</strong></span>②(X) → <span class=\"cs-stat\"><strong>§307</strong></span>①. 甲·乙 = 진실로 굳게 믿음 → <span class=\"cs-stat\"><strong>§15</strong></span>①에 의해 <span class=\"cs-stat\"><strong>§307</strong></span>① 해당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 하나의 기사로 A·B 명예 동시 훼손 → 각 명예훼손죄 상상적 경합</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [<span class=\"cs-stat\"><strong>§310</strong></span> 진실성 착오의 법적 취급]</div><div class=\"cs-li\" style=\"margin-left:0px\">① <span class=\"cs-stat\"><strong>§307</strong></span>① 행위가 진실한 사실 + 오로지 공공의 이익 → 불벌(<span class=\"cs-stat\"><strong>§310</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 허위를 진실로 믿고 공익 위해 작성 → 진실성 착오</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 위법성조각사유의 전제사실 착오설·허용된 위험설 등, 판례 = 공익 관련이면 진실 증명이 없어도 진실로 믿었고 그렇게 믿을 상당한 이유가 있으면 위법성(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 풍문·투약 장면만 목격, 추가 확인 전무 → 상당한 이유(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [결론] 甲·乙 = A·B에 대한 각 명예훼손죄의 공동정범, 양죄는 상상적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [김참말 방조범 긍정 견해]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [부정 견해] 소극적구성요건표지이론·유추적용제한책임설 → 甲·乙의 불법고의 조각 → 제한적 종속형식상 김참말에게 방조범(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [긍정 견해]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 법효과제한책임설 = 고의불법 인정·책임고의만 조각</div><div class=\"cs-li\" style=\"margin-left:0px\">② 엄격책임설 = '정당한 이유' 부정 → 고의범</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 허용된 위험설 = 성실한 검토의무 위반 → 고의범</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 판례 = 상당한 이유 없어 고의범 → 제한적 종속형식상 김참말에게 방조범(O)</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제310조(위법성의 조각)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">제307조 제1항의 행위가 진실한 사실로서 오로지 공공의 이익에 관한 때에는 처벌하지 아니한다.</div></div><div class=\"cs-h\">Ⅰ. 적용범위 – <span class=\"cs-stat\">제307조</span> 제1항 (구성요건의 확정)<span class=\"cs-exam\">【변사16, 모사25·24·20·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-stat\"><strong>§307</strong></span>① 명예훼손죄에 적용 <span class=\"cs-fact-tag\">[위법성 조각]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 정통망법위반(명예훼손)·출판물 명예훼손에서 '정통망'·'출판물'·'비방목적' 등이 부정</div><div class=\"cs-li\" style=\"margin-left:16px\">② 허위사실 적시했으나 허위성 인식 없어 <span class=\"cs-stat\"><strong>§15</strong></span>①에 의해 <span class=\"cs-stat\"><strong>§307</strong></span>①이 적용되는 경우 → 최종적으로 <span class=\"cs-stat\"><strong>§307</strong></span>①이 구성요건으로 확정되면 <span class=\"cs-stat\"><strong>§310</strong></span> 적용 <span class=\"cs-fact-tag\">[각 구성요건 중 부정되는 것을 순차 검토해 적용법조 확정]</span><span class=\"cs-exam\">【변23·21·12】</span> <span class=\"cs-fact-tag\">[군형법 유추적용]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 군형법은 <span class=\"cs-stat\"><strong>§310</strong></span> 같은 규정을 두지 않음</div><div class=\"cs-li\" style=\"margin-left:16px\">② 그러나 입법자가 의도하지 않은 규율 공백에 대해 체계·입법의도·목적상 정당한 한도 내에서 유사 사안의 법규범 적용 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">③ <span class=\"cs-stat\"><strong>§310</strong></span>은 군형법 <span class=\"cs-stat\"><strong>§64</strong></span>③ 행위에 유추적용된다</div><div class=\"cs-h\">Ⅱ. 진실한 사실로서 오로지 공공의 이익에 관한 때</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>진실한 사실</strong> 개념: '진실한 사실' = 전체 취지상 중요 부분이 객관적 사실과 합치 → 세부 차이·다소 과장 표현 있어도 무방<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공공의 이익</strong> 판단기준 (判例) : 객관적으로 공익 관련 + 행위자도 주관적으로 공익 위해 적시한 것 주요 동기·목적이 공익이면 부수적 사익 목적·동기 있어도 <span class=\"cs-stat\"><strong>§310</strong></span> 적용<span class=\"cs-exam\">【변23·12】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 공공의 이익 = 국가·사회·일반 다수인 이익 + 특정 사회집단·구성원 전체 관심·이익 포함</div><div class=\"cs-li\" style=\"margin-left:16px\">② '사회 일반 일부 이익'만 관련해도 타인과 공동생활 관계 사항이면 공익성</div><div class=\"cs-li\" style=\"margin-left:16px\">③ '개인에 관한 사항'이라도 공익 관련·사회적 관심 획득(가능) 시 <span class=\"cs-stat\"><strong>§310</strong></span> 적용 배제 X 공적 인물·제도·정책에 한정 X '사인'도 관계 사회적 활동의 성질·사회적 영향 헤아려 공익 관련성 판단 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[징계절차 회부 단계 공개 X]</span> 공익성<span class=\"cs-x\"><strong>(X)</strong></span> — 징계혐의는 절차 거쳐 확정 → '회부'만 된 단계 공개로 명예훼손 시 피해 가볍지 않아 회사 운영 도모라는 공익으로 볼 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[종친회 회장 출마 반대 \"사기꾼\"]</span> <span class=\"cs-stat\"><strong>§310</strong></span> 위법성 조각<span class=\"cs-o\"><strong>(O)</strong></span> — <span class=\"cs-crime\">특경법위반(횡령)</span> 전과 있어 주요부분 객관적 사실 합치 · 회장 적격은 구성원 전체 관심·이익(공익성)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[총학생회장 임원진 음주운전 관행 페북 게시]</span> <span class=\"cs-stat\"><strong>§310</strong></span> 인정<span class=\"cs-o\"><strong>(O)</strong></span> — 중요부분 진실·주된 의도 공익</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>증명책임</strong> 인정자료:</div><div class=\"cs-li\" style=\"margin-left:16px\">① 진실·공익성은 행위자가 증명해야 하나</div><div class=\"cs-li\" style=\"margin-left:16px\">② 그 증명은 엄격한 증거에 의할 것은 아니다<span class=\"cs-exam\">【변21·16·12】</span></div><div class=\"cs-h\">Ⅲ. <span class=\"cs-stat\">제310조</span> 진실성에 대한 착오의 형법적 취급 (위전착 쟁점)<span class=\"cs-exam\">【변사16, 모사25·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-stat\"><strong>§307</strong></span>① 행위가 진실·공익이면 처벌 X(<span class=\"cs-stat\"><strong>§310</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《적시 사실이 허위임에도 진실로 오인한 경우 법적 효과 문제》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①위법성조각사유의 전제사실 착오설 (소극적구성요건표지이론·유추적용제한책임설·법효과제한책임설·엄격책임설)</div><div class=\"cs-li\" style=\"margin-left:16px\">②허용된 위험설(성실한 검토의무 이행 시 위법성 조각)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[위법성 조각]</span> 적시 사실이 공익 관련이면 진실 증명 없어도 진실로 믿었고 그렇게 믿을 만한 '상당한 이유' 있으면 <span class=\"cs-stat\"><strong>§310</strong></span>에 의해 '위법성' 없음<span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 진실성 착오 시 고의로 명예훼손 불법을 실현했으나 책임비난은 실질상 부주의에 있음 → 법효과제한책임설 타당</div></div>", ["§309", "§307", "§15", "§310", "§64", "제310조", "제307조"], 3, "gak_명예주거"], ["개인023", "모욕죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제311조(모욕)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">공연히 사람을 모욕한 자는 1년 이하의 징역이나 금고 또는 200만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 공연성 (전파가능성)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①<span class=\"cs-stat\"><strong>§311</strong></span>(모욕)은 '공연히'를 요건으로 함</div><div class=\"cs-li\" style=\"margin-left:16px\">②전파가능성 법리는 모욕죄에도 동일 적용<span class=\"cs-exam\">【변17·13】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①소수에게 발언해도 상대방이 불특정·다수인에게 전파할 가능성이 '객관적'으로 인정되면 공연성<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②특정 소수에게만 발언은 공연성 부정의 유력한 사정</div><div class=\"cs-li\" style=\"margin-left:16px\">③그 하에서 전파가능성은 검사의 엄격한 증명 必 공연성 인정 여부는 전파가능성 등 종합해 '객관적'으로 판단 발언 후 실제 전파 여부는 전파가능성 판단의 소극적 사정으로 고려 가능 전파가능성으로 공연성 인정되는 경우에도 미필적 고의 必 → 전파가능성 인식 전제로 위험 용인 내심의사 존재·증명 있어야 전파가능성 용인 여부는 행위 형태·상황 등 구체적 사정 기초로 일반인 평가 고려하며 '행위자 입장'에서 심리상태 추인 → 고의 인정에 신중</div><div class=\"cs-h\">Ⅱ. 모욕적 표현 – 구성요건</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>모욕적 표현</strong> 개념: 모욕죄는 '외부적 명예'(사회적 평가) 보호법익 '모욕' = 사실 적시 없이 사회적 평가를 저하시킬 추상적 판단·경멸적 감정 표현 판단기준 (判例) : 표현의 형식·내용이 모욕적·경멸적 인신공격이거나 인격권 침해면 의견표명의 한계 벗어나 허용 X 모욕 해당 여부는 상대방의 주관적 '명예감정' 침해 기준 X → 관계·경위·방법·상황 등 객관적 제반 사정에 비추어 '외부적 명예' 침해 표현인지 기준으로 엄격 판단 상대방을 불쾌하게 할 무례·예의에 벗어난 정도이거나 부정적·비판적 의견·감정을 나타내며 경미한 추상적 표현·욕설 사용 정도면 특별한 사정 없는 한 외부적 명예 침해로 볼 수 없어 모욕죄<span class=\"cs-x\"><strong>(X)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[112 늦게 도착 항의 \"아이 씨발!\" X]</span> 모욕죄<span class=\"cs-x\"><strong>(X)</strong></span> — 인격적 가치의 사회적 평가 저하 표현 아니면 다소 무례·저속해도</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>비언어적·시각적 수단</strong> 적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①시각적 수단만의 모욕도 피해·가벌성은 언어적 수단과 차이 없음</div><div class=\"cs-li\" style=\"margin-left:16px\">②수단·방법 제한 없어 비언어적·시각적 수단만으로도 사회적 평가 저하 추상적 판단·경멸적 감정 전달이면 모욕죄 성립 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[인터넷방송 '두꺼비' 합성]</span> 모욕<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[단순 얼굴 가림 용도 아님]</span> — 지속적으로 외모 비하·비방·조롱해온 점 등 고려 시 사회적 평가 저하 경멸적 감정 전달</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[단, 피해자 얼굴을 '개' 얼굴로 합성한 영상은 부정적 감정을 해학적으로 표현한 것에 불과·모욕 X]</span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>추상적 위험범</strong> 개념: 모욕죄는 추상적 판단·경멸적 감정을 공연히 표시함으로써 성립 → 외부적 명예가 현실적으로 침해되거나 구체적·현실적 침해 위험이 발생할 것 不要</div><div class=\"cs-h\">Ⅲ. 위법성조각 (형법 <span class=\"cs-stat\">제20조</span> 정당행위) – <span class=\"cs-stat\">제310조</span> 적용 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-stat\"><strong>§310</strong></span>은 <span class=\"cs-stat\"><strong>§307</strong></span>①에만 적용, 모욕죄엔 적용 X <span class=\"cs-fact-tag\">[모욕죄는 </span><span class=\"cs-stat\">§20</span><span class=\"cs-fact-tag\"> 정당행위로 판단]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 글이 모욕적 표현을 담은 판단·의견이라도 건전한 사회통념상 사회상규에 위배되지 않으면 <span class=\"cs-stat\"><strong>§20</strong></span> 정당행위로 위법성 조각 <span class=\"cs-fact-tag\">[부사관 단톡방 '또라이']</span> 인터넷 단문의 글이라도 의견을 강조·압축한 것으로 평가되고 지나치게 모욕·악의적이지 않으면 위법성 조각 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[자동차 기사 \"기레기\" 댓글]</span> <span class=\"cs-stat\"><strong>§20</strong></span> 위법성 조각<span class=\"cs-o\"><strong>(O)</strong></span> — '기레기'는 모욕적 표현이나, 객관적 타당성 있는 사실 전제로 의견의 타당함 강조 과정의 부분적 표현</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[방송 시청자 의견란 \"소중한 자식을 변명의 방패로\"]</span> 사회상규 위배<span class=\"cs-x\"><strong>(X)</strong></span> —</div><div class=\"cs-li\" style=\"margin-left:32px\">①모욕적 언사 O</div><div class=\"cs-li\" style=\"margin-left:32px\">②의견의 타당함 강조 과정의 부분적 표현</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">['어용'·'앞잡이' 현수막·피켓 장기 반복 게시]</span> 사회상규에 위배되지 않는 행위로 보기 어려움 (모욕 O)</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">['국민호텔녀']</span> 정당행위<span class=\"cs-x\"><strong>(X)</strong></span> (모욕 O) — 여성 연예인의 사회적 평가 저하 모멸적 표현·정당한 비판 범위 벗어남</div>", ["§311", "§310", "§307", "§20", "제311조", "제20조", "제310조"], 2, "gak_명예주거"], ["개인024", "업무방해죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 교실 창문에 얼굴 들이밀고 20분간 소란·수업 중단</strong></u> <span class=\"cs-exam\">【변사18】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">丙, 국립초등학교 딸 담임교사 A가 딸을 혼내는 것에 불만 → 도로에 인접한 교실에서 수업 중인 A를 보고 창문을 열어 교실 안으로 얼굴을 들이밀고 \"잘 사는 애들만 대접받는 더러운</div><div class=\"cs-li\" style=\"margin-left:0px\">세상\" 외침 → A의 제지에도 약 20분간 소란, A는 수업 중단. 丙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [건조물침입죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 신체 전부가 들어가야 기수인지 — 일부침입설/전부침입설, 판례 = 일부침입설. 보호법익이 사실상 주거의 평온 → 신체 일부라도 평온을 해하는 정도면 기수 → 일부침입설 타당, 일부침입의 고의로 침입해도 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">② 교실 안으로 얼굴을 들이밀어 사실상 평온 침해 → 건조물침입죄(<span class=\"cs-stat\"><strong>§319</strong></span>①) 기수(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [공무집행방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 창문 열고 큰 소리로 외친 것만으로는 공무원 A에 대한 폭행·협박(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙 = <span class=\"cs-crime\">공무집행방해죄</span>(<span class=\"cs-stat\"><strong>§136</strong></span>①)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [업무방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [담임교사 A]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원이 직무상 수행하는 공무 방해는 업무방해죄로 의율(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② A에 대한 업무방해죄(<span class=\"cs-stat\"><strong>§314</strong></span>①)(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [학생들]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 초등학생의 수업 듣기 = 권리 행사·의무 이행일 뿐 '직업 기타 사회생활상 지위에 기해 계속 종사하는 사무·사업'(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 학생들에 대한 업무방해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 丙 = 건조물침입죄 기수</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제314조(업무방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 제313조의 방법(허위의 사실을 유포하거나 기타 위계) 또는 위력으로써 사람의 업무를 방해한 자는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 업무의 개념</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>'타인'의 업무</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지방공사 사장 신규직원 채용 O]</span> 업무방해죄 객체인 타인의 업무<span class=\"cs-o\"><strong>(O)</strong></span> — 공사 기관으로서 공사 업무 집행 → 권한 귀속주체인 사장 본인에 대해서도<span class=\"cs-exam\">【변23·17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>업무</strong> 개념: '업무' = 직업·계속적으로 종사하는 사무·사업 → 경제적 활동뿐 아니라 사회생활상 지위에서 계속 행하는 일체의 사회적 활동 판단기준 (判例) : 일회적 사무라도 어느 정도 계속 행해지거나 계속적 본래 업무수행과 밀접불가분 관계면 업무<span class=\"cs-o\"><strong>(O)</strong></span> 회사 경영행위에는 목적사업 직접 수행뿐 아니라 확장·축소·전환·폐지 등 정당한 경영권 행사도 업무 포함<span class=\"cs-exam\">【변26】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[종중총회 진행 O]</span> 1회성이라도 계속성 있는 본래 업무수행 일환이면 업무<span class=\"cs-o\"><strong>(O)</strong></span> → 종중 정기총회 주재 회장의 의사진행업무<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[현수막 △]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①단순 의사표현 일환의 일회·일시적 현수막 설치는 업무 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②그러나 계속성 있는 본래 업무수행 일환·밀접불가분 관계면 업무 O <span class=\"cs-fact-tag\">[지주협의회 입장 홍보는 업무 X → 끈 절단해도 업무방해 X (재물손괴죄 성립)]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[이사회 이사 O, 감사 X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①주된 업무와 밀접불가분 부수적 업무도 포함</div><div class=\"cs-li\" style=\"margin-left:48px\">②이사회가 편의상 감사 등 의견 청취는 실질상 이사들의 심의·결의 업무 → 의견 진술한 감사의 업무 방해 X <span class=\"cs-fact-tag\">[이사의 심의·의결 업무 방해]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[수업듣기 X]</span> 초등학생 수업듣기는 권리 행사·의무 이행에 불과 → 업무 X <span class=\"cs-fact-tag\">[사립학교 교원 수업은 업무, 국공립학교 교원은 공무]</span><span class=\"cs-exam\">【변23·20】</span><span class=\"cs-exam\">【변사18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[주주 X]</span> 주주총회 의결권 행사는 주식 보유자 자격의 권리 행사 → 업무 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[공장이전 X]</span> 비닐가공공장 이전은 일시적 사무일 뿐 계속성 지닌 업무 아님 → 업무 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[자가용 운전 X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①개인적 일상생활 일환 사무는 업무 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②주부가 개인 용무로 자가용 운전은 개인생활상 행위 → 업무 X</div><div class=\"cs-li\" style=\"margin-left:48px\">③범퍼-손수레를 쇠사슬로 묶어도 업무방해 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[농성 X]</span> 백화점 입주상인이 영업 않고 점거농성하며 임의 전기시설 사용·화재위험 → 단전조치 시 보호받을 업무 부존재·안전관리 정당권한 행사 → 업무방해 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[강제집행과 조합업무 X]</span> 강제집행은 집행관 고유 직무·집행위임 조합의 업무 아님 → 방해해도 조합 업무 방해 X <span class=\"cs-fact-tag\">[집행관 폭행 시 </span><span class=\"cs-crime\">공무집행방해죄</span><span class=\"cs-fact-tag\">]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>공무</strong> 적용범위: <span class=\"cs-neg-tag\">[공무 X]</span> 형법이 업무방해죄와 별도로 공무집행방해죄를 둔 것은 공무는 폭행·협박·위계에 한해 처벌하겠다는 취지 → 공무원의 공무 방해는 업무방해죄로 의율 X<span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">【변사18, 모기19】</span> <span class=\"cs-fact-tag\">[공무직 근로자 O]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①공무원 아닌 자의 업무 방해는 업무방해죄 의율 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">②형법상 공무원 = 법령 근거로 국가·지자체·공법인 사무 종사, 노무가 단순 기계적·육체적인 것에 한정되지 않은 자 <span class=\"cs-fact-tag\">[수원시 공무직 근로자(노점상 단속 지원)는 공무원 아님 → 업무방해죄의 업무]</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[경찰청 민원실 면담 요구 욕설·행패 X]</span> 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[시청 브리핑룸 봉쇄로 시장 기자회견 저지 X]</span> 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>보호가치 있는 업무</strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①보호가치 여부는 '사실상 평온'하게 이루어져 사회적 활동 기반이 되는지로 결정</div><div class=\"cs-li\" style=\"margin-left:16px\">②타인의 위법한 침해로부터 보호가치 있으면 되고 기초 계약·행정행위가 반드시 적법할 필요 X 사무·활동 자체가 위법 정도가 중해 사회생활상 도저히 용인될 수 없는 반사회성 띠면 업무 X 개시·수행에 실체상·절차상 하자 있어도 반사회성에 이르거나 그와 동등 평가 받을 정도가 아니면 업무<span class=\"cs-o\"><strong>(O)</strong></span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[무단전차 O]</span> 임대인 승낙 없이 전차해도 불법침탈 아니고 평온하게 영업·점유 계속했으면 업무<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[불법점거 O]</span> 甲이 80명 용역직원과 함께 A측 경비원을 끌어내고 공사현장 점거 → 업무는 적법·유효할 필요 없고 위법한 침해로부터 보호가치 있으면 됨 → 업무방해죄 공동정범<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[특수건조물침입죄도 성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[의료기관]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①<span class=\"cs-neg-tag\">[개설·운영 X]</span> 의료인 아닌 자의 의료기관 개설·운영은 업무 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②<span class=\"cs-fact-tag\">[진료행위 O]</span> 무자격 개설 의료기관 고용 의료인의 진료행위가 당연히 반사회성 띠는 것은 아님<span class=\"cs-exam\">【변26·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[무자격중개 X]</span> 공인중개사 아닌 자의 중개업은 법 금지 범죄 → 업무 X<span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[성매매 X]</span> 성매매알선은 업무 X<span class=\"cs-exam\">【변14·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[직무집행정지가처분 X]</span> 가처분으로 직무집행 정지된 자가 결정에 반해 직무 수행 → 반사회성까지는 아니어도 법적 보호 측면에서 동등 평가 → 업무 X<span class=\"cs-exam\">【변23·17】</span></div><div class=\"cs-h\">Ⅱ. 위력</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>위력</strong> 개념: '위력' = 자유의사를 제압·혼란케 할 일체의 세력, 유·무형 불문 폭행·협박은 물론 사회적·경제적·정치적 지위·권세에 의한 압박 포함<span class=\"cs-exam\">【변24】</span> 유형력 행사에 국한 X 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①위력은 자유의사 제압에 충분한 세력에 이르러야</div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 현실적으로 자유의사가 제압되어야 하는 것은 아님<span class=\"cs-exam\">【변24】</span> 위력 해당 여부는 일시·장소·동기·목적·인원수·태양·업무 종류·피해자 지위 등 고려해 객관적 판단, 피해자 의사로 결정 X 공적 관심사 표현의 자유 제한은 사적 영역보다 더 신중해야</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>제3자에 대한 위력의 행사</strong> 적용범위: 위력은 원칙적으로 피해자에게 행사돼야 → 상대방이 제3자인 경우 피해자 자유의사 제압 가능성이 직접 발생해 피해자에 대한 위력과 동일시할 특별한 사정 없으면 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>정당한 권한의 행사</strong> 판단기준 (判例) : 정당한 권한 행사로 볼 수 있으면 내용·수단이 사회통념상 허용 못 할 특별한 사정 없는 한 '위력'<span class=\"cs-x\"><strong>(X)</strong></span> 제3자로 하여금 조치 취하게 해 업무 곤란·위험 야기해도, 행위자가 제3자 의사결정 관여 권한·업무상 지시 지위 있으면 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[회계자료열람권 지부장이 열람 요구 중 언성 높인 정도 X]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>구체적 판례</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대부업체 수백 회 전화공세 O]</span> 업무방해죄<span class=\"cs-o\"><strong>(O)</strong></span> — 소액 지연이자로 법적 조치 거론하며 채무자에 수백 회 전화 → 사회통념 허용한도 벗어난 채권추심<span class=\"cs-exam\">【변18·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의자 임의 폐원신고 O]</span> 위계 아니라 '위력'으로 업무방해 — 명의자 지위 이용해 승낙 없이 폐원신고</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[파업]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①근로자는 단결권·단체행동권 보유(헌<span class=\"cs-stat\"><strong>§33</strong></span>①) → 파업이 언제나 업무방해죄는 아님</div><div class=\"cs-li\" style=\"margin-left:48px\">②사용자가 예측할 수 없는 시기에 전격적으로 이루어져 사업운영에 심대한 혼란·손해 초래해 사업계속 자유의사가 제압·혼란될 경우에만 위력 → 업무방해죄<span class=\"cs-exam\">【변13】</span> 쟁의행위가 업무방해죄 해당 시 제3자가 정을 알면서 실행 용이하게 하면 업무방해방조죄 성립 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[차량 앞 가로막기 O]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①차량 앞을 가로막은 것은 '위력' O</div><div class=\"cs-li\" style=\"margin-left:48px\">②출입 장애 생긴 이상 업무방해 위험 발생</div><div class=\"cs-li\" style=\"margin-left:48px\">③경찰관이 의자째 옮겨도 위력·위험 발생 부정 X 정치적 집회·행위가 표현의 자유·행동의 자유로 보호 가능성 있어도 법질서상 용인 못 할 정도로 사회적 상당성 결여 시 위력 개념에 포섭 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[교장 면접점수 상향 발언 X]</span> 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span> — 다소 과도한 표현 사용해도 면접위원 자유의사 제압·사회통념상 허용 못 할 위력 행사로 보기 어려움</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[마트노조 현장점검 따라다니며 피켓 X]</span> 자유의사 제압 위력으로 단정 어려움 — 1~2m 거리 유지·물리적 저지·욕설·협박 없이 약 30분 점검 계속</div><div class=\"cs-h\">Ⅲ. 위계</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>사람의 오인, 착각 또는 부지</strong> 개념: '위계' = 행위 목적 달성 위해 상대방에게 오인·착각·부지를 일으켜 이용하는 것 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①정보처리장치에 정보 입력도 담당자의 오인·착각·부지 일으킬 목적이면 위계 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 오인·착각·부지 일으킨 상대방이 없으면 위계 X 컴퓨터 정보 입력이 담당자의 오인·착각·부지 목적이면, 담당자를 직접 대상으로 한 것이 아니어도 위계 아니라 할 수 없음<span class=\"cs-exam\">【변26】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[지방공사 사장 시험성적 조작 X]</span> 위계 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span> — 담당자들과 공모·양해하에 성적 조작 → 법인 공사에 오인·착각·부지 일으킨 것 아님<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">['쪼개기 송금' X]</span> 위계<span class=\"cs-x\"><strong>(X)</strong></span> — 1일 100만원 한도 회피 위해 타인 명의 입력·분할 입금 → 직원 관여·오인 없고 적발 시스템도 없음</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>업무담당자의 심사</strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①신청 수용 여부를 결정하는 업무는 신청사유가 사실과 부합하지 않을 수 있음을 전제로 심사 → 담당자가 충분히 확인 않고 허위 신청사유·소명자료를 가볍게 믿고 수용하면 불충분한 심사에 기인 → 위계 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 허위 주장·허위 소명자료 제출에 담당자가 나름 충분히 심사했으나 허위를 발견 못 해 수리하면 위계로 위험 발생 → 위계 업무방해죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모사25, 모기25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[계좌개설 허위 기재 X]</span> 위계 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span> — 접근매체 양도 의사로 목적·양도의사 허위 기재했으나 담당자가 답변만 믿고 증빙 요구 등 추가 확인 없이 개설 → 불충분한 심사 기인<span class=\"cs-exam\">【모사25, 모기25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>구체적 판례</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대학원 시험문제 유출·베껴쓰기 O]</span> 위계로 입시감독 업무방해 — 출제 문제를 알려주어 답안 베껴 정 모르는 감독관에 제출<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[수협 점수조작 면접 O]</span> 조작에 공모·양해 없는 면접위원의 면접업무 방해됨 — 조작으로 필기 합격시켜 면접 응시케 함<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[허위 이력서·서류로 채용 합격 O]</span> 위계로 채용업무 방해 — 타인 명의 허위 학력·경력 이력서·서류 제출로 합격<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[채용공고 자격요건 무단 변경 X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①공고가 인사규정 부합 여부는 심사·면접위원 업무와 무관·오인 X(주위적 무죄)</div><div class=\"cs-li\" style=\"margin-left:48px\">②대표이사는 인사담당자 의사결정 관여 권한 있어 위력·위계 업무방해 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[면접 종료 후 최종합격자 영향력 X]</span> 면접위원 A가 채점표 제출·이탈해 면접업무 종료 후 남은 위원 설득해 합격자 결정 → 이미 면접 마친 A에게 오인·착각·부지 일으킨 것 아님</div><div class=\"cs-h\">Ⅳ. 허위사실 유포</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '허위사실 유포' = 객관적으로 진실과 부합하지 않는 '사실' 유포, 단순 의견·가치판단은 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 허위사실은 기본적 사실이 거짓이어야 하는 것 아니고 기본 사실은 진실이라도 거짓이 덧붙여져 업무방해 위험 있으면 해당 중요부분이 객관적 사실 합치·세부 약간 차이·다소 과장 정도로 업무방해 위험 없으면 허위사실 X 의견표현과 사실 적시 혼재 시 '전체적으로 보아' 허위사실 유포 업무방해인지 판단, 분리 판단 X</div><div class=\"cs-h\">Ⅴ. 추상적 위험범</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span> 업무방해 결과 실제 발생 요하지 않고 결과 초래 '위험' 발생하면 충분 단 결과발생 염려 없으면 불성립<span class=\"cs-exam\">【변13】</span> 그 위험 발생이 위계·위력으로 '인한' 것이어야 업무수행 자체 아니라 업무의 적정성·공정성이 방해된 경우에도 성립<span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대체도로 이용 가능 X]</span> 업무방해죄<span class=\"cs-o\"><strong>(X)</strong></span> — 도로폐쇄에도 대체도로로 종전과 같이 운행 가능 → 결과발생 염려 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[문제 유출 후 미제출 X]</span> 업무방해죄<span class=\"cs-o\"><strong>(X)</strong></span> — 출제위원이 문제를 제출 전 유출해도 준비단계에 불과, 이후 시험실시자에 미제출이면 추상적 위험조차 없음<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[논문 예심자료 제출 X]</span> 지도교수 수정·보완 거친 예심자료 제출로 대학원장에 오인·착각·부지 일으키거나 위험 발생했다 단정 어려움</div><div class=\"cs-h\">Ⅵ. 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 고의는 업무방해 목적·계획적 의도 요하지 않고 타인 업무 방해 가능성·위험에 대한 인식·예견으로 충분 확정적·불확정적(미필적 고의) 불문<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅶ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">허위사실 유포 1개 행위가 허위사실 유포 업무방해죄와 허위사실적시 명예훼손죄 구성 시 상상적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">폭행이 동일 피해자 업무방해의 수단이 되어도 '불가벌적 수반행위'로 흡수관계 X <span class=\"cs-fact-tag\">[상상적 경합]</span><span class=\"cs-exam\">【변26·25·20·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">업무방해 '과정'의 재물손괴·협박이 경미하지 않으면 각 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대출사기]</span> 허위 임차인 명의 전세보증금 대출 과정에서 허위 서류·정보·외관으로 위계 업무방해 +<span> </span>대출금 편취 → <span class=\"cs-crime\">사기죄</span>와 위계 업무방해죄 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[신약개발 임상시험 사기]</span> 임상시험 대금 편취 <span class=\"cs-crime\">특경법위반(사기)죄</span>와 위계로 신약 개발업무 방해한 업무방해죄는 실체적 경합</div><div class=\"cs-h\">Ⅷ. 정당행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[시장번영회 단전조치]</span> <span class=\"cs-stat\"><strong>§20</strong></span> 정당행위 → 업무방해죄<span class=\"cs-o\"><strong>(X)</strong></span> — 관리규정 위반 점포주에 회원 동의 얻어 시행 중인 규정에 따라 단전<span class=\"cs-exam\">【변13】</span></div>", ["§319", "§136", "§314", "§33", "§20", "제314조", "제313조"], 3, "gak_명예주거"], ["개인025", "컴퓨터등장애업무방해죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제314조(업무방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">② 컴퓨터등 정보처리장치 또는 전자기록등 특수매체기록을 손괴하거나 정보처리장치에 허위의 정보 또는 부정한 명령을 입력하거나 기타 방법으로 정보처리에 장애를 발생하게 하여 사람의 업무를 방해한 자도 제1항의 형과 같다.</div></div><div class=\"cs-h\">Ⅰ. 행위 – 손괴, 허위의 정보 또는 부정한 명령 입력, 기타 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[관리자 ID·PW 무단 변경 O]</span> 컴퓨터등장애업무방해죄<span class=\"cs-o\"><strong>(O)</strong></span> — 권한 없는 자가 관리자 아이디·비밀번호를 무단 변경 → '부정한 명령 입력'으로 정당한 접속 불가케 함 → 정보처리 장애 현실 발생·업무방해 위험</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[비밀번호 설정+하드 분리 O]</span> <span class=\"cs-stat\"><strong>§314</strong></span>② 성립 — 방해 의도로 함부로 비밀번호 '설정'은 '허위정보·부정명령 입력', 하드디스크 분리·보관은 '손괴'<span class=\"cs-exam\">【변23·22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[비밀번호 미인계 X]</span> <span class=\"cs-stat\"><strong>§314</strong></span>② '기타방법' 업무방해죄<span class=\"cs-x\"><strong>(X)</strong></span> — 시스템관리자가 퇴직하며 후임자에게 비밀번호를 알려주지 않은 것만으로는 정보처리장치 작동에 직접 영향·기능 저해 X</div><div class=\"cs-h\">Ⅱ. 정보처리에 장애를 발생하게 하여 사람의 업무를 방해</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건:</div><div class=\"cs-li\" style=\"margin-left:16px\">①정보처리장치가 사용목적 부합 기능 못 하거나 다른 기능을 하는 등 '정보처리 장애'가 '현실적으로 발생'해야</div><div class=\"cs-li\" style=\"margin-left:16px\">②장애로 '업무방해 위험' 발생한 이상 결과 실제 미발생해도 성립<span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[허위 클릭정보 통계 반영 O]</span> 컴퓨터등장애업무방해죄<span class=\"cs-o\"><strong>(O)</strong></span> — 통계집계시스템 서버에 허위 클릭정보 전송·통계 반영으로 정보처리 장애 현실 발생 → 검색순위 변동 실제 초래 안 해도<span class=\"cs-exam\">【변16】</span></div>", ["§314", "제314조"], 2, "gak_명예주거"], ["개인026", "신용훼손죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제313조(신용훼손)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">허위의 사실을 유포하거나 기타 위계로써 사람의 신용을 훼손한 자는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[허위사실 유포]</span> '허위사실 유포' = 진실과 부합하지 않는 과거·현재 사실 유포 미래 사실도 입증 가능하면 포함 <span class=\"cs-fact-tag\">[위계]</span> '위계' = 행위목적 달성 위해 상대방에게 오인·착각·부지 일으켜 이용 <span class=\"cs-fact-tag\">[신용]</span> 신용 = 경제적 신용(지급능력·지급의사에 대한 사회적 신뢰) <span class=\"cs-fact-tag\">[추상적 위험범]</span> 신용을 저하시킬 '염려 있는 상태' 발생 시 성립 <span class=\"cs-fact-tag\">[고의]</span> 확정적 고의 不要 → 허위사실 유포·위계 사용 및 신용 저하 염려 발생에 대한 미필적 인식으로 족</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[甲이 자기 A퀵서비스 배달내역을 B퀵서비스 명의 영수증에 기입해 불만을 B에게 떠넘김]</span> 신용훼손죄<span class=\"cs-o\"><strong>(X)</strong></span> — 불친절·지연은 지급능력·지급의사 신뢰 저해 아님 <span class=\"cs-fact-tag\">[주위적 신용훼손죄 무죄, 예비적 허위사실 유포 업무방해죄 유죄]</span><span class=\"cs-exam\">【모기24】</span></div>", ["제313조"], 1, "gak_명예주거"], ["개인027", "경매·입찰방해죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제315조(경매, 입찰의 방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">위계 또는 위력 기타 방법으로 경매 또는 입찰의 공정을 해한 자는 2년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 경매방해죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span> 경매의 공정을 해하면 성립하는 추상적 위험범 → 결과의 불공정이 현실화될 것 不要 <span class=\"cs-fact-tag\">[거동범]</span><span class=\"cs-fact-tag\">[입찰방해죄 동일]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : '경매 공정을 해하는 행위' = 공정한 자유경쟁을 방해할 염려 있는 상태 발생 → 가격 결정뿐 아니라 적법·공정한 경쟁방법 자체를 해하는 행위 포함 법률적으로 경매결과에 영향 미칠 행위뿐 아니라 경매 참가하려는 자의 '의사결정에 사실상 영향' 미칠 행위도 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[허위 임차권 권리신고·배당요구]</span> 참가자 의사결정에 사실상 영향 줄 사정에 해당<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[선순위 근저당권 있어 허위 임차권으로 대항 못 해도 동일]</span></div><div class=\"cs-h\">Ⅱ. 입찰방해죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '입찰' = 공정 자유경쟁 통한 적정 가격형성 목적의 '입찰절차' → '임의 선택'에 따라 진행하는 계약체결 과정은 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : '입찰 공정을 해하는 행위' = 공정 자유경쟁 방해 염려 상태 발생 → 적정 가격형성에 부당한 영향뿐 아니라 적법·공정 경쟁방법·경쟁구도 형성 저해 행위도 포함 전원 담합 不要 → 일부 참가자 사이 담합이라도 공정을 해하면 입찰방해죄 성립</div>", ["제315조"], 1, "gak_명예주거"], ["개인028", "비밀침해죄, 전자기록내용탐지죄, 업무상비밀누설죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제316조(비밀침해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 봉함 기타 비밀장치한 사람의 편지, 문서 또는 도화를 개봉한 자는 3년 이하의 징역이나 금고 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 봉함 기타 비밀장치한 사람의 편지, 문서, 도화 또는 전자기록등 특수매체기록을 기술적 수단을 이용하여 그 내용을 알아낸 자도 제1항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제317조(업무상비밀누설)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 의사, 한의사, 치과의사, 약제사, 약종상, 조산사, 변호사, 변리사, 공인회계사, 공증인, 대서업자나 그 직무상 보조자 또는 차등의 직에 있던 자가 그 직무처리중 지득한 타인의 비밀을 누설한 때에는 3년 이하의 징역이나 금고, 10년 이하의 자격정지 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제318조(고소)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">본장의 죄는 고소가 있어야 공소를 제기할 수 있다.</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 비밀침해죄·전자기록내용탐지죄<span class=\"cs-exam\">【변기26】</span>·업무상비밀누설죄는 절대적 친고죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 전자기록 = 독립적으로 쓰이는 것 아니라 개인·법인이 정보 생성·처리·저장·출력 목적으로 구축·운영하는 시스템에서 예정된 증명적 기능 수행하는 것 포함 아이디 등은 전자방식으로 노트북에 저장된 기록 → <span class=\"cs-stat\"><strong>§316</strong></span>② '전자기록등 특수매체기록' 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[봉함·비밀장치 요건]</span> <span class=\"cs-stat\"><strong>§316</strong></span>② 전자기록등내용탐지죄는 '봉함 기타 비밀장치'된 것을 기술적 수단으로 알아낸 자 처벌 → 비밀장치 없는 것은 기술적 수단으로 알아내도 불성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">['키로그'(spytector) 몰래 설치]</span> 전자기록등내용탐지죄<span class=\"cs-o\"><strong>(X)</strong></span> —</div><div class=\"cs-li\" style=\"margin-left:32px\">①아이디·비밀번호는 전자기록 O이나</div><div class=\"cs-li\" style=\"margin-left:32px\">②그 아이디 등·텍스트 파일에 봉함·비밀장치 없음(노트북 자체 보안설정 없음)<span class=\"cs-exam\">【변기26】</span></div>", ["§316", "제316조", "제317조", "제318조"], 1, "gak_명예주거"], ["개인029", "주거침입죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제319조(주거침입, 퇴거불응)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람의 주거, 관리하는 건조물, 선박이나 항공기 또는 점유하는 방실에 침입한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 전항의 장소에서 퇴거요구를 받고 응하지 아니한 자도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제320조(특수주거침입)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 전조의 죄를 범한 때에는 5년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제322조(미수범)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">본장의 미수범은 처벌한다.</div></div><div class=\"cs-h\">Ⅰ. 주체 (<span class=\"cs-stat\">§319</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[소유자O]</span> 타인이 점유·관리하는 가옥의 소유자도 주거침입죄 주체<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[임대차 종료 후 임차인 계속점유]</span> 소유자가 무단으로 들어감 → 주거침입죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[소유권 분쟁 계속]</span> 소유 주장 피고인 vs 점유·관리 피해자 → 피해자의 추정적 승낙·사회상규 위배X로 볼 수 없음</div><div class=\"cs-h\">Ⅱ. 주거 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[위요지O]</span> '건조물'은 건조물 자체 + 부속 위요지 포함<span class=\"cs-exam\">【변12】</span> 위요지 = 건조물 인접 주변토지로서 외부경계에 담 등 설치되어 건조물 이용에 제공 +<span> </span>외부인 함부로 출입불가가 객관적으로 명확 인접 부속토지라도 구획·통제 없어 통상 보행으로 경계 쉽게 넘으면 객체 X<span class=\"cs-exam\">【변24·22】</span> <span class=\"cs-fact-tag\">[공용부분O]</span> 다세대·아파트 등 공동주택 내부 엘리베이터·공용계단·복도도 사실상 주거평온 보호필요 → 객체 '주거'<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강간 후 통로에서 방안 엿봄]</span> 대문 몰래 열고 들어와 담장-방 사이 좁은 통로 창문으로 엿봄 → 주거침입죄<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[위요지]</span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-h\">Ⅲ. 침입</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>침입</strong> 개념: <span class=\"cs-fact-tag\">[사실상 주거의 평온]</span> 보호법익 = 사실상 주거의 평온 점유할 법적권한 없어도 사실상 권한 있는 거주자의 사실적 지배·관리관계가 평온히 유지되는 상태(사실적 성질) <span class=\"cs-fact-tag\">[침입]</span> 사실상 평온상태를 해치는 행위태양으로 주거에 들어가는 것 → 출입 당시 객관적·외형적 행위태양 기준 판단이 원칙<span class=\"cs-exam\">【변26】</span> 판단기준 (判例) : 주거에 들어감이 거주자 의사에 반한다는 '주관적 사정'만으로는 침입 X 의사에 반하는지는 평온상태 해치는 행위태양 평가 시 고려요소 중 하나일 뿐 주된 평가요소 X 야간건조물침입절도죄의 건조물침입 판단에도 위 법리 적용 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[퇴사 후 임시출입증 감사실 출입]</span> 방실침입죄<span class=\"cs-o\"><strong>(O)</strong></span> — 퇴사 30일 후 승낙 없이 하드디스크 가지러 06:48경 임시출입증 받아 감사실 출입<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[입주자대표회의 주차장 출입금지]</span> 건조물침입죄<span class=\"cs-o\"><strong>(O)</strong></span> — 외부인(세차업체)이 결정에 반해 출입 → 구체적 제지 없었어도 관리권자 의사에 반함</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>관리자의 건조물 관리 권한</strong> 판단기준 (判例) : 건조물침입죄 보호법익 = 관리하는 건조물의 사실상 평온 → 관리자의 법률상 정당권한 有無는 성립 불좌우 사실상 점유·관리하면 정당권원 없는 사법상 불법점유여도 적법절차로 점유 풀지 않는 한 사실상 평온 보호 → 사법상 권리자라도 정당절차 없이 침입하면 건조물침입죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[매매해제·강제집행 후 매도인 출입]</span> 주거침입죄<span class=\"cs-x\"><strong>(X)</strong></span> — 명도받아 점유하던 매수인이 계약해제·중도금반환 승소판결로 강제집행 착수 후, 매도인이 매수인이 잠근 출입문 열고 들어감 → 매수인 권리포기로 알 수 있고 주거 평온상태 소멸</div><div class=\"cs-h\">Ⅳ. 주거침입죄의 착수 및 기수 (<span class=\"cs-stat\">§322</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수시기</strong> 개념: 실행착수 = 구성요건 일부 실현행위까지 요구 X but 침입 위한 구체적 행위(문 시정장치 부수기·문 열기 등) 개시로 범죄실현의 현실적 위험성 포함 행위 개시 要<span class=\"cs-exam\">【모사24】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[출입문 당겨봄]</span> 열려있으면 들어가겠다는 의사로 출입문 당겨봄 → 착수<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[초인종]</span> 사람 있는지 확인 위해 초인종 누른 행위만으로는 착수<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수시기</strong> <span class=\"cs-issue\">《신체 전부가 들어가야 기수인지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①일부침입설(신체 일부라도 사실상 평온 해하면 기수)</div><div class=\"cs-li\" style=\"margin-left:16px\">②전부침입설(<span class=\"cs-stat\"><strong>§322</strong></span> 미수처벌 규정 있으므로 전부 들어가야 기수·일부는 미수)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[일부침입설]</span> 신체 극히 일부만 들어가 사실상 평온 해하는 정도 아니면 미수, 신체 일부만 들어가도 사실상 평온 해하면 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 보호법익이 사실상 주거평온 → 신체 일부라도 평온 해하는 정도면 기수 → 일부침입설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>확정판결</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[무단침입 유죄확정 후 계속거주]</span> 확정 이후 퇴거 않고 계속 거주 → 확정 이후 행위는 별도 주거침입죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅴ. 주거침입죄의 고의</div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>: <span class=\"cs-fact-tag\">[일부침입설]</span> 범의는 신체 전부가 들어간다는 인식 要X, 신체 일부라도 들어간다는 인식 있으면 족 야간에 창문 열고 얼굴 들이미는 행위 → 신체 일부가 들어간다는 인식하에 했으면 범의<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[전부침입설]</span> 신체 일부만 들어간다는 의사면 미수의 고의에 불과 → 불벌</div></div><div class=\"cs-h\">Ⅵ. 공동거주자의 출입</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공동거주자·관리자</strong> 적용범위: 객체는 '타인' 거주 주거 → 행위자가 단독 또는 공동으로 거주·관리·점유하는 주거에 임의 출입해도 주거침입죄 X 단, 공동거주자가 공동생활관계 이탈·사실상 지배·관리 상실 등 특별사정 있으면 성립 가능<span class=\"cs-exam\">【변24】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[스마트키 야간출입 절취]</span> 제한 없이 쓰던 스마트키로 야간에 들어가 절취 → 야간건조물침입절도<span class=\"cs-o\"><strong>(X)</strong></span>, 절도죄만 <span class=\"cs-fact-tag\">[건조물침입X]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>내부에 있는 공동거주자의 의사에 반한 출입 (별거중 걸쇠 손괴)<span class=\"cs-exam\">【모기24·22】</span></strong> 판단기준 (判例) : 공동거주자가 누리는 사실상 평온 법익은 상호관계로 일정부분 제약, 상호 용인하에 공동주거관계 형성 → 상호간 특별사정 없는 한 다른 공동거주자의 자유출입·이용 금지 불가 공동거주자 1인이 정당이유 없이 다른 공동거주자 출입 금지한 경우, 다른 공동거주자가 대항해 들어가도 공동주거 취지에 맞춘 이용방편일 뿐 법익침해행위 X → 주거침입죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변25】</span> 출입 위해 잠금장치 손괴 등 물리력 행사로 평온 해쳐도 별도 규정 처벌 별론, 주거침입죄 X <span class=\"cs-fact-tag\">[공동소유도 타인의 소유 → 출입문 걸쇠손괴 </span><span class=\"cs-crime\">폭처법위반(공동재물손괴등)</span><span class=\"cs-fact-tag\"> 유죄]</span> 공동거주자 승낙받아 함께 들어간 외부인의 출입·이용이 전체적으로 승낙한 공동거주자의 통상적 공동생활 출입·이용의 일환·수반행위로 평가되면, 이를 금지하는 다른 공동거주자 평온 해쳤어도 외부인도 주거침입죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[처와 불화로 나온 후 '부모'와 함께 아파트 출입]</span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅶ. 공동거주자 아닌 자의 출입</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>현재하는 거주자의 승낙을 받은 경우</strong> 판단기준 (判例) : 외부인이 현재하는 거주자로부터 현실적 승낙받아 통상적 출입방법으로 들어감 → 부재중 다른 거주자 추정적 의사에 반해도 침입<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[혼외성관계]</span><span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">【모사22】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[TV 설치 요청]</span> 연인 피해자 요청으로 통상적 출입방법으로 안방 출입 → 범죄목적(CCTV 부착) 숨겨도 주거침입죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[임차 카페 열쇠교부 후 집기철거]</span> 관리자 승낙 아래 통상적 출입방법으로 점포 출입 → 침입<span class=\"cs-x\"><strong>(X)</strong></span> 집기 철거목적 알았으면 승낙 안했을 사정 있어도 평온 해치는 태양으로 평가X <span class=\"cs-fact-tag\">[재물손괴 유죄]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>'일반인의 출입이 허용된 장소' (음식점 도청, 시청사 로비)</strong> 판단기준 (判例) : 일반인 출입허용 영업점에 영업주 승낙받아 통상적 출입방법으로 들어감 → 범죄목적이거나 알았으면 승낙 안했을 사정 있어도 평온 해치는 것 아님 → 침입<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사22】</span> 야간건조물침입절도죄 건조물침입 판단에도 동일 법리 <span class=\"cs-fact-tag\">[야간 편의점 절취 → 야간주거침입절도 X, 절도죄만]</span> <span class=\"cs-exam\">[모사24, 모기23]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[식당 녹음·녹화장치]</span> 주인 승낙받아 장치 설치·회수 목적 출입 → 건조물침입죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[통비법위반O]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[PC방 몰카]</span> 통상적 출입방법으로 들어감 → 여성 몸 훔쳐볼 목적이어서 알았으면 승낙 안했을 사정 있어도 건조물침입죄 단정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[시청사 로비·마트]</span> 개방된 건조물에 출입제한·제지 없는 상태서 통상적 방법 출입 → 침입<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[안산시의회 청사]</span> 방호요원 출입제지에도 밀치며 들어감 → 관리자 명시적 의사에 반해 물리력 행사, 객관적·외형적 행위태양상 평온상태 침해<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>'통제 장소'에 관리자의 '현실적 승낙'을 받은 경우</strong> 판단기준 (判例) : 출입 통제되는 건조물에 관리자 승낙받아 통상적 출입방법 출입 → 승낙에 기망·착오 등 하자 있어도 <span class=\"cs-stat\"><strong>§319</strong></span>① 건조물침입죄<span class=\"cs-x\"><strong>(X)</strong></span> 현실적 승낙 있었으므로 가정적·추정적 의사 고려X, 동기 착오는 승낙 유효성에 영향X → 실제목적 알았으면 승낙 안했을 사정 있어도 성립X 객관적·외형적 행위태양상 평온 해치는 모습으로 평가X <span class=\"cs-fact-tag\">[교도소 안경·명함 녹화]</span><span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>사적주거, 통제장소에 몰래 들어간 경우</strong> 판단기준 (判例) : 일반개방 장소라도 관리자가 필요에 따라 출입 제한 가능 사생활보호 필요성 큰 사적주거·출입 엄격통제 건조물에 승낙 없이 몰래 들어가거나, 출입금지·제한에도 무시하고 출입 → 평온상태 침해로 침입<span class=\"cs-o\"><strong>(O)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[접근금지가처분 위반 변호사사무실]</span> 간접강제결정(100m 이내 접근금지) 부작위의무 위반해 출입 → 명시적 의사 반함+객관적·외형적 행위태양상 평온 침해 → 건조물침입죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">5. <strong>아파트 공용부분 및 상가</strong> 가. <strong>아파트 등 공용부분</strong> 판단기준 (判例) : 공동현관 출입도, 거주자·관리자만 아는 비밀번호 입력해야 출입 가능하거나 외부인 통제·관리 표시·경비원 존재 등 무단출입 통제·관리 사정이 있고, 외부인이 이를 인식하고도 승낙 없이 정당이유 없이 비밀번호 임의입력 등으로 몰래 출입한 경우 등, 목적·경위·태양·시간 종합해 평온상태 해치는 태양이면 주거침입<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[주거침입강간 등]</span><span class=\"cs-exam\">【모사23】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[CCTV 공동현관 추행목적]</span> 늦은 밤 피해자 뒤쫓아 공동현관 출입, 계단·엘리베이터 앞까지 들어감 → 거주자·관리자 모르게 들어간다는 의도, 추정적 승낙 없음 → 주거침입강간죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모사23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[빌라 CCTV·주차금지 문구]</span> 공동현관·공용계단·세대현관 앞은 확장된 주거공간, CCTV 2대+'CCTV 작동중'·'외부차량 주차금지' 문구로 무단출입 통제·관리 취지 대외표시 → 평온상태 해치는 태양으로 출입<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[소규모 다세대 5층 공용계단 본드흡입]</span> 공동현관·공용계단·세대현관 앞 공간은 전유부분에 필수부속, 공용부분 좁고 밀착, 엘리베이터 등 별도출입 없음, 오로지 주거용도 외관 분명 → 주거의 사실상 평온 해치는 주거침입<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[1층 공동현관에 잠금장치·CCTV 없어 무단출입 통제·관리 안했어도 5층 공용계단은 '사람의 주거' 객체 O]</span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">나. <strong>상가 공용부분</strong> 판단기준 (判例) : 일반인 출입허용 상가 등 영업장소에 영업주 승낙받아 통상적 출입방법 출입 → 특별사정 없는 한 건조물침입<span class=\"cs-x\"><strong>(X)</strong></span> 범죄목적이거나 알았으면 승낙 안했을 사정 있어도 객관적·외형적 행위태양상 평온 해치는 방법으로 평가X → 침입<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[주거침입X, 형법상 강간죄만]</span><span class=\"cs-exam\">【모사23】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[야간 상가 1층 통상출입]</span> 야간에 일반인 출입허용 상가 1층 출입문으로 통상적 출입 → 평온상태 침해 사정 없음. CCTV는 일반관리용, 외부인 통제·감시용으로 단정X<span class=\"cs-exam\">【모사23】</span></div>", ["§319", "§322", "제319조", "제320조", "제322조"], 3, "gak_명예주거"], ["개인030", "퇴거불응죄", "<div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 진정부작위범은 거동범이라 미수 인정 X가 일반적 견해이나, 진정부작위범인 퇴거불응죄에는 미수범 처벌규정<span class=\"cs-o\"><strong>(O)</strong></span> 퇴거 = 행위자 신체가 주거에서 나감</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[숙박계약 종료]</span> 퇴거불응죄 보호법익 = 사실상 주거평온 → 거주·관리·점유할 법률상 정당권한 없어도 거주자·관리자·점유자 될 수 있음 숙박계약 종료로 고객이 퇴거요구받은 경우도 원칙 동일 고객의 개별객실 점유가 오히려 숙박업자의 전체 숙박업소 사실상 평온을 침해하는 특별사정 있으면, 적법 퇴거요구에 불응 시 퇴거불응죄 성립 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[가재도구 남겨둠]</span> 정당 퇴거요구받고 나가면서 가재도구 등 남겨둬도 퇴거불응죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22】</span></div>", [], 1, "gak_명예주거"], ["개인031", "금제품의 재물성", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 밀수품을 훔쳐 팔기로 마음먹고 미리 알던 비밀번호로 주간에 밀수업자 A의 집에</div><div class=\"cs-li\" style=\"margin-left:0px\">몰래 들어가 밀수입 보석을 가지고 나옴. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [주거침입죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 침입 = 주거의 사실상 평온상태를 해치는 행위태양으로 들어가는 것</div><div class=\"cs-li\" style=\"margin-left:0px\">② 알던 비밀번호로 몰래 들어감 → 주거침입죄(<span class=\"cs-stat\"><strong>제319조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① A가 밀수한 보석 = 상대적 금제품. 금제품 절취 시 절도죄의 재물이 될 수 있는지 — 위 학설 및 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲 = 절도죄(<span class=\"cs-stat\"><strong>제329조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 주거침입죄 + 절도죄의 실체적 경합</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《금제품이 절도죄 객체가 될 수 있는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(금제품은 경제적 이용가능성 없음)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(절차상 몰수 전까지 소지·점유 보호 필요)</div><div class=\"cs-li\" style=\"margin-left:16px\">③절충설(절대적 금제품은 객체X, 상대적 금제품은 객체O)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 리프트탑승권=유가증권 작성권한 없는 자가 위조한 것이라도 절차상 몰수 전까지 소지자 점유 보호해야 → 재물로서 절도죄 객체<span class=\"cs-o\"><strong>(O)</strong></span> 발매기 전산조작으로 위조한 탑승권을 뜯어간 행위는 위조행위+위조탑승권 절취행위 결합 → 위조탑승권은 장물 <span class=\"cs-fact-tag\">[위조 유가증권은 절대적 금제품]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 절차상 몰수 전까지 소지·점유 보호 필요 → 긍정설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[절대적 금제품]</span> 소유가 금지된 물품 = 위조유가증권·위조통화·아편흡입기 <span class=\"cs-fact-tag\">[상대적 금제품]</span> 소지가 금지된 물품 = 마약·밀수품<span class=\"cs-exam\">【모사24】</span></div>", ["제319조", "제329조"], 1, "gak_절도강도"], ["개인032", "재물의 개념과 정보의 재물성", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제346조(동력)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">본장의 죄에 있어서 관리할 수 있는 동력은 재물로 간주한다.</div></div><div class=\"cs-h\">Ⅰ. 재물의 개념 (<span class=\"cs-stat\">§346</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 관리할 수 있는 동력은 재물로 간주(<span class=\"cs-stat\"><strong>§346</strong></span>·<span class=\"cs-stat\"><strong>§354</strong></span>·<span class=\"cs-stat\"><strong>§361</strong></span>·<span class=\"cs-stat\"><strong>§372</strong></span>) 관리할 수 있는 동력도 장물죄의 장물에 포함 <span class=\"cs-fact-tag\">[장물죄엔 </span><span class=\"cs-stat\">§346</span>&lt;span color=\"pink_bg\"&gt; 준용규정 없어 학설:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설, 判例 긍정설]&lt;/span&gt;</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[관리가능성설]</span> 절도죄 객체 = 관리가능 동력 포함 '재물'에 한함 횡령죄 재물은 동·부동산 유체물 한정X, 관리가능 동력도 간주되나 여기서 '관리'는 물리적·물질적 관리 → 사무적 관리가 가능한 채권·권리 등은 재물에 포함 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[광업권]</span> 재물인 광물을 취득할 수 있는 권리에 불과, 재물 자체X → 횡령죄 객체<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-h\">Ⅱ. 정보의 재물성</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[정보]</span> 컴퓨터 저장 '정보' 자체는 유체물X·물질성 있는 동력X → 재물<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[복사·출력]</span> 절도죄는 점유·이용가능성 배제하고 배타적 이전 필요한데, 정보를 복사·출력해도 정보 자체 감소X·피해자 점유·이용가능성 감소X → 절도죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[임직원의 영업비밀·영업상 주요자산 유출 시 </span><span class=\"cs-crime\">업무상배임죄</span><span class=\"cs-fact-tag\">]</span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[생성 문서]</span> 출력해 생성한 문서는 피해회사 업무용 보관문서가 아니라 피고인이 가져갈 목적으로 업무와 무관하게 새로 생성 → 피해회사 소유 문서로 볼 수 없음 <span class=\"cs-fact-tag\">[복사'용지' 절도죄는 성립 가능]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">&lt;!-- 원문 p285 말미 ☞<span class=\"cs-fact-tag\">[CASE]</span>는 \"배임죄 부분 CASE 참조(348p)\"라는 교차참조로, 별도 모범답안 전문이 없으므로 CASE-FULL로 옮기지 않음(해당 CASE는 배임죄 논점에서 처리). --&gt;</div>", ["§346", "§354", "§361", "§372", "제346조"], 1, "gak_절도강도"], ["개인033", "절도죄 일반", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">[법무사21]</span> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 丁이 운영하는 'B스포츠피부'에 마사지 받으러 갔다 대기 손님이 많아 그냥 나오며 영업점 내 丁 소유 휴대전화를 허락 없이 가지고 나와 여자친구 A와 1~2시간 통화 후, 丁에게</div><div class=\"cs-li\" style=\"margin-left:0px\">알리지 않고 정문 옆 화분에 놓아두고 감. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [휴대전화에 대한 절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 절도죄(<span class=\"cs-stat\"><strong>제329조</strong></span>)의 불법영득의사 = 권리자를 배제하고 타인의 물건을 자기 소유물과 같이 경제적 용법에 따라 이용·처분할 의사</div><div class=\"cs-li\" style=\"margin-left:0px\">② 일시 사용 목적이어도 경제적 가치가 상당히 소모되거나 / 상당한 장시간 점유하거나 / 본래의 장소와 다른 곳에 유기하면 일시 사용(X) → 불법영득의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 1~2시간 통화 후 알리지 않고 정문 옆 화분에 유기 → 불법영득의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲 = 절도죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [휴대전화 사용으로 인한 컴퓨터등사용사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 통화버튼·인터넷 접속버튼을 누르는 것만으로는 정보 또는 명령의 입력(X) → 정보처리(X) → <span class=\"cs-crime\">컴퓨터등사용사기죄</span>(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 컴퓨터등사용사기죄(<span class=\"cs-stat\"><strong>제347조의2</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 절도죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제329조(절도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">타인의 재물을 절취한 자는 6년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 절취 (<span class=\"cs-stat\">§329</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 절취 = 타인 점유 재물을 점유자 의사에 반하여 점유 배제하고 자기·제3자 점유로 옮기는 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 절도죄 객체 재물은 객관적 금전적 교환가치 不要, 소유·점유자의 주관적 가치로 족 (타인에게 이용되지 않는다는 소극적 관계로 가치 성립해도 무관)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[타인점유]</span> 타인 점유 여부 = 객관적 관리범위·사실적 관리가능성 +<span> </span>주관적 지배의사 참작, 궁극적으로 형상·구체적 사정 따라 사회통념상 규범적 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[타인소유]</span> 권원 없이 식재한 수목 소유권은 토지소유자, 권원으로 식재하면 식재자 → 권원 없이 식재한 감나무 감 수확 → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강간피해자 손가방]</span> 도피하며 현장에 놓아둔 손가방은 점유이탈물X, 사회통념상 피해자 지배하 물건 → 손가방 속 돈 꺼냄 → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[졸도]</span> 졸도해 의식상실해도 현장 일실 물건은 자연히 그 지배하<span class=\"cs-exam\">【모사18】</span></div><div class=\"cs-h\">Ⅱ. 실행의 착수와 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수시기</strong> 개념: 착수시기 = 재물에 대한 타인의 사실상 지배를 침해하는 데 밀접한 행위 개시한 때 <span class=\"cs-neg-tag\">[물색행위 시작한 때]</span> <span class=\"cs-neg-tag\">[훔칠 물건 찾을 새도 없이 발각·도망 시 착수X]</span><span class=\"cs-exam\">【변24】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[착수O]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①차안 밍크코트 발견하고 절취 생각으로 자동차 손잡이 당김</div><div class=\"cs-li\" style=\"margin-left:48px\">②주간에 절도 목적 방 안까지 들어갔다 재물 못찾고 거실 돌아나옴<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[착수O]</span> 소매치기가 양복 주머니 금품 절취하려 손 뻗쳐 겉을 더듬음 → 착수<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[착수X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①절취 생각으로 자동차 안 손전등 비춰봄<span class=\"cs-exam\">【변22·15·15】</span></div><div class=\"cs-li\" style=\"margin-left:48px\">②공사현장 들어가 창문으로 신축 아파트 지하실 안쪽 살핌</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[예비단계]</span> 소 흥정하는 피해자 뒤에서 가방으로 돈든 하의 주머니 스치며 지나감 → 주의력 흐트리는 예비단계, 착수X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수시기</strong> <span class=\"cs-issue\">《절도죄의 기수시기》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①접촉설</div><div class=\"cs-li\" style=\"margin-left:16px\">②취득설</div><div class=\"cs-li\" style=\"margin-left:16px\">③이전설</div><div class=\"cs-li\" style=\"margin-left:16px\">④은닉설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[취득설]</span> 타인 소지 침해해 재물이 자기 소지로 이동, 즉 자기 사실적 지배하에 둔 때 기수</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[기수O]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①입목 절취 위해 캐낸 때 점유 침해되어 사실적 지배하에 놓임 → 기수, 운반·반출 不要</div><div class=\"cs-li\" style=\"margin-left:48px\">②절도범이 혼자 입목 완전히 캐낸 후 제3자 가담해 함께 운반 → 특수절도죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[절도범은 절도기수, 제3자는 장물운반죄]</span><span class=\"cs-exam\">【변13】</span><span class=\"cs-exam\">【모사18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[기수O]</span> 야간에 까페 내실 침입해 정기적금통장 등 꺼내들고 나오던 중 발각·반환 → 점유 침해하고 자기 지배로 옮김 → 야간주거침입절도 기수 <span class=\"cs-fact-tag\">[주거 벗어나기 전이라도 절도 기수 가능]</span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[기수X]</span> 시동 걸려다 기기 만지다 핸드브레이크 풀려 내리막길에서 시동 안걸린 채 10m 전진·가로수 충격 <span class=\"cs-neg-tag\">[절도미수O, 무면허운전X]</span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅲ. 불법영득의사</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>불법의 의미<span class=\"cs-exam\">【변사17】</span></strong> <span class=\"cs-issue\">《불법영득의사의 '불법'의 의미》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①영득의 불법설(실질적으로 소유권 일치 상태 야기했는지로 판단; 반환청구권 있으면 영득 위법X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②절취의 불법설(수단인 절취가 적법하지 않으면 불법영득의사 인정)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[절취의 불법설]</span> 약정상 인도청구권 인정돼도 취거 당시 점유이전에 대한 점유자의 명시·묵시 동의 없으면 불법영득의사 부정 못함</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[굴삭기 취거]</span> 대금 불이행 시 회수해도 좋다는 약정+각서·계약서·양도증명서 교부 후 채무불이행하자 담당자가 굴삭기 취거·매도 → 매수인 의사에 자기 점유 배제하고 가져가도 좋다는 의사까진 포함X → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span>·불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[매수인에게 소유권 이전등록되어 판매회사 소유 아님]</span><span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>영득의사</strong> 개념: 불법영득의사 = 권리자 배제하고 타인 물건을 자기 소유물처럼 경제적 용법에 따라 이용·처분할 의사 목적물의 '물질' 영득 의사든 '가치만' 영득 의사든 불문, 영득의사 있으면 족 판단기준 (判例) : 점유자 의사에 반한 취거가 결과적으로 소유자 이익이 되거나 추정적 승낙 볼 사정 있어도, 특별사정 없는 한 그것만으로 불법영득의사 부정X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[리스승용차 담보제공, 사채업자가 甲 변제불능하자 B에 매도, 甲이 리스회사 반납 위해 취거]</span> 절도죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[예금통장O]</span> 예금통장은 예금액 증명기능=경제적 가치 → 무단사용해 예금 인출하면 증명기능·경제적 가치 소모 인출 후 바로 반환해도 소모가 무시할 정도로 경미하지 않은 이상 증명기능의 경제적 가치에 대한 불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span> → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span><span class=\"cs-exam\">[모사14, 변기20]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[신용카드X]</span> 신용카드 자체엔 경제적 가치 화체X·재산권 표창 유가증권X, 회원·서비스 증표 가치뿐 → 현금 인출해도 카드 자체 경제적 가치 소모X → 일시사용 후 곧 반환하면 불법영득의사<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[현금카드·직불카드도 동일]</span><span class=\"cs-exam\">【변20】</span><span class=\"cs-exam\">【변사18, 모사14, 변기20】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>'영구적 또는 장기간' 권리자를 배제하려는 의사 (소극적 요소)</strong> 개념: 사용절도는 권리자를 일시적으로 배제하는 의사만 있는 점에서 절도와 구별 판단기준 (判例) : 일시사용 목적 점유침탈도</div><div class=\"cs-li\" style=\"margin-left:16px\">①경제적 가치 상당 소모</div><div class=\"cs-li\" style=\"margin-left:16px\">②상당 장시간 점유</div><div class=\"cs-li\" style=\"margin-left:16px\">③본래 장소와 다른 곳 유기 시 일시사용으로 볼 수 없어 영득의사<span class=\"cs-o\"><strong>(O)</strong></span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[휴대전화 유기]</span> 허락없이 가지고 나와 통화 후 1~2시간 후 말없이 영업점 정문 화분에 놓아둠 → 경제적 용법에 따라 이용(적극적 요소)+본래 장소와 다른 곳 유기(소극적 요소) → 불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22·16·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[오토바이 유기]</span> 자동차등불법사용죄는 불법영득의사 없이 일시사용 시 적용, 불법영득의사 인정되면 절도죄만 성립 승낙없이 오토바이 타고 가 다른 장소에 버림 → 자동차등불법사용죄<span class=\"cs-x\"><strong>(X)</strong></span>, 절도죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[후일 변제의사]</span> 승낙없이 지갑 가져가면 후일 변제의사 있어도 불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[하드디스크 4개월 후 반환]</span> 결근하다 감사실 침입해 하드디스크 떼어간 후 4개월 가까이 지나 반환 → 일시보관 후 반환으로 평가 어려워 불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[비자금 가방]</span> 사표 제출 후 평소 전적 보관·관리하던 비자금 서류·금품 가방 가지고 나왔으나 이후 정상 근무 → 불법영득의사<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[총기 보충]</span> 군인이 총기 분실하고 보충 위해 총기 취거 → 불법영득의사<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>'일시적'이나마 경제적 용법에 따라 사용할 의사 (적극적 요소)</strong> 판단기준 (判例) : 단순 점유침해만으로 절도죄 구성X, but 영구적으로 경제적 이익 보유할 의사는 不要 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[증거인멸 지갑 소각]</span> 살해된 피해자 주머니서 꺼낸 지갑을 살해도구 골프채·옷 등 증거품과 함께 차에 싣고 가 쓰레기소각장에서 태움 → 증거인멸 행위로 불법영득의사 인정 어려움 <span class=\"cs-exam\">[모사21, 변기22]</span></div>", ["§329", "제329조", "제347조"], 3, "gak_절도강도"], ["개인034", "유실물의 점유관계", "<div class=\"cs-h\">Ⅰ. 원래 점유자가 소재를 알고 있는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 원래 점유자가 소재를 알고 다시 찾아올 수 있으면 점유 인정 → 유류물·분실물 아님 이 경우에도 타인이 현실적으로 점유 취득했으면 그 타인의 점유에 속함</div><div class=\"cs-h\">Ⅱ. 원래 점유자가 소재를 모르는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 소재 모르면 점유이탈물 <span class=\"cs-fact-tag\">[타인이 현실적으로 점유취득하면 당연히 그 타인 점유]</span> 타인의 배타적 지배범위에 두고 온 물건은 장소 관리자가 현실 점유취득 못했어도 관리자 점유에 속함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[당구장·PC방]</span> 물건 잃은 장소가 당구장처럼 타인 관리하에 있으면 일응 관리자 점유 → 관리자 아닌 제3자가 취거 = 유실물횡령<span class=\"cs-x\"><strong>(X)</strong></span>, 절도죄<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">['PC방'도 동일]</span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[고속버스]</span> 운전사는 관수자로 승객 물건 점유X, 유실물 교부받을 권능뿐 → 현실 발견 전엔 점유개시X → 다른 승객이 발견해 가져가면 절도<span class=\"cs-x\"><strong>(X)</strong></span>, 점유이탈물횡령</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[지하철 승무원]</span> 현실 발견 전엔 점유개시X → 점유이탈물횡령죄 별론, 절도죄<span class=\"cs-x\"><strong>(X)</strong></span></div>", [], 1, "gak_절도강도"], ["개인035", "사자의 점유", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사23】 </span><span class=\"cs-o\">(13)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 양부(養父) A의 병실에서 산소호흡기를 제거해 A를 살해. A 명의 부동산을 임의 처분하기로 마음먹고 살해 직후 병실의 A 인감도장을 가지고 나와 'A가 甲에게 인감증명서 발급을 위임한다'는 A 명의 위임장 1장을 작성, 같은 날 주민센터 담당 직원 C에게 제출해 A의</div><div class=\"cs-li\" style=\"margin-left:0px\">인감증명서를 발급받음. 甲의 죄책은? (13점) [존속살해 및 주거침입의 점은 제외]</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① A의 인감도장 = 상속인들의 공동소유 또는 국가 소유(민법 <span class=\"cs-stat\"><strong>제1058조</strong></span> 제1항), 甲은 상속결격(민법 <span class=\"cs-stat\"><strong>제1004조</strong></span> 제1호) → 타인의 소유물(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 살해 직후 절도 범의가 생겨 그 장소의 피해자 재물을 가지고 나온 경우 — 점유이탈물횡령죄설/절도죄설, 판례 = 생전 점유가 사망 후에도 계속 → 절도죄설. 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲 = 절도죄(<span class=\"cs-stat\"><strong>제329조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [사문서위조죄 및 동행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 명의인이 허무인이거나 작성일자 전에 이미 사망했어도 공문서뿐 아니라 사문서에도 위조죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② A 명의 위임장 위조 후 직원 C에게 제출 → 사문서위조죄 및 동행사죄(<span class=\"cs-stat\"><strong>제231조</strong></span>, <span class=\"cs-stat\"><strong>제234조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ A의 인장을 위임장에 날인한 <span class=\"cs-crime\">사인부정사용죄</span>는 사문서위조죄에 흡수 → 별도 성립(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 절도죄 + 사문서위조죄 + 위조사문서행사죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 타인 '소유'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 타인과 공유관계에 있는 물건도 타인의 재물에 속함 재물 소유자 사망 시 상속인들 공동소유, 상속인 없으면 국가 소유(민<span class=\"cs-stat\"><strong>§1058</strong></span>①) 존속살해는 상속결격이라 살해한 상속인 소유 될 수 없음(민<span class=\"cs-stat\"><strong>§1004</strong></span> 1호)</div><div class=\"cs-h\">Ⅱ. 타인 '점유'</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>재물을 강취할 목적으로 살해한 경우</strong> 효과: 강도살인죄 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>살해한 직후 범의가 생겨 재물을 가지고 나온 경우 <span class=\"cs-exam\">[변사23, 모사23·16]</span></strong> <span class=\"cs-issue\">《살해 직후 재물을 가지고 나온 경우 사자의 점유 인정 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①점유이탈물횡령죄설(사자·상속인 점유 인정X → 절도죄X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②절도죄설(피해자 생전점유 계속 → 타인 점유 O)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[절도죄설]</span> 살해한 방에서 사망 피해자 곁에 4시간 30분쯤 있다가 물건을 영득의사로 가지고 나옴 → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span> — 피해자 생전 점유는 사망 후에도 여전히 계속<span class=\"cs-exam\">【변17·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 사망과 시간적·장소적 근접성 인정되면 생전점유 계속 → 절도죄설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>피해자가 다른 원인으로 이미 사망한 경우</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[사자 계속점유 부정]</span> 주거침입 당시 피해자 이미 사망, 피고인은 사망과 무관, 사망시기·경과시간 불분명 → 사자 계속점유 인정<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[점유이탈물횡령죄 성립]</span> <span class=\"cs-fact-tag\">[상속인 점유이전 부정]</span> 절도죄 '점유'는 순수한 사실상 지배관계로 민법상 점유와 불일치 상속점유 이전의 민<span class=\"cs-stat\"><strong>§193</strong></span>은 절도죄 '타인 점유'엔 적용여지X → 상속인은 사실상 지배를 가져야 점유, 그때부터 비로소 상속인에 대한 절도죄 성립 가능 <span class=\"cs-exam\">[변기22, 모사24]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[섬 발전기]</span> 광산개발 위해 발전기 반입했다 광업권 취소로 창고에 두고 철수, 10년 미출현·사망 후 甲이 옮김 타인 점유 물건<span class=\"cs-x\"><strong>(X)</strong></span> — 취거 당시 원소유자·상속인이 점유의사로 사실상 지배 안함<span class=\"cs-exam\">【변13】</span></div>", ["§1058", "§1004", "§193", "제1058조", "제1004조", "제329조", "제231조", "제234조"], 2, "gak_절도강도"], ["개인036", "야간주거침입절도죄와 특수절도죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사17】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 丙이 '장물' 300만 원을 보관 중임을 알고 훔치려 늦은 밤 丙의 집에 몰래 들어감 → 丙이 해 뜰 때까지 잠들지 않아 기다리다 오전 9시경 장롱 속 종이봉투의 현금 300만 원을</div><div class=\"cs-li\" style=\"margin-left:0px\">들고 나옴. 乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [야간주거침입절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [주거침입죄] 늦은 밤 몰래 들어감 → 주거침입죄(<span class=\"cs-stat\"><strong>제319조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [야간주거침입절도죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 야간의 의미 — 위 학설 및 판례. 주거침입만 야간이면 족하다는 견해가 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 늦은 밤 침입 → 절취가 주간(오전 9시)이어도 야간주거침입절도죄(<span class=\"cs-stat\"><strong>제330조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [장물취득죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [장물죄의 본질] 추구권설/유지설/결합설, 판례 = 결합설로 평가. 양자 모두에서 본질을 파악하는 결합설 타당</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [장물을 절취한 경우]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 추구권설 → 장물취득죄(O), 유지설·결합설 → 본범과의 합의가 없어 장물취득죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 판례 = 타인이 갈취한 재물을 그 의사에 반해 절취 → 절도죄만 성립, 장물취득죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙에게 장물취득죄(<span class=\"cs-stat\"><strong>제362조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 乙 = 야간주거침입절도죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제330조(야간주거침입절도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">야간에 사람의 주거, 관리하는 건조물, 선박, 항공기 또는 점유하는 방실에 침입하여 타인의 재물을 절취한 자는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제331조(특수절도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 야간에 문이나 담 그 밖의 건조물의 일부를 손괴하고 제330조의 장소에 침입하여 타인의 재물을 절취한 자는 1년 이상 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 흉기를 휴대하거나 2명 이상이 합동하여 타인의 재물을 절취한 자도 제1항의 형에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 야간주거침입절도 (<span class=\"cs-stat\">§330</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>실행의 착수시기</strong> 개념: 야간에 절취 목적으로 주거침입한 경우 주거침입 단계에서 이미 야간주거침입절도죄 착수<span class=\"cs-exam\">【변26】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[베란다 난간]</span> 야간에 물건 훔칠 의도로 아파트 베란다 철제난간까지 올라가 유리창문 열려 시도 → 착수<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[가스배관]</span> 야간에 절취 위해 가스배관 오르다 1층 방범창 딛고 배관 잡은 상태서 발각·뛰어내림 → 주거 사실상 평온 침해할 현실적 위험성 개시로 보기 어려움 (착수X)<span class=\"cs-exam\">【변19·13】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>절취의 목적</strong> 적용범위: 야간주거침입절도죄=주거침입죄+절도죄 결합범, 주거침입 선행 → 주거침입 시 절도고의 있어야 침입 후 비로소 절도고의 생기면 주거침입죄+절도죄 경합범일지언정 야간주거침입절도죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26】</span> 절취 아닌 살인 목적으로 주거침입 → 야간주거침입절도죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>야간의 의미 <span class=\"cs-exam\">[변사17, 모사24, 모기25]</span></strong> <span class=\"cs-issue\">《§330 야간주거침입절도죄의 '야간'의 의미》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①주거침입·절취 중 어느 하나만 야간이면 족</div><div class=\"cs-li\" style=\"margin-left:16px\">②주거침입만 야간이면 족</div><div class=\"cs-li\" style=\"margin-left:16px\">③절취행위만 야간이면 족</div><div class=\"cs-li\" style=\"margin-left:16px\">④주거침입·절취 모두 야간</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: 야간 주거침입행위의 위험성에 주목해 중처벌 → 주거침입이 주간이면 야간주거침입절도죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·21·19·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 형법이 '야간절도죄' 별도 처벌규정 없음 → 주거침입만 야간이면 족하다는 견해 타당 <span class=\"cs-fact-tag\">[위 판례 논거]</span></div></div><div class=\"cs-h\">Ⅱ. 특수절도 (<span class=\"cs-stat\">§331</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong><span class=\"cs-stat\">제331조</span> 제1항 (야간손괴후주거침입절도)</strong> 개념: <span class=\"cs-stat\"><strong>§331</strong></span>① '손괴' = 물리적으로 문호·장벽 등 건조물 일부 훼손해 효용 상실시키는 것 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[착수O]</span> 야간에 절도 목적으로 출입문 자물통 고리 절단·손괴 후 침입하려다 발각 → 특수절도죄 착수<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20·16·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">창문·방충망을 창틀에서 분리만 하고 물리적 훼손·효용상실 안시킨 경우 특수절도죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">['야간주거침입절도죄' 성립]</span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong><span class=\"cs-stat\">제331조</span> 제2항 (흉기휴대, 합동절도)</strong> 판단기준 (判例) : 2인 이상 합동해 야간 아닌 주간에 절도 목적 주거침입해도 물색행위 시작 전이면 특수절도죄 착수<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[주간에 합동해 시정장치 손괴하다 발각·도주 → 특수절도죄 착수X]</span><span class=\"cs-exam\">【변13】</span></div>", ["§330", "§331", "제319조", "제330조", "제362조", "제331조"], 3, "gak_절도강도"], ["개인037", "준강도죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사25】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">주점 운영 甲, 종업원 乙과 공모 — 甲이 망보면 乙이 A의 가방 속 현금을 훔치기로. A가 공원 벤치에 앉자 甲이 망보기 시작, 乙이 가방을 집어드는 순간 甲은 급한 전화를 받고 주점으로 귀환. A가 가방을 들고 공원을 나가려는 乙을 목격, 100m 쫓아가 어깨·목덜미를 붙잡자 乙이 항거하려 A를 넘어뜨리고 발로 밟아 전치 6주 골절상. 甲·乙의 죄책? 단 甲은 ㉠ 판례의 입장에서 설명하고 ㉡ 그 판례법리에 대한 비판논거를 제시. (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [특수절도죄의 성립여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① '합동'의 의미 — 공모공동정범설/가중적 공동정범설/현장설/현장적 공동정범설, 판례 = 현장설</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공모 + 甲 망보기 + 乙 절취 = 현장에서 시간적·장소적 협동 → 특수절도죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲은 실행 착수 후 이탈, 乙에 의해 기수 → 특수절도기수(<span class=\"cs-stat\"><strong>제331조</strong></span> 제2항, 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [준강도 또는 강도상해죄의 성립여부] (A) [판례의 입장]</div><div class=\"cs-li\" style=\"margin-left:0px\">① \"2인 이상 합동절도 중 1인이 체포를 면탈할 목적으로 상해를 가한 때 나머지도 이를 예기하지 못한 것으로 볼 수 없으면 강도상해죄를 면할 수 없다\"</div><div class=\"cs-li\" style=\"margin-left:0px\">② 현장의 피해자를 상대로 한 절취는 발각·추격 상황을 충분히 예견 가능 → 甲이 이미 현장을 벗어났어도 강도상해죄(<span class=\"cs-stat\"><strong>제337조</strong></span>)(O) (B) [판례에 대한 비판]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 준강도·강도상해죄는 각 고의범 → 준강도 공동정범은 '폭행'의, 강도상해 공동정범은 '상해'의 고의 공동이 要. 판례는 예견가능성(과실)을 기준으로 고의 공동이 없는 甲에게 고의범을 인정 → 고의·과실을 엄격 구별하는 형법 규율에 부합(X), 책임주의 위반</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공동정범(<span class=\"cs-stat\"><strong>제30조</strong></span>)은 기능적 행위지배 要 → 공모도 실행분담도 없는 甲에게 기능적 행위지배(X). 그 검토 없이 준강도·강도상해 공동정범을 인정함은 부당 (C) [소결] 甲에게 '폭행'·'상해'의 고의 공동(X) → 특수절도죄만 성립</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [특수절도죄의 성립여부] 甲과 합동하여 절취 → 특수절도기수죄(<span class=\"cs-stat\"><strong>제331조</strong></span> 제2항, 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [준강도죄의 성립여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 준강도(<span class=\"cs-stat\"><strong>제335조</strong></span>)의 폭행·협박 = 절도의 기회, 즉 사회통념상 절도행위가 완료되지 않았다고 인정될 단계에서 행해질 것 要</div><div class=\"cs-li\" style=\"margin-left:0px\">② A가 100m 쫓아가 붙잡자 체포면탈·재물탈환 항거 목적으로 폭행 → 절도범행 완료 전 폭행 → 준강도죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 준강도/준특수강도 구별기준 — 절취태양기준설/폭행·협박태양기준설, 판례 = 폭행·협박태양기준설. 甲이 이미 이탈한 후 폭행 → 준특수강도(X), 준강도(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [강도상해죄의 성립여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 강도상해죄(<span class=\"cs-stat\"><strong>제337조</strong></span>)의 '강도'에 준강도죄의 강도범인 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">② 미필적 고의 — 판례 = \"발생 가능성의 인식 + 발생 위험을 용인하는 내심의 의사\" 용인설. 넘어뜨린 후 발로 밟음 → 상해의 미필적 고의(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙 = 강도상해죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 판례의 입장은 부당 → 甲은 특수절도죄 기수범만</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = 강도상해죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제335조(준강도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">절도가 재물의 탈환에 항거하거나 체포를 면탈하거나 범죄의 흔적을 인멸할 목적으로 폭행 또는 협박한 때에는 제333조 및 제334조의 예에 따른다.</div></div><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제333조(강도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">폭행 또는 협박으로 타인의 재물을 강취하거나 기타 재산상의 이익을 취득하거나 제삼자로 하여금 이를 취득하게 한 자는 3년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제334조(특수강도)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 야간에 사람의 주거, 관리하는 건조물, 선박이나 항공기 또는 점유하는 방실에 침입하여 제333조의 죄를 범한 자는 무기 또는 5년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 흉기를 휴대하거나 2인 이상이 합동하여 전조의 죄를 범한 자도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제337조(강도상해, 치상)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">강도가 사람을 상해하거나 상해에 이르게 한때에는 무기 또는 7년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제338조(강도살인·치사)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">강도가 사람을 살해한 때에는 사형 또는 무기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 10년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제339조(강도강간)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">강도가 사람을 강간한 때에는 무기 또는 10년 이상의 징역에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 준강도의 요건 (<span class=\"cs-stat\">§335</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>주체 – 절도</strong> 적용범위: 주체=절도범인, 객체=재물 <span class=\"cs-fact-tag\">[미수·기수 불문]</span> 절도 실행착수 이상 주체<span class=\"cs-o\"><strong>(O)</strong></span> (예비단계 그친 경우 X)<span class=\"cs-exam\">【변25·15】</span> <span class=\"cs-neg-tag\">[교사·방조범]</span> 주체<span class=\"cs-x\"><strong>(X)</strong></span> (정범 국한) → 절도교사·방조죄 + 폭행·협박죄 실체적 경합 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[술값 면탈·재산상 이익 취득]</span> 준강도<span class=\"cs-x\"><strong>(X)</strong></span> — 절도 객체는 재물, 재산상 이익 취득은 절도 아님<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>절도의 기회</strong> 개념: 폭행·협박은 절도 실행 중·실행 직후·범의포기 직후로서 사회통념상 범죄행위 미완료 단계에서 행해져야<span class=\"cs-exam\">【변사25】</span> 판단기준 (判例) : 절도 현장, 또는 시간·장소 접착으로 피해자측 체포가능·죄적인멸 가능 상황 (추적태세, 체포 후 신병확보 불확실 포함) = 절도의 기회<span class=\"cs-exam\">【변26·25】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[도주 중 보안요원에 붙잡혀 보안사무실 인도]</span> 절도의 기회<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[방범대원에 파출소 연행 중]</span> <span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[절도 후 10분·200m 떨어진 버스정류장에서 뒤쫓아온 피해자에 붙잡혀 집으로 돌아와 비로소 폭행]</span> 절도의 기회<span class=\"cs-x\"><strong>(X)</strong></span> → 준강도<span class=\"cs-x\"><strong>(X)</strong></span>, 절도죄+폭행·협박죄 실체적 경합<span class=\"cs-exam\">【변20】</span><span class=\"cs-exam\">【변사22】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>폭행 또는 협박</strong> 성립요건: 목적(<span class=\"cs-stat\"><strong>§335</strong></span>) =</div><div class=\"cs-li\" style=\"margin-left:16px\">①재물탈환 항거</div><div class=\"cs-li\" style=\"margin-left:16px\">②체포 면탈</div><div class=\"cs-li\" style=\"margin-left:16px\">③범죄흔적 인멸 개념: (재물탈환 항거목적) 절도가 재물을 배타적 지배로 옮긴 뒤 탈환당하지 않으려 대항 폭행·협박 정도: 반항 억압할 정도 要, 실제 억압까진 不要</div><div class=\"cs-h\">Ⅱ. 준강도의 기수·미수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《준강도의 기수·미수 판단기준》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①절취행위기준설</div><div class=\"cs-li\" style=\"margin-left:16px\">②폭행·협박행위기준설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[절취행위기준설]</span> 재물탈취와 폭행·협박은 시간적 전후 차이일 뿐 위법성 동일 → 기수여부는 '절도행위'의 기수·미수 기준<span class=\"cs-exam\">【변26·25·24·23·22·19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 본질적 재산범죄인 점, 강도 기수·미수도 절취행위 기준인 점 → 절취행위기준설 타당</div></div><div class=\"cs-h\">Ⅲ. 준강도와 준특수강도의 구별기준<span class=\"cs-exam\">【변사25·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《'흉기 휴대'·'합동'(특수강도 요건)을 준강도의 어느 행위에 갖춰야 하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①절취태양기준설(신분적 가중유형으로 보아 절도의 가중사유 유무로 결정)</div><div class=\"cs-li\" style=\"margin-left:16px\">②폭행·협박태양기준설(강도처럼 폭행·협박 태양으로 구별)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[폭행·협박태양기준설]</span> 처음엔 흉기 미휴대였으나 체포면탈 목적 폭행·협박 시 비로소 흉기 휴대·사용 → <span class=\"cs-stat\"><strong>§334</strong></span>의 예에 의한 준강도(특수강도의 준강도)<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 강도도 폭행·협박 유형에 따라 단순·특수 구별 → 준강도도 폭행·협박태양기준설 타당</div></div><div class=\"cs-h\">Ⅳ. 절도 공범 중 1인의 양적 초과</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>준강도 및 강도상해죄의 공동정범</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[합동절도 중 1인이 체포면탈 목적 폭행하여 상해]</span> 나머지 범인도 '예기' 못한 것으로 볼 수 없으면 강도상해죄 죄책 면할 수 X<span class=\"cs-exam\">【변17】</span><span class=\"cs-exam\">【변사25, 모기24】</span> <span class=\"cs-fact-tag\">[TIP·판례비판]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①고의 없는 자에게 고의범 책임 불가 → 공모자 중 1인이 '공집방·방화' 등 별개 고의범죄 시, 고의 없는 자는 예견가능성 무관하게 책임 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②'폭행·협박'·'상해'는 고의범인데 판례가 '예견가능성'(과실·결과적가중범 요소)으로 다른 절도공범에 준강도·강도상해 인정 → 기능적 행위지배 없는 자에 고의정범 인정 문제 + 책임주의 반함</div><div class=\"cs-li\" style=\"margin-left:16px\">③사례답안: 판례 인정 '준강도'·'강도상해' 외 다른 고의범죄는 고의 없는 절도공범자에 인정 X<span class=\"cs-exam\">【변사25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>구체적 판례</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[흉기 준비]</span> 식칼 나눠갖은 특수절도범들이 발각·각기 도주 중 1인이 체포면탈 목적 상해 → 나머지도 예기 못했다 볼 수 X → 강도상해죄 책임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[발각 시 현장에 있었음]</span> 생맥주집 함께 절취 중 발각→피고인 먼저 도주, 뒤이어 도주하던 공범이 현장에서 붙잡혀 상해 → 예기 못했다 볼 수 X → 강도상해죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[이미 체포된 경우]</span> 피해자가 피고인 체포·동리사람에 인계 후 1km 더 추격, 몽둥이로 공범 구타하자 공범이 몽둥이 빼앗아 상해 → 공범은 준강도상해, but 피고인은 상해 예기 못함 → 강도상해죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[이미 상당한 거리 도주]</span> 망보던 피고인이 인기척에 먼저 도주해버린 후 창구에 낀 공모자가 붙잡혀 상해 → 상당거리 도주로 폭행 예기 불가 → 강도상해죄 책임<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변사24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>공무집행방해 등 '별개의 고의범'</strong> 적용범위: <span class=\"cs-fact-tag\">[질적 초과]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①공모내용과 전혀 다른 별개 범죄 실행 → 다른 공범자는 초과부분 책임 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②공범 1인이 공무집행방해(특수공무집행방해치상) 범함 → 다른 공범자는 예견가능성 무관하게 책임 X</div><div class=\"cs-h\">Ⅴ. 강도예비·음모죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[준강도 목적뿐]</span> 강도예비·음모죄는 미필적으로라도 '강도' 목적 要 → '준강도' 목적뿐이면 처벌 X <span class=\"cs-fact-tag\">[절도 발각 대비 도움될 정도 생각에 등산용칼 준비 → 강도예비죄 X]</span><span class=\"cs-exam\">【변25·24·22·17·15·14】</span></div>", ["§335", "§334", "제331조", "제337조", "제30조", "제335조", "제333조", "제334조"], 3, "gak_절도강도"], ["개인038", "강도죄·특수강도죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲의 1,000만 원 반환 독촉에 시달리던 乙, A의 재물을 강취하기로 하고 지인에게서 A의 집 구조·금고위치 정보를 입수하고 현장 답사. 3일 뒤 밤 11시경 A의 단독주택 외부 벽면을 타고 2층으로 올라가 창문을 열고 들어가다 집안에서 거구의 남자 2명이 다가오자 겁먹고 도망.</div><div class=\"cs-li\" style=\"margin-left:0px\">乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [야간주거침입강도죄의 실행의 착수시기]</strong> 야간주거침입강도죄(<span class=\"cs-stat\"><strong>제334조</strong></span> 제1항)의 착수시기 — 주거침입시설/폭행·협박시설, 판례는 양쪽 입장이 다 있음. 구조가 같은 야간주거침입절도죄와 달리 볼 이유(X) → 주거침입시설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [야간주거침입강도죄의 실행 착수]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 주거침입죄(<span class=\"cs-stat\"><strong>제319조</strong></span> 제1항)의 침입 = 사실상 평온상태를 해치는 행위태양으로 들어가는 것, 판단은 출입 당시 객관적·외형적 행위태양 기준이 원칙</div><div class=\"cs-li\" style=\"margin-left:0px\">② 주거침입죄의 착수 = 침입의 범의로 시정장치를 부수거나 문을 여는 등 구체적 행위를 시작해 구성요건 실현의 현실적 위험성을 포함하는 행위를 개시할 것 要</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 주거침입시설에 의하면, 외부 벽면을 타고 2층 '창문을 열고 들어가다' 도망 → 착수(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [중지미수의 인정여부]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 중지미수(<span class=\"cs-stat\"><strong>제26조</strong></span>)의 자의성 — 판례 = 일반 사회통념상 범죄 완수에 장애가 되는 사정에 의한 것이 아니면 중지미수(절충설)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 거구의 남자 2명이 다가오자 겁먹고 도망 = 사회통념상 장애사유에 의한 중지</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙에게 중지미수(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 乙 = <span class=\"cs-stat\"><strong>제334조</strong></span> 제1항 특수강도죄의 장애미수</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 폭행 또는 협박</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[최협의]</span> 폭행·협박 정도 = 사회통념상 객관적으로 상대방 반항을 억압·항거불능케 할 정도</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 폭행·협박 당한 자 ≠ 탈취당한 재물의 소유자·점유자여도 무방</div><div class=\"cs-h\">Ⅱ. 처분행위 – 불필요</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>재물</strong> 적용범위: <span class=\"cs-fact-tag\">[재물]</span> 폭행·협박으로 타인 재물 탈취한 이상, 피해자가 우연히 재물탈취 사실 몰라도 강도죄 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>재산상 이익</strong> <span class=\"cs-issue\">《재산상 이익 취득에 피해자의 처분행위가 필요한지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①적극설(처분행위 불요 시 이익 노린 살인 전부 강도살인 되어 부당→처분행위 필요)</div><div class=\"cs-li\" style=\"margin-left:16px\">②소극설(강도는 탈취죄→처분행위 불요)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[소극설]</span> 재산상 이득행위도 반항 억압할 폭행·협박 수단으로 재산상 이익 취득하면 족함 → 상대방 의사에 의한 처분행위 강제 不要</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 강도는 반항 억압으로 자유의사 결여 상태에서 탈취하는 범죄 → 소극설 타당</div></div><div class=\"cs-h\">Ⅲ. 재물 또는 재산상 이익의 취득</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>폭행·협박과 재물 취거 사이의 인과관계</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[합의 성교 중 시비→이불 덮어씌우고 폭행 후 나가다 우발적으로 손가방 현금 취거]</span> 인과관계<span class=\"cs-x\"><strong>(X)</strong></span> → 강도죄<span class=\"cs-x\"><strong>(X)</strong></span> — 폭행·협박이 재물 탈취방법으로 사용된 것도 아니고 반항억압 상태 이용 취득도 아님</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>재산상 이익의 취득</strong> 적용범위: 재산상 이익 = 적극적 이익(재산 증가) + 소극적 이익(부채 감소) 모두 포함 반항 억압 폭행·협박으로 채무부담·채권포기·채무면제 의사표시 하게 한 경우처럼, 자유의사 결여 상태에서 처분행위 '외형' 지닌 행동에 의한 이득도 재산상 이익 포함 법률상 정당한 이행청구 가능·사법상 유효 이득 아니어도 외견상 재산상 이득 인정할 사실관계만 있으면 해당 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[협박으로 지불각서 작성·강취]</span> 외형상 서면에 따른 채무부담 의사표시<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[성매매대금 받고→반환 요구하는 피해자 폭행·협박 후 돈 갖고 이탈]</span> 외견상 반환 면함 → <span class=\"cs-crime\">사기죄</span>+특수강도죄 실체적 경합 (합동강도는 사기의 불가벌적 사후행위 아님)</div><div class=\"cs-h\">Ⅳ. 불법영득·이득의사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 채무면탈 강도죄의 불법이득의사는 단순 폭력범죄와 구별하는 중요 구성요건 표지 → 폭행·협박 당시 채무면탈 불법이득의사 있었는지 신중·면밀 심리</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">[술값 일부만 내고 나가려다 붙잡히자 격분→A 폭행, 말리는 B도 폭행, 도망간 B 쫓다 '다시 돌아와' A 재폭행 후 경찰 올 때까지 바닥에 '누워' 있음] 강도죄 불법영득의사<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅴ. 날치기<span class=\"cs-exam\">【모사21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강도]</span> 날치기 중 상대방 반항에 부딪혔음에도 5m 끌고가며 억지로 재물 탈취 → 반항 억압 후 강취 = 강도 <span class=\"cs-fact-tag\">[재물 탈취 위한 폭행이므로 재물탈환 항거 폭행 아님 → 준강도 아닌 강도]</span><span class=\"cs-exam\">【변23·18·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[절도]</span> 날치기처럼 반항억압 목적 없이 점유탈취 과정서 우연히 넘어뜨리거나 상해 → 강도<span class=\"cs-o\"><strong>(X)</strong></span>, 절도<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅵ. 실행의 착수<span class=\"cs-exam\">【변사21】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>단순강도죄 (<span class=\"cs-stat\">§333</span>)</strong> 개념: <span class=\"cs-fact-tag\">[폭행·협박시]</span> 재물강취·강제이득 수단으로서 반항 억압할 정도의 폭행·협박이 개시된 때 착수</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>특수강도죄 (<span class=\"cs-stat\">§334</span>)</strong> 가. <strong>야간주거침입강도죄 (<span class=\"cs-stat\">§334</span>①)</strong> <span class=\"cs-issue\">《야간주거침입강도죄 실행 착수시기》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①주거침입시설(주거침입+강도 결합범→선행하는 주거침입 시)</div><div class=\"cs-li\" style=\"margin-left:16px\">②폭행·협박시설(폭행·협박 시)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[주거침입시설]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①<span class=\"cs-stat\"><strong>§334</strong></span>①은 주거침입+강도 결합범, 주거침입 선행 → '주거침입 한 때' 착수</div><div class=\"cs-li\" style=\"margin-left:16px\">②<span class=\"cs-stat\"><strong>§334</strong></span>②(흉기휴대·합동)도 야간에 주거 침입하여 강도 이루어지면 '주거침입 한 때' 착수 <span class=\"cs-fact-tag\">[폭행·협박시설]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①<span class=\"cs-stat\"><strong>§334</strong></span>①·②의 특수강도 착수 = 반항 억압할 정도의 '폭행·협박에 나아갈 때'</div><div class=\"cs-li\" style=\"margin-left:16px\">②강도 범의로 야간에 칼 휴대 주거침입 후 동정 살피다 갑자기 욕정으로 칼로 협박·강간 → 동정만 살핀 단계는 특수강도 착수 X → 성폭법 <span class=\"cs-stat\"><strong>§3</strong></span>② 특수강도강간죄 불성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①주거침입시설 – 구조 동일한 야간주거침입절도와 착수시기 달리 볼 이유 X → 주거침입시설 타당</div><div class=\"cs-li\" style=\"margin-left:16px\">②폭행·협박시설 – 주거침입 단계 체포 시 내심 의사만으로 야간주거침입절도/강도 구별함은 불합리 → 폭행·협박시설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">나. <strong>흉기휴대 및 합동으로 인한 특수강도 (<span class=\"cs-stat\">§334</span>②)</strong> 개념: <span class=\"cs-fact-tag\">[폭행·협박시]</span> 흉기휴대·합동 특수강도 착수 = 폭행·협박 개시한 때<span class=\"cs-exam\">【변25】</span><span class=\"cs-exam\">【모사25】</span></div>", ["§333", "§334", "§3", "제334조", "제319조", "제26조"], 3, "gak_절도강도"], ["개인039", "강도상해·치상죄, 강도살인·치사죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A에게 진 많은 빚을 갚을 수 없자 A를 죽여 채무를 면하기로 하고 A를 살해. 그런데 A의 처는 A가 甲에게 거액을 빌려준 사실을 잘 알아 경찰서에 관련 서류 제출.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\">① 상속인이 채무의 존재를 아는 경우 강도살인죄(<span class=\"cs-stat\"><strong>제338조</strong></span>) 성부 — 위 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">② A의 처가 사실을 알고 서류 제출 → 채무 면탈 의사로 채권자를 살해해도 일시적으로 채권자측 추급을 면한 것에 불과 → 재산상 이익의 지배가 채권자측에서 甲에게 이전(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲 = 강도살인죄(X), <span class=\"cs-stat\"><strong>제250조</strong></span> 제1항 단순살인죄만</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 주체 – 강도</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 강도상해의 강도 = '특수강도' 포함 강도상해·치상죄: 재물강취 기수·미수 불문<span class=\"cs-exam\">【변15】</span><span class=\"cs-exam\">【모사24】</span> 강도상해·살인의 강도 = '준강도죄'의 강도범인 포함<span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">【변사25】</span> <span class=\"cs-stat\"><strong>§334</strong></span>① 특수강도(야간주거침입강도) 성립 시 '주거침입죄' 별도 처벌 X <span class=\"cs-stat\"><strong>§334</strong></span>① 특수강도에 의한 강도상해 성립 시에도 주거침입죄 별도 처벌 X</div><div class=\"cs-h\">Ⅱ. 강도의 기회</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 강도가 '강도의 기회'(강도 실행 중·실행 직후·범의포기 직후로서 사회통념상 범죄행위 미완료 단계)에 살인 → 강도살인<span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 상해행위가 강도 기수 前이어야 하는 것 X → 강도 후에도 피해자 계속 끌고다니거나 차량에 태워 이동하는 등 심리적 저항불능 상태 미해소 상태에서 상해 시, 강취·상해 간 다소 시간·공간 간격 있어도 강도상해 성립<span class=\"cs-exam\">【변18·16】</span></div><div class=\"cs-h\">Ⅲ. 강도상해·치상죄의 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 강도치상죄 = 강도 피해자 아닌 제3자에게 상해 입혀도 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[절도미수범이 범죄흔적 인멸 목적 상해]</span> 강도상해 미수<span class=\"cs-x\"><strong>(X)</strong></span> → 강도상해죄 기수<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅳ. 강도상해·살인의 공동정범</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>강도상해 – 강도의 공범자 중 1인이 상해를 가한 경우</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[합동강도 중 1인이 그 기회에 피해자 상해]</span> 나머지도 예기 못한 것으로 볼 수 없으면 강도'상해' 죄책 면할 수 X<span class=\"cs-exam\">【변17·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[합동강도 1인이 공모대로 과도 들고 강도 착수하여 피해자 찔러 상해]</span> 대문 밖 망본 공범이 구체적 상해까지 공모 안 했어도 강도상해죄 책임 면할 수 X<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>강도살인 – 강도의 공범자 중 1인이 살인한 경우</strong> 적용범위: 강도살인은 고의범 → 공동정범 성립엔 강도뿐 아니라 '살인'에 관한 고의의 공동 必 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공범 1인이 강도 기회에 피해자 살해]</span> 다른 공모자가 살인 공모 안 했어도, 살해·치사 결과 '예견' 불가한 경우 아니면 강도'치사' 죄책 면할 수 X<span class=\"cs-exam\">【변16·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[합동강도 중 1인이 살해]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①그 범인=강도살인 기수·미수</div><div class=\"cs-li\" style=\"margin-left:48px\">②다른 공범자도 살해 고의의 공동 있었으면 강도살인 기수·미수</div><div class=\"cs-li\" style=\"margin-left:48px\">③고의 공동 없으면: 사망 시 강도치사 / 강도살인 미수·상해만이면 강도상해·치상 / 무상해면 강도죄만 (단 예견가능성은 있어야)</div><div class=\"cs-h\">Ⅴ. 채무면탈 목적 강도살인죄의 성립여부<span class=\"cs-exam\">【모사23·16】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>상속인에게 채권의 존재를 확인할 방법이 '있는' 경우</strong> 판단기준 (判例) : 강도살인 성립엔 강도죄 성립(불법영득·이득의사) 要 '재산상 이익 취득'은 재산상 이익이 사실상 피해자에 불이익하게 범인·제3자 앞으로 이전되었다 볼 상태 必 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[채무 명백+상속인 존재+상속인이 채권 확인방법 확보]</span> 강도살인<span class=\"cs-x\"><strong>(X)</strong></span> — 채무면탈 목적 채권자 살해해도 일시적 추급 면함에 불과 → 재산상 이익 지배 이전 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[재물]</span> 불법영득의사가 살해 후 상당시간 지나 생김(살인 완료 후) → 별도 범의의 재물취거를 앞선 살인과 합쳐 강도살인으로 처단<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[처가 대여금 채권 알아 채무면탈 강도살인 불성립 → 이후 범의로 '재물' 가져간 것도 강도살인 X (사자 점유 계속되면 절도죄)]</span><span class=\"cs-exam\">【모사23】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>상속인에게 채권의 존재를 확인할 방법이 '없는' 경우</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[술값 채권 알려지지 않아 상속인이 채권 행사 가능성 X 상황에서 채무면탈 목적 살해]</span> 재산상 이익 취득 목적 살해 = 강도살인<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[채무면탈 목적 채권자 살해 후 반항능력 상실 이용 '즉석에서' 소지 재물까지 탈취]</span> 살인 이용 재물탈취 → 강도살인 <span class=\"cs-fact-tag\">[술값·택시비 면탈 살해는 상속인이 통상 채권 몰라 채무면탈 강도살인 성립 → 직후 재물취거도 포괄 강도살인(별도 절도 X)]</span></div><div class=\"cs-h\">◎ 성폭법위반<span class=\"cs-fact-tag\">[특수강도(강간·유사강간·강제추행·준강간·준유사강간·준강제추행)]</span> 정리표</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">강도강간 (형법 <span class=\"cs-stat\"><strong>§339</strong></span>) 신분('결합범'): 강도강간 행위: 강도 착수/미수·기수: 강간 형량: 무기 또는 10년 이상의 징역</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">특수강도강간 '등' (성폭법 <span class=\"cs-stat\"><strong>§4</strong></span>②) 신분('결합범'): 특수강도O(미수O), 특수강도의 준강도X 행위: 특수강도 착수/미수·기수: 강간(준강간)·유사강간(준유사강간)·강제추행(준강제추행) 형량: 사형, 무기징역 또는 10년 이상의 징역</div>", ["§334", "§339", "§4", "제338조", "제250조"], 3, "gak_절도강도"], ["개인040", "강도강간, 특수강도강간", "<div class=\"cs-h\">Ⅰ. 성폭법위반(강도강간)죄의 주체</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 성폭법위반(특수강도강제추행)죄 = 특수강도+강제추행 '결합범'으로 특수강도 신분 취득자가 새로운 고의로 강제추행에 나아갈 때 성립 → 주체는 <span class=\"cs-stat\"><strong>§334</strong></span> 특수강도범·특수강도미수범에 한정 <span class=\"cs-stat\"><strong>§335</strong></span>·<span class=\"cs-stat\"><strong>§342</strong></span>의 특수강도의 준강도범·준강도미수범은 주체<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[실제 '결합범']</span><span class=\"cs-exam\">【모사23】</span></div><div class=\"cs-h\">Ⅱ. 강간범이 강도·특수강도를 실행한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①강간범이 '강간 후' 특수강도 범의로 재물 강취 → 성폭법 <span class=\"cs-stat\"><strong>§3</strong></span>② 특수강도강간죄 의율<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②강간범이 '강간 후' 강도 범의로 재물 강취 → 강도강간 아니라 <span class=\"cs-crime\">강간죄</span>+<span class=\"cs-crime\">강도죄</span> 경합<span class=\"cs-exam\">【변18·13】</span></div><div class=\"cs-h\">Ⅲ. 강간범이 강간행위 종료 전 강도·특수강도 실행 후 계속 강간</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①강간범이 '강간행위 종료 전 실행행위 계속 중' 강도 → 이때 강도 '신분' 취득 → 그 자리서 강간 계속 시 강도강간죄</div><div class=\"cs-li\" style=\"margin-left:16px\">②특수강간범이 강간 종료 전 '특수강도' 행위 후 그 자리서 강간 계속 → 특수강도강간죄<span class=\"cs-exam\">【변26·22·19·18·13】</span> 폭행·협박으로 재물 탈취한 이상 피해자가 우연히 몰라도 강도죄 성립 → 강간 목적 폭행·협박으로 반항 억압 후 그 상태 계속 이용하여 재물 탈취 시, 재물탈취용 새 폭행·협박 없어도 강도죄 성립</div><div class=\"cs-h\">Ⅳ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[강도미수(재물 부재)+항거불능 피해자 간음 결의·강간 착수 미수+반항억압 폭행으로 상해]</span> 강도강간미수죄 + 강도치상죄 상상적 경합 <span class=\"cs-fact-tag\">[고의로 상해 시 강도강간미수죄 + 강도상해죄 상상적 경합]</span></div>", ["§334", "§335", "§342", "§3"], 2, "gak_절도강도"], ["개인041", "절도·강도의 죄수관계", "<div class=\"cs-h\">Ⅰ. 절도죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>절도죄의 죄수관계</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[범행장소·관리자 동일]</span> 단일범의로 시간·장소 접착, 같은 관리인 관리 하 방 안에서 소유자 다른 물건 절취 → 1개 절도죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[범행장소·관리자 상이]</span> A 집 방에서 A 재물 절취 + 세든 B 방 침입하여 재물 절취 → 장소·관리자 달라 실체적 경합범</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>주거침입죄와의 관계</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-stat\"><strong>§331</strong></span>② 특수절도(합동)는 주거침입이 구성요건 아님 → 절도범이 '주간'에 범행수단으로 주거침입 시 주거침입죄는 절도죄와 실체적 경합<span class=\"cs-exam\">【변16·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">①상습 단순절도범이 수단으로 '주간' 주거침입 → 주간 주거침입 위법성 평가는 <span class=\"cs-stat\"><strong>§332</strong></span>·<span class=\"cs-stat\"><strong>§329</strong></span> 구성요건에 미포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">②'단순 상습절도죄'범이 수단으로 '주간' 주거침입, 또는 상습절도 목적 '주간' 주거침입 후 절도 미이행·주거침입에 그친 경우 → 상습절도죄와 별개로 주거침입죄 구성<span class=\"cs-exam\">【변19·18·17】</span><span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">특가법 <span class=\"cs-stat\"><strong>§5의4</strong></span> '제6항' 상습절도 등 죄를 범한 경우 → 주거침입이 절도상습성 발현인 이상 각 주거침입은 상습절도 등 죄에 흡수, 별개 주거침입죄 구성 X<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>불가벌적 사후행위</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[불법영득의사 없이 자동차 일시사용]</span> 유류소비는 일시사용에 필연 부수 → 별개 절도죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자동차 절취 후 등록번호판 떼어냄]</span> 새로운 법익 침해 → 절도의 불가벌적 사후행위<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅱ. 준강도죄의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도가 체포면탈 목적 추격해온 수인에 같은 기회에 동시·이시 폭행·협박 → '준강도 포괄일죄'</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도미수범이 수인을 폭행, 그 중 1인이 경찰관 → 준강도미수 포괄일죄 + <span class=\"cs-crime\">공무집행방해죄</span> 상상적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도범이 여러 피해자에 같은 기회 폭행하여 그 중 1인에게만 상해 → 포괄하여 하나의 강도상해죄만 성립<span class=\"cs-exam\">【변24·19·18·17·15·14·12】</span></div><div class=\"cs-h\">Ⅲ. 강도죄의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">강도가 접착 상황에서 '가족을 이루는 수인'에 폭행·협박하여 집안 재물 탈취 → '가족 공동점유' → 소유자 불문 단일 강도죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">강도가 동일 장소·방법·접착 상황에서 수인의 재물 강취해도, 수인의 피해자에 폭행·협박하여 각자 점유·관리 재물을 각각 강취 → 피해자 수만큼 수개 강도죄 단 반항억압 폭행·협박이 사실상 공통이면 1개 행위로 상상적 경합 [①여관 종업원 폭행·협박 상해 중 나온 주인도 밀어넣어 금품 강취+안내실 종업원 현금 취거 → 강도상해죄+강도죄 상상적 경합</div><div class=\"cs-li\" style=\"margin-left:32px\">②안내실 주인 강도상해 후 각 객실 투숙객 강도 → 각 강도죄와 강도상해죄 실체적 경합]</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">강도가 한 개 강도범행 기회에 수명에 각 폭행·각 상해 → 각 피해자별 수개 강도상해죄, 실체적 경합<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅳ. 강도·준강도죄와 공무집행방해죄의 죄수관계<span class=\"cs-exam\">【모사19·18·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도범이 체포면탈 목적 경찰관에 폭행·협박 → 준강도죄 + <span class=\"cs-crime\">공무집행방해죄</span> 상상적 경합<span class=\"cs-exam\">【변19·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">강도범인이 체포면탈 목적 경찰관에 폭행 → 강도죄 + <span class=\"cs-crime\">공무집행방해죄</span> 실체적 경합</div>", ["§331", "§332", "§329", "§5"], 3, "gak_절도강도"], ["개인042", "사기죄 일반", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">[사법17]</span> <span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 고령의 무학자 A와 A 소유 토지 매매계약 체결 → 토지거래허가에 필요한 서류라 속여 A가 근저당권설정계약서에 서명·날인하게 하고 A의 인감증명서도 교부받음 → 사정을 모르는 B에게서 7,000만 원 차용하며 그 계약서·인감증명서로 甲을 채무자로 한 채권최고액 1억 원</div><div class=\"cs-li\" style=\"margin-left:0px\">근저당권설정등기를 B에게 경료. 甲의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [근저당권설정계약서에 서명·날인받은 행위 및 인감증명서를 받은 행위]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [A에 대한 사기죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 피기망자의 행위가 직접 재산상 손해를 초래하는 재산적 처분행위로 평가되고 이를 인식하고 한 것이라면 처분의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② A는 허가 서류로 알고 서명·날인 — 문서 내용을 몰랐어도 서명·날인으로 그 내용에 따른 손해가 초래됨 → 처분행위(O), 서명·날인 행위의 인식이 있었던 이상 처분의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 인감증명서 = 재산적 가치를 가져 형법상 '재물'(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 부동산을 담보로 쓸 재산상 이익 + 인감증명서 취득 → 포괄하여 A에 대한 사기죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [사문서위조죄의 간접정범]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 명의인을 기망해 문서를 작성케 하면 서명·날인이 정당히 성립해도 명의인을 이용해 서명·날인자의 의사에 반하는 문서를 작성케 한 것 → <span class=\"cs-crime\">사문서위조죄</span>(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲 = 사문서위조죄의 간접정범(<span class=\"cs-stat\"><strong>제231조</strong></span>, <span class=\"cs-stat\"><strong>제34조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [근저당권설정계약서를 이용한 행위]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [B에 대한 사기죄] 위조 계약서 + 편취 인감증명서로 사정 모르는 B에게서 7,000만 원 차용 → B에 대한 사기죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [위조사문서행사죄] B에게 위조 계약서 행사 → <span class=\"cs-crime\">위조사문서행사죄</span>(<span class=\"cs-stat\"><strong>제234조</strong></span>, <span class=\"cs-stat\"><strong>제231조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [공정증서원본불실기재죄 및 동행사죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 불실의 사실 = 권리의무관계에 중요한 의미를 갖는 사항이 진실에 반하는 것. 기재 사항이 부존재하거나 외관상 존재해도 무효 하자가 있으면 불실기재(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 계약서가 위조되어 甲·A 사이 의사 합치가 없어 무효 → 이를 이용해 돈을 빌리며 근저당권 설정 → <span class=\"cs-crime\">공정증서원본불실기재죄 및 동행사죄</span>(<span class=\"cs-stat\"><strong>제228조</strong></span> 제1항, <span class=\"cs-stat\"><strong>제229조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> A에 대한 사기죄 + B에 대한 사기죄 + 사문서위조죄 및 동행사죄 + 공정증서원본불실기재죄 및 동행사죄 → 모두 실체적 경합</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제347조(사기)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 기망하여 재물의 교부를 받거나 재산상의 이익을 취득한 자는 20년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 전항의 방법으로 제삼자로 하여금 재물의 교부를 받게 하거나 재산상의 이익을 취득하게 한 때에도 전항의 형과 같다.</div></div><div class=\"cs-h\">Ⅰ. 기망행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 기망은 법률행위 중요부분에 관한 것일 필요 X → 상대방을 착오에 빠뜨려 재산적 처분행위 하게 하는 판단의 기초사실에 관한 것이면 충분</div><div class=\"cs-li\" style=\"margin-left:16px\">①기망은 사람으로 하여금 착오 일으키게 하는 것 → 사람에 대한 기망 없으면 사기죄 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②카드론 대출 앱에 정보 입력→전산 자동처리로 송금, 직원 개입 없음 → 사람 기망 없어 사기죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">【모기25】</span> 불행 고지·길흉화복 긍정결과 약속하고 복비 등 대가 교부받음이 전통관습·종교행위 허용 한계 벗어나면 사기죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[차용금 용도·변제자금 마련방법 허위 고지]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 사실대로 고지했으면 상대방이 응하지 않았을 것인데 진실에 반하는 사실 고지하여 금전 교부받음 담보 제공했다는 사정만으로 달리 볼 수 X<span class=\"cs-exam\">【변사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[자동차 인도+이전등록 서류 교부 후 GPS로 재절취 의사]</span> 사기죄<span class=\"cs-x\"><strong>(X)</strong></span> — 피해자가 언제든 이전등록 가능케 한 이상 소유권 이전 의사 없다 볼 수 X<span class=\"cs-exam\">【변25·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[비의료인 개설 의료기관의 요양급여비 청구·수령]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> —</div><div class=\"cs-li\" style=\"margin-left:32px\">①적법 요양기관인 것처럼 건보공단에 청구</div><div class=\"cs-li\" style=\"margin-left:32px\">②개설 명의 빌려준 의료인이 환자에 요양급여 제공하게 해도 마찬가지<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[변호사가 대법관 로비자금 명목 금원 교부받음]</span> 사기죄 가능<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[도품임 고지 없이 처분(매도)]</span> 상대방에 사기죄(묵시적 기망) — 도품은 2년간 선의취득 제한(민<span class=\"cs-stat\"><strong>§250</strong></span>) <span class=\"cs-fact-tag\">[</span><span class=\"cs-crime\">장물범</span><span class=\"cs-fact-tag\">이 도품 처분해도 동일]</span><span class=\"cs-exam\">【모사15·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[연구비 공동관리계좌]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①처음부터 학생연구원 개별 지급의사 없이 공동관리계좌 처분권 가질 의도 숨기고 산학협력단에 연구비 신청·수령 → 산학협력단에 대한 편취</div><div class=\"cs-li\" style=\"margin-left:32px\">②원래 용도 부합·학생연구원 사실상 처분권 귀속·자발 의사로 조성·운용 시 → 사기죄 단정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[열차승차권(무기명증권) 절취자가 환불]</span> 기망 수반해도 절도죄 외 별도 사기죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 피기망자의 착오</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 기망으로 인한 착오 = 사실·법률관계·법률효과에 관한 것 불문</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 피해자가 법인·단체면 착오·인과관계는 대표 등 최종 의사결정권자 또는 실질 권한 위임받은 자 기준 판단</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대표자·최종결재권자가 기망 '안' 경우]</span> 사기죄<span class=\"cs-o\"><strong>(X)</strong></span> — 기망행위자와 동일·공모 등으로 기망 알았으면 착오 X, 처분행위 있어도 인과관계 X → <span class=\"cs-crime\">업무상횡령죄</span>·<span class=\"cs-crime\">업무상배임죄</span> 별론<span class=\"cs-exam\">【변23·22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대표자·최종결재권자가 '모른' 경우]</span> 실무자·일반 직원이 기망 알았어도 최종결재권자가 몰라 착오·처분에 이르면 → 법인에 대한 사기죄 성립에 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[용도 속여 국민주택 건설자금 대출]</span> 위탁은행 '일선 담당직원'이 용도 외 사용 알았어도 대출 승인권한은 은행장 → 은행장을 '피기망자'로 사기죄 성립</div><div class=\"cs-h\">Ⅲ. 피기망자의 처분행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 피기망자 ≠ 피해자여도 사기죄 성립 <span class=\"cs-fact-tag\">[삼각사기]</span><span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 처분행위는 하자 있는 의사라도 피기망자 의사에 의한 것 要 → 의사무능력자·무의식 상태 행위는 처분행위 X 피기망자가 처분행위 의미·내용 인식 못했어도, 그 행위(작위·부작위)가 직접 재산상 손해 초래하는 재산적 처분행위로 평가되고 그 행위를 피기망자가 인식하고 했다면 처분의사 인정 → 결과까지 인식해야 처분의사 인정되는 것 아님</div><div class=\"cs-li\" style=\"margin-left:16px\">①착오로 내심과 다른 효과 발생시키는 처분문서에 서명·날인하여 그 내용대로 재산상 손해 초래 → 사기죄 처분행위</div><div class=\"cs-li\" style=\"margin-left:16px\">②처분결과(문서 구체적 내용·법적 효과) 인식 못했어도 서명·날인 행위 인식 있었으면 처분의사 인정<span class=\"cs-exam\">【변25·24·20】</span><span class=\"cs-exam\">【모사24·22】</span> 처분행위 = 피해자가 자유의사로 직접 재산상 손해 초래하는 작위·부작위 → 착오로 채권 존재 몰라 행사 안 한 부작위도 처분행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[①3,000만원 담보서류로 잘못 알고 1억원 근저당권설정계약서 서명·날인]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[②토지거래허가 서류로 알고 다른 근저당권설정계약서 서명·날인]</span> 모두 처분행위·처분의사 인정<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[출판사가 출고현황표 조작해 실제 출판부수 속여 인세 일부만 지급→작가가 나머지 인세청구권 존재 자체 몰라 미행사 = 부작위 처분행위]</span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배당이의 1심 패소·항소한 자가 항소취하]</span> 즉시 1심 확정·상대방 배당금 수령 이익 → 항소취하는 재산적 처분행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[가압류집행 마친 자가 가압류 해제]</span> 소유자가 부담 없는 부동산 소유 이익 → 가압류 해제도 재산적 처분행위 이후 피보전채권 부존재 밝혀져도 재산상 이익 없었다 볼 수 X<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[타인 명의 등기서류 위조·등기공무원 제출로 소유권이전등기]</span> 사기죄<span class=\"cs-x\"><strong>(X)</strong></span> — 피해자 처분행위 없고 등기공무원에 처분권한 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사업자등록 명의 대여]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①명의대여로 피고인이 임대보증금반환채무 등 면하는 것 아님</div><div class=\"cs-li\" style=\"margin-left:32px\">②명의 대여만으로 채무 면하는 재산상 이익 취득의 재산적 처분행위 있다 보기 어려움<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅳ. 재물 또는 재산상 이익의 취득</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>재물</strong> 적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①대가 일부 지급·담보 제공돼도 편취액 = 차액 아니라 교부받은 금원 '전부'</div><div class=\"cs-li\" style=\"margin-left:16px\">②사기 특경법위반죄도 마찬가지</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>재산상 이익</strong> 적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①재산상 이익 = 적극적 이익(채권 취득·담보 제공) + 소극적 이익(채무 면제) 포함 기망으로 채권자가 채무 확정적 소멸·면제 특약 등 처분행위 시 채무면제라는 재산상 이익 사기죄</div><div class=\"cs-li\" style=\"margin-left:16px\">②후에 처분행위가 사기 이유로 취소 가능해도 마찬가지 기망으로 인한 이익이 결과적으로 누구에게 귀속하는지는 사기죄 성부에 영향 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[비트코인]</span> 사기죄 객체인 재산상 이익 해당<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[성행위 대가 지급 면함]</span> 부녀가 '금품 받을 전제로 성행위' 시 그 대가는 사기죄 객체인 경제적 이익 → 부녀 기망하여 대가 지급 면함 → 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[불법원인급여이나 사기죄 성립]</span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[전매 1회 제한 택지분양권 이중매도, 순차매수 B·C에 숨기고 자기 명의 형식 매매계약서 작성]</span> 甲이 직접 대금 수령 안 해도 B·C에 대한 사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[법원 기망하여 부재자 재산관리인 선임]</span> 재산상 이익 취득<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[재물의 사용·수익권]</span> 재물과 별개의 재산상 이익 보기 어려움 → 형법상 사기죄 보호 재산상 이익에 미포함 <span class=\"cs-neg-tag\">[임차 오피스텔 사용·수익 중 보증금 반환 약속에 속아 보증금 반환 안 받고 점유권 이전해도 재산상 이익 처분 아님 → 사기죄 X]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>기망행위에 의한 국가적 또는 공공적 법익 침해</strong> 판단기준 (判例) : 사기죄 보호법익은 재산권 → 기망으로 국가적·공공적 법익 침해된 사정만으로 사기죄 X 국가적·공공적 법익 침해라도 동시에 '재산권' 침해와 동일 평가 가능하면, 특별 처벌규정 없는 한 사기죄 성립 가능 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[기망으로 조세 포탈·환급·공제]</span> 형법상 사기죄<span class=\"cs-x\"><strong>(X)</strong></span> — 강제징수하는 국가·지자체의 권력작용을 재산권과 동일 평가 불가 → <span class=\"cs-crime\">조세범처벌법 위반죄</span> 별론<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[도급·물품구매조달계약 행정법규·입찰자격·계약절차 위반]</span> 기망행위 단정 X → 위반으로 계약 이행돼도 일의 완성 불가능할 만큼 위법이 일의 내용에 본질적인지 심리·판단 要 <span class=\"cs-neg-tag\">[국가기술자격증 대여·자본금 납입가장 숨김만으로 사기죄 X]</span></div><div class=\"cs-h\">Ⅴ. 피해자의 재산상 손해 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[불필요설]</span> 사기죄 본질은 기망에 의한 재물·재산상 이익 취득 → 상대방에 현실적 재산상 손해 발생 不要</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[금원 편취]</span> 기망에 의한 금원 교부 있으면 그 자체로 재산침해·사기죄 성립 → 상당한 대가 지급·전체 재산상 손해 없어도 영향 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[분식회계 재무제표로 금융기관 기망·대출]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 변제의사·능력, 충분한 담보, 전체 재산 무손해, 사후 대출금 상환해도 영향 X<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅵ. 인과관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: 사기죄 = 기망행위→착오·처분행위→재물·재산상 이익 취득, 그 사이 순차적 인과관계 존재 要<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 착오 원인에 피기망자 측 과실 있어도 사기죄 성립<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[금융기관 자체 신용조사와 무관한 대출]</span> 체계적 신용조사하는 금융기관이 대출 시, 대출 당시 변제능력 없고 자체 신용조사와 무관하게 차용인의 '변제하겠다'는 말만 믿고 대출 → 기망행위와 대출 사이 인과관계 인정<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변18】</span></div><div class=\"cs-h\">Ⅶ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 재물 교부 = 현실 인도 不要 → 재물이 범인 사실상 지배로 들어가 '자유로운 처분 가능 상태'면 교부<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[타인 명의 계좌·현금인출카드 소지]</span> 통장/도장은 명의인 보관·자신은 카드 소지 상태에서 명의인 기망하여 그 계좌로 송금하게 함 → 카드로 언제든 인출 가능하므로 송금받은 이상 기수 이후 명의인이 인출해도 범죄성립 후 사정일 뿐 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[전기통신금융사기]</span> 피해자 기망하여 사기이용계좌로 송금·이체받으면 편취 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">이미 취득한 재물·재산상 이득 사후 반환·변상해도 사기죄 성립에 영향 X</div><div class=\"cs-h\">Ⅷ. 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건:</div><div class=\"cs-li\" style=\"margin-left:16px\">①범의 인정엔 사기죄 성립요소 전부에 대한 인식 必</div><div class=\"cs-li\" style=\"margin-left:16px\">②재물·재산상 이익 취득이라는 결과 요소에 대한 인식까지 있어야 범의 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 기업경영자가 파산 채무불이행 가능성 인식했어도, 피할 수 있다 믿고 계약이행 노력 의사 있었으면 사기 고의 단정 X</div><div class=\"cs-li\" style=\"margin-left:16px\">①사기 공모공동정범이 기망방법 구체적으로 몰라도 공모관계 부정 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②자기 행위가 범죄에 이용되는 사실 모르고 나아간 경우 고의 없어 죄책 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[보이스피싱 현금수거책]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①공모·범의는 다른 공범과 순차·암묵 상통하여 피해자 현금 수거 사실 인식으로 족함</div><div class=\"cs-li\" style=\"margin-left:32px\">②미필적 인식 충분, 전체 범행방법·내용까지 구체적 인식 不要<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-h\">Ⅸ. 권리행사와 사기죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[불법영득(이득)의사 – 사취의 불법설]</span> 기망 수단 권리행사가, 권리행사 행위와 기망행위 전체적 관찰 시 사회통념상 권리행사 수단으로 용인 못할 정도면 사기죄 구성</div><div class=\"cs-h\">Ⅹ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">'동일 피해자'에 수회 기망·편취 시</div><div class=\"cs-li\" style=\"margin-left:32px\">①범의 단일·범행방법 동일이면 사기죄 포괄일죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">②범의 단일성·계속성 부정 또는 범행방법 상이면 각 실체적 경합범</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">피해자에 대가 지급된 경우, 그 대가를 다시 편취하거나 위탁받아 보관 중 횡령</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">→ 새 법익 침해 → 기존 사기죄와 별도 새 사기죄·<span class=\"cs-crime\">횡령죄</span> 성립<span class=\"cs-exam\">【변25·22】</span></div><div class=\"cs-h\">Ⅺ. 보론 – 편의시설부정이용죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[타인 전화카드(후불식 통신카드) 절취하여 전화통화 이용]</span> <span class=\"cs-crime\">편의시설부정이용죄</span> 불성립 — 피해자가 요금 납부 책임 부담 → '대가 지급 없이' 공중전화 이용에 해당 X<span class=\"cs-exam\">【변17】</span></div>", ["§250", "제231조", "제34조", "제234조", "제228조", "제229조", "제347조"], 3, "gak_사기공갈"], ["개인043", "불법원인급여와 사기죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사14】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">丙, 도박자금이 떨어지자 구경하던 丁에게 변제 의사 없이 높은 이자를 약속하고 도박자금을 빌려달라 함 → 丁은 丙의 상습도박 전과를 알면서 300만 원 대여 → 丙은 도박으로 전액 탕진.</div><div class=\"cs-li\" style=\"margin-left:0px\">丙과 丁의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [사기죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 도박자금 대여 = 불법원인급여 → 급여자는 반환 청구(X). 이때 사기죄 성부 — 부정설/긍정설, 판례 = 긍정설. 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 변제 의사 없이 차용 → 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [상습도박죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 상습도박 전과가 있는데도 도박 → 도박의 습벽(O) (상습성이 명확하지 않으나 출제의도 고려)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙 = <span class=\"cs-crime\">상습도박죄</span>(<span class=\"cs-stat\"><strong>제246조</strong></span> 제2항, 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [丁의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 도박의 상습성 = '행위'가 아니라 '행위자'의 속성(반복하는 습벽) → 부진정신분</div><div class=\"cs-li\" style=\"margin-left:0px\">② 비신분자가 부진정신분범에 가담한 경우 <span class=\"cs-stat\"><strong>제33조</strong></span> 본문·단서의 관계 — 진정·부진정신분범 구별설/성립·과형 구별설, 판례 = 성립·과형 구별설. 단서는 본문의 적용을 전제한다고 해석함이 문언에 충실 → 성립·과형 구별설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 판례에 의하면 丁 = <span class=\"cs-stat\"><strong>제33조</strong></span> 본문에 의해 상습도박방조죄 성립, <span class=\"cs-stat\"><strong>제33조</strong></span> 단서에 의해 단순도박방조죄의 형으로 처벌</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 급여자를 기망하여 불법한 급여를 하게 한 경우 급여자는 수익자에 반환청구 X(민법 <span class=\"cs-stat\"><strong>§746</strong></span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《기망으로 불법원인급여를 하게 한 수익자에게 사기죄가 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(반환청구 불가 → 법이 보호할 재산상 손해 부존재 → 불성립)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(반환청구권 존재는 사기죄 요건 아님 → 성립)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 기망으로 불법원인급여 재물 제공케 한 경우 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 반환청구 불가해도 무방<span class=\"cs-exam\">【변22·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 수익자는 기망으로 재물·이익 취득 → 형법 독자적 관점서 사기죄 인정 → 긍정설 타당</div></div>", ["§746", "제347조", "제246조", "제33조"], 1, "gak_사기공갈"], ["개인044", "부작위에 의한 사기죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사15】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 아파트를 A에게 6억 원에 매도하고 계약금 6,000만 원 수령. A가 잔금 지급 시 수표를 잘못 세어 1억 원권 5장 + 1,000만 원권 5장 교부 → 甲은 현장에서 세어보고</div><div class=\"cs-li\" style=\"margin-left:0px\">1,000만 원 초과 지급을 알았음에도 돌려주지 않음. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\">① 매도인이 사실대로 고지했다면 매수인이 초과 교부하지 않았을 것임이 경험칙상 명백 → 잔금을 '교부받기 전 또는 교부받던 중' 알게 되었으면 고지할 신의칙상 의무 有 → 사기죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② A가 초과 지급을 알았다면 그 법률행위를 하지 않았을 것이 명백 → 甲은 현장에서 세어보고 초과를 알았으므로 고지의무(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲 = 부작위에 의한 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 부작위에 의한 사기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 부작위 기망 = 법률상 고지의무 있는 자가 상대방이 착오에 빠져 있음을 알면서 고지 X<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 고지의무 = 법령·계약·관습·조리 → 거래실정·신의칙으로 결정 상대방이 고지받았더라면 거래에 임하지 않았을 관계 인정 시 → 신의칙상 고지의무<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 초과 지급된 금원 수령<span class=\"cs-exam\">【변사15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[교부 전/중 인식]</span> 신의칙상 고지의무<span class=\"cs-o\"><strong>(O)</strong></span> → 사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[교부 완료 후 인식]</span> 편취수단 의미 X → 사기죄<span class=\"cs-x\"><strong>(X)</strong></span> (<span class=\"cs-crime\">점유이탈물횡령죄</span> 별론)</div><div class=\"cs-h\">Ⅲ. 목적물의 하자를 고지하지 않은 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>판례 법리 (부작위 기망)</strong> 판단기준 (判例) : 매수인 권리확보 위험 알면서 미고지·계약체결·대금수령 +<span> </span>고지받았다면 계약/지급 안 했을 것 명백 → 신의칙상 고지의무<span class=\"cs-o\"><strong>(O)</strong></span> 매매 법률관계에 영향 없어 권리실현 장애 안 되는 사유 → 고지의무<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>구체적 판례</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[경매진행중 임대차, 임차인 등기열람 가능]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변21·18·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[도시계획 협의매수·수용 예정 미고지]</span> 부작위 사기죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변18·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[가맹점주 허위 매출전표 미고지·대금청구]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 변제의사·능력 있어도 무방<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[이면약정 감춘 채 집단 중도금대출 교섭·수령]</span> 부작위 기망<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[이중매매, 제1계약 해제불가 사정 미고지]</span> 기망<span class=\"cs-x\"><strong>(X)</strong></span> — 제2매수인 권리실현 장애 아님 (이중양도담보도 同)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[중고차 할부금채무 미고지]</span> 부작위 기망<span class=\"cs-x\"><strong>(X)</strong></span> — 채무 당연승계 아님<span class=\"cs-exam\">【변24·18·13】</span></div>", ["제347조"], 3, "gak_사기공갈"], ["개인045", "보험사기", "<div class=\"cs-h\">Ⅰ. 착수 시기</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>원칙 – 보험금 '청구한 때'(계약체결만으로 착수 X)</strong> 개념: <span class=\"cs-fact-tag\">[청구시]</span> 기존 보험 이용·보험사고 야기·보험금 청구 → '청구한 때' 착수<span class=\"cs-exam\">【변15·13】</span> 판단기준 (判例) : 상법상 고지의무 위반 계약체결 사정만으로 편취 기망행위 단정 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[유효요건 흠결 계약(제3자가 피보험자 가장)]</span> 계약체결만으로는 편취 기망 착수<span class=\"cs-x\"><strong>(X)</strong></span> — 예비행위 불과, 후에 정범 실행 나아가면 방조범 성립 가능<span class=\"cs-exam\">【변16, 변기22】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>예외 – 계약'체결만'으로 착수 O</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[보험사고 기발생 묵비/개연성 농후 인식/사고 조작의도 계약]</span> 기망행위<span class=\"cs-o\"><strong>(O)</strong></span> — '보험사고 우연성' 등 본질 해할 정도</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[과거병력·치료이력 묵비, 향후 치료 개연성 농후]</span> 기망<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[약관상 고지의무 질병 미고지·계약 후 바로 그 질병으로 청구]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 보험사 과실·해제가능해도 무방<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[당뇨·고혈압 발병 숨기고 계약]</span> 계약체결시 기망<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 기수 시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[수령시]</span> 보험금 지급받은 때 기수<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[경미한 상해 과장·장기입원·과다 보험금 수령]</span> '보험금 전체' 사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div>", [], 2, "gak_사기공갈"], ["개인046", "사기와 책략절도", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-o\">(25)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 02:20경 거리·편의점 안에 사람이 없자 물건을 훔치려 편의점 입장. 사는 척하며 기회를 엿보던 중 주인 A가 바닥에 떨어진 B의 지갑을 발견, \"선생님 지갑이 맞느냐\" 묻자 \"내 것이 맞다\"고 답해 교부받음. 이어 대금 지불 의사 없이 담배 1보루를 받아 신용카드를 찾는 척하다, 다른 손님이 A에게 물건 위치를 묻는 틈에 담배·지갑을 갖고 도주.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (25점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [건조물침입죄의 성립여부]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 일반인 출입이 허용된 음식점에 영업주 승낙을 받아 통상적 출입방법으로 들어갔다면, 범죄 목적이었거나 알았다면 승낙하지 않았을 사정이 있어도 출입 당시 객관적·외형적 행위태양상 사실상 평온을 해쳤다고 평가할 수 없어 침입(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 야간건조물침입절도죄(<span class=\"cs-stat\"><strong>제330조</strong></span>)의 건조물침입 판단에도 같은 법리 적용</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 절도 목적이어도 평온상태 침해 사정(X) → 건조물침입죄(<span class=\"cs-stat\"><strong>제319조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [사기죄와 절도죄의 성립여부]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [사기와 절도의 구별]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 절취 = 점유자의 의사에 반해 점유를 배제하고 자기·제3자의 점유로 옮김 ↔ 기망으로 처분행위를 하게 해 취득 = 사기죄</div><div class=\"cs-li\" style=\"margin-left:0px\">② 외관상 교부가 있어도 재물이 범인의 사실상 지배 아래 들어가 자유로운 처분이 가능한 상태에 놓이지 않고 여전히 피해자 지배 아래면 처분행위(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [지갑의 경우]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 삼각사기에서 피기망자와 피해자의 관계 — 권한설/지위설, 판례 = 지위설</div><div class=\"cs-li\" style=\"margin-left:0px\">② A는 습득한 지갑을 소유자 B에게 돌려줄 지위 → 처분 권능·지위(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲이 자기 것이라 기망 → A가 그 권능·지위에 기초해 교부 → 甲이 자유로운 처분 가능 상태 → 처분행위(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲 = 지갑의 진정한 주인 B에 대한 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [담배의 경우]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 외관상 교부는 있었으나 결제 전까지는 여전히 A의 지배 아래 → 처분행위(X) (담배는 소유자와 피기망자가 모두 A)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲 = A에 대한 절도죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 건조물 '침입'(X)이므로 야간주거침입절도죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 지갑 소유자 B에 대한 사기죄 + 담배 소유자 A에 대한 절도죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 사기와 책략절도</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 절취 = 타인 점유 타인 소유물을 '점유자 의사에 반하여' 점유배제·이전 기망으로 '처분행위'케 하여 재물·이익 취득 시 → 절도 아닌 사기</div><div class=\"cs-h\">Ⅱ. 사기죄의 처분행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 피기망자 의사에 기초한 행위로 재물·이익 취득 평가 시 → 처분행위 인정 처분행위 = 기망에 따라 착오로 사실상 지배를 범인에게 이전 → 외관상 교부 있어도 여전히 피해자 지배 하로 평가되면 처분행위 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[금괴 운반책, 피해자가 감시자 고용해 이동 감시·관리]</span> 사실상 지배 취득<span class=\"cs-o\"><strong>(X)</strong></span> → 처분행위·편취<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[지문인식 조회 빙자, 현금 비닐봉지 현관문 손잡이에 걸어둠]</span> 사실상 지배 이전<span class=\"cs-o\"><strong>(X)</strong></span> → 사기 무죄, 절도 성립</div><div class=\"cs-h\">Ⅲ. 피기망자의 처분 권능 또는 지위 (피해자≠피기망자)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《삼각사기에서 피기망자가 피해자와 어떤 관계여야 피해자 재산 처분 가능한지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①권한설(피해자 재산 처분할 법적 권한 필요)</div><div class=\"cs-li\" style=\"margin-left:16px\">②지위설(사실상 처분 지위면 족)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[지위설]</span> 피기망자가 피해자 위해 재산 처분할 '권능'·'지위' 있어야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 처분행위는 유효 법률행위 한정 X, 하자 있는 법률행위·사실행위 포함 → 지위설 타당</div></div><div class=\"cs-h\">Ⅳ. 절도 판례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[금방서 귀금속 구입 가장·건네받아 화장실 핑계 도주]</span> 절도죄<span class=\"cs-o\"><strong>(O)</strong></span> — 도주 전까지 피해자 점유<span class=\"cs-exam\">【변24·13, 변사24, 모사24·21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[예식장 신부측 축의금 접수인 행세·교부받음]</span> 접수처 점유 침탈 절도죄<span class=\"cs-o\"><strong>(O)</strong></span> — 교부취지는 '신부측' 전달, '피고인'에 처분권 준 것 아님</div><div class=\"cs-h\">Ⅴ. 사기 판례 (주위적 절도 무죄, 예비적 사기 유죄)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[매장주인이 습득한 손님 지갑, \"선생님 지갑 맞냐\"에 \"내 것\" 답하고 교부받음]</span> 사기죄<span class=\"cs-o\"><strong>(O)</strong></span> — 매장주인은 소유자에 돌려줄 지위 → 소유자 위해 처분할 권능·지위 O → 처분행위 O, 절취로 평가 X<span class=\"cs-exam\">【변26, 모사25·24, 변기24】</span></div><div class=\"cs-h\">◎ 사기와 책략절도 정리표</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">구분: 유형 / 처분권능·지위(피해자≠피기망자) / 처분행위(사실상 지배 이전) / 결론 <span class=\"cs-fact-tag\">[편의점 점원서 담배 교부받고 대금 미지급 도주]</span> 권능·지위 O / 처분행위 X(여전히 피해자 지배) / 절도 <span class=\"cs-fact-tag\">[금방서 목걸이 건네받아 화장실 핑계 도주]</span> 권능 문제안됨(피해자=피기망자) / 처분행위 X / 절도<span class=\"cs-exam\">【변사24, 모사24】</span> <span class=\"cs-fact-tag\">[피해자 책 잠깐 본다며 보는 척하다 가져감]</span> 피해자=피기망자 / 처분행위 X / 절도 <span class=\"cs-fact-tag\">[금괴 운반책에 외관상 교부하나 감시자 둠]</span> 피해자=피기망자 / 처분행위 X / 절도 <span class=\"cs-fact-tag\">[지문인식 조회 빙자, 현금 현관문 손잡이에 걸어둠 후 가져감]</span> 피해자=피기망자 / 처분행위 X / 절도 <span class=\"cs-fact-tag\">[상점서 '다른 손님'에게 타 손님 놓아둔 돈 집어달라 함]</span> 권능 X(권능·지위 없음) / 처분행위 O / 절도(간접정범)<span class=\"cs-exam\">【모사18】</span> <span class=\"cs-fact-tag\">[지갑 습득 상점주인에게 자기 것이라 속여 받아감]</span> 권능 O / 처분행위 O / 사기(절도 무죄)<span class=\"cs-exam\">【모사25·24, 변기24】</span></div>", ["제330조", "제319조", "제347조"], 2, "gak_사기공갈"], ["개인047", "사기의 도구로 이용된 자에 대한 사기죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사19】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲·乙 보이스피싱 공모. 甲은 A에게 \"검찰청 수사관이다. 네 명의 계좌가 범죄에 이용돼 곧 돈이 들어온다. 그 돈 포함 전액을 인출해 검찰청 앞으로 와라\". 乙은 B에게 \"서초경찰서 경찰이다. 개인정보가 유출됐으니 안전한 계좌로 옮겨야 한다\"며 A 명의 계좌번호를 알려줌. B가 A 계좌로 1,000만 원 이체 → A가 그 돈 포함 전액 1,500만 원을 인출해 甲에게 교부.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲과 乙의 죄책은? (15점) [(저자)전기통신금융사기 특별법(약칭)은 논외로 함]</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [공동정범]</strong> 공모 + 각 실행행위 분담 → 사기죄의 공동정범(<span class=\"cs-stat\"><strong>제30조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [B에 대한 사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 피기망자의 행위가 직접 재산상 손해를 초래하는 재산적 처분행위로 평가되고 이를 인식하고 한 것이라면 처분의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② B는 안전한 계좌로 옮긴다고 믿고 이체 — 실제 결과를 인식 못했어도 이체로 손해가 초래되었고 이체 행위의 인식은 있었음 → 처분행위·처분의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲·乙 = B에 대한 1,000만 원 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)의 공동정범</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [A에 대한 사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [500만 원 부분] 검찰청 수사관을 사칭해 A의 돈 500만 원을 교부받음 → A에 대한 사기죄의 공동정범(위 처분행위·처분의사 판례)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [B가 A의 계좌로 이체한 1,000만원 부분]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 피해자에 대한 사기범행의 실현 수단으로 편취물을 전달하는 도구로만 이용된 타인에게는 사기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② A는 B에게서 편취한 1,000만 원의 전달 도구일 뿐 → B에 대한 사기죄만 성립, 도구로 이용된 A에 대해 별도 사기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲·乙 = A에 대한 500만 원 사기죄 + B에 대한 1,000만 원 사기죄 각 공동정범의 실체적 경합</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[도구 이용자에 사기죄 X]</span> 피해자에 대한 사기범행 실현수단으로 타인을 기망해 편취 재물·이익 전달 도구로서만 이용 → 피해자에 대한 사기죄 성립할 뿐, 도구로 이용된 타인에 대한 사기죄 별도 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·20·18】</span></div>", ["제30조", "제347조"], 1, "gak_사기공갈"], ["개인048", "소송사기", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A에게서 X토지를 매수한 사실이 없는데 A가 사망하자 A와의 매매계약서를 만들어 A를 상대로 소유권이전등기청구의 소를 제기하며 이를 증거로 첨부. 소장에 A의 주소를 허위</div><div class=\"cs-li\" style=\"margin-left:0px\">기재해 소장 등을 자신이 수령하는 방법으로 승소판결. 甲의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [사문서위조죄 및 동행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 허무인·사망자 명의 문서를 위조해도 사문서위조죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 사망한 A 명의 매매계약서를 만들어 소장에 첨부 → 사문서위조죄 및 동행사죄(<span class=\"cs-stat\"><strong>제231조</strong></span>, <span class=\"cs-stat\"><strong>제234조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사망자를 상대로 한 소송사기 — 위 학설과 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [위계공무집행방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 피고의 주소를 허위 기재해 법원공무원이 소환장을 허위주소로 송달케 한 사실만으로는 <span class=\"cs-crime\">위계공무집행방해죄</span>(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 위계공무집행방해죄(<span class=\"cs-stat\"><strong>제137조</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = 사문서위조죄 + 위조사문서행사죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 소송사기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 허위 내용 소송제기·법원 기망 고의 시 → 허위증거 없어도 당사자 주장이 법원 기망에 충분하면 기망수단<span class=\"cs-o\"><strong>(O)</strong></span> 소송사기 성립: 채권 부존재만으로 부족 +<span> </span>부존재 잘 알면서 허위 주장·증명으로 법원 기망 인식 必 단순 사실오인·법률평가 오류로 존재 믿은 경우 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[소송·조정절차 주장]</span> 범행 인정 외에는, 주장이 객관적으로 명백히 허위 +<span> </span>거짓 인식/증거조작 인정 등 범죄성립 명백한 경우 아니면 유죄 인정 X — 조정절차상 다소간 허위·과장 언행이 신의칙상 허용범위 내면 기망 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[회생계획인가결정]</span> 허위로 법원 기망해 유리한 인가결정 → 사기죄 성립 가능 단 주장이 인가요건과 밀접·인가 여부·내용 달라질 정도여야</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[소송비용액확정결정]</span> 허위로 유리한 결정 받으면 사기죄 성립 가능 단 '당사자비용'은 소명자료 조작 없이 실제와 다른 비용액 주장만으로는 기망 단정 곤란<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅱ. 법원의 처분행위</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>사자를 상대로 한 소송사기<span class=\"cs-exam\">【모사21·17, 변기16】</span></strong> <span class=\"cs-issue\">《사자 상대 소송제기 시 사기죄 성립여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①불능범설(결과발생 불가·위험성 없음)</div><div class=\"cs-li\" style=\"margin-left:16px\">②불능미수설(위험성 있음)</div><div class=\"cs-li\" style=\"margin-left:16px\">③무죄설(기망행위로 평가 불가, 위험성 불문 무죄)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[무죄설]</span> 사망자 상대 판결은 효력 없어 상속인에게 미치지 않음 → 법원 재판이 피해자 처분행위에 갈음하는 내용·효력 없음 → 사기죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 사자 상대 소송은 법원 재판이 처분행위에 갈음하는 효력 없음 → 무죄설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>구체적 판례</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[소유권보존등기 명의자 상대 말소소송·허위 주장]</span> 승소확정 시 단독으로 말소 후 보존등기 가능 → '방해제거·소유명의 취득 지위'라는 재산상 이익 취득, 기수시기=판결 확정시<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[소유권이전등기 명의인 상대 말소소송·허위 주장]</span> 승소 시 자기 등기명의 회복 → 말소등기청구 소제기가 실행착수<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[미등기건물, 건축허가명의자 甲 상대 채권자 乙이 강제경매 신청·보존등기]</span> 사기죄<span class=\"cs-o\"><strong>(X)</strong></span> — 재판·보존등기 효력이 진정한 원시취득 소유자에 미치지 않음 → 법원 재판이 처분행위에 갈음하는 효력 X<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅲ. 원고의 소송사기 착수와 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[소제기시]</span> 권리 부존재 알면서 법원 기망 인식으로 '소를 제기하면' 착수, 소장 유효송달 不要 — 상대방 주소 허위기재로 타인이 서류 받아 소송 진행된 경우도 同</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[집행 O]</span> 강제집행 소송사기는 집행절차 개시신청 또는 진행중 배당신청 시 착수</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[압류 O]</span> 허위채권 공정증서 집행권원으로 소유권이전등기청구권 압류신청 시 착수<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[경매 O]</span> 유치권 경매신청자는 피담보채권액 기초 배당 → 허위로 부풀린 유치권 경매신청은 착수<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[임차권등기명령]</span> 임대차 통정허위표시 무효라도 외형상 우선변제권 취득 = 재산상 이익 → 허위 임대차계약서로 임차권등기명령 신청 시 착수<span class=\"cs-exam\">【변17·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[가압류 X]</span> 가압류는 보전방법 불과 → 허위채권 피보전권리 가압류만으로는 현실적 청구 의사표시 X → 본안 미제기 시 착수 X<span class=\"cs-exam\">【변19·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[소송사기미수 종료시기]</span> 패소 종국판결 확정 등 소송 종료된 때 (공소시효는 범죄행위 종료 때부터 진행)</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수</strong> 개념: <span class=\"cs-fact-tag\">[판결확정시]</span> 소유권이전등기 이행청구소송 승소판결 '확정된 날' 기수 判例(죄수관계): 법원 기망·승소확정판결로 소유권이전등기 경료 시 → 사기죄와 별도로 <span class=\"cs-crime\">공정증서원본불실기재죄 및 동행사죄</span> 성립(실체적 경합)</div><div class=\"cs-h\">Ⅳ. 피고의 소송사기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[착수]</span> 적극적으로 법원 기망 의사로 허위서류 증거제출·주장 답변서·준비서면 '제출' 시 <span class=\"cs-fact-tag\">[기수]</span> 허위서류 작성·증거제출·위증 등 적극적 방법으로 법원 기망·착오케 하여 '승소확정판결'로 재산상 의무이행 면한 경우 사기죄 성립</div><div class=\"cs-h\">Ⅴ. 친족상도례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[법원 아닌 제3자가 피해자]</span> 사기죄 보호법익은 재산권 → 피기망자인 법원은 피해자 될 수 없고 재물 편취당한 제3자가 피해자 → 제3자와 범인이 직계혈족이면 <span class=\"cs-stat\"><strong>제354조</strong></span>·<span class=\"cs-stat\"><strong>제328조</strong></span> 제1항으로 형 면제 (형면제는 헌법불합치)</div>", ["제231조", "제234조", "제347조", "제137조", "제354조", "제328조"], 3, "gak_사기공갈"], ["개인049", "공갈죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사12】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 甲에게 5,000만 원을 빌려주고 못 받자 甲에게 전화해 '돈을 갚지 않으면 아들을</div><div class=\"cs-li\" style=\"margin-left:0px\">등교 길에 유괴할 수도 있다'고 말함 → 甲이 경찰에 신고해 돈은 받지 못함. 乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\">[변사12 변형]</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [공갈죄의 협박]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공갈죄의 협박 = 의사결정의 자유를 제한하거나 의사실행의 자유를 방해할 정도로 겁먹게 할 만한 해악의 고지</div><div class=\"cs-li\" style=\"margin-left:0px\">② '제3자'에 대한 법익 침해를 내용으로 해도 '피해자 본인과 제3자가 밀접한 관계'에 있어 본인에게 공포심을 일으킬 정도면 협박(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ '아들을 등교 길에 유괴할 수도 있다' → 공갈죄(<span class=\"cs-stat\"><strong>제350조</strong></span> 제1항)의 협박(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [공갈죄의 불법영득의사]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 권리행사 수단으로 해악을 고지한 경우 공갈죄 성부 — 긍정설(갈취의 불법설)/부정설(영득의 불법설), 판례 = 긍정설. 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 5,000만 원 대여금채권이 있어도 사회통념상 허용 범위를 넘는 협박 → 불법영득의사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 사회상규에 위배되지 않는 행위에도 해당(X) → <span class=\"cs-stat\"><strong>제20조</strong></span>로 위법성 조각(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲의 신고로 돈을 받지 못함 → 乙 = 공갈미수죄(<span class=\"cs-stat\"><strong>제352조</strong></span>, <span class=\"cs-stat\"><strong>제350조</strong></span> 제1항, <span class=\"cs-stat\"><strong>제25조</strong></span>) &lt;!-- 원문 p338 ☞결론 문장은 \"甲은 공갈미수죄…\"로 인쇄되어 있으나, 이 사안의 행위자(협박자)는 乙이므로 '乙'이 맞음(원문 오기로 보임). 2단계 검수 시 확인. --&gt;</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제350조(공갈)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사람을 공갈하여 재물의 교부를 받거나 재산상의 이익을 취득한 자는 10년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 전항의 방법으로 제삼자로 하여금 재물의 교부를 받게 하거나 재산상의 이익을 취득하게 한 때에도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제350조의2(특수공갈)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제350조의 죄를 범한 자는 1년 이상 15년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">(폭처법) 제2조</div><div class=\"cs-li\" style=\"margin-left:0px\">② 2명 이상이 공동하여 다음 각 호의 죄를 범한 사람은 「형법」 각 해당 조항에서 정한 형의 2분의 1까지 가중한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">　3<span>.</span> 「형법」 제257조 제1항(상해)·제2항(존속상해), 제276조 제2항(존속체포, 존속감금) 또는 제350조(공갈)의 죄</div></div><div class=\"cs-h\">Ⅰ. 공갈 (<span class=\"cs-stat\">§350</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 협박 = 의사결정 자유 제한 또는 의사실행 자유 방해할 정도로 겁먹게 할 해악 고지</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[적법 O]</span> 고지 내용이 위법하지 않아도 해악 될 수 있음 <span class=\"cs-fact-tag\">[언어·거동 O]</span> 명시 방법 不要, 언어·거동으로도 가능 <span class=\"cs-fact-tag\">[간접적 O]</span> 직접 아니어도 제3자 통해 간접적으로도 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[불법한 위세 이용]</span> 직업·지위 기해 재물·이익 요구, 불응 시 부당한 불이익 위구심 야기 → 해악의 고지<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[소비자불매운동 고지]</span> 전체 법질서상 용인 못할 정도로 사회적 상당성 못 갖추면 강요죄·공갈죄 협박에 포섭 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[신력·길흉화복]</span> 천재지변·신력·길흉화복도 해악 포함 가능 단 행위자가 이를 사실상 지배·영향 미칠 수 있다고 믿게 하는 명시·묵시 행위 있어야 성립 <span class=\"cs-neg-tag\">[조상천도제 안 지내면 나쁜 일 생긴다 고지·천도비용 수령(X)]</span></div><div class=\"cs-h\">Ⅱ. 피공갈자의 처분행위</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>처분행위</strong> 성립요건: 재산상 이익 공갈죄 = 공갈행위로 피공갈자가 재산상 이익 공여하는 처분행위 있어야 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부작위 O]</span> 처분행위는 부작위로도 족 → 외포심에 묵인하는 동안 공갈자가 직접 탈취해도 성립 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[단순도주 X]</span> 피해자 처분행위 없이, 의무 있는 재산상 이익 공여 면하려 폭행·도주로 상대방의 이익 실현에 장애만 발생 → 공갈죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[택시요금 지급 요구 피해자 때리고 달아난 사안]</span><span class=\"cs-exam\">【변기13】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>삼각공갈</strong> 적용범위: 공갈 상대방≠피해자 가능, 단 재물·이익을 처분할 '사실상·법률상 권한 또는 지위'에 있어야</div><div class=\"cs-h\">Ⅲ. 재물 또는 재산상 이익의 취득</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>재물<span class=\"cs-exam\">【모사20, 변기26, 모기25】</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자기 재물 X]</span> 공갈죄 대상은 타인 재물 → 공갈해 자기 재물 교부받으면 공갈죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[특정된 절취금전]</span> 절취금전만 소지 등 구체적 특정 가능해 명백히 구분되는 예외적 경우 → 절도 피해자 관계서 그 금전은 절도범 타인의 재물이라 할 수 없음<span class=\"cs-exam\">【변18】</span> → 절도 피해자가 절도범 공갈해 그 돈 교부받아도 타인 재물 갈취 아님 → 공갈죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>재산상 이익</strong> 적용범위: 이득액 = 불법영득 대상 재물·이익의 가액, 기수시기 기준 산정 이후 사정변경(예견 가능해도) 불고려 <span class=\"cs-fact-tag\">[5억 이상 특경법 적용]</span></div><div class=\"cs-h\">Ⅳ. 재산상 손해의 발생 – 불필요</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 하자 있는 의사에 기한 재물 교부 자체가 공갈죄 재산상 손해 → 전체재산 감소 요구 X</div><div class=\"cs-h\">Ⅴ. 공갈죄의 착수와 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[착수]</span> 수단인 폭행·협박 개시된 때 <span class=\"cs-fact-tag\">[기수]</span> 지정 예금구좌에 입금케 하면 자유처분 가능 상태 → 기수<span class=\"cs-exam\">【변23】</span> <span class=\"cs-fact-tag\">[기수]</span> 부동산 공갈은 소유권이전등기 경료받은 때 기수 (이전등기 서류 교부받은 때 X)</div><div class=\"cs-h\">Ⅵ. 권리행사와 공갈죄<span class=\"cs-exam\">【변사12, 모사20·18, 모기25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>권리행사와 공갈죄</strong> <span class=\"cs-issue\">《권리행사 수단으로 해악 고지 시 공갈죄 성립여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(불법영득의사=갈취의 불법 → 외관상 권리행사라도 실질 권리남용이면 성립)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(불법영득의사=영득의 불법 → 정당한 권리 있으면 강요·폭행·협박죄만 성립, 공갈죄 X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 정당한 권리 실현수단이라도 그 수단·방법이 사회통념상 허용 정도·범위를 넘으면 공갈죄 착수 <span class=\"cs-fact-tag\">[공갈죄 성립]</span><span class=\"cs-exam\">【변17·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 불법영득의사=갈취의 불법 → 긍정설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>정당한 권리자의 권리실행 상당 수단인 경우</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[고소권 행사 수반]</span> 정당한 권리자의 권리실행 수단으로 인정될 여지 있으면, 권리남용 정도의 특별사정 없는 한 공갈죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[합의금 불응 시 불이익 언동·고소했으나 성폭력 성립 미증명이어도 당연히 해악 고지 아님]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>정당한 권리행사 범위를 넘는 경우</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[동거 정산·금전채권 있어도 권리행사 빙자, 사회통념상 용인 어려운 협박]</span> 공갈죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[기망으로 비싸게 매수한 자가 계약 취소 없이 전매차익 받아낼 셈으로 협박]</span> 정당 범위 넘어 공갈죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[교통사고 손해배상청구권 기화로 운전사 바뀐 것 알고 과다 금원 요구·신고 태도로 외포·교부]</span> 공갈죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공사현장서 일행과 집기 손괴·신용 훼손 게시 태도, 원상회복·손배청구권 실현 목적이라도 사회통념 허용범위 넘음]</span> 공갈죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-h\">Ⅶ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈죄 포괄일죄]</span> 동일 피해자에 단일·계속된 범의로 범행 → 포괄일죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈죄와 사기죄]</span> 협박·기망 동시 사용 시 의사형성에 영향 준 요소에 따라 공갈죄 또는 사기죄 / 우열 못 가리면 상상적 경합<span class=\"cs-exam\">【모사16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈죄와 횡령죄]</span> 공갈해 재물 교부케 하면 공갈죄 성립, 이후 소비·처분해도 횡령죄 X<span class=\"cs-exam\">【모사16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈죄와 협박죄]</span> 수단인 협박은 공갈죄에 흡수 → 별도 협박죄 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈죄와 도박죄]</span> 도박행위가 공갈 수단이어도 공갈죄에 흡수 X <span class=\"cs-fact-tag\">[실체적 경합]</span> <span class=\"cs-fact-tag\">[\"돈 안 주면 도박죄로 신고\" 협박]</span><span class=\"cs-exam\">【변25】</span></div>", ["§350", "제350조", "제20조", "제352조", "제25조", "제2조", "제257조", "제276조"], 3, "gak_사기공갈"], ["개인050", "컴퓨터등사용사기죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제347조의2(컴퓨터등 사용사기)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">컴퓨터등 정보처리장치에 허위의 정보 또는 부정한 명령을 입력하거나 권한 없이 정보를 입력·변경하여 정보처리를 하게 함으로써 재산상의 이익을 취득하거나 제3자로 하여금 취득하게 한 자는 20년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">&lt;!-- 원문 헤더에 \"변기20\"이 실제로 두 번 인쇄되어 있음(고해상도 확인 완료). --&gt;</div><div class=\"cs-h\">Ⅰ. 허위의 정보 또는 부정한 명령을 입력하거나 권한 없이 정보를 입력·변경</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[프로그램 오류 이용]</span> 전자복권시스템 환불명령·구매명령 반복해 오류로 가상현금 입금 → '허위정보 입력'은 아니어도 프로그램 오류를 적극 이용해 정당하지 않은 사무처리 → '부정한 명령의 입력'<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[통화·접속버튼]</span> 휴대전화 통화·인터넷 접속버튼만 누른 것은 정보·명령 입력·정보처리 X → 컴사기<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사15】</span></div><div class=\"cs-h\">Ⅱ. 정보처리를 하게 함으로써 재산상의 이익을 취득하거나 제3자로 하여금 취득</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '정보처리' = 사기죄의 처분행위에 상응 → 허위정보 등으로 계산·데이터 처리되어 직접 재산처분 결과 초래해야 하고, 이익취득은 사람 처분행위 개재 없이 컴퓨터 정보처리 과정서 이루어져야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[타인 명의 카드번호·비번 입력 결제·대출]</span> 가맹점·대출금융기관에 대한 컴사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 권한 없이 자기 계좌로 이체한 후 인출한 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>이체행위</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[무단 인터넷뱅킹 이체]</span> 권한 없이 타인 계좌서 자기 계좌로 이체 → 컴사기죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[절취 신용카드로 계좌이체]</span> 컴사기죄 해당은 별론, 절취행위로는 볼 수 없음<span class=\"cs-exam\">【변21】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>인출한 행위와 제3자의 장물취득죄</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[무단 계좌이체로 취득한 예금채권]</span> 재물 아닌 재산상 이익 → 자기 계좌서 인출해도 장물 예치·인출로 볼 수 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[인출 현금]</span> 자기 현금카드 사용권한자의 정당 사용, 지급기 관리자 의사에 반하지 않고 기망·처분행위 없음 → 절도·사기 구성요건 X → 인출 현금은 재산범죄로 취득한 재물 아니어서 장물<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-exam\">【변24·22·20·19·18·17·16·14, 모기22】</span></div><div class=\"cs-h\">Ⅳ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[허위정보 입금완료 시]</span> 금융기관 직원이 전산단말기로 특정계좌에 입금된 것처럼 허위정보 입력 → 입금절차 완료로 장차 인출 가능한 재산상 이익 취득 → 기수 이후 입금 취소·미인출되어도 영향 X<span class=\"cs-exam\">【변24·12】</span></div><div class=\"cs-h\">Ⅴ. 친족상도례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[조부 예금통장 절취한 손자가 지급기 조작해 자기 계좌로 이체]</span> 피해자는 이중지급 위험에 처하는 친척 거래 금융기관 → 친족상도례 적용<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[컴사기죄]</span><span class=\"cs-exam\">【변24, 모사25, 변기20】</span></div>", ["제347조"], 3, "gak_사기공갈"], ["개인051", "초과인출과 컴퓨터등사용사기죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">PC방 손님 A가 아르바이트생 甲에게 현금카드를 주며 3만 원 인출을 부탁 → 甲은 A가 알려준 비밀번호로 신한은행 현금자동지급기에서 5만 원을 인출, A에게 3만 원만 주고 2만 원은</div><div class=\"cs-li\" style=\"margin-left:0px\">말하지 않고 가짐. 甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\">① <span class=\"cs-stat\"><strong>제347조의2</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">② 위 학설 및 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲 = 컴퓨터등사용사기죄와 배임죄의 상상적 경합</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《현금카드 인출 위임받은 자가 위임금액 초과 인출·취득한 경우 죄책》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①절도죄설(지급기 관리자 의사에 반해 재물인 현금 취득)</div><div class=\"cs-li\" style=\"margin-left:16px\">②배임죄설(위임 사무 처리하며 임무위배 초과 인출)</div><div class=\"cs-li\" style=\"margin-left:16px\">③횡령죄설(초과 인출 현금도 위임자 소유 → 타인 재물 보관자)</div><div class=\"cs-li\" style=\"margin-left:16px\">④컴사기죄설(현금도 재산상 이익)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[컴사기죄]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①(컴사기 신설 이전) 배임죄 인정 판례 有</div><div class=\"cs-li\" style=\"margin-left:16px\">②(신설 이후) 위임범위 초과 인출 시 인출현금 총액 중 위임초과분 '비율'에 상당하는 '재산상 이익' 취득 → 그 차액 상당액에 관해 <span class=\"cs-stat\"><strong>§347</strong></span>조의2 컴사기죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19·18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 위임초과분 비율 상당 재산상 이익 취득 → 컴사기죄, 동시에 타인 사무처리자로 임무위배해 이익 취득·위임자에 손해 → 배임죄도 성립 → 양죄 상상적 경합</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[TIP]</span> 위임범위 3만원 인출 후 다시 위임 없는 2만원을 추가 인출했다면, 컴사기죄가 아니라 추가 인출 2만원에 대한 절도죄 성립<span class=\"cs-exam\">【모사25】</span></div>", ["§347", "제347조"], 1, "gak_사기공갈"], ["개인052", "신용·직불·현금카드 관련범죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사18】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 합의금 마련하려 기숙사 룸메이트 C의 지갑에서 신용카드(현금카드 겸용)를 몰래 꺼내 편의점 앞 현금자동지급기에서 평소 알던 비밀번호로 C 계좌 잔고 전액 300만 원을 인출하고</div><div class=\"cs-li\" style=\"margin-left:0px\">200만 원은 현금서비스를 받은 뒤 카드를 제자리에 반환. 乙의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [신용카드에 대한 절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">①·② 타인 신용카드로 현금을 인출해도 카드 자체의 경제적 가치가 인출된 예금액만큼 소모되지 않음 → 일시 사용하고 곧 반환하면 불법영득의사(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 곧바로 반환한 이상 신용카드 자체에 대한 절도죄(<span class=\"cs-stat\"><strong>제329조</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [신용카드 사용에 관한 범죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [절도죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 절취한 신용카드를 부정사용해 현금자동인출기 에서 예금을 인출하거나 현금서비스를 받으면 관리자의 의사에 반해 그 지배를 배제하고 현금을 자기 지배로 옮긴 것 → 절도죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 예금 300만 원 + 현금서비스 200만 원 인출 → 절도죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [신용카드 사용범죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 여신전문금융업법 <span class=\"cs-stat\"><strong>제70조</strong></span> 제1항 제3호</div><div class=\"cs-li\" style=\"margin-left:0px\">② '분실 또는 도난된 신용카드'는 점유이탈 카드를 취득하거나 점유를 배제한 자가 반드시 유죄일 것을 요하지 않음 → 카드 절도죄가 성립하지 않아도 신용카드부정사용(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 부정사용 = 신용카드·직불카드의 본래 용법에 따른 사용 → 현금카드 기능으로 '예금'을 인출한 행위는 포함(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 절취 카드를 인출기에 넣고 비밀번호를 조작해 '현금서비스'를 받는 행위는 포함(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">⑤ 乙 = 현금서비스 200만 원 부분에 한해 여신전문금융업법위반죄</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 乙 = 500만 원 절도죄 + 현금서비스 200만 원 여신전문금융업법위반죄, 양죄는 보호법익·행위태양이 전혀 달라 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 여신전문금융업법위반죄 (신용카드·직불카드)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>분실·도난, 강취·횡령, 기망·공갈</strong> 적용범위: <span class=\"cs-fact-tag\">[분실·도난 카드]</span> 취득·점유배제 행위자가 반드시 유죄 처벌받을 것 要 X (신용카드 사용절도O) <span class=\"cs-fact-tag\">[기망·공갈 취득]</span> '자유로운 의사에 의하지 않고 점유 배제'되어 '사실상 처분권 취득'한 카드 의미 <span class=\"cs-fact-tag\">[피해자가 사용권한 부여한 경우 편취 인정돼도 부정사용 X — 파기된 원심 논리]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[유흥주점 폭행·협박 후 합의금 결제 카드]</span> 부정사용<span class=\"cs-x\"><strong>(X)</strong></span> — 점유가 피해자 의사에 반해 이탈·배제됐다 보기 어려움</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>부정사용</strong> 개념: <span class=\"cs-fact-tag\">[본래의 용법]</span> 여전법 <span class=\"cs-stat\"><strong>§70</strong></span>①4호 '사용' = 강취·횡령·기망·공갈 취득 카드를 진정한 카드로서 '본래의 용법'대로 사용<span class=\"cs-exam\">【변사18, 변기14, 모사25, 모기24·12】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[현금서비스O]</span> 절취 신용카드 현금인출기 주입·비밀번호 조작해 '현금서비스' → 부정사용 포함 부정사용은 새로운 법익침해로 절도범행 불가벌적 사후행위 아님 → 절도죄와 실체적 경합<span class=\"cs-exam\">【변22, 변사18, 모기24·21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[예금인출X]</span> 절취 직불카드로 현금지급기서 '예금' 인출 → 부정사용 개념 포함 X <span class=\"cs-exam\">【변22, 변사18, 변기14, 모사25, 모기24·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[예금이체X]</span> 예금 계좌이체도 부정사용죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[제시만·미완성]</span> 대금결제 위해 가맹점 제시+매출전표 서명·교부 일련행위가 '사용' 단순 제시만으론 실행착수일 뿐 사용 완성 X, 카드회사 승인받아도 同 <span class=\"cs-neg-tag\">[절취카드 제시했으나 도난카드 발각돼 매출표 미작성·검거 → 미수]</span> <span class=\"cs-neg-tag\">[미수범 처벌규정 X]</span><span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사문서 흡수]</span> 매출표 서명·교부가 사문서위조·동행사 구성요건 충족해도 부정사용죄에 흡수 → 별도 성립 X<span class=\"cs-exam\">【변20·15】</span></div><div class=\"cs-h\">Ⅱ. 형법상 범죄 (신용·직불·현금카드)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>예금·현금서비스 인출</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공갈]</span> 현금카드 갈취 후 승낙받아 현금 인출 → 단일·계속 범의의 일련행위로 포괄 하나의 공갈죄, 인출을 절도죄로 별도 처단 X<span class=\"cs-exam\">【변18·15·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사기]</span> 현금카드 기망 편취 후 현금 인출도 同 (포괄 하나의 사기죄)</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[편취+무권한 인출]</span> 카드 편취해도 명의자가 사용권한 부여한 적 없으면 인출은 별도 절도죄<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[강도]</span> 현금카드 강취 시 사용승낙 의사표시 볼 여지 X → 강취카드로 예금 인출은 강도죄와 별도 절도죄<span class=\"cs-exam\">【변21·19·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[절도]</span> 절취 신용카드 부정사용해 현금서비스 인출·현금 취득 → 부정사용죄 + 별도 절도죄, 실체적 경합<span class=\"cs-exam\">【변16·15, 모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[컴사X]</span> <span class=\"cs-stat\"><strong>§347의2</strong></span> 컴사죄 객체는 재산상 이익뿐 → 절취 신용카드로 현금 인출(재물죄)은 컴사죄로 처벌 X<span class=\"cs-exam\">【모사25·24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>가맹점 사용</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[강도]</span> 강취 신용카드로 정당소지인인양 점주 속여 주류 등 취득 → 부정사용죄와 별도 사기죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[절도]</span> 절취카드 가맹점 부정사용 반복 → 거래안전·공중신뢰 침해로 포괄일죄 가맹점별 각 사기죄는 실체적 경합이나, 부정사용죄와 사기죄는 법익·태양 달라 실체적 경합 → 부정사용 포괄일죄 취급 지장 X<span class=\"cs-exam\">【변25·22·21】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>계좌이체행위·인터넷뱅킹</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[계좌이체=컴사]</span> 절취 신용카드로 현금지급기 계좌이체 → 컴사죄 별론, 절취행위로 볼 수 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[인터넷뱅킹]</span> 무권한 인터넷뱅킹으로 타인 예금 자기계좌 이체 → 컴사죄</div><div class=\"cs-h\">Ⅲ. 신용카드 부정발급</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>'자기명의'로 발급받은 신용카드 사용</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자기명의 기망발급]</span> 대금결제 의사·능력 없이 카드회사 기망해 발급받은 경우, 자동지급기 인출이든 가맹점 물품구입이든 모두 카드발급에 터잡은 사기 포괄일죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[정상발급 후 기망사용]</span> 일시적 자금궁색 아니라 과다부채 누적으로 변제 의사·능력 없음에도 카드 사용 → 사기죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용범위: 위와 같이 발급받은 카드 사용해도 부정사용죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>'타인명의'로 발급받은 신용카드 사용</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[현금서비스]</span> 타인명의 모용 발급 카드로 현금서비스 → 카드회사 허용범위 밖, 자동지급기 관리자 의사에 반함 → 절도죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자동대출]</span> 모용 발급 카드번호·비밀번호로 ARS·인터넷 신용대출로 이익 취득 → 대출금융기관에 대한 컴사죄<span class=\"cs-exam\">【변19·15·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[부정사용죄]</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 카드회사 기망 발급은 여전법 <span class=\"cs-stat\"><strong>§70</strong></span>①4호 '사람 기망 취득'에 해당 X → 부정설 타당 부정설에 의하면 매출전표 서명은 사문서위조·동행사죄 실체적 경합 <span class=\"cs-fact-tag\">[긍정설: 여전법위반죄만 성립]</span></div></div>", ["§70", "§347", "제329조", "제70조"], 3, "gak_사기공갈"], ["개인053", "횡령죄 일반", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제355조(횡령, 배임)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 타인의 재물을 보관하는 자가 그 재물을 횡령하거나 그 반환을 거부한 때에는 5년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 타인의 사무를 처리하는 자가 그 임무에 위배하는 행위로써 재산상의 이익을 취득하거나 제삼자로 하여금 이를 취득하게 하여 본인에게 손해를 가한 때에도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제356조(업무상의 횡령과 배임)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">업무상의 임무에 위배하여 제355조의 죄를 범한 자는 10년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 주체 – 위탁관계에 의한 보관 (진정신분범) (<span class=\"cs-stat\">§355</span>①)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>보호 가치 있는 위탁관계</strong> 적용범위: 위탁관계는 계약뿐 아니라 사무관리·관습·조리·신의칙으로도 성립 횡령죄 위탁관계는 보호할 만한 가치 있는 신임에 의한 것으로 한정 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[범죄수단 위탁]</span> 범죄 실현수단으로 형성된 위탁관계는 그 행위 처벌 여부 불문 보호가치 신임 X <span class=\"cs-fact-tag\">[무자격자끼리 요양병원 설립·교부 투자금 임의처분 → 횡령죄 X]</span><span class=\"cs-exam\">【변26, 모기23】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>보관</strong> 개념: <span class=\"cs-fact-tag\">[동산]</span> 보관 = 재물에 대한 사실상 또는 법률상 지배력 있는 상태 <span class=\"cs-fact-tag\">[예금]</span> 보관은 사실상 지배뿐 아니라 법률상 지배·처분 가능 상태 포함 위탁금전 은행 예치해도 보관자 지위 <span class=\"cs-fact-tag\">[부동산]</span> 보관자 지위는 점유 아닌 제3자에 유효 처분할 수 있는 '권능' 유무로 결정 → 원인무효 이전등기 명의자는 보관자 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[등록차량]</span> 사실상·법률상 지배력 있으면 보관 등록 요하는 타인차량 인도받아 사실상 처분 → 횡령죄, 보관위임자·보관자가 등록명의자일 필요 X. 지입차량도 同(지입차주·수임자 사실상 처분) <span class=\"cs-fact-tag\">[횡령 지입차량 대포차 매수인은 </span><span class=\"cs-crime\">장물취득죄</span><span class=\"cs-fact-tag\">]</span><span class=\"cs-exam\">【변24·19, 모사20, 변기26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[미등기건물]</span> 관리위임 보관자가 임의로 자기명의 보존등기 → 그때 이미 횡령죄 완성(불법영득의사 외부발현) 이후 근저당설정은 불가벌적 사후행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[양도·승낙 여지]</span> 당초 보관한 타인 재산이라도 이후 양도·임의사용 승낙 여지 있으면 그 의문 해명 안 되는 한 유죄 단정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[매수차량 반환거부]</span> 매매약정으로 정당한 법률상 지위·권리 보유하며 사용한 것일 뿐 위탁관계 전제 보관 아님, 등록명의 무관 사용승낙 여지, 대내적으로 소유권 매수인 보유 여지 큼 → 횡령 무죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공동상속]</span> 공동상속 부동산 단독점유 중 다른 상속인 지분 임의처분해도 처분권능 없어 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23, 모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[원인무효등기+보상금]</span> 특별조치법 허위보증서로 임의 이전등기한 자는 처분권능 새로 발생 X → 보관자 X. 원인무효등기 이용해 보상금 수령해도 보관관계 성립 X <span class=\"cs-fact-tag\">[토지수용자에 대한 사기죄]</span></div><div class=\"cs-h\">Ⅱ. 객체 – 타인 소유의 재물</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>재물</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[주권O]</span> 예탁결제원 예탁·계좌대체 양도 '주권'은 유가증권=재물 → 횡령죄 객체<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[주식X]</span> 주권 미발행 상태 예탁·계좌대체 양도 '주식'은 재물 아님 → 횡령죄 객체<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[주식은 주권 발행 여부 불문 횡령 불성립(X)]</span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>타인 소유</strong> 적용범위: 객체가 타인 재물인 이상 구체적 소유자 누구인지는 성립 무관 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[1인회사]</span> 사실상 1인주주라도 회사재산이 곧 주주 소유 X → 회사자금 임의처분 횡령죄<span class=\"cs-exam\">【변16·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[동업재산O]</span> 동업재산은 합유 → 존속 중 지분 임의처분·처분대금 소비 시 횡령죄, 지분비율 관계없이 횡령액 전부 죄책<span class=\"cs-exam\">【변23·15·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[내적조합O]</span> 대외적으로 조합관계 안 드러나는 '내적 조합'도 同</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[선의취득X]</span> 소유권 선의취득 인정되면 반환요구 거절해도 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[채권양도X]</span> 대항요건 안 갖춘 채 채무자로부터 추심·수령한 금전 소유권은 양도인 귀속, 양수인 위한 보관자 지위 X → 임의처분해도 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span>. 장래 금전채권 양도도 同 <span class=\"cs-fact-tag\">[부가가치세 환급금채권]</span><span class=\"cs-exam\">【변25·14, 모사24, 변기19, 모기21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[채권양도담보X]</span> 기존채무 '담보' 위해 다른 채권 양도 시 담보가치 유지·보전 신임관계 X → 통지 없이 변제받아 소비해도 민사 채무불이행일 뿐 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[경매X]</span> 경매부동산 소유권은 대금부담자 불문 낙찰명의인 취득 → 임의처분해도 타인 재물 아님, 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[수인 분담·1인명의 낙찰]</span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[익명조합X]</span> '익명조합'은 출자재산이 영업자 재산 → 영업자는 보관자 아님, 영업이익금 소비해도 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[매수·전매 전적 일임한 무명계약=익명조합 유사 → 횡령 X]</span><span class=\"cs-exam\">【변26·21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[조합탈퇴X]</span> 2인 조합서 1인 탈퇴 시 조합재산은 잔존조합원 단독소유 → 투자금 환급 계산만 남음 <span class=\"cs-fact-tag\">[횡령 불성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[가맹점X]</span> 가맹점계약은 계속적 물품공급계약, 동업 아님 → 가맹점주 보관 판매대금은 점주 소유, 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-h\">Ⅲ. 횡령하거나 반환을 거부 (불법영득의사)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 불법영득의사 = 자기 또는 제3자 이익 위해 타인 재물을 자기 소유인 양 사실상·법률상 처분하는 의사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 소유자 이익 반해 처분 시 불법영득의사<span class=\"cs-o\"><strong>(O)</strong></span>, 소유자 이익 위해 처분 시 특별한 사정 없으면 <span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[회사자금 사적처분]</span> 주주·대표이사 등이 자기/제3자 이익 위해 회사자금 사적 용도로 임의처분 → 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[가지급금]</span> 이자·변제기 약정, 이사회 결의 등 절차 없이 거액 회사자금 인출·사용 → 횡령죄, 사후 반환·변상 의사 있어도 불법영득의사 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[담보제공]</span> 회사재산 제3자 자금조달 담보 등 사적 임의처분 시 주총·이사회 결의 유무 불문 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[뇌물·배임증재]</span> 회사자금으로 뇌물공여 시 상대방 이익 도모 목적 → 업무상횡령죄 부정청탁·<span class=\"cs-crime\">배임증재</span>도 同<span class=\"cs-exam\">【변19, 변사26, 모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령+배임증재 별개]</span> 횡령 자금 일부로 배임증재 공여 시 범의·태양·법익 달라 별개, 횡령 약식명령 기판력이 <span class=\"cs-crime\">배임증재</span>에 미치지 X <span class=\"cs-fact-tag\">[실체적 경합]</span><span class=\"cs-exam\">【변26, 변사26, 모기25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[변호사비용]</span> 법인 구성원이 업무수행 법령위반으로 '형사재판' 받게 된 경우 법인자금으로 개인 변호사비용 지급 → 횡령</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[비자금]</span> 분식·자금조달 수단이면 불법영득의사 인정 어려우나, 개인 착복 목적으로 별도 조성 시 조성행위 자체로 불법영득의사 실현<span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[비자금 입증]</span> 개인용도 사용 신빙자료 많으면 횡령 추단 가능하나, 불법영득의사 부정 사유·부합자료 있으면 함부로 횡령 인정 X<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[휴대전화]</span> 몸싸움 중 피해자가 두고 간 휴대전화 건네받아 보관 중 임의사용 → 조리상 보관지위 있으나 임의사용만으론 불법영득의사 단정 어려움<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅳ. 횡령죄의 기수와 미수</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[위험범]</span> 횡령죄는 법익침해 위험 있으면 결과 미발생해도 성립하는 '위험범' <span class=\"cs-fact-tag\">[객관적 행위]</span> 횡령행위는 불법영득의사 실현 일체 행위 내심 의사만으론 부족, 불법영득의사가 외부 인식될 객관적 행위 있을 때 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[담보제공]</span> 보관재물 함부로 담보제공 → 담보제공 무효·소유권 침해결과 불문 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수목 계약금]</span> 보관 수목 제3자 매도계약·'계약금' 수령·소비 → '수목'에 대한 횡령'미수'죄<span class=\"cs-exam\">【변23·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[약속어음 할인]</span> 보관 약속어음 현금할인 자체가 불법영득 실현이면 횡령액은 할인현금액 아닌 어음 액면금 상당액</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[반환거부]</span> 공동상속 임야 보관 중 매도후 분배·이전등기 요구받고 반환거부 → 횡령죄</div><div class=\"cs-h\">Ⅴ. 횡령죄의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상상적 경합]</span> 여러 위탁관계 보관 재물을 1개 행위로 횡령 → 위탁관계별 수개 횡령죄, 상상적 경합 <span class=\"cs-fact-tag\">[죄수=위탁관계 수]</span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[은폐 재이체]</span> 횡령 은폐 목적 허위 회계처리로 입금 내역 남긴 후 곧 재이체 → 별개 횡령행위 X</div><div class=\"cs-h\">◎ 횡령죄 재물 보관자 정리표 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">유형 = 재물 보관자 부동산: 제3자에게 법률상 유효하게 처분할 수 있는 '권능' 유무로 결정 동산 / 예금 / 등록차량: 재물에 대한 사실상 또는 법률상 지배력이 있는 상태</div>", ["§355", "제355조", "제356조"], 3, "gak_횡령배임"], ["개인054", "불법원인급여와 횡령죄", "<div class=\"cs-h\">Ⅰ. 불법원인급여물에 대한 횡령죄 성립여부<span class=\"cs-exam\">【변사25·21, 모사25·22·17·14, 변기12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《불법원인급여물을 임의소비한 경우 횡령죄 성립 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(형법 독자성 강조, 반환청구권 없어도 횡령 인정)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(소유권 수급자 귀속 → 타인성 부정 → 횡령 불성립)</div><div class=\"cs-li\" style=\"margin-left:16px\">③절충설(급여/위탁 구별, 위탁의 경우에만 횡령)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[원칙]</span> 뇌물공여·배임증재 목적 전달 교부 금전은 민법 <span class=\"cs-stat\"><strong>§746</strong></span> 불법원인급여물 → '소유권 상대방 귀속', 전달 않고 임의소비해도 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·19·14·12】</span> <span class=\"cs-fact-tag\">[예외]</span> 포주-윤락녀 화대 분배약정 보관 중 임의소비 시 포주 불법성이 윤락녀보다 현저히 커 소유권 여전히 윤락녀 잔존 → 포주 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[민법 </span><span class=\"cs-stat\">§746</span><span class=\"cs-fact-tag\"> 단서]</span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 급여자·수익자 불법성 정도에 따라 개별사안 구체 검토하는 판례 타당</div></div><div class=\"cs-h\">Ⅱ. 구체적 판례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[범죄수익 수표교환]</span> 유사수신 사기수익인 정 알고 수표 현금교환 대가 약정은 범죄수익은닉규제법상 반사회성 현저 → 교부수표 불법원인급여물, 소유권 피고인 귀속 → 미교환 수표·이미 교환한 현금 임의소비해도 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[기부금 보관]</span> 병원 대신 제약회사서 의약품 매출비례 기부금 명목 금원 받아 병원 위해 보관한 것뿐이면 불법원인급여 아님 → 임의소비 시 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["§746"], 2, "gak_횡령배임"], ["개인055", "위탁매매와 횡령죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 선배 A에게서 A 소유 중고차 처분을 부탁받고 B에게 5,000만 원에 매도했음에도 4,000만 원에 팔았다고 기망하고 4,000만 원만 A에게 줌. B에게서 수표로 받은 잔액 1,000만 원은 정을 아는 乙에게 보관을 부탁했으나 乙이 유흥비로 탕진.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲과 乙의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [위탁매매와 횡령죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 위탁품 처분 후 매매대금을 임의 소비한 위탁매매인의 죄책 — 횡령죄설/배임죄설, 판례 = 횡령죄설. 상법 <span class=\"cs-stat\"><strong>제103조</strong></span>의 취지상 횡령죄설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲 = A에 대해 1,000만 원 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [사기죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 자기가 점유하는 타인의 재물을 횡령하려 기망수단을 쓴 경우 피기망자의 재산처분행위가 없어 일반적으로 횡령죄만 성립, 사기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [장물보관죄] 수표 1,000만 원 = 甲이 횡령해 영득한 장물 → 정을 알고 보관 → 장물보관죄(<span class=\"cs-stat\"><strong>제362조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [횡령죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 장물보관죄가 성립하면 이미 소유자의 소유물추구권을 침해 → 이후 횡령행위는 불가벌적 사후행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙에게 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 횡령죄, 乙 = 장물보관죄</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《위탁매매인이 위탁품 또는 위탁판매대금을 임의소비한 경우 어떤 범죄가 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①횡령죄설(판매대금은 수령과 동시에 위탁자에게 소유권)</div><div class=\"cs-li\" style=\"margin-left:16px\">②배임죄설(금전 가치성, 판매대금 수탁자에게 소유권 귀속)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[횡령죄설]</span> 위탁품 소유권은 위임자, 판매대금은 수령과 동시에 위탁자 귀속 → 위탁매매인 임의사용·소비 시 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span> 단 이익분배 등 판매대금 처분 특약 있으면 정산관계 미해명 시 곧바로 횡령죄 X<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 위탁물·취득물은 위탁자 소유라는 상법 <span class=\"cs-stat\"><strong>§103</strong></span> 취지 → 횡령죄설 타당</div></div>", ["§103", "제103조", "제355조", "제347조", "제362조"], 1, "gak_횡령배임"], ["개인056", "착오 송금과 횡령죄", "<div class=\"cs-h\">Ⅰ. 착오송금과 횡령죄<span class=\"cs-exam\">【변사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[횡령O]</span> 착오로 잘못 송금·입금된 경우 예금주-송금인 사이 신의칙상 보관관계 성립 → 임의인출·소비는 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span>, 거래관계 없어도 同<span class=\"cs-exam\">【변19·16·14】</span></div><div class=\"cs-h\">Ⅱ. 착오로 송금된 금원을 반환하지 않고 '상계'한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : '반환거부'가 횡령이려면 단순 거부론 부족, 거부행위가 횡령행위와 같다고 볼 정도여야 반환거부에 정당한 이유 있으면 불법영득의사 X 착오송금 시 신의칙상 보관관계 성립하나, 착오송금 금전이 용도특정 위탁금전과 동일하다거나 수취인에게 금전수수 수반 사무처리 위임했다 볼 수 없어 상계권 행사가 위임취지에 반한다 평가 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X회사 대표 甲이 A 착오송금 500만원 중 X의 A에 대한 채권액 100만원 반환거부]</span> 정당한 상계권 행사 → 불법영득의사<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-h\">Ⅲ. 가상자산 착오 이체</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령X]</span> 비트코인은 유체물·관리가능 동력 아니고, 가치변동 크고 강제통용력 없어 화폐가치를 법률상 지배한다 볼 수 없어 재물 X → 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[전단무죄]</span><span class=\"cs-exam\">【변25, 변기26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배임X]</span> 착오·시스템 오류로 법률상 원인 없이 가상자산 이체받은 자는 신임관계 기초 보존·관리 지위 X → 배임죄<span class=\"cs-o\"><strong>(X)</strong></span> 착오송금 횡령 판례 유추해 신의칙으로 배임 처벌은 죄형법정주의 위반<span class=\"cs-exam\">【변25·24, 변기26】</span></div>", [], 2, "gak_횡령배임"], ["개인057", "보이스피싱 관련 범죄", "<div class=\"cs-h\">Ⅰ. '전기통신사기범인'(정범)의 죄책</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[기수시기]</span> 보이스피싱범이 피해자 기망해 사기이용계좌로 송금·이체받으면 사기죄 기수 <span class=\"cs-fact-tag\">[특별법위반의 점 논외]</span><span class=\"cs-exam\">【변21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[피해자 횡령X]</span> 범인이 피해자 자금 점유해도 위탁·신임관계 없고, 사기이용계좌 인출은 기존 사기범행 예정행위로 새 법익침해 아님 → 사기 '피해자'에 대한 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-h\">Ⅱ. '계좌명의인'의 죄책</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>'피해자'에 대한 횡령죄</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[비공범-횡령O]</span> 계좌명의인은 피해자와 법률관계 없이 사기피해금 반환의무 → 피해자 위한 보관지위, 영득의사로 인출하면 피해자에 대한 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25·23·22, 모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[사기 공범-횡령X]</span> 접근매체 양도해 사기범행 방조한 종범이 사기이용계좌 송금 피해자 자금 임의인출해도 同 (횡령 X)<span class=\"cs-exam\">【변24·21·19, 모사24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>'전기통신금융사기범'에 대한 횡령죄</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[공범 불문-횡령X]</span> 명의인 인출은 사기범에 대한 관계에선 횡령죄<span class=\"cs-x\"><strong>(X)</strong></span> 접근매체 양도해도 사기범이 송금·이체액 취득했다 볼 수 없고, 제3자 명의 계좌 송금 유도 자체가 범죄 명의인-사기범 관계는 보호가치 위탁관계 아님<span class=\"cs-exam\">【변24, 모사25·24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>계좌명의인의 장물취득죄<span class=\"cs-exam\">【모사24】</span></strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[재물성O]</span> 피해자가 본범 기망에 속아 '현금'을 피고인 계좌로 '송금'했다면, 재물인 현금 교부가 예금계좌 송금 형식으로 된 것에 불과 → 피해자의 은행에 대한 예금채권은 당초 미발생<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[취득X]</span> 장물취득의 '취득'은 점유 이전받아 사실상 처분권 획득 본범에 편취금 귀속 과정 없이 피해자→피고인 계좌 송금으로 종료, 이후 인출은 예금반환청구 결과일 뿐 본범 점유이전 아님 → 장물취득죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변21·19·15·14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>계좌명의인의 은행에 대한 사기죄</strong> 판단기준 (判例) : 통장 재발급 후 제3자에 편취당한 송금의뢰인 돈 출금 시, 은행 예금지급은 예금계약에 따른 것으로 은행이 착오로 처분한 것 아님 → 은행 상대 사기죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사25·24】</span></div>", [], 3, "gak_횡령배임"], ["개인058", "용도를 특정하여 위탁한 금전과 횡령죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">[사법12]</span> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A학교법인 이사장으로서 그 법인이 설치·운영하는 사립학교 B대학 및 별개 법인인 B대학 산학협력단 운영에 직·간접 영향력을 행사하고 산학협력단 자금 입출금을 지시하기도 함. 증권회사 근무 친구 乙과 산학협력단이 국가에서 용도를 특정해 교부받은 보조금(보조금 관리에 관한 법률상 다른 용도 사용 금지)을 빼내 주식에 투자해 수익을 나누기로 합의 → 甲이 보조금 중 2억 원을 빼내 乙에게 전달, 乙은 사정을 알고 주식에 투자.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 행위가 업무상횡령죄에 해당되는지 여부를 논하시오. (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [위탁관계]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 업무상횡령죄의 '업무'는 사실상의 것도 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">② 재물 보관의 위탁관계도 사실상의 관계면 충분</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 별개 법인인 산학협력단 운영에 영향력을 행사하고 자금 입출금을 지시 → 업무상 재물 보관자의 지위(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [용도를 정하여 위탁한 금전]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 용도가 '엄격히' 제한된 자금을 위탁받아 보관하는 자가 제한된 용도 외의 목적으로 사용하면 횡령죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 법률상 다른 용도 사용이 금지된 보조금을 주식투자에 사용 → 업무상횡령죄(<span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)(O)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 용도를 정하여 위탁한 금전<span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《용도를 정하여 위탁받은 금전을 수탁자가 임의소비한 경우 죄책》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①횡령죄설(소유권 위탁자에게 유보)</div><div class=\"cs-li\" style=\"margin-left:16px\">②배임죄설(금전 가치성 강조, 상대방에 소유권 이전)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[횡령죄설]</span> 목적·용도 정한 금전은 그 용도 사용 전까지 소유권 위탁자 유보</div><div class=\"cs-li\" style=\"margin-left:16px\">① 특정성 不要 시 취지 반하지 않고 대체가능한 상태면 일시사용도 횡령 X</div><div class=\"cs-li\" style=\"margin-left:16px\">② 취지 반해 다른 용도 소비할 때 비로소 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 용도특정 위탁 시 사용 전까지 위탁자에게 소유권 유보 → 횡령죄설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[수령 금전]</span> 금전수수 수반 사무처리 위임받아 제3자로부터 수령한 금전은 용도한정 위탁금전처럼 수령과 동시에 '위임자 소유', 위임받은 자는 보관관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[불법영득의사]</span> 위탁취지 반해 권한 없이 소유권자 처분(반환거부 포함)하려는 의사 소유자 이익 위해 처분 시 특별한 사정 없으면 불법영득의사 X</div><div class=\"cs-h\">Ⅱ. 용도가 '엄격히' 제한된 자금</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 용도 '엄격히' 제한된 자금을 제한용도 외로 사용 → 횡령죄, 보관 중 '특정 용도·목적 소멸'돼도 반환·임의소비 승낙 전까지 위탁자 소유물 → 횡령죄 용도 엄격제한 자금을 제한용도 외 사용 시 결과적으로 본인 위하는 면 있어도 사용행위 자체로 불법영득의사 실현 → 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[교비회계]</span> 사립학교 교비회계 수입 다른 용도 사용 → 사용행위 자체로 불법영득의사 실현, 횡령죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사회단체보조금]</span> 경비부족 메우려 보조금 전용해도 용도 엄격제한된 이상 불법영득의사 부인 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[산학협력단 국고보조금]</span> 업무는 법령·계약뿐 아니라 관례·사실상의 것도 포함, 위탁관계도 사실상 관계면 충분 이사장이 대학·산학협력단 자금 입출금 지시 등 → 산학협력단 자금 '사실상 보관자' 용도 엄격특정 국고보조금을 교비계좌 송금·교직원 급여 사용 → 업무상횡령죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모사20】</span></div>", ["제356조", "제355조"], 2, "gak_횡령배임"], ["개인059", "명의신탁과 횡령죄", "<details class=\"cs-case\"><summary><u><strong>[CASE(1)]</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A와의 명의신탁약정에 따라 A 소유로 등기돼 있던 'X토지'를 자기 명의로 소유권이전 등기 → 자기 명의로 등기돼 있음을 기화로 B에게 매도하고 소유권이전등기 경료.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [A에 대한 횡령죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 무효인 명의신탁약정에 따른 신탁자·수탁자 사이의 사실상 위탁관계는 범죄를 구성하는 불법적 관계 → 형법상 보호할 가치 있는 신임(X) → 수탁자는 신탁자에 대해 '타인의 재물을 보관하는 자'(X). 부동산실명법 위반 양자간 명의신탁에서 수탁자가 임의 처분해도 신탁자에 대한 횡령죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 A에 대한 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [B에 대한 사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 명의수탁자가 부동산을 제3자에게 매도한 경우 제3자에게 소유권이전 등기가 경료되어 실질적 재산상 손해(X) → 제3자에 대한 사기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 B에 대한 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 아무런 죄책도 지지 않음</div></div></details></div></details><details class=\"cs-case\"><summary><u><strong>[CASE(2)]</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">C가 乙에게 'Y토지'를 매도, 계약 당시 乙은 C에게 실제 매수인은 D이고 자신은 명의신탁 약정에 따라 D를 대신해 계약을 체결하고 등기만 한다고 알려줌 → 乙이 사업자금이 추가로</div><div class=\"cs-li\" style=\"margin-left:0px\">필요하자 E에게 Y토지를 매도하고 소유권 이전. 乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [명의신탁자 D에 대한 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [횡령죄] 수탁자 명의 소유권이전등기는 무효이고 소유권은 매도인이 그대로 보유 → 수탁자는 취득 계약의 당사자도 아닌 신탁자에 대해 '타인의 재물을 보관하는 자'(X) → 처분해도 신탁자에 대한 횡령죄(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [배임죄] 수탁자가 신탁자에게 매매대금 등을 부당이득으로 반환할 의무를 부담해도 '타인의 사무를 처리하는 자'(X) → 처분해도 배임죄(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [소결] 乙 = D에 대해 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)·배임죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, 제1항) 모두(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [매도인에 대한 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 말소등기의무의 존재나 수탁자에 '의한' 유효한 처분가능성을 들어 수탁자가 '매도인'에 대해 '타인의 재물을 보관하는 자'·'타인의 사무를 처리하는 자'라고 볼 수(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = 매도인 C에 대해 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)·배임죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [제3자 E에 대한 사기죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 명의수탁자가 부동산을 제3자에게 매도한 경우 소유권이전등기가 경료되어 실질적 재산상 손해(X) → 제3자에 대한 사기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = 제3취득자 E에 대한 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 乙 = 아무런 죄책도 지지 않음 &lt;!-- 원문 p365 CASE(2) 결론이 \"甲은…\"으로 인쇄되어 있으나 CASE(2)의 행위자는 乙이므로 '乙'이 맞음(원문 오기로 보임). --&gt;</div></div></details></div></details><div class=\"cs-h\">Ⅰ. '유효'한 명의신탁과 횡령</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>명의수탁자의 죄책</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[근저당=기수]</span> 보관 부동산에 불법영득의사로 근저당권설정등기 경료 → 횡령행위 기수<span class=\"cs-exam\">【변19·16·15】</span> <span class=\"cs-fact-tag\">[불가벌적 사후행위 법리]</span> 선행 처분행위로 위험발생·기수 후, 후행 처분이 선행 위험을 현실적 법익침해로 완성하는 수단에 불과하거나 당연 예상될 수 있는 것이면 후행행위는 불가벌적 사후행위 그러나 후행 처분이 예상 못한 새 위험 추가로 위험 증가시키거나 선행과 무관한 방법으로 법익침해 결과 발생시키면 별도 횡령죄 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[근저당 후 매각]</span> 근저당설정으로 기수 후 별개 근저당 설정해 위험 추가하거나 매각해 결과 발생시키면 불가벌적 사후행위<span class=\"cs-o\"><strong>(X)</strong></span>, 별도 횡령죄 <span class=\"cs-fact-tag\">[실경]</span><span class=\"cs-exam\">【변26·25·20·16·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[수용보상금+반환거부]</span> 신탁부동산 일부 수용보상금 일부 소비 후 나머지 전체 반환거부 → 새 법익침해로 별개 횡령죄, 불가벌적 사후행위 아님<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>상대방의 죄책<span class=\"cs-exam\">【변사15·13】</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공동정범X]</span> 종중부동산 수탁자(유효신탁) 무단 매각처분 횡령 시 매수인이 정 알아도 수탁자와 '짜고' 불법영득 공모 아닌 한 횡령죄 공동정범<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변16·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[장물취득X]</span> 유효신탁서 수탁자는 외부관계상 소유자 간주 → 취득 제3자는 정 알든 모르든 장물취득죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[무효 명의신탁]</span> 수탁자 횡령죄 불성립 → 상대방에 공동정범·장물취득죄 성립 여지 X</div><div class=\"cs-h\">Ⅱ. '무효'인 명의신탁과 횡령죄 (전부 '전단'무죄)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>양자간 명의신탁<span class=\"cs-exam\">【변사13, 모사23, 모기21】</span></strong> 판단기준 (判例) : 무효 명의신탁의 사실상 위탁관계는 부동산실명법 위반 불법적 관계일 뿐 보호가치 신임 X 말소등기의무·유효처분가능성으로도 보관자 지위 X → 양자간 명의신탁 수탁자 임의처분해도 명의신탁자에 대한 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>중간생략 명의신탁<span class=\"cs-exam\">【변사18·15, 모사24·21·16, 모기22】</span></strong> 판단기준 (判例) : 사실상 위탁관계는 불법적 관계일 뿐 보호가치 신임 X 명의신탁자는 신탁부동산 소유권 없고 위탁신임관계 인정 X → 수탁자는 신탁자 재물 보관자 아님, 임의처분해도 '명의신탁자'에 대한 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·19·18·17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>매도인 '악의' 계약명의신탁<span class=\"cs-exam\">【모사14】</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁자에 횡령·배임X]</span> 부동산실명법 <span class=\"cs-stat\"><strong>§4</strong></span>②본문상 수탁자 등기 무효·소유권은 매도인 보유 → 수탁자는 계약당사자 아닌 명의신탁자에 대해 보관자 X, 부당이득 반환의무 있어도 배임 '사무처리자' X<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[매도인에 횡령·배임X]</span> 말소등기의무·유효처분가능성으로도 '매도인'에 대한 보관자·사무처리자 지위 X<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>매도인 '선의' 계약명의신탁<span class=\"cs-exam\">【모기18】</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁자에 횡령죄X]</span> 부동산실명법 <span class=\"cs-stat\"><strong>§4</strong></span>②단서상 물권변동 유효·명의신탁약정 무효 → 수탁자는 매도인뿐 아니라 신탁자에 대해서도 유효하게 소유권 취득 → 타인 재물 보관자 X<span class=\"cs-exam\">【변17·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁자에 배임죄X]</span> 선의 소유자와 계약한 계약명의신탁서 수탁자가 신탁자 위해 신탁부동산 관리·무단처분 금지 의무 부담하는 등 사무처리자 지위 X<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-h\">Ⅲ. 명의수탁자의 제3자에 대한 사기죄<span class=\"cs-exam\">【모사21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 수탁자가 제3자에 매도·이전등기 시 대외적 처분권한 있음 분명, 제3자도 자기명의 등기로 재산상 손해 없어 고지의무·기망 X → 제3자에 대한 사기죄 성립 여지 X<span class=\"cs-exam\">【변20】</span> 자동차 명의수탁자 처분도 同<span class=\"cs-exam\">【변15】</span></div>", ["§4", "제355조", "제347조"], 3, "gak_횡령배임"], ["개인060", "횡령죄의 죄수관계", "<div class=\"cs-h\">Ⅰ. 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 일단 횡령 후 다시 그 재물을 처분하는 것은 불가벌적 사후행위 횡령물에 도품·유실물특칙 적용 X → 횡령물 고지 없이 처분해도 상대방 유효 선의취득 가능, 상대방에 대한 사기죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[위탁자에 대한 횡령죄와 매수인에 대한 사기죄 모두 성립·상상적 경합이라는 견해도]</span><span class=\"cs-exam\">【모사21】</span></div><div class=\"cs-h\">Ⅱ. 사기죄와 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 사기죄는 타인 점유 재물을 처분행위로 취득하는 죄 → 자기 점유 타인재물 영득에 기망수단 써도 사기죄<span class=\"cs-x\"><strong>(X)</strong></span>, 횡령죄만<span class=\"cs-exam\">【변17·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[예금주 사기X/은행 횡령O]</span> 은행원이 예금주 예금 돈을 입금 않고 몰래 유용 시, 돈 받아 확인한 이상 예금계약 유효 성립 → 예금주 피해 없어 사기죄 X 甲·乙 공모해 예금유인·乙이 돈 받아 유용 → 업무상횡령죄 <span class=\"cs-neg-tag\">[은행에 대한 사기X]</span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-h\">Ⅲ. 사기·공갈로 취득한 재물에 대한 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사기-신주대금]</span> 대표이사가 타인 기망해 신주 인수시켜 납입대금 보관 중 횡령 → 사기와 다른 새 법익침해로 별개 업무상횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사기-약속어음]</span> 할인 위해 배서양도 교부받은 수탁자가 자기채무 변제 충당 시 횡령죄 단 당초부터 기망해 어음 교부받았으면 교부 즉시 사기죄, 이후 채권변제 충당은 불가벌적 사후행위일 뿐 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공갈]</span> 공갈로 재물 교부케 한 경우 공갈죄 성립, 소비·처분해도 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span> (횡령은 불법영득의사 없이 점유 시작해야)<span class=\"cs-exam\">【모사16】</span></div><div class=\"cs-h\">Ⅳ. 배임죄와 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 타인 사무처리자가 임무위배로 회사에 자기채무 연대보증채무 부담시킨 후, 회사 금전 보관자 지위서 자기채무 변제하려 회사자금 인출·개인채무 변제 → 배임죄와 다른 새 법익침해로 불가벌적 사후행위 아닌 별죄 횡령죄, 인출자금이 연대보증채무 변제에 쓰여도 同</div><div class=\"cs-h\">Ⅴ. 횡령죄와 강제집행면탈죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 보관재물을 영득의사로 은닉하면 횡령죄, 채권자 강제집행 면탈 결과 있어도 별도 <span class=\"cs-crime\">강제집행면탈죄</span><span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅵ. 장물보관과 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 절도범으로부터 장물보관 의뢰받아 정 알고 보관 중 임의처분해도 '장물보관죄' 성립 시 이미 소유물추구권 침해 → 이후 횡령은 불가벌적 사후행위, 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24, 변사25·18·13, 모사25·16】</span> '업무상 과실'로 장물보관 중 처분한 행위는 <span class=\"cs-crime\">업무상과실장물보관죄</span> 평가에 포함, 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅶ. 뇌물죄·배임수재죄와 횡령죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 보관·관리자가 공사대금 부풀려 약정하고 과다지급분 일부 되돌려받는 행위는 그 타인에 대한 부풀린 금액 상당 횡령<span class=\"cs-exam\">【모사24】</span> 횡령 취득금을 공범끼리 수수한 것이 공모에 따른 내부 분배에 지나지 않으면 별도 <span class=\"cs-crime\">뇌물죄</span><span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변사17】</span></div>", [], 3, "gak_횡령배임"], ["개인061", "배임죄 일반", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, A주식회사 1인 주주인 아버지에게서 주식 전부를 상속받고 대표이사 취임. 40억 원 상속세 납부의무를 담보하려 이사회 승인을 거쳐 A회사 소유 시가 100억 원 S건물에 대한민국을 근저당권자로 채권최고액 40억 원 근저당권 설정. 이후 자금 압박 중 상속세 납부 위해 丁에게서 40억 원 차용, 丁은 차용 목적을 알면서 대여금 채권 담보 명목으로 S건물에 소유권이전등기청구권 가등기를 요구 → 甲이 승낙하고 이사 X·乙에게 알림. 실망한 X는 사직서를 내고 여행을 떠났고, 이를 모르는 甲은 이사회 개최 없이 X가 참석·결의한 것처럼 회의록을 작성해 X 명의로 서명날인 후 비치, S건물에 丁 명의 가등기를 마침. 甲의 죄책을 논하시오. (20점) (가등기에 관한 공전자기록등불실기재 및 불실기재공전자기록등행사의 점은 논외로 함)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [특경법위반(배임)죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [근저당권을 설정한 행위]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 1인 회사 주주가 개인채무 담보를 위해 회사 소유 부동산에 근저당권설정등기를 마쳐 주면 배임죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 대표이사가 임무에 배임해 주주·회사채권자에게 손해가 될 행위를 했다면 이사회·주주총회 결의가 있어도 정당화(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 근저당권설정등기로 배임죄가 성립하는 경우 이득액 = 담보되는 '피담보채무' 상당액</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 개인채무 40억 원 담보 위해 100억 원 S건물에 채권최고액 40억 원 근저당권 설정 → 이득액 40억 원 → <span class=\"cs-crime\">특경법위반(배임)죄</span>(특경법 <span class=\"cs-stat\"><strong>제3조</strong></span> 제1항 제2호, 형법 <span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제2항)(O). 이사회 승인을 얻었어도 같음</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [가등기를 설정한 행위]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 근저당권설정으로 배임죄가 성립한 뒤 그 부동산에 새 담보권을 설정하면 선순위 근저당권의 담보가치를 공제한 나머지 담보가치 상당의 재산상 이익을 침해 → 별도의 배임죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 100억 원 S건물에 丁 명의 가등기 → 추가 배임행위로 40억 원 상당 이득 취득 → 별도의 특경법위반(배임)죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [소결] 甲의 각 특경법위반(배임)죄는 실체적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [사문서위조죄 및 동행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 대표이사에게 이사회를 개최하지 않은 채 불참 이사 명의로 이사회 회의록을 작성할 권한(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② X의 사직서 제출을 몰랐어도 이사회 없이 X가 참석·결의한 것처럼 회의록을 작성·서명날인·비치 → <span class=\"cs-crime\">사문서위조죄 및 위조사문서행사죄</span>의 실체적 경합(<span class=\"cs-stat\"><strong>제231조</strong></span>, <span class=\"cs-stat\"><strong>제234조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 각 특경법위반(배임)죄 + 사문서위조죄 + 위조사문서행사죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 주체 – 타인의 사무처리자 (<span class=\"cs-stat\">§355</span>②·<span class=\"cs-stat\">§356</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>타인의 사무처리자</strong> 개념: <span class=\"cs-fact-tag\">[진정신분범]</span> 주체 = 타인의 사무를 처리하는 지위에 있는 자 (判例) '타인의 사무처리자' = 당사자관계의 전형적·본질적 내용이 통상 계약의 이익대립관계를 넘어 신임관계에 기초하여 타인 재산을 보호·관리하는 자 적용범위: <span class=\"cs-fact-tag\">[법인이 의무자]</span> 법인은 배임죄 주체 X → 법인 대표하는 자연인(대표기관)이 주체<span class=\"cs-exam\">【변16·13】</span> <span class=\"cs-fact-tag\">[대내관계]</span> 신의칙상 사무처리할 신임관계 존재하면 족 — 제3자에 대한 대외적 사무권한 존재 不要 신임관계 발생근거: 법령·법률행위·관습·사무관리 → 권한 소멸 후/해임 후 인계 전 사무처리도 포함 고유권한자뿐 아니라 보조기관(직·간접으로 처리 담당)도 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>구체적 판례</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지입차주 실질소유 차량]</span> 지입회사 운영자 = 타인의 사무처리자<span class=\"cs-o\"><strong>(O)</strong></span> — 실질재산인 지입차량 재산상 사무 대행<span class=\"cs-exam\">【변기26, 모기22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[할부 완납 전 지입회사 소유차]</span> 타인의 사무처리자<span class=\"cs-x\"><strong>(X)</strong></span> — 지입차량이 지입차주 실질재산이라 보기 어려움</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[금융기관 임직원-예금주]</span> 재산관리 사무처리자<span class=\"cs-x\"><strong>(X)</strong></span> → 임의로 예금 인출해도 업무상배임<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[동업 종료 후 정산·채권추심·채무변제]</span> 피고인 자신의 사무 → 투자자 위한 타인의 사무<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 임무 위배</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 법령·계약·신의칙상 당연히 기대되는 행위를 하지 않거나 당연히 해선 안 될 행위를 하여 신임관계 저버리는 일체 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 본인의 동의 있으면 임무위배 X <span class=\"cs-neg-tag\">[단 피해자 사후동의로는 배임 성립 부정 X]</span> 배임행위 = 법률행위뿐 아니라 사실행위·부작위로도 가능, 법률상 유효 여부 불문</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공무원 임무위배로 제3자 이익취득·국가손해]</span> 업무상배임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대학교수 판공비 법인카드 개인용도]</span> 업무상횡령<span class=\"cs-x\"><strong>(X)</strong></span> → 업무상배임<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[1인주주·대주주라도 회사에 손해 임무위배]</span> 배임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대표이사 배임행위]</span> 이사회·주총 결의 있어도 정당화 X<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[회사임원 임무위배]</span> 대주주 양해·이사회결의 있어도 성립 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[LBO 차입매수]</span> 인수자 반대급부 없이 피인수회사 재산 임의 담보제공 → 특가법위반(배임)<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[이사가 변제능력 상실자에 합리적 채권회수조치 없이 대여]</span> 배임행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[유상감자]</span> 합리이유 없이 과다자산 유출로 경영·자금운영에 구체적·현실적 위험 초래 → 회사재산 보호의무 위배·손해</div><div class=\"cs-h\">Ⅲ. 재산상 이익의 취득</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[재산상 이익]</span> 손해 가하였어도 행위자·제3자 재산상 이익 취득 없으면 배임 X <span class=\"cs-fact-tag\">[전체적 재산가치 감소]</span> 재산상 손해 = 전체적 재산가치 감소 → 취득하는 '재산상 이익'에도 동일 적용 <span class=\"cs-fact-tag\">[관련성]</span> 이익취득·손해발생은 대등한 병렬적 성립요건(<span class=\"cs-stat\"><strong>§356</strong></span>, <span class=\"cs-stat\"><strong>§355</strong></span>②) → 이익·손해 간 '일정한 관련성' 인정되어야 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X]</span> 새마을금고 규정위반 금융상품 매입·수수료 지급 → 수수료는 용역대가 → 관련성 없어 업무상배임 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X]</span> 군위군수 정기예금 중도해지·재예치 → 재예치는 선택 → 재예치처 자금운용기회 = 재산상 이익 단정 어려움</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X]</span> 입주자대표회의 회장 날인거부로 연체료 부담 → 연체료는 손해배상 → 공급업체 재산상 이익 취득 단정 어려움 → 업무상배임 X<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅳ. 재산상 손해의 발생</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>현실적인 손해 또는 재산상 실해 발생의 위험</strong> 개념: <span class=\"cs-fact-tag\">[재산상 실해 발생 위험]</span> 손해에 현실적 손해뿐 아니라 실해 발생 위험 초래도 포함 판단기준 (判例) : <span class=\"cs-fact-tag\">[경제적 관점]</span> 손해 유무 판단은 법률적 판단 X, 경제적 관점으로 파악<span class=\"cs-exam\">【변19】</span> <span class=\"cs-fact-tag\">[구체적·현실적 위험]</span> 실해 발생 위험은 구체적·현실적 위험 야기 정도 要, 막연한 가능성 정도로는 부족 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지급능력 없는 타인 약속어음 회사명의 배서]</span> 손해 발생 알면서 배서 → 배임<span class=\"cs-o\"><strong>(O)</strong></span>, 경영판단이라도 면책 X<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지점장 한도외 지급보증(유효)]</span> 실해 발생 위험 초래 → 배임 기수<span class=\"cs-exam\">【모사25】</span> <span class=\"cs-fact-tag\">[어음 사채업자에 할인유통 후 지급완료됨]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[체비지대장 명의 임의말소]</span> 채권적 청구권은 대장 기재와 무관 → 권리침해·실해 발생 위험 X → 배임<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지급보증했으나 주채무(물품대금) 미발생]</span> 손해와 같은 정도의 구체적 위험 발생 평가 어려움</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>전체적 재산가치의 감소</strong> 판단기준 (判例) : 급부·반대급부 상응하고 다른 손해 없으면 재산상 손해 X 일단 손해 위험 발생시킨 이상 나중 피해회복돼도 배임 성립 영향 X 손해액 구체적·명백히 산정 안 돼도 배임 성립 영향 X 손해에 장차 취득 기대되는 이익 상실도 포함 → 선이자 공제 대출/어음할인 시 손해 = 선이자 포함 대출금 전액·어음 액면금 전액<span class=\"cs-exam\">【변19】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[재단법인 이사장 담보 없이 대여]</span> 원리금 제때 변제돼도 배임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[학교법인 교비회계 수입 타 회계 편입]</span> 그것만으로는 손해·제3자 이익<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부실대출]</span> 손해액 = 담보초과·회수불능액이 아닌 손해위험 있는 '대출금 전액'</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부당 고가 도급계약 체결]</span> 배임액 = 도급금액 전액 - 정당 도급금액</div><div class=\"cs-h\">Ⅴ. 실행의 착수와 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수시기</strong> 개념: <span class=\"cs-fact-tag\">[임무위배행위 개시]</span> 배임 범의로 임무에 위배한 행위를 개시한 때 실행착수 <span class=\"cs-fact-tag\">[부진정부작위범]</span> 부작위 착수 = 작위의무 불이행 시 재산권 행사 불가 객관적 예견 등 구성요건적 결과발생 위험 구체화된 상황에서 부작위</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수시기</strong> 개념: <span class=\"cs-fact-tag\">[손해를 가한 때]</span> 이익취득하여 본인에게 손해를 가한 때 기수</div><div class=\"cs-h\">Ⅵ. 고의 및 불법영득의사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[고의]</span> 본인에 손해 가한다는 의사 + 자기·제3자 이득의사가 임무위배 인식과 결합하여 성립 <span class=\"cs-fact-tag\">[불법이득의사]</span> 자기·제3자 이익 목적으로 임무위배행위 하는 의사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[신주인수권부사채 인수대금 미납입·사채상환의무 부담]</span> 장차 미지급 계획 있어도 고의·불법영득의사 부정 X, 이후 실제 미부담도 범죄 후 정황에 불과</div><div class=\"cs-h\">Ⅶ. 죄수관계</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>배임죄와 불가벌적 사후행위</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[1인회사 주주 근저당설정 배임 성립 후 새 담보권 설정]</span> 나머지 담보가치 상당 침해 → 별도 배임<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>배임죄와 사기죄</strong> 가. <strong>'본인'에 대한 업무상배임죄와 사기죄 (상상적 경합)<span class=\"cs-exam\">【변사22, 모사16】</span></strong> 判例(죄수관계): 사기죄(기망)·업무상배임죄(임무위배) 구성요건 상이·별개 장 규정 → 1개 행위에 양죄 구성요건 모두 구비 시 법조경합 X, 상상적 경합<span class=\"cs-exam\">【변12】</span> <span class=\"cs-fact-tag\">[신협 전무가 담당직원 기망해 예금인출금·대출금 교부받음]</span> (단순배임도 동일) 나. <strong>'본인'에 대한 배임행위와 '제3자'에 대한 기망행위 (실체적 경합)<span class=\"cs-exam\">【모기24】</span></strong> 判例(죄수관계): 배임행위가 제3자에 대한 사기 구성하고 본인에 손해 발생 시 → 사기 + 배임, 보호법익·태양 달라 상상적 경합 X, 실체적 경합<span class=\"cs-exam\">【변20·18】</span> <span class=\"cs-fact-tag\">[전세계약 권한 없이 임차인 기망·보증금 교부(사기) + 월세계약 임무 위반한 전세계약으로 건물주에 보증금반환채무 부담케 함(업무상배임)]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>배임죄와 위조죄</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[회사명의 합의서 임의작성·교부]</span> 사문서위조행사(확정) + 업무상배임 → 1행위 수죄 → 상상적 경합<span class=\"cs-exam\">【변24】</span> <span class=\"cs-fact-tag\">[연결효과에 의한 상상적 경합 문제]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>업무상배임죄와 배임수재죄</strong> 判例(죄수관계): 행위태양 전연 달라 일반법·특별법 아닌 별개 독립범죄 → 흡수·결과적가중범 관계 X → 실체적 경합<span class=\"cs-exam\">【변사26】</span></div>", ["§355", "§356", "제3조", "제356조", "제355조", "제231조", "제234조"], 3, "gak_횡령배임"], ["개인062", "배임행위의 거래상대방", "<details class=\"cs-case\"><summary><u><strong>[CASE(1)]</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 자금 압박 중 상속세 납부 위해 丁에게서 40억 원 차용 → 丁은 차용 목적을 알면서도 대여금 채권 담보 명목으로 S건물에 소유권이전등기청구권 가등기를 요구, S건물에 丁 명의</div><div class=\"cs-li\" style=\"margin-left:0px\">가등기를 마침. 丁의 죄책에 대한 유죄와 무죄의 논거를 각각 제시하시오. (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [유죄의 논거]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [배임죄의 교사범]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 거래상대방의 대향적 행위가 필요한 유형의 배임죄 에서는 배임 의도가 전혀 없던 실행행위자에게 배임행위를 교사하거나 전 과정에 관여하는 등 적극 가담한 경우에 한해 배임교사죄·배임죄의 공동정범(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丁은 차용 목적을 알면서 A회사 소유 S건물에 가등기를 요구하고 마침 → 특경법위반(배임)죄의 교사범 성립 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [배임죄의 방조범] 판례와 달리, 丁이 적극 교사·가담에 이르지 않아 교사범·공동정범이 성립하지 않는 경우에도 甲의 배임행위를 직접 용이하게 하고 법익침해를 강화 → 방조범 성립 가능</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [무죄의 논거]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 거래상대방의 관여 정도가 교사범·공동정범에 이르지 않아 법질서 전체의 관점에서 사회적 상당성을 갖춘 경우에는 정범의 행위가 배임행위임을 알고 거래해 외견상 방조로 평가될 행위가 있어도 범죄를 구성할 정도의 위법성(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 판례에 의하면 丁이 40억 원을 대여하며 담보를 요구함은 사회적 상당성을 갖춘 행위 → 위법성(X) → 특경법위반(배임)죄의 방조범(X)</div></div></details></div></details><details class=\"cs-case\"><summary><u><strong>[CASE(2)]</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(18)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">A회사 1인주주·대표이사 甲, A회사 소유 S건물 부지에 건물을 신축하려 했으나 자금 조달이 어렵고 A회사 발행 약속어음(액면가 3억 원) 할인도 여의치 않자, A회사 기술담당 이사 乙 및 신용도 높은 B주식회사 대표이사 丙에게 사례금을 주고 B회사 배서를 받아 은행에서 할인받기로 합의. 乙이 甲 보관 A회사 비자금 2,000만 원을 건네받아 丙에게 주며 배서를 부탁 → 丙은 돈을 받고 A회사의 자금지급 능력이 없음을 알면서 어음에 B회사 명의로 배서.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲, 乙, 丙의 죄책은? (18점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [업무상배임죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 주식회사 이사가 타인 발행 약속어음에 회사 명의로 배서할 때 그 타인의 어음금 지급능력이 없어 회사에 손해가 발생하리라는 점을 알면서 나아갔다면 회사에 대한 배임행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙은 A회사의 자금지급능력이 없음을 알면서 B회사 명의로 배서 → 업무상배임죄(<span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, 제1항) [대표권 남용의 법리에 따라 답안을 작성할 수도 있다. 이 경우에도 어음할인을 위한 것이므로 유통되었다고 볼 수 있어 기수범이 성립한다.]</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [배임수재죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① '부정한 청탁' = 사회상규 또는 신의성실의 원칙에 반하는 내용이면 족</div><div class=\"cs-li\" style=\"margin-left:0px\">② 임무에 위배해 B회사와 무관한 A회사 발행 약속어음에 배서해 달라는 부정한 청탁을 받고 2,000만원 취득 → 배임수재죄(<span class=\"cs-stat\"><strong>제357조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [결론] 丙 = 업무상배임죄 + 배임수재죄의 실체적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [甲, 乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [업무상배임교사죄] (A) [교사범의 성립여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 거래상대방의 대향적 행위가 필요한 유형의 배임죄에서는 배임 의도가 전혀 없던 실행행위자에게 교사하거나 전 과정에 관여하는 등 적극 가담한 경우에 한해 배임교사죄·배임죄의 공동정범(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲·乙이 공모해 배임 결의가 전혀 없던 丙에게 사례금까지 주며 배서하게 함 → 각 교사범(O) (B) [공범과 신분]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 업무자·타인의 사무처리자라는 이중 신분이 없는 자가 업무상배임죄를 교사한 경우 — 진정·부진정신분범구별설/성립·과형 구별설, 판례 = 성립·과형 구별설. 단서는 본문의 적용을 전제한다고 해석함이 문언에 충실 → 성립·과형 구별설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲·乙 = <span class=\"cs-stat\"><strong>제33조</strong></span> 본문에 의해 각 업무상배임교사죄(<span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, <span class=\"cs-stat\"><strong>제31조</strong></span> 제1항) 성립, <span class=\"cs-stat\"><strong>제33조</strong></span> 단서에 의해 각 배임교사죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, <span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)의 형으로 처벌</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [업무상횡령죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공동정범(<span class=\"cs-stat\"><strong>제30조</strong></span>) = 공동가공의 의사 + 공동의사에 의한 기능적 행위지배를 통한 실행</div><div class=\"cs-li\" style=\"margin-left:0px\">② 회사 이사 등이 업무상 임무에 위배해 보관 중인 회사 자금으로 부정한 청탁을 하고 배임증재를 하면 회사에 대해 업무상횡령죄를 면하지 못함</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲이 보관하던 비자금 2,000만 원을 乙에게 주고 乙이 丙에게 전달·배서 부탁 → 각 기능적 행위지배로 실행행위 분담</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲·乙 = 각 업무상횡령죄의 공동정범(<span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제1항, <span class=\"cs-stat\"><strong>제30조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [배임증재죄] 甲·乙은 배임증재를 공모하고 실행행위를 분담 → 각 배임증재죄의 공동정범(<span class=\"cs-stat\"><strong>제357조</strong></span> 제2항, 제1항, <span class=\"cs-stat\"><strong>제30조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 丙 = 업무상배임죄 + 배임수재죄의 실체적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲·乙 = 각 업무상배임교사죄 (단, 배임교사죄의 형으로 처벌) + 업무상횡령죄 공동정범 + 배임증재죄 공동정범의 실체적 경합 &lt;!-- 원문 (2)(나)④ 업무상횡령죄 인용조문이 \"<span class=\"cs-stat\"><strong>제357조</strong></span> 제2항, 제1항\"으로 인쇄되어 있으나, 업무상횡령은 <span class=\"cs-stat\"><strong>제356조</strong></span>·<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항이 맞음(<span class=\"cs-stat\"><strong>제357조</strong></span>는 배임수재·증재). 도메인 지식으로 교정함. --&gt;</div></div></details></div></details><div class=\"cs-h\">Ⅰ. '거래상대방'의 공동정범 또는 교사범 성립가능성 <span class=\"cs-exam\">[변사26·18, 모사24·23]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">원칙 : 대향적 행위 필요 유형 배임죄에서 거래상대방은 별개 이해관계로 반대편에서 독자 거래 → 수익자는 배임죄 공범<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">예외 : 실행행위자 행위가 본인에 대한 배임임을 인식한 상태에서, 배임 의도 전혀 없던 실행행위자에게 배임 교사하거나 전 과정 관여 등 '적극 가담'한 경우에 한해 공동정범 인정<span class=\"cs-exam\">【변19·18】</span> <span class=\"cs-neg-tag\">[소극적으로 배임행위에 편승하여 이익 취득한 것만으로는 공동정범 X]</span></div><div class=\"cs-h\">Ⅱ. '거래상대방'의 배임방조죄 <span class=\"cs-exam\">[변사26, 모기23]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 거래상대방 관여가 교사·공동정범 정도에 이르지 않고 법질서 전체 관점상 사회적 상당성 갖춘 경우 → 배임임을 알고 거래하여 외견상 방조로 평가될 행위 있어도 위법성 X<span class=\"cs-exam\">【변사26, 모기23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[1인회사 주주가 개인 상속세 위해 법인부동산 담보제공하는 사정 알면서 가등기 요구·경료받은 거래상대방]</span> 배임방조<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-h\">Ⅲ. 거래상대방의 장물취득죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배임으로 영득한 것은 재산상 이익, 배임에 제공된 대지는 범죄로 영득한 것 자체 X]</span> 취득·전득자에 장물취득죄<span class=\"cs-o\"><strong>(X)</strong></span> (배임 가공 여부는 별론)<span class=\"cs-exam\">【변14】</span></div>", ["제356조", "제355조", "제357조", "제33조", "제31조", "제30조"], 3, "gak_횡령배임"], ["개인063", "대표권남용과 배임죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사18】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲 = X주식회사 대표이사, 乙 = 사채업자. 甲이 수억 원대 내기 골프 자금을 빌리고 변제기에 갚지 않자 乙은 그 채무가 회사와 무관한 개인 용도임을 잘 알면서 채무담보 목적으로 약속어음 발행을 요청 → 甲 승낙. 乙이 회사 사무실에서 회사 약속어음 용지에 액면금 5억 원· 발행일 등을 기재하고 甲이 수취인을 乙로 기재한 뒤 \"X주식회사 대표이사 甲\" 명판과 법인 인감도장을 날인해 교부. 그러나 회사가 실제로 어음금을 지급하거나 손해배상책임을 부담한 바</div><div class=\"cs-li\" style=\"margin-left:0px\">없고 어음이 제3자에게 유통되지도 않음. 甲과 乙의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 대표이사가 대표권을 남용해 약속어음을 발행했고 상대방이 그 사실을 알았거나 알 수 있었다면 발행행위는 회사에 대해 효력(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 다만 회사가 실제로 어음금을 지급했거나 민사상 손해배상책임을 부담하거나 어음이 실제로 제3자에게 유통되는 등 특별한 사정이 없는 한 재산상 실해 발생의 위험이 초래되었다고 볼 수 없어 배임미수죄</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙이 개인 용도임을 알면서 요청 → 발행행위 무효. 어음금 지급·손해배상 책임·제3자 유통 모두 없음 → 현실적 손해도 실해 발생의 위험도(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲 = 업무상배임미수죄(<span class=\"cs-stat\"><strong>제359조</strong></span>, <span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제2항)</div><div class=\"cs-li\" style=\"margin-left:0px\">⑤ 특경법은 미수범에 적용(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [업무상배임죄의 공동정범]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 거래상대방의 대향적 행위가 필요한 유형의 배임죄에서는 배임 의도가 전혀 없던 실행행위자에게 교사하거나 전 과정에 관여하는 등 적극 가담한 경우에 한해 배임교사죄·배임죄의 공동정범(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙은 어음 발행을 요청하고 회사 사무실에서 어음 용지에 액면금·발행일을 기재하는 등 전 과정에 관여 = '적극 가담' → 공동정범(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [공범과 신분]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 비신분자가 부진정신분범(이중 신분범)에 가담한 경우 <span class=\"cs-stat\"><strong>제33조</strong></span> 본문·단서의 관계 — 진정·부진정신분범 구별설/성립·과형 구별설, 판례 = 성립·과형 구별설. 단서는 본문의 적용을 전제한다고 해석함이 문언에 충실 → 성립·과형 구별설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = <span class=\"cs-stat\"><strong>제33조</strong></span> 본문에 의해 업무상배임미수죄 성립, <span class=\"cs-stat\"><strong>제33조</strong></span> 단서에 의해 단순배임미수죄의 형으로 처벌</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲·乙 = 업무상배임미수죄의 공동정범. 단 乙은 단순배임미수죄의 형으로 처벌</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 일반적 대표권 남용행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 대표이사가 대표권 남용 등 임무위배로 회사명의 의무부담행위 → 일단 회사 행위로서 유효, 상대방이 진의 알았거나 알 수 있었으면 회사에 무효</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상대방 부지 → 유효]</span> 회사 채무 발생·이행의무 부담 → 그 채무 발생 자체가 현실적 손해·실해 발생 위험 → 현실 이행 전이라도 배임 기수</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상대방 악의·과실 → 무효]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">① 원칙 무효, 경제적 관점에서도 현실적 손해·실해 발생 위험 초래 X → 실제 채무이행·불법행위책임 등 사정 없으면 기수 X</div><div class=\"cs-li\" style=\"margin-left:32px\">② 그러나 배임 범의로 임무위배행위 실행착수 → 배임 미수<span class=\"cs-exam\">【변26·21·14】</span></div><div class=\"cs-h\">Ⅱ. 대표권을 남용한 어음발행행위 <span class=\"cs-exam\">[변사26·18, 모기21·18]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 약속어음은 발행인이 인적 항변으로 소지인에 대항 X(어음법 <span class=\"cs-stat\"><strong>§17</strong></span>·<span class=\"cs-stat\"><strong>§77</strong></span>) → 발행 '무효'라도 제3자에 '유통'되면 어음채무 부담 위험 구체적·현실적 발생 → 이행 전이라도 배임 '기수'<span class=\"cs-exam\">【변25·22·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[상대방 악의·과실로 무효 + 지급·손배·유통 등 특별사정 없음]</span> 현실적 손해·실해 발생 위험 초래 X → 배임 기수<span class=\"cs-o\"><strong>(X)</strong></span>, 배임미수<span class=\"cs-exam\">【변19】</span></div>", ["§17", "§77", "제359조", "제356조", "제355조", "제33조"], 2, "gak_횡령배임"], ["개인064", "영업상 주요한 자산에 대한 업무상배임", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사23】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">X회사 경쟁사 상무 D가 甲에게 'X회사가 10억 원가량 투입해 새로 개발한 기밀인 메모리칩 도면 파일을 빼내 주면 3억 원을 주겠다'고 제안 → 창업 자금이 부족하던 甲이 승낙 → 09:00경 출근해 도면 파일을 자기 USB에 몰래 복사, 가지고 나와 D에게 넘기고 현금 3억 원 수령.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (15점) [주거침입 및 특별법위반의 점은 제외함]</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [절도죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 메모리칩 도면 파일 = '정보' → 그 자체가 유체물도 관리할 수 있는 동력도 아님 → 재물(X)(<span class=\"cs-stat\"><strong>제346조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">② '정보'를 복사·출력해도 정보 자체가 감소하거나 피해자의 점유· 이용가능성이 감소하지 않음 → 복사·출력 행위로 절도죄 구성(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ USB에 복사해 가지고 나왔어도 甲에게 절도죄(<span class=\"cs-stat\"><strong>제329조</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [업무상배임죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 회사 직원의 무단 자료 반출이 업무상배임죄가 되려면 그 자료가 영업비밀일 필요까지는 없어도, 불특정 다수인에게 공개되지 않아 보유자를 통하지 않고는 통상 입수 불가 +<span> </span>보유자가 취득·개발에 상당한 시간·노력·비용을 들인 '영업상 주요한 자산'에는 해당해야</div><div class=\"cs-li\" style=\"margin-left:0px\">② 재직 중 영업비밀·영업상 주요한 자산을 무단 반출하면 유출·반출 시에 업무상배임죄 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 10억 원을 투입해 개발한 기밀 도면 파일을 경쟁사에 유출할 의도로 복사·반출 → 반출 시 업무상배임죄(<span class=\"cs-stat\"><strong>제356조</strong></span>, <span class=\"cs-stat\"><strong>제355조</strong></span> 제2항) 기수</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [배임수재죄]</strong> 경쟁사 상무 D에게서 기밀을 빼내달라는 부정한 청탁을 받고 3억 원 수령 → 배임수재죄(<span class=\"cs-stat\"><strong>제357조</strong></span> 제1항) 기수</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = 업무상배임죄 + 배임수재죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 영업비밀 또는 영업상 주요 자산</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[영업상 주요한 자산]</span> 무단 자료 반출이 업무상배임에 해당하려면 영업비밀일 필요는 X, 적어도 불특정다수에 미공개로 보유자 통하지 않고 통상 입수 불가 +<span> </span>보유자가 취득·개발에 상당한 시간·노력·비용 들인 '영업상 주요한 자산'이어야<span class=\"cs-exam\">【변사23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공지 정보 조합이라도 조합 자체가 업계 미공지·전체로 공지 이상 정보 포함하여 통상 입수 어려우면 공지<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[가정용 맥주제조기 공정흐름도 = 영업상 주요한 자산 O]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">비밀유지조치 없이 판매로 공지된 제품 → 통상적 역설계로 쉽게 입수가능 → 영업상 주요한 자산<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[재직중-유출·반출시]</span> 재직 중 유출·이용목적으로 무단 반출 → '유출·반출시' 업무상배임 기수<span class=\"cs-exam\">【변사23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[퇴사시]</span> 적법 반출로 반출 자체는 배임 아니어도, 퇴사 시 반환·폐기의무 있음에도 유출·이용목적으로 반환·폐기 X → '퇴사시' 기수<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[퇴사후]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">① 퇴사 후에는 타인의 사무처리자 지위 X → 반환·폐기 안 한 영업비밀 유출·이용해도 이미 성립한 배임의 실행행위에 불과 → 별도 배임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:32px\">② 제3자가 유출·이용에 공모·가담해도 사무처리자 지위 없으면 배임 공범도 X<span class=\"cs-exam\">【변12】</span></div>", ["제346조", "제329조", "제356조", "제355조", "제357조"], 2, "gak_횡령배임"], ["개인065", "이중매매 – 배임죄가 성립하는 유형", "<div class=\"cs-h\">Ⅰ. 부동산 소유권이전등기의무와 배임죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>타인의 사무처리자의 지위 – 진정신분범<span class=\"cs-exam\">【모사24】</span></strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[제1매수인으로부터 중도금 수령]</span> 중도금 지급 등 계약 본격 이행단계 → 매도인은 소유권이전의무 벗어날 수 없고 매수인 재산보전 협력할 신임관계 → 그때부터 '타인의 사무처리자' → 이전 전 제3자 처분·등기 시 배임<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>실행의 착수 및 기수<span class=\"cs-exam\">【모사24】</span></strong> 개념: <span class=\"cs-neg-tag\">[착수]</span> 제2매수인으로부터 계약금만 받고 중도금 미수령이면 실행착수<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span> <span class=\"cs-fact-tag\">[기수]</span> 제2매수인에 이전등기 마쳐준 때 배임 성립 — 손해에 실해 발생 위험 초래도 포함, 제1매수인 소유권이전등기청구권 이행불능·위험이면 성립<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>타인의 사무처리자의 지위에 관한 구체적 판례</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[순위보전 가등기O]</span> 가등기는 손해회복방안일 뿐 물권변동 효력 X → 매도인 소유권이전의무 유지 → 신임관계 전형적·본질적 내용 변경 X → 배임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[서면증여O]</span> 서면증여자는 취소·해제 없는 한 소유권이전의무 벗어날 수 없음 → 타인의 사무처리자 → 제3자 처분·등기 시 배임<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[교환O]</span> 교환계약 본격 이행단계 → 이행받은 당사자는 상대방 재산보전 협력할 신임관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대물변제약정O]</span> 대물변제'약정'(확정적 소유권이전)도 해제 불가 상태면 배임<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[① 공사완료로 해제불가한 공사대금채무 변제 위해 빌라 확정 양도 = 대물변제'약정' → 배임 O]</span> <span class=\"cs-neg-tag\">[② 공사·매수대금 미지급 시 폐기하기로 한 분양계약서 = 대물변제'예약' → 배임 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[증여X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">① 서면에 의하지 않은 증여는 언제든 해제 가능</div><div class=\"cs-li\" style=\"margin-left:48px\">② 불륜지속 대가 매매형식 매도증서·공증은 <span class=\"cs-stat\"><strong>§103</strong></span> 위반 무효 → 각 배임<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅱ. 부동산 전세권설정등기의무</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[전세권설정계약 중도금까지 받고 임의로 근저당설정등기 경료]</span> 전세금반환채무 담보능력 상실 위험 → 배임<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[향후 부정 가능성 있으나 아직 미폐기]</span></div><div class=\"cs-h\">Ⅲ. 선매수인에게 이행한 경우 후매수인에 대한 배임죄 성립여부</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">① 이중매도 후 매도인이 선매수인에 소유권이전의무 이행 → 후매수인 관계에서 위법한 임무위배 X</div><div class=\"cs-li\" style=\"margin-left:16px\">② 선매수인에 대한 매매가 특별사정으로 사기죄 구성해도 무효·취소 없는 한 선매수인에 대한 소유권이전의무 소멸 X</div>", ["§103"], 3, "gak_횡령배임"], ["개인066", "이중매매 – 배임죄가 성립하지 않는 유형", "<details class=\"cs-case\"><summary><u><strong>[CASE(1)]</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">丙, 자기 고가 골프채를 D에게 1,500만 원에 양도하기로 하고 계약금·중도금 800만 원을</div><div class=\"cs-li\" style=\"margin-left:0px\">받았음에도 그 골프채를 E에게 1,800만 원에 양도. 丙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\">① 동산매매에서 매도인에게는 자기 사무인 동산인도채무 외에 별도로 매수인의 재산 보호·관리에 협력할 의무(X) → 매도인은 매수인의 사무를 처리하는 지위(X) → 목적물을 처분해도 배임죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 계약금·중도금 800만 원을 받았어도 丙은 D의 사무를 처리하는 자(X) → 丙에게 배임죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, 제1항)(X) &lt;!-- 원문 CASE(1) 문제 헤더는 <span class=\"cs-exam\">【변사21】</span>, ☞답안 헤더는 <span class=\"cs-exam\">【변사18】</span>로 서로 다르게 인쇄됨(원문 불일치). --&gt;</div></div></details></div></details><details class=\"cs-case\"><summary><u><strong>[CASE(2)]</strong></u> <span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 승용차 구입 시 B에게서 매수대금 용도로 3,000만 원을 차용하고 담보로 자기 소유 승용차에 B를 저당권자로 하는 저당권 설정 → 담보가치를 유지·보전하지 않고 자동차 밀수출업자 Y에게 1,000만 원을 받고 매도·인도 → B가 저당권을 실행하려 했으나 자동차 소재가 발견되지</div><div class=\"cs-li\" style=\"margin-left:0px\">않아 실행 불가. 乙의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [배임죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 자동차 등 특정동산 저당법 등과 배임죄에 관한 위 판례 법리</div><div class=\"cs-li\" style=\"margin-left:0px\">② 저당권을 설정해 주었어도 담보물의 담보가치를 유지·보전할 의무는 乙 자신의 사무일 뿐 B의 사무를 맡아 처리하는 것(X) → 乙은 B의 사무를 처리하는 자(X) → 승용차를 Y에게 처분해도 배임죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제2항, 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [권리행사방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 승용차 = 乙 소유 → 자기의 물건(O), B에게 저당권을 설정 → B의 저당권의 목적(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② '은닉' = 타인의 점유·권리의 목적이 된 자기 물건 등의 소재를 발견하기 불가능하게 하거나 현저히 곤란한 상태에 두는 것. 밀수출업자 Y에게 매도·인도해 소재 불명으로 저당권 실행 불가 → '은닉'(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 乙 = <span class=\"cs-crime\">권리행사방해죄</span>(<span class=\"cs-stat\"><strong>제323조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 乙 = 권리행사방해죄</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 기본 판례 법리</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념 (判例) : '타인의 사무처리자' = 당사자관계의 전형적·본질적 내용이 통상 계약의 이익대립관계를 넘어 신임관계에 기초하여 타인 재산을 보호 또는 관리하는 자</div><div class=\"cs-h\">Ⅱ. 부동산 관련 배임죄가 성립하지 않는 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>대물변제'예약' 후 처분</strong> 판단기준 (判例) : 대물변제예약의 궁극목적 = 차용금반환채무 이행확보 → 소유권이전등기의무는 궁극목적 달성 위한 부수적 내용 → 신임관계 기초 '타인의 사무' X → 대물 부동산 제3자 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20·17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>① 근저당설정계약,</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">② 양도담보설정계약 후 처분 <span class=\"cs-exam\">[모사23, 모기21]</span><strong> 판단기준 (判例) :</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">① 저당권설정계약에 따른 저당권설정의무는 채무자 자신의 의무·사무 → 이익대립관계 넘는 신임관계 기초 채권자 사무 X → 채무자를 '타인의 사무처리자' X</div><div class=\"cs-li\" style=\"margin-left:16px\">② 따라서 제3자에 먼저 저당권 설정·담보물 양도로 담보가치 감소·상실시켜 채권실현에 위험 초래해도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·22】</span> 위 법리는 부동산 '양도담보설정계약' 체결·소유권이전등기의무 있음에도 제3자 처분한 경우에도 적용</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>담보신탁계약 후 처분</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[담보신탁·자금관리대리사무계약 후 제3자 앞 소유권보존등기]</span> 새마을금고 주된 관심은 신탁등기 아닌 대출금 채권회수 → 신임관계 기초 우선수익권 보호·관리하는 사무처리자 지위 X → '타인의 사무처리자'<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변21】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>담보가등기와 근저당권설정등기 약정 후 처분</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[차용금채무 담보 위한 매매예약 가등기·근저당설정 약정]</span> 당사자관계 본질 = 변제와 담보 → 신임관계 기초 채권자 사무 X → 대표이사도 '타인의 사무처리자' X → 배임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">5. <strong>부동산 '수분양권' 양도 후 처분과 배임죄</strong> 판단기준 (判例) : 수분양권 매도인이 수분양권 이전할 의무는 자신의 사무 → '타인의 사무처리자' X → 수분양권·향후 취득 목적물 미리 제3자 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">6. <strong>소유권이전등기 받은 '매수인'의 융통자금 소비</strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">① 매수인의 매매대금 지급은 매수인 자신의 법적 의무·자신의 사무</div><div class=\"cs-li\" style=\"margin-left:16px\">② 소유권이전등기 받은 당일 담보제공·융통한 자금을 매도인에 대금으로 지급 안 해도 임무위배<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅲ. 동산·주식·채권의 '매매·양도' 관련</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>동산(등기·등록 동산 포함)의 매매와 배임죄 <span class=\"cs-exam\">[변사21, 모사12]</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[동산]</span> 동산매매 매도인에게 인도채무 외 매수인 재산 보호·관리 협력의무 X → 매수인에 대한 타인의 사무처리자 X → 목적물 인도 않고 타에 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변18·17·16·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[등록 동산]</span> 등기·등록 요하는 동산 매매도 동일 → 자동차 등 매도인이 소유권이전등록 안 하고 타에 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[동산 이중매매 선이행]</span> 선매수인에 소유권이전의무 이행해도 후매수인 관계에서 위법한 임무위배 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>채권·주식 양도 후 이중양도</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[주권발행 전 주식 양도]</span> 양도인은 양수인에 대한 타인의 사무처리자 X → 대항요건(양도통지·승낙) 안 갖추고 타에 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[점포임차권 양도]</span> 계약금·중도금 받아도 점포명도의무는 민사상 채무 → 타인의 사무<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[질권설정]</span> 통지·승낙 시 제3채무자가 질권자 동의 없이 변제해도 질권자에 대항 X, 질권자는 직접 변제청구·공탁청구 가능(민법 <span class=\"cs-stat\"><strong>§353</strong></span>②③) → 질권설정자 배임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅳ. 동산·주식·채권의 '양도담보' 관련</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>'동산·주식'의 양도담보와 배임죄</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[제공]</span> 동산을 양도담보로 '제공'하여 담보가치 유지·보전의무 부담해도 신임관계 기초 채권자 사무 X → 계약·설정 전후 불문 본질은 금전채권 실현·피담보채무 변제 → 채무자는 '타인의 사무처리자' X → 제3자 처분으로 담보가치 감소·상실시켜도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변17】</span> <span class=\"cs-fact-tag\">[점유개정 방식 양도담보 제공한 동산을 제3자에 매각한 사안]</span> <span class=\"cs-fact-tag\">[체결]</span> 위 법리는 동산 양도담보설정계약 '체결'하여 채권자에 양도할 의무 있음에도 제3자 처분한 경우에도 적용 <span class=\"cs-fact-tag\">[주식]</span> 주식 양도담보설정계약 '체결'한 채무자가 해당 주식 처분한 경우에도 동일 적용 <span class=\"cs-fact-tag\">[등기·등록 동산]</span> 등기·등록 요하는 동산 양도담보에도 적용 → 자동차 등 양도담보설정 채무자가 의무 다하지 않고 타에 처분해도 배임<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>'채권'의 양도담보와 배임죄<span class=\"cs-exam\">【변기23】</span></strong> 판단기준 (判例) : 채권양도담보계약 체결에도 본질은 피담보채권(금전채권) 실현 → 담보 목적 채권의 담보가치 유지·보전의무는 채무자 자신의 사무 → 채무자는 '타인의 사무처리자' X <span class=\"cs-fact-tag\">[전세보증금반환채권 담보양도 약정 후 양도통지 전 제3자에 전세권근저당 설정 → 배임 X]</span></div><div class=\"cs-h\">Ⅴ. 자동차 등 특정동산 저당법 등과 배임죄<span class=\"cs-exam\">【모기21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 저당권설정계약상 채무자 의무는 설정 전후 불문 본질이 금전채권 실현·피담보채무 변제 → 자동차 등 특정동산 저당법에 따라 저당권 '약정'·'설정'해도 담보권 실행 협조의무는 채무자 자신의 급부의무 → 채무자는 '타인의 사무처리자' X → 담보물 제3자 처분으로 담보가치 감소·상실시켜도 배임<span class=\"cs-o\"><strong>(X)</strong></span> 위 법리는 '공장 및 광업재단 저당법' 저당권 설정 동산을 채무자가 임의처분한 경우에도 적용</div><div class=\"cs-h\">Ⅵ. 동산·채권 등의 담보에 관한 법률과 배임죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 동산을 '동산·채권 등의 담보에 관한 법률'에 따른 동산담보로 제공하여 담보가치 유지·보전의무 부담해도 신임관계 기초 채권자 사무 X → 채무자는 '타인의 사무처리자' X → 제3자 처분으로 담보가치 감소·상실시켜도 배임<span class=\"cs-o\"><strong>(X)</strong></span></div>", ["§353", "제355조", "제323조"], 3, "gak_횡령배임"], ["개인067", "동산양도담보의 법률관계", "<div class=\"cs-h\">Ⅰ. 소유관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[점유개정 동산양도담보]</span> 금전채무 담보 위해 채무자가 동산을 채권자에 양도하되 점유개정으로 계속 점유 → 소유권 신탁적 이전</div><div class=\"cs-li\" style=\"margin-left:16px\">①대내적 관계: 채무자가 의연히 소유권 보유</div><div class=\"cs-li\" style=\"margin-left:16px\">②대외적 관계: 채무자는 무권리자(이미 채권자에 양도)</div><div class=\"cs-h\">Ⅱ. 채무자 (대내적 소유자)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령죄]</span> 매매형식 취해 동산 담보제공·계속 사용하다 채권자 승낙받아 매각 → 매각대금은 채무자 소유 → 소비해도 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[위 동산·매각대금은 채무자 소유]</span><span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배임죄]</span> 동산양도담보 계약 체결 또는 점유개정 양도 후 채무자 계속 점유 → 타인의 사무처리자 X → 배임죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[이중매매에서 상술]</span><span class=\"cs-exam\">【변24·17】</span></div><div class=\"cs-h\">Ⅲ. 채권자</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령죄]</span> 점유개정 양도담보로 채무자가 여전히 점유 → 소유권은 채무자에 잔존, 채권자는 양도담보물권만 취득 → 다른 사유로 보관하게 된 채권자는 타인 물건 보관자 = 횡령죄 주체<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변12】</span></div><div class=\"cs-h\">Ⅳ. 제3취득자</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[제3취득자]</span> 양도담보권자(채권자)가 설정자 점유 담보목적물을 목적물반환청구권 양도 방법으로 제3자에 처분→소유권 취득케 한 뒤 제3자로 하여금 취거케 함 → 제3자는 자기 소유물 취거 → <span class=\"cs-crime\">권리행사방해죄</span> 구성 여지는 별론, 절도죄는 성립 여지<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div>", [], 2, "gak_횡령배임"], ["개인068", "특경법상 이득액 산정", "<div class=\"cs-h\">Ⅰ. 특경법상 이득액</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>구성요건</strong> 적용범위: 사기죄(<span class=\"cs-stat\"><strong>§347</strong></span>)는 교부 재물·이익 가액 불문 / 특경법위반(사기)은 편취액 5억↑ 또는 50억↑이 구성요건의 일부 <span class=\"cs-fact-tag\">[특경법위반(배임) 동일]</span> 이익 가액 구체적 산정 불가 시 → 재산상 이익 가액 기준 가중처벌하는 특경법 적용 X 특경법 <span class=\"cs-stat\"><strong>§3</strong></span> 이득액 = '단순일죄' 이득액 또는 '포괄일죄' 이득액 합산액, 경합범 수죄의 각 이득액 합산<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변19】</span> 공동 사기 → 공범은 다른 공범 이득액에도 죄책 → 특경법 이득액은 모든 공범 이득액 합산 기준</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>사기죄의 이득액</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[동일 피해자]</span> 반환의사·능력 없이 투자금 교부받아 피해자에 반환했다가 재투자받는 방식으로 계속 수수 → 각 편취 투자금 합계액이 이득액, 반환 원금·수익금 공제 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[피해자별]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①각별 기망→각 재산상이익 편취 시 범의 단일·방법 동일해도 각 피해법익 독립 → 피해자별 독립 사기죄</div><div class=\"cs-li\" style=\"margin-left:48px\">②1개 기망행위로 다수 피해자 편취 → 피해자별 수개 사기죄, 상상적 경합<span class=\"cs-exam\">【변26·24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[피해법익]</span> 피해자들이 하나의 동업체 구성 등 피해법익 동일 시 → 포괄일죄 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부부]</span> 피해법익 동일 근거 없으면 부부라는 사정만으로 포괄일죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부부]</span> 기망 공통(함께 만나 기망)·노후대비 공동목적·공동재산 매도대금 재원·공동 투자결정, 편의상 1인에 사후 담보설정 → 피해법익 동일 → 포괄일죄 계약서 피해자별 작성·별도 계좌 송금해도 포괄일죄와 모순 X <span class=\"cs-fact-tag\">[甲계좌 1억+乙계좌 4.7억 ⇒ 특경법 적용]</span></div><div class=\"cs-h\">Ⅱ. '부동산' 상당의 특경법 이득액 – 부동산소유권이전등기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배임]</span> 이중매매 부동산 가액:</div><div class=\"cs-li\" style=\"margin-left:32px\">①부담 없으면 시가 상당액이 곧 가액</div><div class=\"cs-li\" style=\"margin-left:32px\">②근저당·압류·가압류 있으면 시가에서 (채권최고액 범위 내 피담보채권액, 집행채권액, 청구금액 범위 내 피보전채권액) 공제한 실제 교환가치<span class=\"cs-exam\">【변25·22】</span><span class=\"cs-exam\">【변기14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사기]</span> 기망하여 부동산 소유권 편취 시 특경법 <span class=\"cs-stat\"><strong>§3</strong></span> 적용 가액 산정도 위와 동일</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령]</span> 횡령도 동일<span class=\"cs-exam\">【변19】</span></div><div class=\"cs-h\">Ⅲ. '근저당권' 상당의 특경법 이득액 – 근저당권설정·말소</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배임]</span> 매도인이 제3자로부터 차용·근저당설정등기 해준 경우 → 매수인에게 '피담보채무' 상당액 손해<span class=\"cs-exam\">【변기23·14】</span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령]</span> 근저당설정 방법으로 부동산 횡령 이득액 = 시가에서 기설정 피담보채무 공제 잔액이 아니라 '피담보채무액 내지 채권최고액'<span class=\"cs-exam\">【변26·21·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사기]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①타인 기망하여 제3자 앞 근저당설정케 한 자의 이익 = 부동산 담보이용 이익, 이득액 원칙 시가 범위 내 '채권최고액' 상당</div><div class=\"cs-li\" style=\"margin-left:32px\">②선순위 근저당 있으면 원칙 시가-선순위 '채권최고액' 공제 잔액 한도, 다만 후순위자가 선순위 담보가치를 실제 피담보채권액만큼만 파악한 특별사정 시 시가-선순위 '실제 피담보채권액' 공제 잔액 한도</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사기]</span> 타인명의 근저당 '말소'시킨 자 이익 = 담보가치 상당액, 이득액 원칙 시가 범위 내 '채권최고액' 상당, 말소 당시 실제 채권액이 채권최고액 미달 시 '실제 채권액'이 한도</div><div class=\"cs-h\">◎ '부동산' 상당의 특경법상 이득액 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">배임(부동산 이중매매) / 횡령(유효 명의수탁 부동산 처분) / 사기(부동산 소유권 편취) (공통) 시가에서 (채권최고액 범위 내 피담보채권액, 집행채권액, 청구금액 범위 내 피보전채권액) 공제한 실제 교환가치</div><div class=\"cs-h\">◎ '근저당권' 상당의 특경법상 이득액 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">배임(근저당 설정): 피담보채무액</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">횡령(근저당 설정, 유효 명의신탁): 피담보채무액 내지 채권최고액</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">사기(근저당 설정): 시가 범위 내 채권최고액 상당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">사기(선순위 근저당 있는 부동산에 후순위 설정):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(원칙) 시가-선순위 채권최고액 공제 잔액 한도</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">(예외) 선순위 피담보채권액 공제 잔액 한도</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">사기(근저당 말소): (원칙) 시가 범위 내 채권최고액 상당 (예외) 실제 채권액이 채권최고액 미달 시 실제 채권액 한도</div>", ["§347", "§3"], 3, "gak_횡령배임"], ["개인069", "배임수·증재죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사20】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">A사립학교법인 이사장 甲, 학교 폭력문제 보도 등으로 운영에 어려움을 겪자 임원 변경 방식으로 운영권을 넘기기로 함 → 乙이 운영권을 5억 원에 양도하고 자기를 이사장으로 선임해 달라 부탁, 선임 후 5억 원을 이체하기로 함 → 乙은 이사장 선임 직후 B에게서 교직원 채용</div><div class=\"cs-li\" style=\"margin-left:0px\">부탁을 받고 대가로 1억 원 수령. 甲, 乙의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [운영권 양도와 관련 甲과 乙의 배임수증재]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① '부정한 청탁'은 업무상 배임의 정도에 이를 것을 요하지 않고 사회상규 또는 신의성실의 원칙에 반하는 내용이면 족</div><div class=\"cs-li\" style=\"margin-left:0px\">② 학교법인 이사장이 운영권을 양도하고 양수인 측을 임원으로 선임해 주는 대가로 양도대금을 받기로 하는 청탁은, 학교법인의 존립에 중대한 위협을 초래함이 명백하다는 등 특별한 사정이 없는 한 '부정한 청탁'(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 운영권 5억 원 양도 + 乙을 이사장으로 선임 → 甲·乙 모두 '부정한 청탁'(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲에 대한 배임증재죄(<span class=\"cs-stat\"><strong>제357조</strong></span> 제2항, 제1항)·乙에 대한 배임수재죄(<span class=\"cs-stat\"><strong>제357조</strong></span> 제1항) 모두(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [교직원 채용 관련 乙의 배임수재]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① B를 교직원으로 채용하는 대가로 1억 원을 받는 것은 사회상규·신의성실의 원칙에 반하는 내용 → 부정한 청탁(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = 배임수재죄(<span class=\"cs-stat\"><strong>제357조</strong></span> 제1항)</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제357조(배임수증재)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 타인의 사무를 처리하는 자가 그 임무에 관하여 부정한 청탁을 받고 재물 또는 재산상의 이익을 취득하거나 제3자로 하여금 이를 취득하게 한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 재물 또는 재산상 이익을 공여한 자는 2년 이하의 징역 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 범인 또는 그 사정을 아는 제3자가 취득한 제1항의 재물은 몰수한다. 그 재물을 몰수하기 불가능하거나 재산상의 이익을 취득한 때에는 그 가액을 추징한다.</div></div><div class=\"cs-h\">Ⅰ. 타인의 사무를 처리하는 자 (<span class=\"cs-stat\">§357</span>①)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[진정신분범]</span> 원칙적으로 타인 사무처리자만 배임수재죄 주체, 무신분자는 신분자 범행에 가공한 경우에 한하여 주체 '타인의 사무처리자' = 대내관계에서 신의칙상 사무처리 신임관계 존재 인정되는 자, 대외적 사무권한 존재·포괄적 위탁사무일 것 要 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 신임관계 발생근거 = 법령·법률행위·관습·사무관리 '타인의 사무처리자'의 사무는 재산권 관련 사무에 국한 X (통설)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[현실적 담당O]</span> 장래 담당 합리적 기대되는 임무에 부정한 청탁받고 취득 후 그 임무를 현실적 담당하게 되면 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[청탁 당시 정식 통보 전이나 위촉 사실상 확정 상태(O)]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사후 취득O]</span> 부정한 청탁 후 '사후'에 취득해도 성립<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사무분담 변경O]</span> 청탁 후 사무분담 변경으로 직무 미담당 상태서 수수해도, 여전히 같은 타인 사무처리 지위+청탁 관련 수수면 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사직 후 수수O]</span> 수재 당시 임무 현실적 담당은 요건 아님 → 청탁 후 '사직'으로 미담당 상태서 '수수'해도 청탁 관련이면 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[지위 취득 前 청탁X]</span> 사무처리자 지위 취득 전 부정한 청탁 받으면 배임수재죄 처벌<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[청탁받은 후 평가위원 위촉(X)]</span><span class=\"cs-exam\">【변26·20·16】</span></div><div class=\"cs-h\">Ⅱ. 임무에 관한 부정한 청탁</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>임무에 관하여</strong> 적용범위: '임무에 관하여' = 위탁관계 본래 사무뿐 아니라 밀접 관계 있는 범위 내 사무 포함 고유권한 처리자에 한정 X, 보조기관으로서 직·간접 처리 사무 담당자도 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>부정한 청탁</strong> 개념: 반드시 업무상 배임 정도에 이를 것 要 X, 사회상규 또는 신의칙에 반하는 내용이면 족<span class=\"cs-exam\">【변사26·20, 모사25, 모기25·23】</span> <span class=\"cs-fact-tag\">[묵시적O]</span> 명시적일 필요 X, 묵시적으로 이루어져도 무방 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O 교사채용]</span> 교사채용 명목 800만원 교부받음 → 부정한 청탁<span class=\"cs-exam\">【변사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O 유료기사]</span> 보도대상자가 기자에 '유료기사' 게재 청탁 = 광고를 언론보도로 가장 → 언론 공정성·객관성 신뢰 저버림 → 부정한 청탁, 내용이 객관적 사실 부합해도 동일<span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">[모사25, 모기23]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O 평론 우호여론]</span> 언론인이 평론대상 특정인·기업으로부터 경제적 이익 받으며 우호여론 형성 청탁 → 부정한 청탁 <span class=\"cs-fact-tag\">[논설주간이 여론형성 청탁 후 유럽여행비 3,973만원 대납]</span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O 수의계약]</span> 구매담당 직원에 수의계약·편의 대가 사례 청탁 후 계약체결 후 금원 교부 → 부정한 청탁<span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O]</span> 계약 관련 사무처리자에 '계약상대방 되게 해달라' 부탁+대가 → 부정한 청탁</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O 골프장부킹]</span> 예약담당자가 부킹대행업자 청탁에 회원용 주말부킹권 판매·대금 수수 → 배임수재죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X]</span> 규정 허용 범위 내 최대한 선처 요청 또는 적법·정상적 처리범위 속하는 것이면 부정한 청탁 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X 학교운영권]</span> 학교법인 운영권 양도하고 양수인측 임원 선임 대가로 양도대금 받기로 한 청탁 → 설립목적과 다른 목적 기본재산 매수 등 존립에 중대한 위협 명백한 특별사정 없는 한 부정한 청탁 X<span class=\"cs-exam\">【변사20】</span></div><div class=\"cs-h\">Ⅲ. 재물 또는 재산상의 이익의 취득</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>취득</strong> 개념: <span class=\"cs-fact-tag\">[취득=현실취득]</span> 취득은 현실적 취득만 의미 → 단순 요구·약속만은 불포함<span class=\"cs-exam\">【변20】</span> <span class=\"cs-fact-tag\">[취득시 기수]</span> 재물·이익 취득만으로 기수, 부정행위·배임행위 나아갈 것 不要 판단기준 (判例) : <span class=\"cs-fact-tag\">[예금통장]</span> 증재자로부터 입금계좌 통장·현금카드·신용카드 교부받아 소지하며 언제든 인출가능·실질적 사용·처분권 있으면 '예금된 돈' 취득으로 봄<span class=\"cs-exam\">【변23】</span> <span class=\"cs-fact-tag\">[제3자 취득도 직접취득 평가]</span> 다른 사람이 취득해도 그가 사자·대리인이거나, 청탁받은 자가 그 생활비 부담·채무 부담 등으로 지출 면하는 등 사회통념상 직접 받은 것과 같이 평가되면 성립 <span class=\"cs-fact-tag\">[제3자로 하여금 취득X]</span> <span class=\"cs-fact-tag\">[부정한 청탁의 대가여야]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①수수 재물·이익은 부정한 청탁의 대가·사례여야</div><div class=\"cs-li\" style=\"margin-left:16px\">②대향적 행위 필요 유형 배임죄에서 상대방이 계약상 의무 이행하고 실행행위자가 이행받은 것을 부정한 청탁 대가로 쉽게 단정 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[딸·지배회사 계좌]</span> 입점청탁 대가를 딸에게 주게 하거나 아들명의 자신 지배 주식회사 계좌로 입금케 함 → 직접 받은 것과 동일</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁 특허권 1,000만원 매도·이전등록, 계약상 의무 이행 지급을 대가로 단정 곤란]</span><span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>제3자로 하여금 취득하게 한 때</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[위임한 '타인'은 제3자 아님]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①'제3자'에 특별사정 없는 한 '사무처리 위임한 타인'은 불포함</div><div class=\"cs-li\" style=\"margin-left:16px\">②외형상 위임한 타인에 지급돼도 사회통념상 직접 받은 것과 동일 평가 가능 시 성립 <span class=\"cs-fact-tag\">[신문사가 피고인 실질적 1인 회사면 사실상 피고인 귀속→직접 받은 것과 동일 평가]</span><span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">[모사25, 모기23]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[신문사 교부X]</span> 홍보기사 대가로 '기자들 소속 신문사들'이 교부받음 = 사무처리자·제3자 교부 아님 → 배임수재죄<span class=\"cs-o\"><strong>(X)</strong></span> → 이를 전제한 배임증재죄도 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[조합운영비]</span> 조합 이사장이 대행기획사 선정하며 최종 선정회사로부터 조합운영비 명목 3,000만원 교부받아 조합운영비로 사용 → 자신 아닌 '타인'(조합)에 취득케 한 경우 배임수재죄<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[개인 이익 아닌 조합 경비]</span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-h\">Ⅳ. 배임증재죄와 배임수재죄의 관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 배임수재(<span class=\"cs-stat\"><strong>§357</strong></span>①)·배임증재(<span class=\"cs-stat\"><strong>§357</strong></span>②)는 통상 필요적 공범이나 반드시 수·증재자 같이 처벌해야 하는 것 X, 증재자엔 정당한 업무 청탁이라도 수재자엔 부정한 청탁일 수 있음</div><div class=\"cs-h\">Ⅴ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[동일인 포괄일죄]</span> 동일인으로부터 직무 관련 부정한 청탁받고 여러 차례 금품 수수, 단일·계속 범의+동일 피해법익이면 포괄일죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수인 실경]</span> 여러 사람으로부터 각 청탁받고 각 금품 수수 시, 청탁 동종이라도 단일·계속 범의 아님 → 포괄일죄 X <span class=\"cs-fact-tag\">[실체적 경합]</span><span class=\"cs-exam\">【변22】</span></div><div class=\"cs-h\">Ⅵ. 횡령·배임죄의 공범과 배임수증재</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[내부 이익분배X]</span> 금융기관 임직원이 대출상대방과 공모·임무위배 담보가치 초과대출하고 대출금 일부 돌려받기로 해 수수 = 업무상배임 공동정범 간 내부 이익분배 → 별도 <span class=\"cs-crime\">특경법위반(수재등)죄</span><span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[내부 분배X]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①공동 사기로 얻은 돈을 공범끼리 수수한 것이 내부 분배에 불과하면 배임수증재죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:32px\">②입찰담당자가 공사업자와 공모해 낙찰하한가 알아내 알려주고 낙찰케 하고 돈 수수 → 배임수재죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅶ. 몰수·추징</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 공여 금품에 부정한 청탁 대가 성질과 그 외 행위 사례 성질이 불가분 결합 시 전부가 불가분적으로 부정한 청탁 대가 성질<span class=\"cs-exam\">【변23】</span></div>", ["§357", "제357조"], 3, "gak_횡령배임"], ["개인070", "장물죄 일반", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제362조(장물의 취득, 알선 등)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 장물을 취득, 양도, 운반 또는 보관한 자는 7년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 전항의 행위를 알선한 자도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제364조(업무상과실, 중과실)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">업무상과실 또는 중대한 과실로 인하여 제362조의 죄를 범한 자는 1년 이하의 금고 또는 500만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 장물죄의 주체 (<span class=\"cs-stat\">§362</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[교사·방조범O]</span> 횡령 교사 후 그 횡령물 취득 → 횡령교사죄+장물취득죄 실체적 경합<span class=\"cs-exam\">【변26·25·21】</span><span class=\"cs-exam\">[변사26, 모사25]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[본범과 공동운반]</span> 본범은 장물죄 X, 그 외 자는 장물운반죄 → 절취 차량 정 알면서 강도 위해 운전해준 자는 강도예비+장물운반죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[공동정범·합동범·간접정범X]</span> 장물죄는 본범이 불법영득한 재물 처분에 관여하는 죄 → 자기 범죄로 영득한 물건엔 불성립(불가벌적 사후행위), '자기 범죄'의 정범자엔 공동정범·합동범 포함 <span class=\"cs-fact-tag\">[폭처법상 공동공갈 동일]</span><span class=\"cs-exam\">[변사26, 모사25, 모기25]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[집단 무관]</span> 평소 본범과 공동으로 상습 절도 자행해 실질적 범죄집단 이뤄도, 당해 범행 정범자 아니면 자기 범죄 아님 → 장물취득 불가벌적 사후행위<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅱ. 재산범죄로 영득한 재물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 장물 = 재산죄 범죄행위로 영득된 물건(절도·강도·사기·공갈·횡령 등 영득죄로 취득)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 장물죄도 장물죄 본범 될 수 있음(연쇄장물)<span class=\"cs-exam\">【변사26】</span> 본범은 구성요건 해당 위법행위면 족 <span class=\"cs-fact-tag\">[본범이 책임무능력자로 책임조각돼도 장물죄 성립]</span><span class=\"cs-exam\">【변사26】</span> <span class=\"cs-fact-tag\">[불가벌적 사후행위물O]</span> 재산범죄 후 별도 재산범죄 구성요건 해당 사후행위가 있으면, 불가벌적 사후행위여도 그로 취득한 물건은 장물 가능<span class=\"cs-exam\">【변20】</span> '배임수재'로 취득한 재물도 장물에 해당 이득죄인 컴퓨터등사용사기죄·배임죄는 장물죄 본범<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 대체장물의 장물성</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 장물은 영득 재물 그 자체이거나 물질적 동일성 유지되는 것 → 대체장물은 장물<span class=\"cs-o\"><strong>(X)</strong></span> (매각대금·교환재물·장물로 산 물건 모두 X) 장물의 처분 대가는 장물성 상실</div><div class=\"cs-h\">Ⅳ. 환전통화의 장물성<span class=\"cs-exam\">【모사25·24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《환전한 통화에 장물성이 유지되는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(가치 동일성 중시)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(가치 동일성≠재물 동일성)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 장물 현금·수표를 예금 보관 후 동액 현금·수표 인출 → 물리적 동일성 상실되나 금전적 가치 무변동 → 장물성 유지<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 금전은 가치가 거래상 의미 갖고 유통 → 긍정설 타당</div></div><div class=\"cs-h\">Ⅴ. 취득·양도·운반·보관 및 알선</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[취득]</span> 유상·무상 모두 포함<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[취득=처분권 획득]</span> 취득은 점유 이전받아 사실상 처분권 획득하는 것, 단순 보수받고 일시사용·사용목적 건네받은 것만으론 취득 X <span class=\"cs-fact-tag\">[장물보관죄 직권 인정 의무]</span><span class=\"cs-exam\">【변12】</span> <span class=\"cs-fact-tag\">[알선]</span> 당사자 연결·중개·편의 도모하면, 실제 계약 미성립·점유 미이전이어도 장물알선죄 성립 <span class=\"cs-fact-tag\">[중개 후 매수인 전달하려다 만나기 전 체포된 경우]</span><span class=\"cs-exam\">【변22·17·13】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[횡령물=장물]</span> A가 회사자금으로 B에 주식매각대금 지급 시 그 금원은 횡령행위 제공 물건이 아닌 영득 장물, A의 업무상횡령 기수와 동시에 장물化</div><div class=\"cs-h\">Ⅵ. 장물죄의 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[미필적 고의]</span> 확정적 인식 不要, 장물일지 모른다는 의심 정도 미필적 인식으로 충분 본범 범행 구체적으로 알 필요 X, 미필적 인식으로 족 본범이 어느 범죄로 영득했는지 구체적 명시 不要</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[취득]</span> 취득 당시 장물 정 알면서 취득해야 성립 → 인도받은 후 비로소 장물 의심 가져도 장물취득죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[보관]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①모르고 보관하다 정 알고 계속 보관 = 장물죄, 다만 점유할 권한 있으면 계속 보관해도 장물보관죄 X</div><div class=\"cs-li\" style=\"margin-left:32px\">②모르고 보관 중 알게 됐고 반환 불가능하지 않은데 계속 보관 → 장물보관죄</div><div class=\"cs-h\">Ⅶ. 업무상과실장물죄 (<span class=\"cs-stat\">§364</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[진정신분범]</span> 단순 과실장물죄 처벌규정 없고 업무상과실 보관자만 처벌 → 업무자 신분은 진정신분범 <span class=\"cs-fact-tag\">[부진정신분범X]</span><span class=\"cs-exam\">【변19】</span></div>", ["§362", "§364", "제362조", "제364조"], 3, "gak_기타재산"], ["개인071", "장물을 절도·강도·공갈·사기로 취득한 경우", "<div class=\"cs-h\">Ⅰ. 장물죄의 본질</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《장물죄의 본질》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①추구권설(피해자 반환청구권 행사 곤란케 함)</div><div class=\"cs-li\" style=\"margin-left:16px\">②위법상태유지설(본범 위법 재산상태를 본범·점유자와 합의 아래 유지·존속)</div><div class=\"cs-li\" style=\"margin-left:16px\">③결합설(양자 결합)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[결합설]</span> 결합설 입장으로 평가</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 양자 모두에서 본질 파악하는 결합설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[불법원인급여물]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①추구권설: 반환청구권 없으므로 장물 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②유지설: 사법상 추구권과 무관하게 장물성 긍정</div><div class=\"cs-h\">Ⅱ. 장물을 절도·강도·공갈·사기로 취득한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《장물을 절도·강도·공갈·사기로 취득 시 장물취득죄 성립 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(추구권설, 반환청구권 행사 곤란케 함)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(유지설·결합설, 본범과 합의 없음)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[부정설]</span> 타인 갈취 재물(장물)을 그 타인 의사에 반해 '절취' → 절도죄만 성립, 장물취득죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 유지설·결합설 입장에서 부정설 타당</div></div><div class=\"cs-h\">Ⅲ. 자기의 소유물인 장물을 돌려받은 경우<span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 피해자가 본범·점유자로부터 장물 돌려받는 경우, 장물이나 자기 재물 회수 → 추구권 곤란케 X·위법상태 유지 X → 장물취득죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅳ. 변제를 독촉(공갈)하고 단순히 장물임을 알면서 받은 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 장물 자체를 갈취·절취한 것 아니라 변제 독촉(공갈)하고 단순 장물 정 알면서 변제받은 경우 → 장물취득죄<span class=\"cs-o\"><strong>(O)</strong></span></div>", [], 1, "gak_기타재산"], ["개인072", "장물의 처분", "<div class=\"cs-h\">Ⅰ. 본범이 처분하는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 영득죄로 취득한 장물 '처분'은 재산죄 수반 '불가벌적 사후행위' → 다른 죄 불구성</div><div class=\"cs-h\">Ⅱ. 장물범이 처분하는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[장물보관 후 처분]</span> 절도범으로부터 장물보관 의뢰받아 정 알면서 보관하다 임의 처분해도, 장물보관죄 성립하는 때엔 이미 소유물 추구권 침해 → 이후 횡령은 불가벌적 사후행위 → 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">[변사25·18·13, 모사25·16]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[업무상과실보관 후 처분]</span> '업무상과실'로 보관하다 처분 → <span class=\"cs-crime\">업무상과실장물보관죄</span> 가벌적 평가에 포함 → 별도 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅲ. '제3자'에 대한 사기 (매도·담보제공 등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도범이 절취 장물을 자기 것인양 제3자 기망해 금원 편취 → 소비·손괴와 달리 제3자 관계에서 새 법익침해 → 절도죄 외 사기죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변사19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절도·강도·공갈로 취득한 예금통장으로 은행원 기망·명의인이 찾는 것으로 오신케 해 예금 편취 → 사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">절취한 전당표를 전당포 교부하며 전당물 편취 → 새 법익침해 → 사기죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">횡령자가 유효 권리 있는 것처럼 기망해 횡령물 처분 → 제3자에 대한 사기죄<span class=\"cs-x\"><strong>(X)</strong></span> (반대견해 有) <span class=\"cs-neg-tag\">[도품유실물특칙 적용X]</span></div><div class=\"cs-h\">Ⅳ. 금융기관 발행의 자기앞수표</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li\" style=\"margin-left:16px\">①금융기관 발행 자기앞수표는 즉시 지급받아 현금 대신 기능 → 절취 자기앞수표를 현금 대신 교부는 절도 가벌적 평가에 포함 → 절취 자기앞수표를 음식대금 교부·거스름돈 환불받아도 절도의 불가벌적 사후처분행위, 사기죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②'장물인 자기앞수표 취득' 후 현금 대신 교부도 장물취득 가벌적 평가에 포함되는 불가벌적 사후행위 → 별도 사기죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변21·16】</span><span class=\"cs-exam\">【모기21·19·18】</span></div>", [], 2, "gak_기타재산"], ["개인073", "재물손괴죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제366조(재물손괴등)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">타인의 재물, 문서 또는 전자기록등 특수매체기록을 손괴 또는 은닉 기타 방법으로 그 효용을 해한 자는 3년이하의 징역 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제369조(특수손괴)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제366조의 죄를 범한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 타인소유의 재물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[공유물]</span> 절도죄·횡령죄·재물은닉죄에서 공유물은 해당 범죄 객체인 '타인의 재물'에 속함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[철거예정 아파트O]</span> 재건축 철거예정·전원 이주해 무거주 아파트도 재물손괴죄 객체<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[부패 포도주원액O]</span> 원료 효용가치 상실됐으나 식초 제조 등 다른 용도 사용 가능하면 재물손괴죄 객체<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[식재 수목]</span> 타인 토지에 수목 식재 당시 소유권자로부터 명시·묵시 승낙·동의·허락 받았으면 민법 <span class=\"cs-stat\"><strong>§256</strong></span> 부합 예외의 '권원' 해당 → 수목은 토지에 부합 X, 식재자 소유 <span class=\"cs-neg-tag\">[승낙·무상사용 허락 가능성 배제 곤란→절단 수목이 피해자 소유라 볼 수 없음→특수재물손괴죄 X]</span></div><div class=\"cs-h\">Ⅱ. 손괴, 은닉, 기타 방법</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '기타 방법' = 손괴·은닉에 준하는 정도 유형력 행사로 재물 효용 해하는 행위</div><div class=\"cs-h\">Ⅲ. '재물'의 효용 침해</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[감정상O]</span> '효용을 해한다' = 사실상·'감정상' 본래 사용목적에 제공 못하는 상태로 만드는 것 <span class=\"cs-fact-tag\">[일시적O]</span> '일시적'으로 이용·구체적 역할 못하게 하는 것도 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[차량 구조물]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①차량 앞뒤에 제거 어려운 철근콘크리트 구조물 바짝 붙임 = 유형력 행사(기타 방법)</div><div class=\"cs-li\" style=\"margin-left:32px\">②물리적 훼손·기능 멸실 없어도 운행 불가로 일시적 사용목적 이용 불가케 한 이상 효용 침해<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[자동문 수동화]</span> 자동문을 수동으로만 개폐 가능케 해 자동잠금장치 역할 못하게 함 → 재물손괴죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[낙서·계란]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①래커스프레이로 외벽·벽면 낙서 → 효용 침해<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:32px\">②계란 30여개 투척 → 효용 침해<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[게시 문서]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①소유자 의사로 게시된 문서를 의사에 반해 떼어내어 종래 이용상태 변경·일시 이용 불가케 하면 문서손괴죄 가능</div><div class=\"cs-li\" style=\"margin-left:32px\">②종래 사용상태가 소유자 의사에 반해·무관하게 이뤄진 경우 이를 제거·변경만 할 뿐 새로 사용 지장 초래 않으면 사용가치 해한 것 아님 → 문서손괴죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅳ. 불법영득의사의 부존재</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 재물손괴죄(<span class=\"cs-stat\"><strong>§366</strong></span>)는 이용·처분 의사(불법영득의사) 없다는 점에서 절도·강도·사기·공갈·횡령 등 영득죄와 구별</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[무단 사용·수익]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①타인 소유물을 본래 용법대로 무단 사용·수익 = 소유자 배제·이용가치 영득, 소유자가 효용 못 누려도 '효용 자체' 침해 아님 → 재물손괴죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:32px\">②타인 토지에 무단 건물 신축 = 이미 대지화된 토지를 부지로 사용·수익해 소유자가 효용 못 누리게 한 것일 뿐, 토지 효용 해친 것 아님 → 재물손괴죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【모기23】</span></div>", ["§256", "§366", "제366조", "제369조"], 3, "gak_기타재산"], ["개인074", "자동차의 대내적·대외적 소유관계", "<div class=\"cs-h\">Ⅰ. 특별한 약정이 없는 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 자동차 소유권 득실변경은 등록으로 효력 발생, 등록 없으면 대외·대내 관계 모두 소유권 취득 X (원칙)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[타인명의 등록]</span> 담보제공 차량이 타인명의 등록이면 피고인 소유 아님(등록명의자 소유) → 승낙 없이 미리 소지한 보조키로 운전해 감 → <span class=\"cs-crime\">권리행사방해죄</span><span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변21·17·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[지입]</span> 택시를 회사에 '지입' 운행해도 소유권 보유 약정 등 특별사정 없으면 등록명의 회사 소유 → 승낙 없이 가져감 → 권리행사방해죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[미등록]</span> 렌트카회사 공동대표 1인이 미등록 회사보유 차량을 개인 채무담보로 피해자에 넘긴 것을 다른 공동대표(피고인)가 몰래 회수케 함 →</div><div class=\"cs-li\" style=\"margin-left:32px\">①피해자 점유는 잠정 보호가치 있는 점유에 포함되나</div><div class=\"cs-li\" style=\"margin-left:32px\">②미등록 상태라 회사·피고인 소유물 아님 → 권리행사방해죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅱ. 특별한 약정이 있는 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>소유권 관계 <span class=\"cs-fact-tag\">[대내적·대외적 관계 구분]</span></strong> 적용범위: 등록명의자 아닌 자가 소유권 보유 약정 시 → 내부관계에선 명의자 아닌 자 소유, 제3자 관계에선 등록명의자 소유</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>대내적 관계</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[증여]</span> 사실혼 피해자에 승용차 증여 후 피해자만 운행·관리, 별거하며 재산분할·위자료 명목으로 피해자 소유키로 → 등록명의(피고인)와 무관하게 내부적으로 피해자 소유 → 피고인이 절취하면 절도죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변21】</span><span class=\"cs-exam\">【변기16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁]</span> 제3자가 명의수탁자로부터 승용차 매도 허락·인감증명 교부받아 명의신탁자 몰래 가져감 → 제3자·명의수탁자 공모·가공 절도죄 공모공동정범 <span class=\"cs-fact-tag\">[면세 위해 甲명의 등록, 수탁자 甲·딸 乙 공모, 甲이 이전서류 교부·乙이 신탁자 A 몰래 가져와 처분]</span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>대외적 관계</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대외=명의자]</span> 母 A 명의 구입·등록해 명의신탁한 자동차를 甲에 담보제공 후 몰래 가져감 → 甲 관계에서 소유자는 A, 피고인은 소유자 아님 → 甲 점유 자동차 임의로 가져감 → 절도죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20·14】</span></div>", [], 3, "gak_기타재산"], ["개인075", "권리행사방해죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제323조(권리행사방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">타인의 점유 또는 권리의 목적이 된 자기의 물건 또는 전자기록등 특수매체기록을 취거, 은닉 또는 손괴하여 타인의 권리행사를 방해한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 자기의 물건 또는 전자기록등 특수매체기록 (진정신분범, <span class=\"cs-stat\">§323</span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>진정신분범</strong> 적용범위: 취거·은닉·손괴한 물건이 자기 물건 아니면 권리행사방해죄 X <span class=\"cs-fact-tag\">[판례는 </span><span class=\"cs-stat\">§33</span><span class=\"cs-fact-tag\"> 본문 적용해 사실상 진정신분범 취급]</span> 소유자 아닌 자는 <span class=\"cs-stat\"><strong>§33</strong></span> '본문'에 따라 소유자 범행 가담한 경우에 한해 공범 가능 공범 기소된 물건 소유자에 고의 없는 등 범죄 불성립이면 공동정범 성립 여지 X<span class=\"cs-exam\">【변20】</span> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①교사범 성립엔 정범 실행행위 必, 정범 성립은 교사범 구성요건 일부</div><div class=\"cs-li\" style=\"margin-left:16px\">②정범이 자기 물건 아닌 도어락 비밀번호 변경해도 권리행사방해죄 X → 정범 불성립이면 교사자도 권리행사방해교사죄 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[도어락 사례 – 공범과 신분]</span> [퇴거 거부한 5층 거주 피해자에 대해, 건물 관리 피고인이 아들 A에게 자기 소유 디지털 도어락 비밀번호 변경을 지시하고 지켜보는 가운데 A가 변경]</div><div class=\"cs-li\" style=\"margin-left:48px\">①A가 자기 물건 아닌 도어락 변경해도 권리행사방해죄 X(진정신분범 취급), 정범 A 불성립이면 피고인도 교사죄 X(제한적 종속형식)</div><div class=\"cs-li\" style=\"margin-left:48px\">②A가 전혀 모르면 피고인에 간접정범 가능(사실적 의사지배)</div><div class=\"cs-li\" style=\"margin-left:48px\">③A가 알고 있어도(고의) 기능적 행위지배 없으면 피고인에 간접정범(규범적·사회적 의사지배설)</div><div class=\"cs-li\" style=\"margin-left:48px\">④피고인·A 모두 기능적 행위지배 있으면 피고인에 공동정범</div><div class=\"cs-li\" style=\"margin-left:48px\">⑤실제 사안 검사가 공동정범으로 공소장 변경, 파기환송심 유죄(A엔 <span class=\"cs-stat\"><strong>§33</strong></span> 본문 적용)<span class=\"cs-exam\">【변20】</span><span class=\"cs-exam\">[변사25, 모기23]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>자기 소유 물건</strong> 개념: '자기의 물건' = 범인이 소유하는 물건, 소유 여부는 민법 기타 법령으로 정함 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공유물O]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①공유물은 범인 지분비율 범위에서 '자기의 물건'</div><div class=\"cs-li\" style=\"margin-left:48px\">②제한물권·채권이 다른 공유자 지분만 목적으로 하는 특별사정 없는 한, 공유자는 소유자로서 '자기의 물건'에 대한 권리행사 방해로 평가 → 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공유 자동차]</span> <span class=\"cs-fact-tag\">[피고인이 공유 자동차에 피해자 저당권 설정해주고도 甲에 담보제공·은닉]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①소유권 보유 약정 여부와 무관하게 제3자 관계에선 피고인·乙(1%:99%)이 공유자</div><div class=\"cs-li\" style=\"margin-left:48px\">②지분비율 범위에서 '자기의 물건'이고 피해자 근저당이 피고인 지분도 목적 → 담보 인도는 '자기의 물건' 은닉해 권리행사 방해</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대표이사]</span> 대표이사가 그 지위·직무집행으로 타인 점유 회사 물건 취거 → 회사 대표기관 행위 → 회사 물건도 '자기의 물건'<span class=\"cs-exam\">【변23】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[대리인·지배인]</span> 법인 대리인·지배인이 대표기관과 공모 없이 직무권한 범위 내 타인 점유 법인 물건 취거해도, 대표기관 행위와 효력 동일·불법영득의사 없어 실질 차이 없음 → '자기의 물건' 취거에 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[경매]</span> 부동산경매서 명의신탁약정으로 타인 명의 매각허가·자기 부담 대금완납 → 소유권은 명의인 취득 → '아들' 명의 강제경매로 건물 매수 후 피해자 유치권 점유 침탈해도 자기 물건 아님 → 권리행사방해죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[공동정범 아닌 아들 소유]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[명의신탁]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①중간생략등기형·계약명의신탁으로 '처'에 명의신탁한 점포에 자물쇠 채워 임차인 출입 못하게 함 → 자기 물건 아님</div><div class=\"cs-li\" style=\"margin-left:48px\">②조세포탈 목적 무효면 매도인 소유, 유효라도 제3자(임차인) 관계에선 명의신탁자는 소유자 아님(대외적으로 수탁자 처 소유) → 어느모로나 자기 물건<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[처가 공동정범 아닌 경우]</span></div><div class=\"cs-h\">Ⅱ. 타인의 점유 또는 권리의 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 단순 채권·채무관계(매수인 권리 등)는 '권리의 목적'에 불포함 (일반적 견해) <span class=\"cs-fact-tag\">[점유 범위]</span> 권원에 기한 점유만 아니라, 적법 점유 개시 후 권원 상실 점유, 권원 존부 불명해 법정절차 밝혀질 때까지 점유, 동시이행항변권 등으로 대항 가능한 점유 등 잠정 보호가치 있는 점유 모두 포함 <span class=\"cs-neg-tag\">[본권 점유에 한정 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[무효 경매 낙찰자O]</span> 무효 경매서 경락받아 점유하는 낙찰자 점유는 동시이행항변권에 기한 적법 점유 → 보호대상<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변22·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[절도범 점유X]</span> 절도범 점유처럼 점유할 권리 없음이 외관상 명백한 경우는 불포함</div><div class=\"cs-h\">Ⅲ. 취거, 은닉 또는 손괴</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[취거]</span> 점유자 의사에 반해 자기·제3자 점유로 옮기는 것 → 점유자 의사나 '하자있는 의사에 기하여' 이전된 경우는 취거<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[담보물을 편취당한 장물이라 속여 받아온 경우 X]</span> <span class=\"cs-fact-tag\">[은닉]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①소재를 발견 불능·현저히 곤란한 상태에 두는 것</div><div class=\"cs-li\" style=\"margin-left:16px\">②피고인 소유 자동차에 저당권 설정해주고 다시 담보제공·매도해 '대포차'로 유통 → 은닉</div><div class=\"cs-li\" style=\"margin-left:16px\">③근저당 설정 기계·기구 양도해 소재 발견 곤란케 함 → 은닉 <span class=\"cs-fact-tag\">[손괴]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①근저당 설정 건물 철거</div><div class=\"cs-li\" style=\"margin-left:16px\">②유류분반환청구권에 기해 가압류된 건물 철거</div><div class=\"cs-h\">Ⅳ. 타인의 권리행사 방해</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[위험범]</span> 현실로 방해될 것 不要, 방해할 '우려' 있는 상태 이르면 완성되는 위험범 <span class=\"cs-fact-tag\">[철거된 가압류 건물과 함께 가압류된 토지 가치 상당·신축돼 채권보전 지장 없어도 성립 지장 없음]</span></div><div class=\"cs-h\">Ⅴ. 죄수관계와 친족상도례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[권리자별 상경]</span> 여러 사람 권리 목적 자기 물건 취거·은닉·손괴로 여러 권리행사 방해 → 권리자별 각 권리행사방해죄 성립, 각 죄 상상적 경합<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[친족상도례 개별판단]</span> <span class=\"cs-stat\"><strong>§328</strong></span>① 형면제 요건(현재 상대적 친고죄) 해당 여부는 각 죄마다 살펴야 <span class=\"cs-fact-tag\">[유류분권리자별 개별 적용]</span></div>", ["§323", "§33", "§328", "제323조"], 3, "gak_기타재산"], ["개인076", "강제집행면탈죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제327조(강제집행면탈)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">강제집행을 면할 목적으로 재산을 은닉, 손괴, 허위양도 또는 허위의 채무를 부담하여 채권자를 해한 자는 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 강제집행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 강제집행면탈죄의 강제집행 = 민사집행법 제2편 '강제집행' 또는 '가압류·가처분' 집행</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[O]</span> 광의의 강제집행인 의사진술에 갈음하는 판결의 강제집행</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X]</span> 민사집행법 제3편 담보권 실행 등 경매<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X]</span> 국세징수법상 체납처분<span class=\"cs-exam\">【변17·13】</span></div><div class=\"cs-h\">Ⅱ. '채권'의 존재</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[성립요건]</span> 채권자 권리보호가 주된 보호법익 → '채권의 존재'는 성립요건, 채권 부존재 시 불성립<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[조건부 채권O]</span> 조건부 채권도 성립, 이후 조건 불성취로 채권 소멸돼도 이미 성립한 범죄에 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[상계 소멸 채권X]</span> 상계 의사표시 시 상계 가능한 때로 소급 소멸 → 상계로 소멸한 채권은 '상계 효력 발생 시점 이후'엔 채권 부존재 → 불성립 <span class=\"cs-fact-tag\">[기소 후 제1심 중 상계 의사표시로 범행 전 소급 상계면 전단무죄]</span><span class=\"cs-exam\">【변16】</span><span class=\"cs-exam\">【모기14】</span></div><div class=\"cs-h\">Ⅲ. 강제집행면탈죄의 '객체' – 채무자의 재산</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 객체 = 채무자 재산 중 채권자가 민사집행법상 '강제집행 또는 보전처분 대상' 삼을 수 있는 것</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[장래의 권리O]</span> 장래청구권이 충분히 표시·결정된 법률관계 존재하면 동산·부동산뿐 아니라 장래 권리도 객체 <span class=\"cs-fact-tag\">[경매 배당금지급채권 객체 해당]</span><span class=\"cs-exam\">【변17·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[가압류채권자 지위X]</span> 보전처분 단계 '가압류채권자 지위' 자체는 원칙적으로 강제집행·보전처분 대상 될 수 없어 객체 X, 가압류해방금 공탁해도 동일<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[계약명의신탁]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①'선의' 계약명의신탁의 신탁자:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">부동산실명법 <span class=\"cs-stat\"><strong>§4</strong></span>②단서로 수탁자가 완전한 소유권 취득</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">②'악의': 수탁자 등기 무효, 소유권은 '매도인'이 보유</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">③어느 경우든 명의신탁자는 소유권 미취득</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">→ 그 부동산은 '명의신탁자'에 대한 강제집행·보전처분 대상<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변16】</span><span class=\"cs-exam\">【모기14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[압류금지채권]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①압류금지'채권' 목적물이 채무자 예금계좌 입금되면 예금채권엔 압류금지 효력 미치지 않음 → '예금'은 압류금지채권 아님</div><div class=\"cs-li\" style=\"margin-left:32px\">②계좌 입금 전까진 여전히 대상 될 수 없음 → 기존 계좌 압류된 채무자가 압류 안 된 다른 계좌로 수령해도 불성립<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-h\">Ⅳ. 강제집행을 받을 우려가 있는 객관적 상태</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 현실적으로 강제집행·가압류·가처분 받을 우려 있는 객관적 상태 (적어도 채권자가 소 제기·신청할 '기세' 보이는 상태)에서 면탈 목적 재산 은닉·손괴·허위양도·허위채무 부담해 채권자 해할 '위험' 있으면 성립<span class=\"cs-exam\">【변20·13】</span><span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[구체적 위험]</span> 약 18억 채무초과 상태 자가 발행 약속어음 부도 → 강제집행 당할 구체적 위험 인정<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅴ. 은닉, 손괴, 허위양도 또는 허위채무 부담</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>은닉</strong> 개념: <span class=\"cs-fact-tag\">[소유관계 불명O]</span> '은닉' = 강제집행 실시자에 대해 재산 발견 불능·곤란케 하는 것, 소재 불명뿐 아니라 '소유관계 불명'케 하는 경우도 포함 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[금전등록기 명의변경]</span> 사업자명의 변경 없이 사업장 '금전등록기' 사업자 이름만 변경 → 재산 '은닉'<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[제3자→다른 제3자 변경X]</span> 제3자 명의 사업자등록을 다른 제3자 명의로 변경한 사정만으론 소유관계를 종전보다 더 불명케 해 손해 위험 야기한다 단정 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>허위양도 또는 허위채무 부담</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[허위채무O]</span> 처의 재산분할청구권 기한 가압류 우려 상태서 남편이 면탈 목적 허위채무 부담·소유권이전청구권보전가등기 → 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[송금 후 즉시 현금 인출·반환 방법]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[진의 양도X]</span> '진의'에 의한 양도인 이상 면탈 목적·채권자 불이익 초래해도 허위양도<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[진실한 채무담보X]</span> 장래 발생할 '특정 조건부채권' 담보 위해 근저당 설정한 것이면, 특별사정 없는 한 진실한 채무 담보 위한 것 → 허위채무 부담<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[순위보전 가등기X]</span> 채무 부담하는 양 가장 방편 소유권이전청구권보전 가등기는 원래 순위보전 효력뿐 → 그 사실만으론 허위채무 부담해 채권자 해했다 할 수 없음</div><div class=\"cs-h\">Ⅵ. 채권자를 해할 위험</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[위험범]</span> 강제집행면탈죄는 '위태범' → 채권자 해할 '위험' 있으면 성립, 반드시 현실 손해·행위자 이득 要 X <span class=\"cs-fact-tag\">[현실적 손해 불요]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[다른 재산 有해도O]</span> 면탈 목적 허위채무 부담·근저당설정으로 채권자 해했다 인정되면, 근저당 설정 부동산 외 약간의 다른 재산 있어도 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[담보채무 초과]</span> 허위양도 부동산 시가액보다 담보 채무액이 더 많아도 채권자 해할 위험 없다 할 수 없음<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[충분한 다른 재산]</span> 채권 존재해도 은닉 등 행위 시 기준 집행 확보에 충분한(훨씬 상회하는) 다른 재산 있었으면 해할 우려 쉽사리 단정 X<span class=\"cs-exam\">【변20·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[채권 허위양도]</span> 가압류집행 면탈 목적 제3채무자에 대한 채권을 제3자에 허위양도, 가압류결정 정본이 제3채무자에 송달되기 前 허위양도면 성립 <span class=\"cs-fact-tag\">[송달 후 허위양도면 가압류채권자 지위에 영향 없어 집행 방해 없음→불성립]</span><span class=\"cs-exam\">【변21·17·16】</span></div><div class=\"cs-h\">Ⅶ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 복수 채권자 강제집행 예상 시 재산 은닉·허위양도로 채권자들 해하면 채권자별 각 강제집행면탈죄 성립, 상호 상상적 경합</div><div class=\"cs-h\">Ⅷ. 공소시효</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 채권 허위양도 시 늦어도 제3채무자에 채권양도 통지 있는 때 범죄 종료·공소시효 진행 <span class=\"cs-fact-tag\">[기산점=제3채무자에 채권양도 통지된 때]</span><span class=\"cs-exam\">【변17】</span> 허위채무 채무변제계약 공정증서 작성 후 채권압류·추심명령 받은 때 성립과 동시에 종료·공소시효 진행 <span class=\"cs-fact-tag\">[배당받은 때X]</span><span class=\"cs-exam\">【변16】</span></div>", ["§4", "제327조"], 3, "gak_기타재산"], ["사회001", "문서죄 기본 법리", "<div class=\"cs-h\">Ⅰ. 문서 일반</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공문서</strong> 적용범위: 금융위원회법상 금융감독원 집행간부인 금융감독원장 명의 문서 위조·행사 → 사문서위조·위조사문서행사 아니라 공문서위조·위조공문서행사 해당</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>사문서</strong> 개념: 사문서위조·동행사죄 객체인 사문서 = 권리·의무 또는 사실증명에 관한 타인의 문서·도화(<span class=\"cs-stat\"><strong>§231</strong></span>) →</div><div class=\"cs-li\" style=\"margin-left:16px\">①'권리·의무 문서' = 권리·의무의 발생·변경·소멸 사항 기재된 것</div><div class=\"cs-li\" style=\"margin-left:16px\">②'사실증명 문서' = 권리·의무 문서 이외로 거래상 중요한 사실 증명하는 문서 판단기준 (判例) : '거래상 중요 사실 증명 문서'</div><div class=\"cs-li\" style=\"margin-left:16px\">①법률관계 발생·존속·변경·소멸 증명이 주된 취지인 문서뿐 아니라 법률관계에 간접적으로만 연관·사실상만 영향 줄 의사표시 문서도 포함 가능하나</div><div class=\"cs-li\" style=\"margin-left:16px\">②단순 개인적·집단적 의견표현에 불과해선 안 되고 실체법·절차법상 구체적 권리·의무와 관련성 인정되어야 함 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[담뱃갑]</span> 담뱃갑 안 담배가 특정 제조회사 제조 특정 종류 담배라는 사실 증명 기능 → 문서 등 위조 대상 도화<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[특정 대통령후보 정치적 지지의사 집단표현 위해 허무인 명의 서명부 21장 X]</span><span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>문서의 사본</strong> 적용범위: 전자복사기·모사전송기 기타 유사기기 사용 복사한 문서·도화 사본도 문서·도화로 봄(<span class=\"cs-stat\"><strong>§237의2</strong></span>) 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[위조된 문서원본 복사]</span> '위조된 문서원본'을 전자복사기로 복사해 '사본 만드는 행위'도 별개 문서사본 창출로 문서위조행위 해당<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>이미지 또는 이미지파일</strong> 개념: <span class=\"cs-fact-tag\">[시각성(가독성)·계속성]</span> 문서 = 문자 또는 이에 대신할 '가독적 부호'로 '계속적'으로 물체상 기재된 의사·관념 표시 원본 또는 이와 사회적 기능·신용성 동일시할 기계적 방법 복사본으로서 내용이 법률상·사회생활상 주요사항 증거 될 수 있는 것<span class=\"cs-exam\">【모사18, 모기16】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[이미지 및 이미지파일]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①<span class=\"cs-fact-tag\">[이미지]</span> 모니터 화면 '이미지'는 화면 고정으로 볼 수 X (계속성X, 시각성O)</div><div class=\"cs-li\" style=\"margin-left:48px\">②<span class=\"cs-fact-tag\">[이미지파일]</span> 스캔 작업 '이미지 파일'은 전자기록으로 고정되어 계속성 있으나 시각적 방법으로 이해X(계속성O, 시각성X) → 형법상 문서에 해당<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·21·18·14】</span><span class=\"cs-exam\">【변기25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[전세계약서 스캐너 복사→포토샵 공란→프린터 출력·볼펜으로 보증금액 허위 기재·교부]</span> 사문서변조·변조사문서행사 성립 <span class=\"cs-fact-tag\">[프린터로 출력된 문서를 변조한 행위]</span><span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[주민등록증 이름·번호란에 글자 오려붙인 후 스캔→모니터 출력·이메일 전송]</span> 형법상 문서에 해당<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">5. <strong>명의인</strong> 판단기준 (判例) : 인장 날인X·주민등록번호 기재X라도 일반인이 작성명의자가 진정 작성한 사문서로 믿기 충분한 형식·외관 갖추면 사문서위조·동행사죄 객체 사문서<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변17】</span> <span class=\"cs-fact-tag\">[사자·허무인 명의 문서O]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①명의인이 실재X 허무인이거나 작성일자 전 이미 사망했어도 공공 신용 해할 위험 있어 문서위조 성립</div><div class=\"cs-li\" style=\"margin-left:16px\">②공문서뿐 아니라 사문서도 마찬가지<span class=\"cs-exam\">【변26·21·18·12】</span><span class=\"cs-exam\">【변사23·15, 모사24·21·17, 변기16】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①이 법리는 법인·단체에도 그대로 적용</div><div class=\"cs-li\" style=\"margin-left:16px\">②위조행사한 법인명의 사문서가 법인 해산등기로 법인격 소멸 이후 또는 소멸 이후 일자로 작성됐어도 사문서위조·동행 해당</div><div class=\"cs-h\">Ⅱ. 유형위조 – 위조·변조, 자격모용작성</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>위조</strong> 판단기준 (判例) : 기존 진정문서 중요부분 변경해 새 증명력 갖는 '별개의 문서' 작성 → 변조 아닌 위조 해당 작성명의자 '날인' 정당 성립 사문서라도 내용 기재 정당권한 없는 자가 기재하거나 위임받은 자가 '권한 초과'해 기재함으로써 날인자 의사 반하는 사문서 작성 시 사문서위조 성립 <span class=\"cs-fact-tag\">[문서에 미리 날인 받은 후 내용 기재한 경우]</span> 명의인 기망해 문서 작성케 하는 경우 서명·날인 정당 성립이라도 기망자가 명의인 이용해 서명날인자 의사 반하는 문서 작성케 하는 것 → 사문서위조 <span class=\"cs-fact-tag\">[사문서위조의 간접정범]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①문서작성 보조 직무 공무원이 작성권자 결재 없이 임의로 직인 등 부정사용해 공문서 완성 시 공문서위조</div><div class=\"cs-li\" style=\"margin-left:16px\">②작성권 없는 사람이 허위공문서 기안해 결재 없이 완성한 경우도 마찬가지 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[문서 원본 여부 중요 거래에서 원본 그대로 컬러복사→사본을 원본처럼 행사]</span> 사문서위조·동행사 해당 <span class=\"cs-fact-tag\">[변호사가 경유증표 복사하여 원본인 것처럼 첨부]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">[이사들이 대표이사에게 맡긴 인장으로, 미개최 이사회에 불참 이사가 참석·결의한 것처럼 회의록 작성·날인] 사문서위조·동행사 성립 — 인장 위임은 일상·관행적 업무처리 사용 허락일 뿐 회의록 작성까지 포괄위임 X<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>변조</strong> 개념: 공문서변조 = 권한없이 '이미 진정 성립' 공무원·공무소 명의 문서내용에 '동일성 해하지 않을 정도 변경' 가하는 것 / '이미 허위 작성된 공문서'는 공문서변조 객체X 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①사문서변조 = 진정 성립 문서 내용에 권한 없는 자가 동일성 안 해하는 한도 변경 가해 새 증명력 작출, 권한없는 자에 의해 '변조된 부분'은 진정성립 부분X</div><div class=\"cs-li\" style=\"margin-left:16px\">②따라서 권한없는 자가 '이미 변조된 부분'을 다시 권한없이 변경해도 사문서변조 X 이미 진정 성립 타인 명의 문서 존재X면 사문서변조 성립 X 2인 이상 작성명의인 있는 때 한 명이 타명의자와 합의없이 행사목적으로 내용 변경 → 사문서변조 성립<span class=\"cs-exam\">【변17】</span> 최종 결재권자 보조 기안업무 담당 공무원이 이미 결재받아 완성된 공문서를 적법절차 없이 내용 변경 → 특별사정 없는 한 공문서변조 성립<span class=\"cs-exam\">【변21】</span> 이사가 회의록에 서명 대신 서명거부사유 기재·그에 서명하면 회의록 일부 되므로, 작성권한자 이사장이라도 임의 삭제 시 사문서변조 해당 인감증명서 사용용도란 기재는 동장이 작성한 증명문구와 무관 → 권한없는 자가 사용용도란 고쳐 써도 공문서변조·변조공문서행사 성립 X</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>자격모용작성</strong> 적용범위: 자격모용 사문서작성죄 '타인' = 자연인뿐 아니라 법인·법인격 없는 단체 등 거래관계에서 독립한 사회적 지위 갖고 활동하는 존재 포함 <span class=\"cs-fact-tag\">['○○부동산 대표 △△△']</span> 주식회사 대표 자격 계약 시 피고인 자신 위한 행위 아니고 작성명의인 회사 위해 법률행위 한다는 것 인식할 정도 표시 있으면 대표관계 표시<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>위조·변조 및 자격모용작성의 정도</strong> 판단기준 (判例) : 일반인이 공무원·공무소 권한 내 작성 문서로 믿을 형식·외관 구비 문서 작성 시 공문서위조·변조 성립 사문서위조 = 명의자가 진정 작성한 문서로 볼 정도 형식·외관 갖춰 일반인이 명의자 진정 사문서로 오신하기 충분한 정도면 성립 자격모용사문서작성 = 일반인이 명의인 '권한 내' 작성 문서로 믿게 할 형식·외관 갖추면 성립 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[등기사항전부증명서 열람일시 삭제·복사]</span> 열람일시는 등기부상 권리관계 기준일시 나타내는 증명 중요부분, 삭제됐음을 쉽게 알아볼 형식·외관 못 갖춤 → 권리·사실관계 다른 새 증명력 문서 창출·공공신용 해할 위험 발생 → 공문서변조·동행 해당<span class=\"cs-exam\">【변23】</span><span class=\"cs-exam\">【모기22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사진 바꿔 붙인 외국공무원 발행 국제운전면허증, 유효기간 경과로 사용 불가라도]</span> 발급 권한 있는 자로부터 받은 것으로 오신 충분 형식·외관 갖추면 문서위조죄 '위조' 문서 해당<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[甲이 다른 서류 찍힌 乙 직인 오려내 풀로 붙인 후 '복사'해 수상후보자추천서 등 작성·발송]</span> 사문서위조·위조사문서행사 성립 — 주의깊게 관찰 안하면 비정상 부분 알기 어려움<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">[중국인 피고인이 콘도 입주민 A시설운영위원회 대표성 외양 작출 목적, 미리 제작한 A위원회 직인 날인 후 인감증명서 '용도'란에 오려붙여 1매 작성·단체대화방 게재] 공문서 외관·형식 갖췄다 인정 어렵고 공문서위조 성립 어려운 이상 촬영파일 단체대화방 게재도 위조공문서행사 해당<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 작성 권한</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>권한의 남용과 초과(초월)</strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①문서 작성권한 위임 있어도 위임받은 자가 '위임받은 권한 초월'해 작성 시 사문서위조 성립</div><div class=\"cs-li\" style=\"margin-left:16px\">②단지 위임받은 '권한 범위 내에서 남용'해 작성한 것뿐이면 사문서위조 성립X<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①공문서 작성권자로부터 요건 구비 여부 심사해 구비 확인 시 '한하여' 직인 사용해 작성권자 명의 공문서 작성 포괄권한 수여받은 업무보조 공무원이 '위임 취지 반하여' 허위내용 기재·보관 직인 '날인' → 공문서위조 성립</div><div class=\"cs-li\" style=\"margin-left:16px\">②그 행위 지시한 중간결재자 공무원도 공문서위조 공범 책임 면할 수 X<span class=\"cs-exam\">【모사19】</span> 사립학교 학교장 부재중 교감이 성적증명서 발급 대결 위임 있어도 부정 행사는 '위임 본지 반하는 것' → 권한없는 자 결재에 의한 성적증명서 작성으로 사문서위조 해당</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>명시적·묵시적 승낙 – 양해</strong> 판단기준 (判例) : 공문서인 기안문서 작성권한자가 직접 서명 않고 피고인에게 지시해 자기 서명 흉내내어 결재란 대신 서명케 한 경우 → 작성권자 지시·승낙에 의한 것으로 공문서위조 구성요건해당성 조각 사문서 작성 시 명의자 명시적·'묵시적' 승낙 내지 위임 있었다면 사문서위조·변조 해당X<span class=\"cs-exam\">【변26·25】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[연대보증용 인감도장·인감증명서 교부]</span> 피해자가 연대보증인 될 것 허락하고 필요 문서 작성에 쓰일 인감도장·인감증명서(대출보증용) 채무자에게 건넨 취지 = 채권자에 동액 채무 부담 문서 작성 허락 → 차용금증서에 피해자를 연대보증인 아닌 직접 차주로 했어도 정당 권한 범위 내 적법 작성<span class=\"cs-exam\">【변18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[매수인으로부터 토지매매계약 체결 포괄권한 위임받은 자가 실제 매수가보다 높은 가격 기재]</span> 작성권 있는 자가 허위내용 문서 작성한 것뿐 → 사문서위조 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·18】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>추정적 승낙</strong> 판단기준 (判例) : 타인 명의 사문서 작성·수정 당시 명의자 현실적 승낙은 없었으나 승낙 얻기 불가능했고 당시 모든 '객관적 사정' 종합해 명의자가 행위 당시 사실 알았다면 '당연히 승낙했을 것 추정'되는 경우 사문서위·변조 성립X<span class=\"cs-exam\">【변26·18】</span> 명의자 명시적 승낙·동의 없음 알면서 '명의자 이외의 자' 의뢰로 문서 작성 시, 명의자가 알았다면 승낙했을 것 기대·예측한 것만으로는 승낙 추정X 사문서변조 시 변조 당시 명의인 명시적·묵시적 승낙 없이 한 것이면 변조 문서가 명의인에 유리해 결과적으로 의사 합치해도 사문서변조 구성요건 충족<span class=\"cs-exam\">【변23·17】</span> 문서명의인 이미 사망했는데도 생존한다는 점이 문서 중요내용 이루거나 전제로 문서 작성됐다면, 사망 명의자 승낙 추정된다는 이유로 사문서위조 성립 부정 불가<span class=\"cs-exam\">【변14】</span> 사문서위조·공정증서원본 불실기재 '성립한 후' 사후에 피해자 동의·추인 등 사정으로 기재대로 효과 승인받거나 등기가 실체적 권리관계 부합하게 돼도 이미 성립한 범죄에는 아무 영향 없음<span class=\"cs-exam\">【변23·13·12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>명의신탁과 포괄적 승낙</strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①신탁자에 아무 부담 없이 재산이 수탁자에게 명의신탁된 경우 특별사정 없는 한 수탁자가 자신 명의사용을 포괄적으로 신탁자에게 허용한 것 → 신탁자가 수탁자 명의로 신탁재산 처분 서류 작성 시 개별 승낙 안 받아도 사문서위조·동행 성립X</div><div class=\"cs-li\" style=\"margin-left:16px\">②사법행위·공법행위 구별해 신탁재산 처분 관련 사법상 행위에만 명의사용 승낙 제한 불가 <span class=\"cs-fact-tag\">[공법행위인 과세표준 신고행위O]</span> 수탁자가 명의신탁 받은 사실을 '부인'해 신탁재산 소유권 '다툼' 있는 경우 또는 부인 안해도 신탁자 처분권한 다투는 경우 → 수탁자 명의사용 포괄허용 철회로 볼 수 있어 명의사용 허용X</div><div class=\"cs-h\">Ⅳ. 행사할 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 문서변조죄 행사할 목적은 적극적 의욕·확정적 인식 要X, 미필적 인식 있으면 족함 자격모용사문서작성죄 '행사할 목적' = 문서가 정당 권한에 기해 작성된 것처럼 타인이 오신하도록 할 목적, 대표자격 모용 문서 작성 인식·용인하며 진정 문서로서 효용에 쓸 목적 사문서 작성 시 '행사 목적'·'고의' 인정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[총괄대표이사 자격 도급계약서]</span> 작성자가 '행사할 목적'으로 자격 모용해 사문서 작성한 이상 상대방이 자격모용 사실 알았거나 모용 자격과 무관한 직인 날인해도 '행사할 목적' 인정 — X회사 대표이사가 Y건설회사 전문경영인으로 '내정'된 것처럼 속여 계약금 편취하며 A·B회사 '총괄대표이사' 자격 작성 도급계약서에 자기 이름·A회사 대표이사 직인 날인</div><div class=\"cs-h\">Ⅴ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">연명문서 위조 → 작성명의인 수에 해당하는 문서위조죄 상상적 경합 <span class=\"cs-fact-tag\">[연명문서 행사죄도 상상적 경합]</span><span class=\"cs-exam\">【변26·24】</span><span class=\"cs-exam\">【변기13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">행사목적으로 타인 인장 위조하고 그 위조 인장 사용해 권리·의무·사실증명 타인 사문서 위조 시 인장위조죄는 사문서위조죄에 흡수, 따로 인장위조죄 성립X<span class=\"cs-exam\">【변26·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[X작가협회 회원이 타인 명의 도용해 협회 교육원장 비방 호소문 작성 후 회원들에 우편 송달]</span> 사문서'위조'죄·명예훼손죄 각 성립, 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">예금통장 강취하고 예금자 명의 예금청구서 위조 후 은행원 제출·행사해 예금인출금 명목 금원 교부받음 → 강도·사문서위조·동행사·사기 각 성립, 실체적 경합<span class=\"cs-exam\">【변17】</span></div>", ["§231", "§237"], 3, "gak_사회"], ["사회002", "법인 명의 문서작성", "<div class=\"cs-h\">Ⅰ. 대표이사·지배인의 사문서위조</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 주식회사 대표이사가 대표 자격 표시 방식으로 작성한 문서 명의자 = 주식회사 '위조' 해당 여부는 작성자가 '주식회사 명의 문서' 적법 작성할 '권한' 있는지에 따라 판단하고 문서에 대표이사로 표시된 사람으로부터 위임·승낙 받았는지로 판단X</div><div class=\"cs-li\" style=\"margin-left:16px\">①주식회사 적법 대표이사는 회사 영업 관해 재판상·재판외 모든 행위 권한 있으므로 대표이사가 직접 주식회사 명의 문서 작성은 자격모용·위조 해당X 원칙</div><div class=\"cs-li\" style=\"margin-left:16px\">②문서 내용이 진실에 반하는 허위이거나 대표권 남용해 자기·제3자 이익 도모 목적 작성이라도 그러함 주식회사 지배인은 회사 영업 관해 재판상·재판외 모든 행위 권한 있으므로 지배인이 직접 주식회사 명의 문서 작성은 위조·자격모용사문서작성 해당X 원칙<span class=\"cs-exam\">【변17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 이 법리는 대표이사가 대표 자격 표시 방식으로 약속어음 등 '유가증권' 작성 시에도 마찬가지 적용</div><div class=\"cs-h\">Ⅱ. 포괄적 위임과 개별적 위임</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 주식회사 대표이사가 권한 포괄적 위임해 타인으로 하여금 대표이사 업무 처리케 하는 것 허용X →</div><div class=\"cs-li\" style=\"margin-left:16px\">①대표이사로부터 포괄적 위임받은 사람이 '주식회사 명의 문서' 작성은 원칙적 권한없는 사람 문서작성행위로 자격모용사문서작성·위조 해당</div><div class=\"cs-li\" style=\"margin-left:16px\">②대표이사로부터 개별적·구체적으로 주식회사 명의 문서 작성 위임·승낙 받은 경우에만 예외적 적법 작성 가능</div><div class=\"cs-h\">◎ 작성자별 성부 정리표 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">작성자 / 문서 / 사문서위조 / 자격모용사문서작성 대표이사 A (개별·구체적 위임 받은 사람) · X주식회사 대표이사 A : 사문서위조<span class=\"cs-x\"><strong>(X)</strong></span> / 자격모용사문서작성<span class=\"cs-x\"><strong>(X)</strong></span> · X주식회사 대표이사 C : 사문서위조<span class=\"cs-x\"><strong>(X)</strong></span> / 자격모용사문서작성<span class=\"cs-x\"><strong>(X)</strong></span> 대표이사 아닌 B (포괄 위임만 받은 사람) · X주식회사 대표이사 B : 사문서위조<span class=\"cs-x\"><strong>(X)</strong></span> / 자격모용사문서작성<span class=\"cs-o\"><strong>(O)</strong></span> · X주식회사 대표이사 A 또는 C : 사문서위조<span class=\"cs-o\"><strong>(O)</strong></span> / 자격모용사문서작성<span class=\"cs-x\"><strong>(X)</strong></span></div>", [], 1, "gak_사회"], ["사회003", "공전자·사전자기록 위작·변작", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제227조의2(공전자기록위작·변작)</strong></span> 사무처리를 그르치게 할 목적으로 공무원 또는 공무소의 전자기록등 특수매체기록을 위작 또는 변작한 자는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제232조의2(사전자기록위작·변작)</strong></span> 사무처리를 그르치게 할 목적으로 권리·의무 또는 사실증명에 관한 타인의 전자기록등 특수매체기록을 위작 또는 변작한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 사무처리를 그르치게 할 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '사무처리를 그르치게 할 목적' = 위작·변작된 전자기록이 사용됨으로써 정보 생성·처리·저장·출력 목적으로 구축·설치한 시스템 운영 주체인 개인 또는 법인의 사무처리를 잘못되게 하는 것</div><div class=\"cs-h\">Ⅱ. '타인'의 전자기록등 특수매체기록 (사전자기록)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[사전자기록]</span> 법인이 설치·운영하는 전산망 시스템에 제공되어 정보 생성·처리·저장·출력 이뤄지는 전자기록 등 특수매체기록은 그 법인 임직원과의 관계에서 '타인'의 전자기록 등 특수매체기록 해당<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-h\">Ⅲ. 위작의 개념<span class=\"cs-exam\">【모사25·23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《'위작·변작' 개념에 문서의 무형위조가 포함되는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①공전자·사전자기록 모두 무형위조 포함된다는 포함설</div><div class=\"cs-li\" style=\"margin-left:16px\">②공전자기록은 무형위조 포함되지만 사전자기록은 포함되지 않는다는 구별설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[判例 무형위조 포함설]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①시스템 설치·운영 주체와의 관계에서 전자기록 생성 관여 '권한 없는 사람'이 전자기록 '작출'하거나 생성 필요 단위정보 '입력'하는 경우는 물론, 시스템 설치·운영 주체로부터 직무범위 내 개개 단위정보 입력 '권한' 부여받은 사람이 그 권한 '남용'해 '허위' 정보 입력함으로써 시스템 설치·운영 주체 의사 반하는 전자기록 생성하는 경우도 공전자기록등위작죄(<span class=\"cs-stat\"><strong>§227의2</strong></span>) '위작'에 포함<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②이 법리는 사전자기록등위작죄(<span class=\"cs-stat\"><strong>§232의2</strong></span>) '위작'에도 마찬가지 적용<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 위작은 '위조'와 '허위작성' 결합한 것으로 해석 가능하고, 전자기록 작성엔 여러 사람 개입해 작성명의인 개념 상정 어려우므로 → 포함설 타당</div></div>", ["§227", "§232", "제227조", "제232조"], 2, "gak_사회"], ["사회004", "허위공문서작성 및 허위진단서작성", "<details class=\"cs-case\"><summary><u><strong>[CASE] 보조공무원의 허위 시험평가서 기안</strong></u> <span class=\"cs-exam\">【변사22】 </span><span class=\"cs-o\">(18)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 대위로 육군사관학교에 재직하며 납품 관련 시험평가서 기안 보조업무 담당 중 B방위산업체 근무 고교동창 丁에게서 납품할 탄환의 시험평가서가 필요하니 도와달라는 부탁을 받고, 다른 업체의 탄환 실험데이터를 도용해 결과를 허위 기재한 육군사관학교장 명의 시험평가서를</div><div class=\"cs-li\" style=\"margin-left:0px\">작성한 뒤 정을 모르는 결재권자의 도장을 받음. 乙, 丁의 죄책은? (18점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 허위공문서작성죄(<span class=\"cs-stat\"><strong>제227조</strong></span>) = '작성권한자인 공무원'을 주체로 하는 진정신분범</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙은 기안을 담당하는 보조공무원이었을 뿐 시험평가서 작성권한(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 보조공무원이 허위공문서를 기안해 정을 모르는 작성권자의 결재를 받아 완성한 경우 허위공문서작성죄의 간접정범(<span class=\"cs-stat\"><strong>제34조</strong></span> 제1항) 성부 — 부정설/긍정설, 판례 = 긍정설. 대부분의 서류가 기안 담당 보조공무원에 의해 작성되는 현실을 고려하면 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 乙 = 허위공문서작성죄의 간접정범</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [丁의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 범행의 결의가 없는 乙에게 부탁해 실행하게 함 → 교사범(<span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丁 = <span class=\"cs-stat\"><strong>제33조</strong></span> 본문에 따라 허위공문서작성교사죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제227조(허위공문서작성등)</strong></span> 공무원이 행사할 목적으로 그 직무에 관하여 문서 또는 도화를 허위로 작성하거나 변개한 때에는 7년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제233조(허위진단서등의 작성)</strong></span> 의사, 한의사, 치과의사 또는 조산사가 진단서, 검안서 또는 생사에 관한 증명서를 허위로 작성한 때에는 3년 이하의 징역이나 금고, 7년 이하의 자격정지 또는 3천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 허위공문서작성죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>문서</strong> 개념: 문서에 관한 죄의 보호법익은 문서의 증명력·의사표시의 안정·신용 → 법률관계·거래상 중요 사실에 관한 관계를 표시하여 증거될 만한 가치 있는 문서가 대상 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[작성명의인 명시 X]</span> 문서 자체에 의하여 누가 작성했는지 추지할 수 있을 정도면 객체 됨<span class=\"cs-exam\">【변21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[피의자신문조서]</span> 말미에 작성자 서명·날인 없으나 첫머리에 작성 사경·참여 사경 직위·성명 기재 → 작성자 추지 가능 → 허위공문서작성죄 객체인 공문서<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>허위</strong> 개념: 허위란 표시된 내용과 진실이 부합하지 않아 공공의 신용을 위태롭게 하는 것 → 내용이 허위라는 사실을 인식하면 성립 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[준공검사조서]</span> 정산설계서 확인·준공검사 안 했음에도 한 것처럼 '정산설계서에 의하여 준공검사'를 하였다는 내용 기입 → 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[원본대조필]</span> 실제 원본대조 없이 '원본대조필 토목기사 피고인' 기재 → 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[인감증명서]</span> 본인 직접 출두 없음에도 직접 신청·발급받은 것처럼 기재 → 공문서위조죄 아닌 허위공문서작성죄<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[재수사결과서]</span> 사경이 검사로부터 재수사 요청받고 피해자 진술 없는 독자적 의견·추측을 직접 들은 진술처럼 기재 → 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[작성의도·목적 부정]</span> 작성권한 공무원이 허위 인식하며 진실 반하는 기재를 한 공문서이므로, 작성 의도·목적이 부정해도 기재 내용에 거짓 없으면 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[법령 오적용]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①적용 전제된 사실관계에 거짓 기재 없으면 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:48px\">②그 잘못이 공무원의 '고의'에 기해도 마찬가지<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>허위공문서작성죄의 간접정범</strong> 가. <strong>'사인'의 허위공문서작성죄의 간접정범·공동정범</strong> 적용범위: <span class=\"cs-fact-tag\">[진정신분범]</span> 작성권한자인 공무원을 주체로 하는 진정신분범 <span class=\"cs-fact-tag\">[공동정범 O]</span> 공무원 아닌 자가 공무원과 공동하여 범한 때 → <span class=\"cs-stat\"><strong>제33조</strong></span> 본문에 의해 공동정범 됨 <span class=\"cs-neg-tag\">[간접정범 X]</span> 공무원 아닌 자는 <span class=\"cs-stat\"><strong>제228조</strong></span> 경우를 제외하고는 간접정범으로 처벌 X<span class=\"cs-exam\">【변19】</span><span class=\"cs-exam\">【변사18, 모기24】</span> 나. <strong>'보조 공무원'의 허위공문서작성죄 간접정범<span class=\"cs-exam\">【변사22, 모기23·21·14】</span></strong> <span class=\"cs-issue\">《보조공무원이 허위공문서 기안 → 정 모르는 작성권자 결재로 완성 시 간접정범 성립여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(작성권한 없는 보조공무원 간접정범 X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(기안 담당 보조공무원은 '사실상·실질적 작성권한' 보유)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①보조직무 공무원이 허위공문서 기안→정 모르는 작성권자 결재로 완성 시 간접정범</div><div class=\"cs-li\" style=\"margin-left:16px\">②공모자도 그 공범 죄책 면할 수 없고 공범은 공무원 신분자로 한정 X<span class=\"cs-exam\">【변23·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 긍정설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[중간·최종 결재]</span> 甲이 허위 자동차운송사업변경 검토조서 작성→사정 아는 중간결재자 乙과 사정 모르는 최종결재자 丙 차례 결재로 변경허가 → 甲·乙은 간접정범 <span class=\"cs-neg-tag\">[허위공문서작성죄 공동정범 X]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">다. <strong>'감독공무원'의 허위공문서작성죄 간접정범</strong> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[감독공무원 O]</span> 경찰서 보안과장이 甲 음주운전 눈감아주려 적발보고서 찢고 (<span class=\"cs-stat\"><strong>제141조</strong></span> 제1항 공용서류손상죄 성립), 부하시켜 가짜 적발보고서에 乙 음주운전 기재케 하여 정 모르는 담당 경찰관으로 처리부에 기재하도록 함 → 허위공문서작성 및 동 행사죄 간접정범 죄책 면할 수 X</div><div class=\"cs-h\">Ⅱ. <span class=\"cs-fact-tag\">[비교]</span> 위조죄의 간접정범</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[직인 보관담당]</span> 작성권자 결재 있을 때만 날인 가능 → 결재 없이 직인 보관담당자를 기망하여 작성권자 직인 날인케 하여 공문서 완성 시 공문서위조죄 성립 <span class=\"cs-fact-tag\">[간접정범]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[진정 성립]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①작성권한 공무원이 기재 사항 인식하고 작성 의사로 서명·날인 → 성립은 진정, 명의 모용 아님</div><div class=\"cs-li\" style=\"margin-left:32px\">②공무원 아닌 자가 관공서에 허위 증명원 제출→정 모르는 담당공무원으로부터 증명서 발급받아도 공문서위조죄 간접정범 의율 X<span class=\"cs-exam\">【변21·17】</span></div><div class=\"cs-h\">Ⅲ. 허위진단서작성죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-stat\"><strong>제233조</strong></span>는 사문서의 무형위조 처벌 규정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">['입퇴원 확인서']</span> 진단서로 보기 어려움</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[허위 인식 필요]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①진단서 내용이 객관적 진실에 반할 뿐 아니라 작성자가 허위임을 인식해야</div><div class=\"cs-li\" style=\"margin-left:32px\">②주관적으로 진찰 소홀·착오로 오진하여 진실 반한 진단서 작성 시 허위 인식 X → 성립<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[부검 이전 작성 사망진단서 기재 사망원인이 부검 결과와 달라도 허위진단서 고의 곧바로 추단 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[대상 한정]</span> 허위진단서작성죄 대상은 '공무원 아닌 의사'가 사문서로 진단서 작성한 경우에 한정 → 공무원인 의사가 공무소 명의로 작성 시 허위공문서작성죄만 성립, 허위진단서작성죄 별도 성립 X<span class=\"cs-exam\">【변18·12】</span><span class=\"cs-exam\">【모기24】</span></div>", ["제227조", "제34조", "제31조", "제33조", "제233조", "제228조", "제141조"], 3, "gak_사회"], ["사회005", "위조 등 문서의 행사죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 등기사항전부증명서 열람일시 삭제·스캔 이미지 전송 (15점)</strong></u> <span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 2020. 3. 10. 상속으로 시가 5억 상당(이후 변동 없음) X부동산 소유권이전등기 경료. 2021. 1. 7.경 인터넷 열람 등기사항전부증명서를 출력해 둠 → 2021. 5. 6. Y에게서 5억 원을 빌리며 근저당권설정등기 경료 → 2022. 2. 10. 선순위 담보가 없는 것처럼 조작해 추가 차용하려 출력해 둔 증명서 하단 열람 일시를 수정테이프로 지우고 스캔해 이미지파일 생성 → 2022. 2. 15. A에게서 1억 원을 추가로 빌리며 이메일로 그 파일을 전송, A는 모니터로 확인 후 담보가 충분하다고 판단해 1억 원을 빌려주고 근저당권설정등기 관련 서류를 받음.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [공문서변조죄의 성립여부]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [공문서변조죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공문서변조 = 권한 없이 이미 진정하게 성립된 공문서의 내용을 동일성을 해하지 않을 정도로 변경하는 것</div><div class=\"cs-li\" style=\"margin-left:0px\">② 일반인이 공무원 등의 권한 내에서 작성된 문서라고 믿을 형식·외관을 구비한 문서를 작성하면 공문서변조죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [수정테이프로 지운 행위] 하단 열람 일시를 수정테이프로 지운 것만으로는 그러한 형식· 외관을 구비한 문서를 작성했다고 볼 수(X) → 공문서변조죄(<span class=\"cs-stat\"><strong>제225조</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [이미지 및 이미지파일의 문서성]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 모니터 화면의 이미지 = 화면에 계속적으로 고정된 것(X), 이미지파일 = 전자기록 장치에 전자적 형태로 고정돼 계속성은 있으나 시각적 방법으로 이해할 수 있는 것(X) → 각 형법상 문서죄의 문서(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲이 생성한 이미지·이미지파일은 문서(X) → 공문서변조죄(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(라) [소결] 甲 = 공문서변조죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [변조공문서행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 행사 방법에 제한(X) → 이미지를 전송해 컴퓨터 화면으로 보게 하는 것도 행사(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 그러나 변조공문서행사죄는 변조된 공문서의 존재를 전제 → 애초에 변조가 없는 이상 변조공문서행사죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [사기죄]</strong> 시가 5억 X부동산에 이미 채권최고액 5억 원 선순위 근저당권이 설정돼 담보가치가 없음에도 증명서를 변조해 선순위가 없어 담보가치가 충분한 것처럼 A를 기망, 1억 원 편취 → 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = 사기죄 [TIP] 하단의 열람 일시를 수정 테이프로 지우고 '복사'한 사안이므로 공문서변조죄 및 동행사죄가 성립한다(판례와 사실관계 다름).</div></div></details></div></details><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">&lt;!-- 확인요망: 헤더 기출표시 첫 항목 '변기25'와 셋째 '변기25·13'이 중복으로 표기됨. 첫 항목이 다른 종류일 가능성 있음 --&gt;</div><div class=\"cs-h\">Ⅰ. 행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 위조문서행사죄의 행사란 위조문서를 진정한 문서인 것처럼 그 효용 방법에 따라 사용하는 것, 행사 방법 제한 없음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 행사는 위조된 문서의 존재를 전제로 함<span class=\"cs-exam\">【변기25】</span> <span class=\"cs-fact-tag\">[방법]</span> 위조문서 직접 제시·기계적 복사본 제시는 물론, 모사전송·스캐너로 이미지화 후 전송하여 컴퓨터 화면상 보게 하는 경우도 행사 <span class=\"cs-fact-tag\">[휴대전화가입신청서 위조 후 스캔 이미지파일 이메일 전송 → 행사 해당]</span><span class=\"cs-exam\">【변19·12】</span><span class=\"cs-exam\">【모사24】</span> <span class=\"cs-fact-tag\">[허위공문서 행사목적]</span> 허위내용 문서를 진실한 문서처럼 효용 따라 사용할 목적 → 허위공문서를 관청에 비치하는 경우도 행사로 인정</div><div class=\"cs-h\">Ⅱ. 상대방</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 행사 상대방 제한 없음 → 위조문서 작성명의인이라도 상대방 될 수 없는 것 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[간접정범]</span> 도구로 이용된 자라도 문서 위조된 것임을 알지 못하는 자에게 행사 → 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26·22·20·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[공범자]</span> 문서 위조된 것임을 이미 '알고 있는 공범자' 등에게 행사 → 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅲ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 위조사문서 행사는 상대방이 위조문서를 '인식할 수 있는 상태에 둠'으로써 기수, 상대방이 실제 '인식'해야 하는 것 아님 → 우송 시 문서가 상대방에게 도달한 때 기수, 실제로 봐야 하는 것 아님</div><div class=\"cs-h\">Ⅳ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 위조사문서행사죄와 이로 인한 사기죄는 실체적 경합관계 <span class=\"cs-fact-tag\">[별개 위조문서 동시에 행사]</span> 각 명의인마다 별개 연대보증서 위조 후 사채업자로부터 돈 빌리며 2개 문서를 한꺼번에 담보로 건네주어 행사 → 각 위조죄는 실체적 경합범, 행사죄는 상상적 경합범</div>", ["제225조", "제347조"], 2, "gak_사회"], ["사회006", "공정증서원본불실기재죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제228조(공정증서원본 등의 부실기재)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원에 대하여 허위신고를 하여 공정증서원본 또는 이와 동일한 전자기록등 특수매체기록에 부실의 사실을 기재 또는 기록하게 한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공무원에 대하여 허위신고를 하여 면허증, 허가증, 등록증 또는 여권에 부실의 사실을 기재하게 한 자는 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 허위사실의 신고</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 불실의 사실기재는 당사자 허위신고에 의하여야 함 → 법원의 '촉탁'에 의하여 등기 마친 경우 성립<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[허위 소명자료 첨부 신청 가압류결정에 기한 법원의 촉탁등기]</span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-h\">Ⅱ. 공정증서원본 또는 이와 동일한 전자기록등 특수매체기록 등</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§228</span><span class=\"cs-fact-tag\">①]</span> 공정증서란 '권리의무'에 관한 공정증서만 가리킴, 사실증명에 관한 것은 포함 X <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§228</span><span class=\"cs-fact-tag\">② '등록증']</span> 공무원이 작성한 모든 등록증이 아니라, 일정 자격·요건 갖춘 자에게 그 자격·요건에 상응한 활동할 수 있는 권능 인정 위해 공무원이 작성한 증서</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[해당 O]</span> 가족관계등록부, 등기부(부동산·법인 등), 자동차등록부, 변호사등록증</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[해당 X]</span> 인감대장, 토지(임야)대장, 가옥·건축물대장, 자동차운전면허대장<span class=\"cs-exam\">【변21】</span>, 주민등록증, 조정조서, 사업자등록증</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[정본 X]</span> '공정증서원본'에 공정증서 '정본' 포함 X → 불실 사실 기재된 공정증서 '정본'을 정 모르는 법원 직원에게 교부한 행위는 불실기재공정증서'원본'행사죄 해당 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[조정조서 X]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①불실기재죄 객체 공정증서원본은 성질상 허위신고에 의해 불실한 사실이 그대로 기재될 수 있는 공문서여야</div><div class=\"cs-li\" style=\"margin-left:32px\">②조정절차에서 작성되는 조정조서는 그런 공문서로 볼 수 없어 공정증서원본 해당 X</div><div class=\"cs-h\">Ⅲ. 불실의 사실을 기재 또는 기록</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>불실의 사실의 기재</strong> 개념: 불실의 사실이란 권리의무관계에 중요한 의미를 갖는 사항이 진실에 반하는 것 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">['가장매매']</span> 기한 소유권이전등기 경료해도 당사자간 '소유권이전등기 경료시킬 의사' 있었으므로 불실기재 해당 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[가등기]</span> 권리자와 의무자 '합의에 의하여 경료'된 이상 불실기재 해당 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[상속]</span> 피상속인에게 실체상 권리 없었다 해도 재산상속인이 '상속을 원인'으로 소유권이전등기 경료 시 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[거래가액]</span> 권리의무관계 중요 의미 사항 해당 X → 사실과 다른 거래가액이 부동산등기부에 등재돼도 불실기재 X<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[채권양도]</span> 양도인이 허위 채권 관하여 정 모르는 양수인과 실제 채권양도 법률행위 한 이상, 공증인에게 공정증서 작성케 해도 불실 사실 기재케 한 것 아님 <span class=\"cs-neg-tag\">[공정증서는 '채권양도의 법률행위'가 진정으로 이루어진 것 증명할 뿐 '채권이 진정하게 존재'함 증명 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[회사설립등기]</span> 발기인 등이 '상법 등 법령 정한 회사설립 요건·절차' 따라 설립등기 → 회사 성립 볼 수 있으면 불실 사실 해당 X 회사 운영 의사 없이 범죄 의도·목적 있었거나 영업 실질 안 갖췄다는 이유만으로는 불실 사실 기록케 한 것 X<span class=\"cs-exam\">【모사22, 모기22】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>부존재 또는 무효사유</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[무효 하자]</span> 공정증서원본 기재사항이 부존재하거나 외관상 존재해도 무효 하자 있으면 불실기재 해당 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[허위 근저당]</span> 실제 채권·채무관계 없는데 허위 채무 가장·담보 명목 허위 근저당권설정등기 → 불실 사실 기재 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[타인 부동산]</span> 근저당권은 근저당물 소유자 아니면 설정 X → 타인 부동산을 자기/제3자 소유라 허위신고 소유권이전등기 경료 후 자기/제3자 소유인 것처럼 가장하여 근저당권설정등기 경료 → 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[물권적 합의 없는 이전등기]</span> 부동산 매수인이 매도인과 '소유권이전 물권적 합의 없는 상태'에서 대리권 없이 서류만 보관 중인 법무사 기망하여 소유권이전등기 신청케 함 → 원인무효 등기로 불실기재 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[집행력 있는 공정증서]</span> 채권·채무관계 없음에도 공증인에게 허위신고 가장 금전채권에 '집행력 있는 공정증서원본' 작성·비치 → 불실기재죄 및 부실기재공정증서원본행사죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[자본금 납입 가장]</span> 등기공무원에게 자본금 납입된 것처럼 허위신고하여 정 모르는 법원 등기 담당 공무원으로 상업등기 전산시스템에 기재·비치 → 공전자기록불실기재죄 및 동행사죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【모기22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[주주총회 의사록 허위작성]</span> 1인 회사와 달리 주식 소유 실질 분산된 주식회사에서 소집·결의절차 없이 주주총회결의 있었던 것처럼 의사록 허위작성 → 중대한 하자로 주주총회결의 부존재 <span class=\"cs-fact-tag\">[공정증서원본불실기재죄 성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[위장혼인]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①'당사자간 혼인 합의 없는 때' 혼인 무효(민법 <span class=\"cs-stat\"><strong>제815조</strong></span> 제1호)</div><div class=\"cs-li\" style=\"margin-left:48px\">②취업 등 목적 위장혼인·혼인신고하여 가족관계등록부 기재·비치 → 공전자기록불실기재 및 동행사죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>취소사유</strong> 판단기준 (判例) : 공정증서원본 기재사항이 객관적으로 존재하는 사실이고 취소사유 하자만 있는 경우 → '취소 전'에 기재된 이상 불실기재죄 구성 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[협의이혼]</span> 이혼 의사표시가 기망에 의해도 취소되기까지 유효 존재 → 협의이혼의사 합치 따라 이혼신고하여 호적 기재 시 불실 사실 해당 X</div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>실체관계에 부합하는 경우</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[성립 X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①소유권이전(보존)등기에 절차상 하자·등기원인 실제와 달라도 실체적 권리관계 부합 위한 것이거나 부합하는 유효 등기면 성립 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②'등기 경료 당시 기준'으로 실체권리관계 부합하여 유효한 경우에 한정</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사후 부합]</span> 등기 경료 당시 실체권리관계 부합하지 않은 등기면, 사후에 이해관계인 동의·추인 등으로 부합하게 돼도 성립에 영향 없음</div><div class=\"cs-h\">Ⅳ. 실행의 착수 및 기수시기</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수시기</strong> 개념: <span class=\"cs-fact-tag\">[허위신고]</span> 공전자기록불실기재죄 실행 착수시기는 공무원에 대하여 허위 신고를 하는 때 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[위장결혼]</span> 당사자·중국 측 브로커 공모 하에 허위 결혼사진 찍고 혼인신고 필요 서류 준비하여 위장결혼 당사자에게 건네준 것만으로는 아직 실행 착수로 보기 어려움</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수시기</strong> &lt;!-- 교정: 원문 소제목 '2. 착수시기'는 '기수시기'의 오기로 보임(내용상 기수) --&gt; 개념: <span class=\"cs-fact-tag\">[기재·기록]</span> 공정증서원본불실기재죄는 실체관계에 부합하지 않는 불실의 사실을 '기재하거나 기록하게 한 때' 성립 <span class=\"cs-fact-tag\">[등기된 때 기수]</span></div>", ["§228", "제228조", "제815조"], 3, "gak_사회"], ["사회007", "공문서·사문서부정행사", "<details class=\"cs-case\"><summary><u><strong>[CASE] 오인 상해·타인 운전면허증 제시·조서 타인명의 서명</strong></u> <span class=\"cs-exam\">【변사19】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲이 丁에게 乙 살해를 부탁, 승낙한 丁이 C를 乙로 오인해 자동차로 들이받았으나 6주 상해에 그침. 사법경찰관 P2가 丁을 적법하게 체포해 인적사항을 확인하자 丁은 친형 D의 운전면허증을 제시, 피의자신문 후 P2가 작성한 피의자신문조서를 교부받아 열람하고 말미에</div><div class=\"cs-li\" style=\"margin-left:0px\">D 명의로 서명날인해 P2에게 건넴. 丁의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [살인미수죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① C를 乙로 오인 = 구체적 사실의 착오 중 객체의 착오 → 구체적 부합설· 법정적 부합설·추상적 부합설 모두 발생한 사실인 C에 대한 살인의 고의 인정</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丁 = C에 대한 살인미수죄(<span class=\"cs-stat\"><strong>제254조</strong></span>, <span class=\"cs-stat\"><strong>제250조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [공문서부정행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사용권한자와 용도가 특정되어 작성된 공문서를 사용권한 없는 자가 권한이 있는 것처럼 가장해 부정한 목적으로 행사하면 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">② 다만 사용권한 없는 자가 사용해도 그 공문서의 본래 용도에 따른 사용이 아니면 성립(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 운전면허증 = 자격증명 + 동일인증명 기능 동시 보유 → 신분확인을 위한 신분증명서 제시 요구에 타인의 운전면허증을 제시함은 사용목적에 따른 행사 → 공문서부정행사죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 丁 = 공문서부정행사죄(<span class=\"cs-stat\"><strong>제230조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [사서명위조죄 및 동행사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 사서명위조죄는 그 서명이 일반인으로 하여금 특정인의 진정한 서명으로 오신하게 할 정도에 이를 것 要</div><div class=\"cs-li\" style=\"margin-left:0px\">② 피의자신문조서 말미에 D 명의로 서명·날인해 P2에게 건넴 → 사서명위조죄 및 동행사죄(<span class=\"cs-stat\"><strong>제239조</strong></span> 제1항, 제2항)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 丁 = 살인미수죄 + 공문서부정행사죄 + 사서명위조죄 + 위조사서명행사죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 공무원 또는 공무소의 문서 또는 도화 (공문서 등)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[진정한 공문서]</span> 공문서부정행사죄는 진정한 공무소 문서를 권한없는 자가 행사 → 위조·변조·허위작성 공문서는 객체 X <span class=\"cs-fact-tag\">[사용권한자·용도 특정 문서]</span> 사용권한자와 용도가 특정되어 작성된 공문서·공도화 부정사용 시 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[절취 전화카드 공중전화기 사용]</span> 권리의무에 관한 타인의 사문서 부정행사에 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사용권한자 불특정]</span> 주민등록표등본<span class=\"cs-exam\">【변14】</span>, 실질적 채권채무관계 없이 당사자 합의로 작성한 차용증·이행각서<span class=\"cs-exam\">【변20】</span>, 금치산·한정치산 선고 후 취소 안 된 사실 증명 신원증명서, 인감증명서·등기필증 → 모두 사용권한자 특정 X·용도 다양 → 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 부정행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 공문서부정행사죄는 공문서 사용에 대한 공공의 신용 보호법익 → '추상적 위험범'</div><div class=\"cs-li\" style=\"margin-left:16px\">② 주체·객체·태양 엄격해석하여 처벌범위 합리적 범위 내로 제한 <span class=\"cs-fact-tag\">[구체적 위험범 X]</span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 사용권한자·용도 특정 작성 공문서·공도화를</div><div class=\"cs-li\" style=\"margin-left:16px\">①사용권한 없는 자가 있는 것처럼 가장하여 부정목적 행사</div><div class=\"cs-li\" style=\"margin-left:16px\">②권한 있는 자라도 정당한 용법 반하여 부정행사 시 성립 <span class=\"cs-fact-tag\">[사문서부정행사죄도 동일 법리]</span> 사용권한자·용도 특정 공문서를 사용권한 없는 자가 사용해도 본래 용도에 따른 사용 아니면 부정행사죄 X</div><div class=\"cs-h\">Ⅲ. 구체적 판례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[운전면허증 제시]</span> 자격증명+동일인증명 기능 동시 → 제3자로부터 신분확인 위해 신분증명서 제시 요구받고 타인 운전면허증 제시 → 사용목적에 따른 행사로 부정행사죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24·16·14, 변사19, 모사19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[허위신고 발급 주민등록증 제시]</span> 자신이 A인 양 허위신고로 사진 부착·지문 찍힌 A 명의 주민등록증 발급받아 검문경찰관 제시 → 허위사실 증명 용도 사용권한 없음 인식 → 부정행사죄<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[운전면허증 이미지파일]</span> 도교법<span class=\"cs-stat\"><strong>§92</strong></span>② 제시 객체는 운전면허증 자체이지 이미지파일 X → 타인 운전면허증 촬영 이미지파일을 휴대전화 화면 등으로 보여주는 행위는 특정 용법에 따른 행사 X·그릇된 신용 형성 위험 X → 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22, 모사20, 모기25·22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[국가유공자증 제시]</span> 본래 용도는 국가유공자 자격 증명(신분 동일성 증명 X) → 조세범처벌법위반 조사 시 타인 행세로 타인 명의 국가유공자증 조사관 제시해도 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[심문조서 진술인란에 타인 명의 서명·제시는 사서명위조·동행사 성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[장애인사용자동차표지]</span> 사용권한 없는 자가 지원 기대 상황 아니면 단순 자동차에 '비치'해도 본래 용도 사용 X → 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[실효된 표지 부착·비주차구역 주차]</span><span class=\"cs-exam\">【변24, 모기23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[주민등록증 이동전화 가입신청]</span> 습득한 타인 주민등록증을 '피고인 가족' 것이라 제시하며 타인 명의·가명으로 이동전화 가입신청 → 본래 사용용도인 '신분확인용' 사용 X → 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[선박국적증서·선박검사증서]</span> 선박 사고 허위신고하며 함께 제출 → 국적·항행자격 증명 용도로 사용된 것일 뿐 본래 용도 벗어난 행사 X → 부정행사죄<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[권한 있는 자의 본래 용법에 따른 사용]</span><span class=\"cs-exam\">【변20·14】</span></div><div class=\"cs-h\">Ⅳ. 미수범 처벌규정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 공문서부정행사죄 = 미수범 처벌규정 O (<span class=\"cs-stat\"><strong>§235</strong></span>) 사문서부정행사죄 = 미수범 처벌규정 X</div>", ["§92", "§235", "제254조", "제250조", "제230조", "제239조"], 3, "gak_사회"], ["사회008", "사서명위조 및 동행사", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제239조(사인등의 위조, 부정사용)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 행사할 목적으로 타인의 인장, 서명, 기명 또는 기호를 위조 또는 부정사용한 자는 3년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 위조 또는 부정사용한 타인의 인장, 서명, 기명 또는 기호를 행사한 때에도 전항의 형과 같다.</div></div><div class=\"cs-h\">Ⅰ. 사서명위조 및 동행사<span class=\"cs-exam\">【변사19, 모사23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[경찰관 주어]</span> \"조서를 진술자에게 읽어 준바 ~ 하므로, 간인한 후 서명 무인케 하다.\" <span class=\"cs-fact-tag\">[피의자신문조서, 진술조서]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: 사서명위조죄 성립 = 서명이 일반인으로 하여금 특정인의 진정한 서명으로 오신하게 할 정도에 이르러야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[국가유공자증 제시+심문조서 서명]</span> 조세범처벌법위반 조사 시 타인 행세로 타인 국가유공자증 조사관 제시(공문서부정사용죄 X), 범칙혐의자 심문조서 진술인란에 타인 명의 서명 → 사서명위조·동행사 실체적 경합 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[PDA 부호 기재]</span> 음주운전 단속되자 동생 이름 대며 조사받으며 PDA 표시 음주운전단속결과통보 중 운전자 A 서명란에 A 이름 대신 의미 알 수 없는 부호 기재 → A의 서명 위조<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 문서의 완성과 사서명위조</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 권한 없는 자가 타인 서명 기재 → 문서 완성 전이라도 일반인이 명의인의 진정한 서명으로 오신 가능 → 서명 완성된 이상 문서 미완성이어도 서명위조죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수사서류]</span> 진술자가 타인 양 행세하며 타인 서명 기재 → 수사기관 열람 전 즉시 파기 등 특별사정 없는 한 사서명위조죄·위조사서명행사죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 사문서위조 및 동행사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[피조사자 주어]</span> \"본인은 ~ 기재된 내용이 틀림없음을 확인합니다.\"</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[주취운전자적발보고서·정황진술보고서]</span> 운전자란에 타인 서명 후 경찰관 제출 → 사문서위조죄·동행사죄<span class=\"cs-o\"><strong>(O)</strong></span></div>", ["제239조"], 1, "gak_사회"], ["사회009", "공기호", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제238조(공인 등의 위조, 부정사용)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 행사할 목적으로 공무원 또는 공무소의 인장, 서명, 기명 또는 기호를 위조 또는 부정사용한 자는 5년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 위조 또는 부정사용한 공무원 또는 공무소의 인장, 서명, 기명 또는 기호를 행사한 자도 전항의 형과 같다.</div></div><div class=\"cs-h\">Ⅰ. 공기호위조죄 및 위조공기호행사죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념:</div><div class=\"cs-li\" style=\"margin-left:16px\">① 인장 = 사람의 동일성 표시 위해 사용하는 일정한 상형 / 기호 = 물건에 압날하여 사람의 '인격상 동일성 이외'의 일정 사항 증명 부호</div><div class=\"cs-li\" style=\"margin-left:16px\">② <span class=\"cs-stat\"><strong>§238</strong></span> 공기호는 해당 부호를 공무원·공무소가 사용하는 것만으로 부족, 그 부호 통하여 증명하는 사항이 구체적으로 특정 ·해당 사항이 그 부호에 의하여 증명될 것 요구</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[검찰 업무표장]</span> '검찰 공무수행 차량' 증명 기능 등 이를 통하여 증명하는 사항 구체적 특정 X → 일반인이 표지판 부착 차량을 '검찰 공무수행 차량'으로 오인해도 증명적 기능 없으면 공기호<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 공기호부정'사용' 및 부정사용공기호'행사'</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념:</div><div class=\"cs-li\" style=\"margin-left:16px\">① <span class=\"cs-stat\"><strong>§238</strong></span>① 공기호(자동차등록번호판) 부정사용 = 진정하게 만들어진 번호판을 권한 없는 자가 사용하거나 권한 있는 자라도 권한 남용·부당사용 / <span class=\"cs-stat\"><strong>§238</strong></span>② 행사죄 = 부정사용한 번호판을 진정한 것처럼 용법 따라 사용 → 행위개념 달리함</div><div class=\"cs-li\" style=\"margin-left:16px\">② 행사 = 자동차에 부착·운행하여 일반인으로 자동차 동일성 오인 야기 가능 상태 (부착 자동차 운행) 의미 → 운행과 별도로 부정사용 번호판을 타인에게 제시하는 등 행위 있어야 행사죄 성립하는 것 X <span class=\"cs-fact-tag\">[부착은 공기호부정'사용', 운행은 부정사용공기호'행사'에 해당하고 양죄는 실체적 경합관계]</span></div>", ["§238", "제238조"], 1, "gak_사회"], ["사회010", "통화, 유가증권, 수표위조", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제207조(통화의 위조 등)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 행사할 목적으로 통용하는 대한민국의 화폐, 지폐 또는 은행권을 위조 또는 변조한 자는 무기 또는 2년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 행사할 목적으로 내국에서 유통하는 외국의 화폐, 지폐 또는 은행권을 위조 또는 변조한 자는 1년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 행사할 목적으로 외국에서 통용하는 외국의 화폐, 지폐 또는 은행권을 위조 또는 변조한 자는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 위조 또는 변조한 전3항 기재의 통화를 행사하거나 행사할 목적으로 수입 또는 수출한 자는 그 위조 또는 변조의 각 죄에 정한 형에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제214조(유가증권의 위조 등)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 행사할 목적으로 대한민국 또는 외국의 공채증서 기타 유가증권을 위조 또는 변조한 자는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 행사할 목적으로 유가증권의 권리의무에 관한 기재를 위조 또는 변조한 자도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\">부정수표 단속법 제5조(위조·변조자의 형사책임)</div><div class=\"cs-li\" style=\"margin-left:0px\">수표를 위조하거나 변조한 자는 1년 이상의 유기징역과 수표금액의 10배 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 통화에 관한 죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>위조·변조죄</strong> 가. <strong>위조와 변조</strong> 개념: 통화 '변조' = 기존 진정통화 전제로 외관·동일성 상실 안 될 정도 변경 의미, 진정통화와의 동일성 상실할 정도면 위조 해당 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[진정통화 가공행위]</span> 명목가치·실질가치 변경 또는 일반인이 다른 진정 화폐로 오신할 정도 새 물건 만든 것 볼 수 없으면 통화 변조<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[500원 주화 표면 깎음]</span> 크기·모양·문양 대부분 남음 → 일본국 자동판매기가 500¥ 주화로 오인해도 일반인이 500¥ 주화로 오신할 정도 아니면 통화변조죄<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">나. <strong>내국에서 유통하는</strong> 개념: <span class=\"cs-stat\"><strong>§207</strong></span>② '내국에서 유통하는' = '통용하는'과 달리 강제통용력 없이 사실상 거래 대가의 지급수단 되고 있는 상태 <span class=\"cs-fact-tag\">['내국'은 대한민국]</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[이태원 스위스 화폐]</span> 관광객이 상품 지급수단 사용·국내은행 환전 가능해도 지급수단 아니라 외국환매매거래 대상으로 상품 유사 → '내국에서 유통하는' 화폐<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">다. <strong>행사할 목적</strong> 개념: '행사할 목적' = 유가증권위조와 달리 위조·변조 통화를 진정통화로서 '유통'에 놓겠다는 목적 → 자신의 신용력 증명 위해 타인에게 보일 목적으로 위조 시 행사할 목적<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>행사죄</strong> 판단기준 (判例) : 위조통화행사죄 객체 위조통화 = 일반인으로 진정통화 오신할 정도면 족, 진물 흡사·진부 식별 불가 정도일 필요 X 위조 외국화폐가 강제통용력 없으면 <span class=\"cs-stat\"><strong>§207</strong></span>③ '외국에서 통용' 해당 X, 국내 사실상 거래 지급수단 아니면 <span class=\"cs-stat\"><strong>§207</strong></span>② '내국에서 유통' 해당 X → 행사해도 <span class=\"cs-stat\"><strong>§207</strong></span>④ 위조통화행사죄<span class=\"cs-o\"><strong>(X)</strong></span> 위조통화임을 '알고 있는 자'에게 교부:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">피교부자가 유통시키리라는 것 예상·인식하며 교부</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">→ 교부행위 자체가 공공의 신용·거래 안전 해할 위험 → 위조통화행사죄 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[위조통화 행사·재물편취]</span> 위조통화행사죄와 사기죄는 실체적 경합관계<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 통화죄는 문서죄에 대해 특별관계 → 통화죄 성립 시 문서죄 별도 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">② 반대로 통화죄 성립 안 하면 위조사문서행사죄·위조사도화행사죄로 의율 가능</div><div class=\"cs-h\">Ⅱ. 유가증권에 관한 죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>유가증권</strong> 개념: <span class=\"cs-stat\"><strong>§214</strong></span> 유가증권 = 재산권이 증권에 화체 + 권리 행사·처분에 증권 점유 필요 두 요소 갖추면 족, 반드시 유통성 가질 필요 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">공중전화카드<span class=\"cs-o\"><strong>(O)</strong></span>, 카드일련번호식 국제전화카드<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">신용카드: 경제적 가치 있어도 유가증권<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">判例(죄수관계): <span class=\"cs-fact-tag\">[죄수]</span> 유가증권위조죄 죄수는 위조된 유가증권 매수 기준 → 약속어음 2매 위조행위는 포괄일죄 아니라 경합범 <span class=\"cs-fact-tag\">[실경]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>위조·변조, 자격모용</strong> 가. <strong>위조</strong> 판단기준 (判例) : 문방구 약속어음 용지 이용 작성해도 전체 형식·내용상 일반인이 진정한 것으로 오신할 정도 요건 갖추면 유가증권<span class=\"cs-o\"><strong>(O)</strong></span> 행사목적으로 일반인이 진정하게 작성된 유가증권으로 오신케 할 정도면 발행명의인이 실재하지 않은 사자·허무인이라도 위조죄 성립 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[폐지 어음 파지면 조합]</span> 찢어 폐지된 타인발행 명의 약속어음 파지면 조합하여 어음 외형 갖춘 경우 새 약속어음 작성한 것 → 유가증권위조죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[백지어음 금액 기입]</span> 타인이 '위조'한 액면·지급기일 백지 약속어음 구입하여 행사목적으로 백지 액면란에 금액 '기입'하여 위조어음 완성 → 백지어음 형태 위조와 별개 유가증권위조죄 구성</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[사자 명의 소급작성]</span> 사자 명의 약속어음 작성 시 처로부터 인장 교부받아 생존 당시 작성한 것처럼 발행일자를 생존 중 일자로 소급 작성 → 발행명의인 승낙 있었다고 볼 수 없어 유가증권위조죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">나. <strong>변조</strong> 판단기준 (判例) : 유가증권변조 = 진정 성립 유가증권 내용에 권한 없는 자가 동일성 해하지 않는 한도 변경 → 이미 타인이 '위조된 약속어음' 기재사항 권한 없이 변경해도 유가증권변조죄 X 이미 변조된 부분을 다시 권한 없이 변경해도 유가증권변조죄 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[자기명의 유가증권]</span> 타인에게 속한 '자기명의' 유가증권에 무단 변경해도 <span class=\"cs-crime\">문서손괴죄</span>·<span class=\"cs-crime\">허위유가증권작성죄</span> 해당 별론, 유가증권변조죄 구성<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[액면금액 변경]</span> 액면금액 권한 없이 '변경'은 유가증권변조 해당할 뿐 위조 X → '위조'된 약속어음 액면금액 권한 없이 '변경'하는 행위가 당초 위조와 별개 새 유가증권위조 되는 것 X</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>허위유가증권작성</strong> 판단기준 (判例) : 약속어음 발행인이 은행 신고 인장 아닌 다른 인장 날인해도 발행인 인장인 이상 어음 효력 영향 없어 허위유가증권작성죄<span class=\"cs-x\"><strong>(X)</strong></span> 배서인 주소기재는 배서 요건 X → 약속어음 배서인 주소 허위기재해도 배서인 인적 동일성 해하여 배서인 누구인지 알 수 없는 경우 아닌 한 허위유가증권작성죄<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>행사죄</strong> 판단기준 (判例) : 위조유가증권행사죄 유가증권 = 위조된 유가증권 원본 의미, 전자복사기 등 사용 기계적 복사한 사본 X <span class=\"cs-fact-tag\">[위조사문서행사죄 성립]</span><span class=\"cs-exam\">【변13】</span> 교부자가 위조유가증권임을 '알고 있는 자'에게 교부해도 피교부자가 '유통시킬 것임 인식'하고 교부 → 교부행위 자체가 유가증권 유통질서 해할 우려 → 위조유가증권행사죄 성립 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공범 간 교부]</span> 교부자·피교부자가 유가증권위조 공모 또는 타에 행사하여 이익 나눌 것 공모한 공범 관계면 그들 사이 교부행위는 그 이외 자에게 행사함으로써 범죄 실현 위한 전단계 행위 → 위조유가증권 아직 범인들 수중 → 행사된 것<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-h\">Ⅲ. 부정수표단속법위반죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[행사죄 X]</span> 부수법은 행사죄 규정 X → 형법상 위조유가증권행사죄 적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 수표 외관이 일반인으로 진정한 수표로 신용하게 할 정도면 수표요건 결하여 실체법상 무효라도 위조죄 성립<span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[행사할 목적 불요]</span> 부수법 <span class=\"cs-stat\"><strong>§5</strong></span>는 수표의 강한 유통성·거래수단 중요성 감안, 수표 위·변조행위엔 범죄성립요건 완화하여 초과주관적 구성요건인 행사 목적 요구 X, <span class=\"cs-stat\"><strong>§214</strong></span>① 위반 다른 유가증권위·변조행위보다 형 가중처벌 취지 <span class=\"cs-fact-tag\">[장난으로 위조해도 성립]</span><span class=\"cs-exam\">【모기19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[배서의 위·변조 X]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">① 부수법 <span class=\"cs-stat\"><strong>§5</strong></span>는 <span class=\"cs-stat\"><strong>§214</strong></span>① 위반행위 가중처벌 규정 → 처벌범위 넓어지지 않도록 제한적 해석 필요</div><div class=\"cs-li\" style=\"margin-left:32px\">② 부수법 처벌행위는 수표 발행 관련 위조·변조 말하고, 수표 배서 위조·변조는 수표 권리의무 관련 기재 위조·변조로 <span class=\"cs-stat\"><strong>§214</strong></span>② 해당 여부 별론, 부수법 <span class=\"cs-stat\"><strong>§5</strong></span> 해당 X <span class=\"cs-fact-tag\">[당좌수표 배서인란 위조]</span> 수표위조 부수법위반 및 이를 행사한 위조유가증권행사죄는 각 형소법 <span class=\"cs-stat\"><strong>§325</strong></span> 전단 무죄, 축소사실인 유가증권위조죄·위조유가증권행사죄(<span class=\"cs-stat\"><strong>§214</strong></span>②·<span class=\"cs-stat\"><strong>§217</strong></span>)는 각 유죄<span class=\"cs-exam\">【모기23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[무고죄와 실체적 경합]</span> 수표금액 지급·거래정지처분 면할 목적으로 금융기관에 거짓신고한 자 처벌하는 부정수표단속법위반죄와, 타인으로 형사처분·징계처분 받게 할 목적으로 공무소·공무원에 허위사실 신고하는 <span class=\"cs-crime\">무고죄</span>는 보호법익 다르고 사회관념상 행위 1개 평가 어려워 실체적 경합</div>", ["§207", "§214", "§5", "§325", "§217", "제207조", "제214조", "제5조"], 3, "gak_사회"], ["사회011", "방화죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제164조(현주건조물 등 방화)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 불을 놓아 사람이 주거로 사용하거나 사람이 현존하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 무기 또는 3년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 죄를 지어 사람을 상해에 이르게 한 경우에는 무기 또는 5년 이상의 징역에 처한다. 사망에 이르게 한 경우에는 사형, 무기 또는 7년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제165조(공용건조물 등 방화)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">불을 놓아 공용으로 사용하거나 공익을 위해 사용하는 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 무기 또는 3년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제166조(일반건조물 등 방화)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 불을 놓아 제164조와 제165조에 기재한 외의 건조물, 기차, 전차, 자동차, 선박, 항공기 또는 지하채굴시설을 불태운 자는 2년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 소유인 제1항의 물건을 불태워 공공의 위험을 발생하게 한 자는 7년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제167조(일반물건 방화)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 불을 놓아 제164조부터 제166조까지에 기재한 외의 물건을 불태워 공공의 위험을 발생하게 한 자는 1년 이상 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 물건이 자기 소유인 경우에는 3년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제170조(실화)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 과실로 제164조 또는 제165조에 기재한 물건 또는 타인 소유인 제166조에 기재한 물건을 불태운 자는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 과실로 자기 소유인 제166조의 물건 또는 제167조에 기재한 물건을 불태워 공공의 위험을 발생하게 한 자도 제1항의 형에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 타인의 권리대상이 된 자기의 물건</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 자기 소유 물건이라도 압류·강제처분 받거나 타인 권리·보험 목적물 된 때 → 타인의 물건으로 간주(<span class=\"cs-stat\"><strong>§176</strong></span>)<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[단독거주 자기소유 주택 방화·화재보험 가입 or 체납처분 압류]</span> 타인소유건조물방화죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-neg-tag\">[현주건조물방화죄X, 자기소유 일반건조물방화죄X]</span></div><div class=\"cs-h\">Ⅱ. 방화죄의 착수와 기수</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>착수시기</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[매개체설]</span> 매개물 점화로 건조물 소훼 내용 방화죄 → 매개물에 불붙였거나 연소작용 계속될 상태 이르렀다면, 곧바로 진화되어 목적물에 옮겨붙지 못해도 실행착수<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[피해자 몸에 불붙은 경우]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>기수시기<span class=\"cs-exam\">【변사25, 모사23】</span></strong> <span class=\"cs-issue\">《방화죄의 기수시기》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①독립연소설</div><div class=\"cs-li\" style=\"margin-left:16px\">②중요부분연소개시설</div><div class=\"cs-li\" style=\"margin-left:16px\">③효용상실설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[독립연소설]</span> 화력이 매개물 떠나 스스로 연소할 수 있는 상태 → 기수, 목적물 중요부분 소실·본래 효용 상실 要하지 않음</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[시체 위 옷가지·불붙인 천조각 던져 방안 태우며 천정까지 옮겨붙음]</span> 완전연소 前 도중 진화되어도 '천정' 옮겨붙은 이상 이미 현주건조물방화죄 기수<span class=\"cs-exam\">【변사25】</span></div><div class=\"cs-h\">Ⅲ. 현주건조물 등 방화죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>현주(현존)건조물 등</strong> 적용범위: <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§164</span><span class=\"cs-fact-tag\"> 전단 현주건조물방화]</span> '공공에 대한 위험'은 구체적 결과 발생 要하지 않음 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사람 거주 가옥 일부인 외양간(우사) 방화]</span> 현주건조물방화죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[타인이 타고 있는 타인 소유 자동차 소훼·공공위험 발생]</span> <span class=\"cs-stat\"><strong>§164</strong></span>① '현존'자동차방화죄로 처벌<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[절취물 용기 점화 목적이 증거인멸이나 인화력 강한 석유로 건물 연소 용이하게 점화→건물 연소]</span> 현주건조물방화 '고의' 인정 가능<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[범인 혼자 사는 단독주택·화재시 타인 현존X]</span> 현주(현존)건조물방화죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[가정불화·죽은 동생 유품 서적 등 뒷마당서 소각하려던 경우]</span> 가옥 불태울 결의로 불놓았다 볼 수 없다면 현주건조물방화 '범의'<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>현주(현존)건조물방화치사상죄</strong> 적용범위: 현주건조물방화치사상죄는 미수범 처벌규정 없음<span class=\"cs-exam\">【변12】</span> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[현주건조물 내 사람 강타·실신시킨 후 동 건조물 방화하여 소사]</span> 현주건조물방화치사죄만 성립 <span class=\"cs-fact-tag\">[부진정결과적 가중범]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[불놓은 집에서 나오려는 피해자들 막아 소사]</span> 방화행위와 살인행위는 별개 법익 해하는 별개 행위 → 현주건조물방화죄와 살인죄 실체적 경합<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅳ. 일반'건조물'방화죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 방화죄 객체 '건조물'은 반드시 주거용 아니어도 되나 사람이 사실상 기거·취침에 사용할 수 있는 정도는 되어야 함</div><div class=\"cs-h\">Ⅴ. 일반'물건'방화죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[일반물건방화]</span> '공공의 위험 발생'은 고의 내용 → 행위자 인식 必(<span class=\"cs-stat\"><strong>§167</strong></span>) <span class=\"cs-fact-tag\">[공공의 위험이 구성요건]</span><span class=\"cs-exam\">【변17】</span> <span class=\"cs-fact-tag\">[무주물 소훼·공공위험]</span> '무주물'을 '자기 소유 물건'에 준하여 <span class=\"cs-stat\"><strong>§167</strong></span>② 적용 처벌</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[노상 전봇대 주변 재활용품·쓰레기 방화]</span> 재활용품·쓰레기는 '무주물'=<span class=\"cs-stat\"><strong>§167</strong></span>② '자기소유 물건'에 준함 → 불붙인 후 가연물 넣어 화염 키워 전선 등 손상 or 바람에 다른 곳 옮아붙을 공공위험 발생시켰다면 일반물건방화죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[자기소유 일반물건 방화죄 성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[지붕·문짝·창문 없고 담장·벽체 붕괴된 철거대상 폐가]</span> 사실상 기거·취침 불가 → <span class=\"cs-stat\"><strong>§166</strong></span> 건조물 아닌 <span class=\"cs-stat\"><strong>§167</strong></span> '물건', 폐가 내외부 쓰레기 태워 주변 수목 4~5그루 태우고 벽 일부 그을린 정도로는 기수 이르렀다 보기 어렵고, 일반물건방화죄는 미수범 처벌규정 없음</div><div class=\"cs-h\">Ⅵ. 실화죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§170</span><span class=\"cs-fact-tag\">② '자기 소유 </span><span class=\"cs-stat\">§166</span><span class=\"cs-fact-tag\"> or </span><span class=\"cs-stat\">§167</span><span class=\"cs-fact-tag\"> 기재 물건']</span> = '자기소유 <span class=\"cs-stat\"><strong>§166</strong></span> 기재 물건' + '자기소유든 타인소유든 불문 <span class=\"cs-stat\"><strong>§167</strong></span> 기재 물건' 의미 <span class=\"cs-fact-tag\">[금지되는 유추·확장해석 아님]</span><span class=\"cs-exam\">【변26, 모사23】</span></div><div class=\"cs-h\">Ⅶ. 방화예비죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 현주건조물방화죄·공용건조물방화죄·타인소유 일반건조물방화죄 → 미수범 처벌규정(<span class=\"cs-stat\"><strong>§174</strong></span>) 및 예비·음모죄 처벌규정(<span class=\"cs-stat\"><strong>§175</strong></span> 본문) 있음 <span class=\"cs-fact-tag\">[필요적 감면]</span> 목적한 죄 실행 이르기 前 자수한 때 형 감경 or 면제(<span class=\"cs-stat\"><strong>§175</strong></span> 단서)</div><div class=\"cs-h\">◎ 방화·실화 정리표 (원문 표 → 텍스트)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[방화와 실화의 죄 정리]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">유형 / 규정 / 공공위험(법조문)·고의 / 미수·예비음모 / 치사상 / 실화(<span class=\"cs-stat\"><strong>§170</strong></span>) / 업무상·중실화(<span class=\"cs-stat\"><strong>§171</strong></span>) 현주건조물(단독거주 제외) : <span class=\"cs-stat\"><strong>§164</strong></span>① 공공위험 X · 고의 X / 미수·예비음모 O / 치사상 <span class=\"cs-stat\"><strong>§164</strong></span>②(미수범X) / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) 공용건조물 : <span class=\"cs-stat\"><strong>§165</strong></span> 공공위험 X · 고의 X / 미수·예비음모 O / 치사상 X / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) 일반건조물 타인소유(압류·보험) : <span class=\"cs-stat\"><strong>§166</strong></span>① 공공위험 X · 고의 X / 미수·예비음모 O / 치사상 X / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>①(위험X) 일반건조물 자기소유 : <span class=\"cs-stat\"><strong>§166</strong></span>② 공공위험 X · 고의 X / 미수·예비음모 O / 치사상 X / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O) 일반물건 타인소유(압류·보험) : <span class=\"cs-stat\"><strong>§167</strong></span>① 공공위험 O · 고의 O / 미수·예비음모 X / 치사상 X / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O) 일반물건 자기소유(무주물) : <span class=\"cs-stat\"><strong>§167</strong></span>② 공공위험 O · 고의 O / 미수·예비음모 X / 치사상 X / 실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O) / 업무상·중실화 <span class=\"cs-stat\"><strong>§170</strong></span>②(위험O)</div>", ["§176", "§164", "§167", "§166", "§170", "§174", "§175", "§171"], 3, "gak_사회"], ["사회012", "도박죄와 사기도박", "<details class=\"cs-case\"><summary><u><strong>[CASE] 도박장 운영·바지사장 위장</strong></u> <span class=\"cs-exam\">【변사14】 </span><span class=\"cs-o\">(30)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 도박장을 직접 운영하기로 하고 단속에 대비해 실직 중이던 사촌동생 乙에게 '영업을 돕고 적발되면 네가 사장이라고 진술해 달라'고 제의 → 乙 승낙. 생활정보지 광고로 종업원을 채용하고, 乙을 사장으로 위장하려 甲의 자금으로 乙이 직접 사무실을 임차하게 함. 알던 도박꾼 丙 등을 '대포폰'으로 불러 '포커' 도박을 시키고 자릿값으로 한 판에 판돈의 10%를 뗌, 乙은 창문으로 망을 봄. 주민 신고로 경찰관 P 등이 출동해 乙 체포, 甲은 도주. 乙은 경찰서에서 자신이 도박장 주인이라며 운영 경위·자금 출처·임대차계약 경위·종업원 채용 등을 구체적으로</div><div class=\"cs-li\" style=\"margin-left:0px\">거짓 진술. 甲, 乙의 죄책은? (30점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [도박장소개설죄의 공동정범]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공동정범(<span class=\"cs-stat\"><strong>제30조</strong></span>) = 공동가공의 의사 + 그 공동의사에 기한 기능적 행위지배를 통한 범죄실행이라는 주관적·객관적 요건 要</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲은 직접 운영, 乙은 직접 운영은 아니나 공모해 사장 위장을 위해 사무실을 임차하고 망을 봄 → 공동가공의 의사에 기한 기능적 행위지배(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲·乙 = 도박장소개설죄의 공동정범. 본죄가 성립하는 이상 도박방조죄는 별도 성립(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [범인도피죄 및 범인도피교사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [乙의 범인도피죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 범인도피죄(<span class=\"cs-stat\"><strong>제151조</strong></span> 제1항)는 '타인'을 도피하게 하는 경우에 성립 → 자기 도피는 불벌. 다만 바지사장 역할을 맡아 수사기관을 착오에 빠뜨리기로 하고, 단순히 실제 업주라 진술하는 데서 나아가 운영 경위·자금 출처· 임대차 계약 체결 경위 등까지 적극 허위진술하거나 허위자료를 제시해 수사기관이 실제 업주를 발견·체포하기 곤란 내지 불가능할 정도에 이르면 범인도피죄 구성 가능</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙은 구성요건 해당(O)(사안 포섭은 위 판례와 동일하므로 생략). 그러나 甲의 사촌동생 → 책임 조각 → 범인도피죄(X)(<span class=\"cs-stat\"><strong>제151조</strong></span> 제2항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [甲의 범인도피교사죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 자기 도피 교사 — 긍정설/부정설, 판례 = 타인에게 도움을 요청하는 행위도 도피행위의 범주에 속하는 한 불벌이나 방어권의 남용이면 범인도피교사죄 → 긍정설</div><div class=\"cs-li\" style=\"margin-left:0px\">② 그 타인이 <span class=\"cs-stat\"><strong>제151조</strong></span> 제2항에 의해 처벌받지 않는 친족 등이어도 범인도피교사죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 미리 乙을 바지사장으로 내세워 사장인 것처럼 허위 진술하게 함 → 방어권 남용 → 범인도피교사죄(<span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [위계공무집행방해죄 및 교사죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 수사기관에 허위사실을 진술해도 위계로 수사가 방해되었다고 볼 수 없어 위계공무집행방해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙이 적극적으로 증거를 조작한 것은 아니므로 위계공무집행방해죄(<span class=\"cs-stat\"><strong>제137조</strong></span>)(X), 정범이 구성요건에 해당하지 않는 이상 甲에게도 위계공무집행방해교사죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = 도박장소개설죄 + 범인도피교사죄의 실체적 경합, 乙 = 도박장소개설죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제246조(도박, 상습도박)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 도박을 한 사람은 1천만원 이하의 벌금에 처한다. 다만, 일시오락 정도에 불과한 경우에는 예외로 한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 상습으로 제1항의 죄를 범한 사람은 3년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제247조(도박장소 등 개설)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">영리의 목적으로 도박을 하는 장소나 공간을 개설한 사람은 5년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 도박죄 - 우연성</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 도박 = 재물 걸고 '우연'에 의해 재물 득실 결정 '우연'이란 주관적으로 '당사자에 있어서' 확실히 예견 or 자유로이 지배할 수 없는 사실에 관해 승패 결정, 객관적으로 불확실할 것 요구 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[당사자 능력이 승패결과에 영향]</span> 다소라도 우연성 사정에 영향받으면 도박죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[내기 골프는 도박]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[골프 핸디캡]</span> 개인 주관적 평가에 상당히 영향받는 흥정 결과 → 기망행위로 보기 어려움 <span class=\"cs-neg-tag\">[도박죄O, 사기죄X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): <span class=\"cs-fact-tag\">[상습성]</span> 상습도박죄·상습도박방조죄의 상습성 = 행위 속성 아닌 '행위자' 속성(도박 반복·거듭 습벽) → 습벽 있는 자가 타인 도박 방조 시 상습도박방조죄, 습벽 있는 자가 도박+도박방조 하면 상습도박방조죄는 무거운 상습도박죄에 포괄시켜 1죄로 처단</div><div class=\"cs-h\">Ⅱ. 도박장소(공간)개설죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 영리 목적으로 스스로 주재자 되어 그 지배하에 도박장소 개설함으로써 성립, 도박죄와 별개 독립 범죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">['영리의 목적']</span> 반드시 도박개장 직접 대가 아니라 도박개장 통해 간접적으로 얻을 이익도 포함, 현실적으로 이익 얻었을 것 要하지 않음 영리 목적으로 도박 개장하면 기수, 현실로 도박 행하여졌음은 묻지 않음 도박장소개설죄 성립 시 별도로 도박방조죄 성립 X (통설)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[인터넷도박게임 사이트 개설자가 영리 목적 개설]</span> 게임이용자들이 실제 게임 하였는지 여부와 관계없이 도박개장죄 기수<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅲ. 사기도박 - 사기죄만 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>사기도박</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[일방이 사기 수단으로 승패 수 지배]</span> 우연성 결여 → 사기죄만 성립, 도박죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변12】</span> 우연성 갖고 도박한 '상대방'도 사기 피해자일 뿐 도박죄 성립 X 편취 이득액 = 도박 당일 피해자가 잃은 도금 상당액</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>실행의 착수와 기수 및 죄수관계</strong> 개념: <span class=\"cs-fact-tag\">[실행착수]</span> 사기적 방법으로 도금 편취하려는 자가 상대방에게 도박 참가 권유하는 등 기망행위 개시한 때<span class=\"cs-exam\">【변20·12】</span> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사기도박 착수 후 숨기려 얼마간 정상 도박]</span> 사기죄 실행행위에 포함 → 피해자에 대한 사기죄만 성립, 도박죄 따로 성립 X<span class=\"cs-exam\">【변25·22·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[피해자가 도박 고수임 직감·사기도박 포기하고 정상 도박만]</span> 포기 후 도박범행은 도박죄, 포기 前 도박으로 인한 사기미수죄와 실체적 경합범 관계<span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[피해자들 유인해 사기도박·도금 편취한 각 사기죄]</span> 상상적 경합 <span class=\"cs-fact-tag\">[피해자 2명 상대 화투 친 경우]</span><span class=\"cs-exam\">【변25】</span></div>", ["제30조", "제151조", "제31조", "제137조", "제246조", "제247조"], 3, "gak_사회"], ["사회013", "기타 사회적 법익", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제116조의2(공중협박)</strong></span> [공중협박죄] [신설]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 불특정 또는 다수의 사람의 생명, 신체에 위해를 가할 것을 내용으로 공연히 공중을 협박한 사람은 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 상습으로 제1항의 죄를 범한 때에는 그 죄에 정한 형의 2분의 1까지 가중한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 제1항 및 제2항의 미수범은 처벌한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제116조의3(공공장소 흉기소지)</strong></span> [공공장소흉기소지죄] [신설]</div><div class=\"cs-li\" style=\"margin-left:0px\">정당한 이유 없이 도로·공원 등 불특정 또는 다수의 사람이 이용하거나 통행할 수 있는 공공장소에서 사람의 생명, 신체에 위해를 가할 수 있는 흉기를 소지하고 이를 드러내어 공중에게 불안감 또는 공포심을 일으킨 사람은 3년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 범죄단체</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>단체 또는 집단</strong> 적용범위: <span class=\"cs-fact-tag\">[적용법률]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①폭처법 규정 범죄 목적 범죄단체 조직 → 폭처법 적용,</div><div class=\"cs-li\" style=\"margin-left:16px\">②그 외 사형·무기·장기 4년 이상 징역 해당 범죄 목적 범죄단체 조직 → 형법 적용(폭처법 <span class=\"cs-stat\"><strong>§4</strong></span>, 형법 <span class=\"cs-stat\"><strong>§114</strong></span>) 개념:</div><div class=\"cs-li\" style=\"margin-left:16px\">①<span class=\"cs-stat\"><strong>§114</strong></span> '단체' = 특정 다수인이 일정 범죄 수행 공동목적 아래 구성한 계속적 결합체로서 단체 주도·내부질서 유지하는 최소한의 통솔체계 갖춘 것</div><div class=\"cs-li\" style=\"margin-left:16px\">②범죄 '집단' = 조직체계 갖춘 계속적 결합체, 최소한의 통솔체계 갖출 필요는 없으나 범죄 계획·실행 용이하게 할 정도의 조직적 구조 갖추어야</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>조직(구성)·가입·활동</strong> 적용범위: 범죄단체조직죄는 범죄 목적 단체 조직함으로써 성립, 목적한 범죄 실행행위 하였는가 여부는 죄 성립에 영향 X <span class=\"cs-fact-tag\">[폭처법 </span><span class=\"cs-stat\">§4</span><span class=\"cs-fact-tag\">① 단체 등 '구성죄']</span> 단체·집단 구성함으로써 즉시 성립·동시 완성되는 즉시범 → 구성만 하면 범죄 성립·동시에 공소시효 진행<span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>죄수관계</strong> 判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[범죄단체 구성·가입 후 구성원 활동]</span> 포괄일죄 관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">범죄집단활동죄와 개별 마약류관리에관한법률위반(향정)죄는 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">범죄단체 조직원의 폭처법위반(단체등의공동강요)죄 개별적 범행과 폭처법위반(단체등의활동)죄는 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">범죄단체 구성원 활동행위와 집단감금 or 집단상해행위는 각각 별개 범죄구성요건 충족하는 독립된 행위 <span class=\"cs-fact-tag\">[실경]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사기 공소사실과 범죄단체 공소사실(</span><span class=\"cs-stat\">§114</span><span class=\"cs-fact-tag\"> 범죄단체조직·활동)]</span> 범행일시·행위태양·공모관계 등 범죄사실 내용 다르고 죄질에도 현저한 차이 → 실체적 경합<span class=\"cs-exam\">【변23, 모사25】</span></div><div class=\"cs-h\">Ⅱ. 일반교통방해죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span> 교통 불가능 or 현저히 곤란한 상태 발생하면 바로 기수, 교통방해 결과 현실적 발생 要하지 않음</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공로 출입 가능한 다른 도로 있는 상태서 토지소유자 일시적 사용승낙 받아 통행 or 소유자 개인적 사용 중 부수적 통행 묵인한 도로]</span> 육로 해당<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[계속범-공동정범 종료시까지]</span> 교통방해 행위는 계속범 성질 → 위법상태 계속 존재, 교통방해 유발 집회에 피고인 참가 시 참가 당시 이미 다른 참가자들에 의해 교통흐름 차단된 상태였어도 다른 참가자들과 암묵적·순차적 공모하여 위법상태 지속시켰다 평가되면 일반교통방해죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①집회·시위가 신고 범위 내 or 신고 내용과 다소 다르게 행해졌어도 신고 범위 현저히 일탈 X → 특별한 사정 없는 한 일반교통방해죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">②당초 신고 범위 현저히 일탈 or 집시법 <span class=\"cs-stat\"><strong>§12</strong></span> 조건 중대 위반하여 도로교통 방해·통행 불가능 or 현저히 곤란하게 하면 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅲ. 시체은닉죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[살해자가 시체 다른 장소로 옮겨 유기]</span> 별도 시체유기죄 성립, 시체유기를 불가벌적 사후행위로 볼 수 없음 <span class=\"cs-fact-tag\">[실체적 경합범]</span><span class=\"cs-exam\">【변19·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[살해 목적 수행 위해 사후 시체발견 불가능·심히 곤란케 하려는 의사로 인적 드문 장소 유인 or 실신 피해자 끌고 가 살해·시체 둔 채 도주]</span> 결과적으로 발견 현저히 곤란해도 별도 시체은닉죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변19·12】</span></div><div class=\"cs-h\">Ⅳ. 음화판매·제조죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">①컴퓨터 프로그램파일은 <span class=\"cs-stat\"><strong>§243</strong></span>(음화판매) 규정 문서·도화·필름 기타 '물건' 해당 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②<span class=\"cs-stat\"><strong>§244</strong></span>(음화제조등) '음란한 물건' 해석에도 그대로 적용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§243</span><span class=\"cs-fact-tag\"> 음란성 판단]</span> 법관이 자신의 정서 아닌 '일반 보통인의 정서' 기준으로 하여야</div><div class=\"cs-h\">Ⅴ. 기타 범죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[자동차파괴죄(</span><span class=\"cs-stat\">§185</span><span class=\"cs-fact-tag\">)]</span> '파괴' = 다른 구성요건 행위인 전복·매몰·추락 등과 같은 수준으로 인정할 만큼 교통기관 기능·용법 전부·일부 불가능하게 할 정도의 파손, 그 정도 이르지 않는 단순 손괴는 포함 X <span class=\"cs-fact-tag\">[수도불통죄(</span><span class=\"cs-stat\">§195</span><span class=\"cs-fact-tag\">)]</span> '수도 기타 시설' = 공중 음용수 공급 주된 목적 설치된 것에 한정 X, 다른 목적 설치되었어도 불특정·다수인에게 현실적으로 음용수 공급하면 충분, 소유관계 따라 달리 볼 것 아님 <span class=\"cs-fact-tag\">[상가입주자들이 상가 2층 화장실 연결해 음용수로 이용중인 수도배관 분리한 행위(O)]</span> <span class=\"cs-fact-tag\">[유골손괴죄(</span><span class=\"cs-stat\">§161</span><span class=\"cs-fact-tag\">)]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①보호법익 = 사자에 대한 사회적 풍속으로서의 종교적 감정 or 종교적 평온</div><div class=\"cs-li\" style=\"margin-left:16px\">②제사주재자 or 그로부터 정당하게 승낙 얻은 자의 동의 없이 함부로 유골의 물리적 형상 변경 등으로 훼손하는 것은 사자에 대한 경애·추모 등 종교적 감정·평온을 해치는 '손괴'에 해당</div>", ["§4", "§114", "§12", "§243", "§244", "§185", "§195", "§161"], 2, "gak_사회"], ["국가001", "직무유기죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제122조(직무유기)</strong></span> 공무원이 정당한 이유없이 그 직무수행을 거부하거나 그 직무를 유기한 때에는 1년 이하의 징역이나 금고 또는 3년 이하의 자격정지에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 일반</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 부진정부작위범 — 구체적 직무수행 작위의무 있음에도 직무 버린다는 인식하 작위의무 불이행으로 성립 <span class=\"cs-fact-tag\">[작위·부작위 모두 가능]</span> <span class=\"cs-fact-tag\">[계속범]</span> 위법한 부작위상태 계속되는 한 가벌적 위법상태 계속 존재 → 즉시범 아님<span class=\"cs-exam\">【변22·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[병가중인 자]</span> 구체적 작위의무 내지 국가기능 저해에 대한 구체적 위험성 없어 → 직무유기죄 주체 될 수<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 직무유기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: 성립하려면 직무내용이 성문 법령상 근거 or 적어도 군대 내 특단의 지시·명령으로 고유의 직무내용 이루어야 <span class=\"cs-fact-tag\">[군형법 </span><span class=\"cs-stat\">§24</span><span class=\"cs-fact-tag\"> 관련]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 직무유기 = 법령·내규상 추상적 성실의무 게을리하는 일체 아니라, 직장 무단이탈·직무 의식적 포기 등 국가기능 저해·국민 피해 야기 구체적 가능성 있는 경우만</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[경찰관이 불법체류자 신병 출입국관리사무소 인계 X·훈방·인적사항조차 미기재]</span> 직무유기 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[태만·착각 등으로 직무 성실 수행 X or 소홀 수행]</span> 직무유기죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">①직무집행 의사로 자신의 직무 수행한 경우 내용 위법 평가만으로 직무유기 성립 X</div><div class=\"cs-li\" style=\"margin-left:32px\">②지자체장이 전공노 주도 파업 참가 소속 공무원들에 대해 관할 인사위원회 징계의결요구 X하고 자체 인사위원회 징계의결요구·훈계처분 지시 → 직무유기 구성<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·14】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[교육기관장 등 징계의결 집행]</span> 장애 없는데 통보받은 날부터 법정 시한 지나도록 집행 유보 모든 경우 성립 X, 의식적 방임·포기 해당 경우만 성립</div><div class=\"cs-h\">Ⅲ. 직무유기죄의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[뇌물수수죄]</span> 경찰관이 오토바이 장기간 반복 보관·반환 처리 및 반환여부 확인 전혀 X ·대가 돈까지 지급받음 → 습득물 처리 지침 직무 의식적 방임·포기, 직무유기 해당 <span class=\"cs-fact-tag\">[판례: 뇌물수수죄와 직무유기죄 실체적 경합 인정, 단 수뢰후부정처사죄 성립 시 그와 상상적 경합]</span><span class=\"cs-exam\">【변사21】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[인권옹호직무명령불준수죄]</span> <span class=\"cs-stat\"><strong>§139</strong></span> 인권옹호직무명령불준수죄와 <span class=\"cs-stat\"><strong>§122</strong></span> 직무유기죄 구성요건·보호법익 비교 시 법조경합 특별관계로 보기 어렵고 양죄 상상적 경합</div>", ["§24", "§139", "§122", "제122조"], 2, "gak_국가공무원"], ["국가002", "부작위범인 직무유기죄와 작위범의 관계", "<details class=\"cs-case\"><summary><u><strong>[CASE] 진술조서 파쇄·허위 불송치결정서 작성</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲의 절도죄·장물취득죄를 수사하던 사법경찰관 戊, 甲의 아버지가 자신이 좋아하는 영화배우임을 알고 사건을 무마하려 절도 피해자 丁에 대한 진술조서를 파쇄하고, 불송치 결정서에 '丁이 소환에 불응하여 조사를 할 수 없었다'고 기재해 수사기록에 편철.</div><div class=\"cs-li\" style=\"margin-left:0px\">戊의 죄책을 논하시오. (15점) [범인은닉의 점은 논외로 함]</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [피해자 丁에 대한 진술조서 파쇄한 행위]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [공용서류손상죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무소에서 사용하는 서류를 손상·은닉하거나 기타 방법으로 효용을 해하면 성립(<span class=\"cs-stat\"><strong>제141조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 戊는 공무소 사용 서류인 丁에 대한 진술조서를 파쇄 → 공용서류손상죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [증거인멸죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 타인의 형사사건·징계사건에 관한 증거를 인멸하면 성립(<span class=\"cs-stat\"><strong>제155조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲의 절도죄·장물취득죄의 증거인 丁 진술조서를 파쇄 → 증거인멸죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [소결] 진술조서 파쇄라는 1개의 행위 → 공용서류손상죄와 증거인멸죄의 상상적 경합(<span class=\"cs-stat\"><strong>제40조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [허위 내용의 불송치 결정서를 작성·비치한 행위]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [직무유기죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 직무유기죄는 부진정부작위범 → 부작위로도 범할 수 있음</div><div class=\"cs-li\" style=\"margin-left:0px\">② 절도죄 증거가 충분해 검사에게 송치해야 함에도 정당한 이유 없이 직무를 유기하고 송치하지 않음 → 일응 부작위에 의한 직무유기죄(<span class=\"cs-stat\"><strong>제122조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [허위공문서작성죄 및 동행사죄] 공문서인 불송치 결정서에 허위 내용을 기재한 뒤 수사기록에 편철 → 허위공문서작성죄(<span class=\"cs-stat\"><strong>제227조</strong></span>) + 허위작성공문서행사죄(<span class=\"cs-stat\"><strong>제229조</strong></span>)의 실체적 경합</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [죄수관계]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원이 위법사실을 발견하고도 직무상 의무에 따른 적절한 조치 없이 적극적으로 은폐할 목적으로 허위공문서를 작성·행사한 경우 직무위배의 위법상태는 허위공문서작성 당시부터 그 속에 포함 → 작위범인 허위공문서작성·동행사죄만 성립, 부작위범인 직무유기죄는 별도 성립(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 戊는 甲의 절도범행을 적극 은폐할 목적으로 허위공문서를 작성·행사 → 직무유기죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 戊 = 공용서류손상죄·증거인멸죄의 상상적 경합 + 허위공문서작성죄 + 허위작성공문서행사죄, 이들 상호간 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 기본 구조</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[판례 기본 문구]</span> 직무위배 위법상태가 (허위공문서작성행위, 범인도피행위, 증거인멸행위, 위계에 의한 공무집행방해행위) 속에 포함 → 작위범(허위공문서작성 및 동행사죄, 범인도피죄, 증거인멸죄, 위계공무집행방해죄)만 성립하고 부작위범 직무유기죄는 따로 성립 X</div><div class=\"cs-h\">Ⅱ. 직무유기죄와 허위공문서작성죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[위법사실 은폐 목적]</span> 공무원이 위법사실 발견하고도 적절 조치 X ·적극 은폐 목적 허위공문서 작성·행사 → 직무위배 위법상태 허위공문서작성 당시부터 포함, 작위범 허위공문서작성·동행사죄만 성립·직무유기죄 따로 성립 X<span class=\"cs-exam\">【변24】</span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[위법사실 은폐 목적]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">① 예비군 중대장이 소속 대원 훈련불참사실 알고도 대대장 보고 등 조치 X ·고의 은폐 목적 참석한 양 허위 학급편성명부 작성·행사</div><div class=\"cs-li\" style=\"margin-left:32px\">② 경찰관이 도박범행 적발하고도 상관 보고·형사입건 등 조치 X ·은폐 목적 근무일지 허위 작성·행사</div><div class=\"cs-li\" style=\"margin-left:32px\">③ 공무원이 신축건물 착공·준공검사 후 허가조건 위배사실 숨기려 허위 복명서 작성·행사 → 각 작위범 허위공문서작성죄·동행사죄만 성립, 부작위범 직무유기죄 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[위법사실 은폐 목적 아닌 경우]</span> 복명서·심사의견서 허위작성이 농지일시전용허가 신청 허가해 주기 위한 것 → 농지불법전용 은폐 목적 아니므로 허위공문서작성·동행사죄와 직무유기죄는 '실체적 경합범'<span class=\"cs-exam\">【모기23】</span></div><div class=\"cs-h\">Ⅲ. 직무유기죄와 범인도피죄<span class=\"cs-exam\">【모사22·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 검사로부터 범인 검거 지시받고도 적절 조치 X ·오히려 범인에게 전화로 도피 권유하여 도피케 함 → 직무위배 위법상태 범인도피행위 속 포함, 작위범 범인도피죄만 성립·직무유기죄 따로 성립 X<span class=\"cs-exam\">【변22·19】</span></div><div class=\"cs-h\">Ⅳ. 직무유기죄와 증거인멸죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 경찰서 과장이 부하직원으로부터 오락실 단속 증거물(변조 기판) 압수 보고받고도 수사계 인계·검찰 송치 등 조치 X ·오히려 압수 변조 기판 돌려주라 지시하여 오락실 업주에게 반환 → 직무위배 위법상태 증거인멸행위 속 포함, 작위범 증거인멸죄만 성립·직무유기죄 따로 성립 X<span class=\"cs-exam\">【변22·18·15】</span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-h\">Ⅴ. 직무유기죄와 위계공무집행방해죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 출원인이 어업허가 받을 수 없는 자임 알면서 적절 조치 X ·오히려 부하직원으로 어업허가 처리 기안문 작성케 한 뒤 스스로 중간결재하여 국장 최종결재 받음 → 직무위배 위법상태 위계공무집행방해행위 속 포함, 작위범 위계공무집행방해죄만 성립·직무유기죄 따로 성립 X</div><div class=\"cs-h\">Ⅵ. 검사의 공소제기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위:</div><div class=\"cs-li\" style=\"margin-left:16px\">① 하나의 행위가 부작위범 직무유기죄와 작위범 범인도피죄 구성요건 동시 충족 시, 공소제기권자는 재량으로 작위범 범인도피죄로 공소 X하고 부작위범 직무유기죄로만 공소 제기 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">② 허위공문서작성죄·동행사죄도 동일 <span class=\"cs-fact-tag\">[하나의 행위가 작위범과 부작위범 구성요건 동시 충족 가능(O)]</span><span class=\"cs-exam\">【변22·13·12】</span></div>", ["제141조", "제155조", "제40조", "제122조", "제227조", "제229조"], 3, "gak_국가공무원"], ["국가003", "공무상비밀누설죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 경찰관이 동창에게 체포영장 신청 예정 알려줌</strong></u> <span class=\"cs-exam\">【변사23】 </span><span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">업무상배임 혐의로 경찰수사가 진행 중임을 직감한 甲이 중학교 동창인 경찰관 乙에게 수사 상황을 알려 달라 부탁 → 乙이 甲에 대한 체포영장을 곧 신청할 예정임을 알려 줌 → 실제로</div><div class=\"cs-li\" style=\"margin-left:0px\">사법경찰관 P1이 다음 날 오후 체포영장을 발부받아 집행 착수. 甲과 乙의 죄책은? (10점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① '법령에 의한 직무상 비밀' = 실질적으로 비밀로 보호할 가치가 있을 것 要</div><div class=\"cs-li\" style=\"margin-left:0px\">② '체포영장을 곧 신청할 예정'이라는 수사기관 내부 정보는 누설될 경우 증거인멸·허위진술로 수사에 장애를 초래할 위험 → 수사기관 내부의 비밀로서 '법령에 의한 직무상 비밀'(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 공무원인 경찰관 乙이 동창 甲에게 알려 줌 → 공무상비밀누설죄(<span class=\"cs-stat\"><strong>제127조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 누설의 결의가 없는 乙에게 부탁 → 일응 교사(<span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 필요적 공범 중 대향범 관계에 있는 자에게 형법 총칙이 적용되는지 — 긍정설/부정설, 판례 = 부정설. 형법 총칙은 임의적 공범을 전제한 규정 → 부정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲 = 공무상비밀누설교사죄(X)</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제127조(공무상 비밀의 누설)</strong></span> 공무원 또는 공무원이었던 자가 법령에 의한 직무상 비밀을 누설한 때에는 2년 이하의 징역이나 금고 또는 5년 이하의 자격정지에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 법령에 의한 직무상 비밀</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 공무상비밀누설죄는 기밀 그 자체 보호 아니라 공무원 비밀엄수의무 침해로 위험받는 이익, 즉 비밀 누설로 위협받는 '국가의 기능' 보호 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">① '법령에 의한 직무상 비밀' = 반드시 법령에 의해 비밀로 규정·분류 명시된 사항 한하지 X<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">② 정치·군사·외교·경제·사회적 필요로 비밀로 된 사항은 물론 정부·공무소·국민이 객관적·일반적 입장에서 외부에 알려지지 않는 것에 상당한 이익 있는 사항도 포함하나</div><div class=\"cs-li\" style=\"margin-left:16px\">③ 실질적으로 비밀로서 보호할 가치 있다고 인정할 수 있는 것이어야 함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[비밀 O]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">① 체포영장 발부자 명단</div><div class=\"cs-li\" style=\"margin-left:32px\">② 직무상 지득한 구술시험 문제</div><div class=\"cs-li\" style=\"margin-left:32px\">③ 특사단 추천의원 정리 문건</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">① 수사기관이 특정 사건 내사·수사 진행 상태에서 확보 자료·죄책·신병처리 의견 등 정보 알 수 있는 수사지휘서 내용 외부 알려질 경우 증거 수집 등 범죄수사 기능 장애 위험</div><div class=\"cs-li\" style=\"margin-left:32px\">② 따라서 검사가 수사 대상·방법 등 사법경찰관리 지휘 내용 기재한 수사지휘서 기재 내용·수사상황은 종국적 결정 전까지 외부 누설 안 될 수사기관 내부 비밀 해당 <span class=\"cs-fact-tag\">[검사가 신병처리에 관하여는 수사지휘를 하지 않았다는 사실]</span><span class=\"cs-exam\">【변26】</span><span class=\"cs-exam\">【변사23·14, 모사25·23·17·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[비밀 X]</span> 재산 소유 주체 정보에 불과한 자동차 소유자 정보는 실질적 비밀 보호가치 있다거나 누설로 국가 기능 위협받는다 볼 수<span class=\"cs-x\"><strong>(X)</strong></span> [구청 공무원이 차적 조회 시스템으로 경찰 잠복근무 차량 소유관계 정보 알아내 지인에게 알려줌 → 공무상비밀누설죄 해당 X]</div><div class=\"cs-h\">Ⅱ. 누설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념:</div><div class=\"cs-li\" style=\"margin-left:16px\">① '누설' = 비밀을 아직 모르는 다른 사람에게 임의로 알려주는 행위</div><div class=\"cs-li\" style=\"margin-left:16px\">② 공무원이 직무상 알게 된 비밀을 그 직무 관련성·필요성에 기하여 해당 직무 집행과 관련 있는 다른 공무원에게 직무집행 일환으로 전달한 경우 → 전달받은 공무원이 직무집행과 무관하게 제3자에게 누설할 것으로 예상되는 등 국가기능 위험 발생 특별한 사정 인정 X 한, 비밀 누설 해당<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 누설받은 자에 대한 총칙 규정의 적용 여부<span class=\"cs-exam\">【변사23·14, 모사25·23·17·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 2인 이상 서로 대향된 행위 존재 필요로 하는 대향범에 공범 형법총칙 규정 적용 X, <span class=\"cs-stat\"><strong>§127</strong></span>은 공무원 등이 법령에 의한 직무상 비밀 누설하는 행위만 처벌 ·누설받은 상대방 처벌 규정 없는 점 비추어, 직무상 비밀 누설받은 자에 공범 형법총칙 규정 적용<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[변호사 사무실 직원이 법원공무원에게 부탁하여 수사 중 사건 체포영장 발부자 명단 누설받은 경우]</span> 변호사 사무실 직원 행위 공무상비밀누설교사죄로 처벌<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span></div>", ["§127", "제127조", "제31조"], 3, "gak_국가공무원"], ["국가004", "직권남용권리행사방해죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제123조(직권남용)</strong></span> 공무원이 직권을 남용하여 사람으로 하여금 의무없는 일을 하게 하거나 사람의 권리행사를 방해한 때에는 5년 이하의 징역, 10년 이하의 자격정지 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 직권</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념:</div><div class=\"cs-li\" style=\"margin-left:16px\">① 직권남용죄 = 공무원이 일반적 직무권한 속하는 사항 관하여 직권 행사 가탁 실질적·구체적 위법·부당 행위 한 경우 성립 '직권의 남용' = 일반적 직무권한 속하는 사항 불법 행사 = 형식적·외형적으로 직무집행 보이나 실질적으로 정당한 권한 이외 행위</div><div class=\"cs-li\" style=\"margin-left:16px\">② 일반적 직무권한 속하지 않는 행위 하는 경우인 지위 이용 불법행위와 구별</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 직권남용죄는 일반적 직무권한 속하는 사항 관하여 직권 행사 가탁 실질적·구체적 위법·부당 행위 한 경우 성립, 일반적 직무권한은 반드시 법률상 강제력 수반 要하지 X<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 어떠한 직무가 공무원 일반적 권한 속하는 사항이라 하려면 그에 관한 '법령상 근거' 必</div><div class=\"cs-li\" style=\"margin-left:16px\">② 다만 법령상 근거는 반드시 명문 근거만 의미 X, '명문 없는 경우'라도 법·제도 종합적·실질적 관찰하여 해당 공무원 직무권한 속한다 해석되는 경우 일반적 권한에 포함<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[퇴임 후]</span> 직권 존재 X → 퇴임 후에도 실질적 영향력 행사 등 퇴임 전 공모 범행 기능적 행위지배 계속 특별한 사정 없는 한, 퇴임 후 범행 관하여 공범 책임<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅱ. 남용</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 직권 행사 목적·방법에 위법·부당 정도 실질적·구체적으로 보아 직무 본래 수행이라 평가할 수 없는 정도 이른 경우 직권 남용 평가 가능하나, 위법·부당 정도 그에 미치지 못하는 경우 직권남용 해당 여부 보다 신중 판단 必</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공무원이 직무와 상관없이 단순히 개인적 친분에 근거 문화예술활동 지원 권유·협조 의뢰]</span> 직권남용 해당<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 의무없는 일을 하게 하거나 사람의 권리행사를 방해</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>의무 없는 일을 하게 한 때</strong> 성립요건:</div><div class=\"cs-li\" style=\"margin-left:16px\">① '사람으로 하여금 의무 없는 일을 하게 한 것'과 '사람의 권리행사를 방해한 것'은 객관적 구성요건요소인 '결과'로서 둘 중 하나 충족되면 성립, 이는 '공무원이 직권을 남용하여'와 구별되는 별개 범죄성립요건</div><div class=\"cs-li\" style=\"margin-left:16px\">② 따라서 공무원 행위가 직권남용 해당한다 하여 그 이유만으로 상대방이 한 일이 '의무 없는 일' 해당한다 인정할 수 X 개념: '의무' = 법률상 의무, 단순한 심리적 의무감·도덕적 의무는 해당 X<span class=\"cs-exam\">【변20】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[상대방이 일반 '사인'인 경우]</span> 특별한 사정 없는 한 직권 대응 따라야 할 의무 없으므로 어떠한 행위 하게 하면 '의무 없는 일 하게 한 때' 해당 가능<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">① 상대방이 공무원이거나 법령 따라 일정한 공적 임무 부여받은 공공기관 등 임직원인 경우 법령 따라 임무 수행 지위 → 직권 대응 어떤 일 한 것이 의무 없는 일인지 관계 법령 따라 개별 판단<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-li\" style=\"margin-left:48px\">② 직무집행 기준·절차 법령에 구체적 명시 ·실무 담당자에게도 기준 적용·절차 관여할 '고유한 권한과 역할 부여'되어 있다면 실무 담당자로 그 기준·절차 위반하여 직무집행 보조하게 한 경우 '의무 없는 일 하게 한 때' 해당</div><div class=\"cs-li\" style=\"margin-left:48px\">③ 그러나 공무원이 자신의 직무권한 속하는 사항 관하여 실무 담당자로 직무집행 보조하는 '사실행위' 하도록 하더라도 공무원 자신의 직무집행으로 귀결될 뿐이므로 원칙적으로 '의무 없는 일 하게 한 때' 해당 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[행정기관들 협조·의견교환]</span> 행정 효율성 위해 필요, 동등 지위뿐 아니라 상하기관·감독기관과 피감독기관 사이에서도 가능 → 일방이 상대방 요청 청취·의견 밝히거나 협조 등 응하는 행위 특별한 사정 없는 한 법령상 의무 없는 일이라 단정 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[상대방이 공무원 또는 유관기관 임직원인 경우]</span> 법령 그 밖 관련 규정 따라 직무수행 과정 준수 원칙·기준·절차 위반 X 한 특별한 사정 없는 한 법령상 의무 없는 일 하게 한 때 해당 보기 어려움</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>권리행사방해</strong> 개념: <span class=\"cs-stat\"><strong>§123</strong></span> 직권남용권리행사방해죄에서 '권리' = 법률에 명기된 권리 한하지 X, 법령상 보호되어야 할 이익이면 족하고 공법상·사법상 권리인지 불문<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅳ. 직권남용으로 인한 결과 발생</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[위험범]</span> 권리행사방해죄는 강학상 '위태범'이지만, 위태범이라는 이유로 권리침해사실 현실적 존재 필요 없다 할 수 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[현실적 방해]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 직권남용권리행사방해죄는 단순히 직권 남용 행위만으로 곧바로 성립 X, 직권 남용하여 '현실적으로' 다른 사람으로 법령상 의무 없는 일 하게 하거나 구체적 권리행사 방해 결과 발생하여야 하고 그 결과 발생은 직권남용 행위로 인한 것이어야</div><div class=\"cs-li\" style=\"margin-left:16px\">② 권리행사 방해 = 법령상 행사할 수 있는 권리의 정당한 행사 방해, 해당하려면 구체화된 권리의 '현실적' 행사 방해된 경우라야<span class=\"cs-exam\">【변25】</span> 공무원 직권남용 있다 하여도 현실적으로 권리행사 저해 없으면 기수 인정 X <span class=\"cs-fact-tag\">[미수범 처벌 규정 X]</span><span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅴ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공무원 행위가 권리행사 방해로 인한 직권남용권리행사방해죄와 의무 없는 일 하게 함으로 인한 직권남용권리행사방해죄 두 행위태양 모두 해당하는 것으로 기소된 경우, 권리행사 방해로 인한 직권남용권리행사방해죄만 성립하고 의무 없는 일 하게 함으로 인한 것은 따로 성립 X<span class=\"cs-exam\">【변25·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">직권남용권리행사방해죄는 국가기능 공정한 행사라는 국가적 법익 보호 주된 목적 → 공무원이 동일 사안 일련의 직무집행 과정에서 단일·계속 범의로 일정 기간 계속 저지른 직권남용행위에 대하여는 설령 상대방 여러 명이라도 포괄일죄 성립 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[체포 요건 충족 X 알면서 재량 범위 벗어남 인식·용인한 채 체포하여 권리행사 방해]</span> 직권남용체포죄와 직권남용권리행사방해죄 성립 <span class=\"cs-fact-tag\">[상상적 경합]</span><span class=\"cs-exam\">【변25】</span></div>", ["§123", "제123조"], 3, "gak_국가공무원"], ["국가005", "뇌물죄 일반", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제129조(수뢰, 사전수뢰)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 공무원 또는 중재인이 그 직무에 관하여 뇌물을 수수, 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공무원 또는 중재인이 될 자가 그 담당할 직무에 관하여 청탁을 받고 뇌물을 수수, 요구 또는 약속한 후 공무원 또는 중재인이 된 때에는 3년 이하의 징역 또는 7년 이하의 자격정지에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제130조(제삼자뇌물제공)</strong></span> 공무원 또는 중재인이 그 직무에 관하여 부정한 청탁을 받고 제3자에게 뇌물을 공여하게 하거나 공여를 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 주체 – 공무원 또는 중재인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[진정신분범]</span> 뇌물죄 '공무원' = 국가·지자체 및 이에 준하는 공법인 사무 종사자로서 노무 내용이 단순 기계적·육체적인 것에 한정되지 않은 자 <span class=\"cs-neg-tag\">[집행관O, 집행관사무원X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[임용무효]</span> 임명권자에 의해 임용되어 공무 종사해 온 사람이 임용결격자여서 임용행위 무효라도 <span class=\"cs-stat\"><strong>§129</strong></span> 공무원으로 봄 → 수뢰죄 처벌<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변18·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[지위 떠난 후 수수]</span> 수수 등 당시 이미 '공무원 지위 떠난 경우'엔 <span class=\"cs-stat\"><strong>§129</strong></span>① 수뢰죄 처벌 X, <span class=\"cs-stat\"><strong>§131</strong></span>③ 사후수뢰죄 요건 해당시만 처벌 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[지자체 위원 위촉]</span> 국가공무원이 지자체 업무 전문가로 위원 위촉받아 한시적 직무수행 → 위촉 종료시 그 위원 지위 소멸 → 이후 종전 위촉 직무 관련 금품수수는 사후수뢰죄 별론, 일반 수뢰죄 처벌 X</div><div class=\"cs-h\">Ⅱ. 뇌물</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 직무에 관한 부당한 이익 내지 불법한 보수 <span class=\"cs-fact-tag\">[보호법익]</span> 직무집행 공정·직무행위 불가매수성 → 뇌물성은 의무위반 행위 유무·청탁 유무 불문<span class=\"cs-exam\">【변14】</span> <span class=\"cs-fact-tag\">[이익 범위]</span> 금전·물품 등 재산적 이익 + 사람의 수요·욕망 충족 일체의 유형·무형 이익 포함</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 성립에 반드시 직무 관한 청탁·부정행위 必 X, 금원수수로 사회일반으로부터 직무집행 공정성 의심받는지 여부도 하나의 판단기준</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">성적 욕구 충족도 뇌물<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[투기적 사업 참여기회]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①참여기회 취득도 뇌물</div><div class=\"cs-li\" style=\"margin-left:32px\">②수수죄 기수시기=투기사업 참여행위 종료시</div><div class=\"cs-li\" style=\"margin-left:32px\">③이후 경제사정 변동으로 이득 못 얻어도 수수죄 성립 영향 X<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[당좌수표 부도]</span> 뇌물로 공여된 당좌수표가 수수 후 부도돼도 뇌물죄 성립 지장 X</div><div class=\"cs-h\">Ⅲ. 직무에 관하여</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>직무</strong> 개념: '직무' = 법령상 직무 + 관련 직무, 과거 담당했거나 장래 담당할 직무 외 사무분장상 현실적으로 담당 안 해도 법령상 일반적 직무권한 속하는 직무 등 그 지위에 따라 담당할 일체의 직무 포함<span class=\"cs-exam\">【변14】</span> 과거·장래 담당 직무 자체 + 그 직무와 밀접관계 있는 행위, 관례·사실상 소관 직무행위 및 결정권자 보좌·영향 줄 수 있는 직무행위도 포함 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[참여주사 양형 청탁]</span> 형사사건 양형은 법원 참여주사 직무와 밀접관계 없음 → 양형 감경 청탁과 함께 금품수수해도 뇌물수수죄 주체<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>전체적 대가관계</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[전체적 대가관계]</span> 직무와 금원수수가 '전체적으로 대가관계' 있으면 수수죄 성립, 청탁 유무·개개 직무행위 대가적 관계 고려 不要, 직무행위 특정 不要<span class=\"cs-exam\">【변18】</span> <span class=\"cs-fact-tag\">[불가분 결합]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①직무행위 대가 + 직무외 행위 대가가 불가분 결합시 수수금품 전부가 직무행위 대가 성질</div><div class=\"cs-li\" style=\"margin-left:16px\">②수회 걸쳐 수수하고 행위별 직무관련성 달리 볼 여지 있으면 행위마다 관련성 판단</div><div class=\"cs-li\" style=\"margin-left:16px\">③비공무원과 공무원 공모 수수시 수수자별 관련성 달리 볼 수 있으면 금품마다 관련성 따져 뇌물성 인정이 책임주의 부합 <span class=\"cs-fact-tag\">[장래 담당 직무 대가]</span> 장래 담당 직무 대가로 이익 수수도 수수죄 성립하나, 수수 당시 장래 직무 관련성 확인 불가할 정도로 막연·추상적이거나 관련 직무권한 행사할지 자체 알 수 없으면 장래 직무 관련 수수로 단정 곤란 <span class=\"cs-fact-tag\">[의례·친분]</span> 직무 대상자로부터 금품 등 받아도 사회상규상 의례상 대가 불과하거나 개인적 친분관계로 교분상 필요 등 특별사정 없는 한 직무관련성 없다고 볼 수 X<span class=\"cs-exam\">【변18】</span> <span class=\"cs-fact-tag\">[사교적 의례]</span> 직무 관련 금품수수면 사교적 의례 형식 빌렸어도 그 수수금품은 뇌물<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변18】</span></div><div class=\"cs-h\">Ⅳ. 수수·요구·약속</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 뇌물수수죄는 직무 관해 뇌물 수수하면 성립, 별도로 뇌물 요구·약속 있어야 하는 것 아님</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[사실상 처분권]</span> 수수 = 뇌물 취득 '취득' = 뇌물에 대한 사실상 처분권 획득 의미, 법률상 소유권까지 취득 要 X 소유권 취득요건 못 갖춰도 점유 취득하고 공여자·소유자로부터 반환 요구받지 않는 관계 이르면 실질적 사용·처분권한 가져 그 물건 자체를 뇌물로 받은 것 <span class=\"cs-fact-tag\">[영득의사]</span> 뇌물수수 = 영득의사로 금품수수 <span class=\"cs-fact-tag\">[약속]</span> 뇌물약속죄 목적물 이익은 약속당시 현존 不要, 예기할 수 있으면 무방, 목적물이 이익인 경우 가액 확정 안돼도 본죄 성립 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[소유권이전 형식 유보]</span> 수수자가 실질적 사용·처분권한 취득했으나 수수 사실 은닉/공여자 계속 비용부담 위해 소유권이전 형식적 요건 유보시 소유권 이전받은 경우와 다르지 않아 뇌물로 받은 것 → 영득의사 인정<span class=\"cs-exam\">【변사22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[자동차]</span> 자동차 뇌물 제공시 등록원부에 수수자가 소유자 등록 안돼도 사실상 소유자로서 실질적 사용·처분권한 있으면 자동차 자체를 뇌물로 취득<span class=\"cs-exam\">【변21】</span><span class=\"cs-exam\">【변사22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[반환액수 예상초과]</span> 피고인이 먼저 뇌물 요구해 증뢰자 제공 돈 받으면 받은 돈 전부 영득의사 인정, 예상보다 너무 많은 액수여서 후에 반환해도 뇌물죄 성립 영향 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">뇌물임 모르고 수수했다 알고 즉시 반환, 증뢰자 일방적으로 두고 가 후일 반환의사로 부득이 일시 보관하다 반환 등 영득의사 없으면 수수<span class=\"cs-o\"><strong>(X)</strong></span>, 일단 영득의사로 수령하면 후 반환해도 성립 영향 X<span class=\"cs-exam\">【변26】</span></div>", ["§129", "§131", "제129조", "제130조"], 3, "gak_국가공무원"], ["국가006", "특정범죄 가중처벌 등에 관한 법률", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\">특정범죄 가중처벌 등에 관한 법률 제2조(뇌물죄의 가중처벌)</div><div class=\"cs-li\" style=\"margin-left:0px\">① 「형법」 제129조·제130조 또는 제132조에 규정된 죄를 범한 사람은 그 수수·요구 또는 약속한 뇌물의 가액(이하 '수뢰액')에 따라 다음 각 호와 같이 가중처벌한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">1<span>.</span> 수뢰액이 1억원 이상인 경우에는 무기 또는 10년 이상의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">2<span>.</span> 수뢰액이 5천만원 이상 1억원 미만인 경우에는 7년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">3<span>.</span> 수뢰액이 3천만원 이상 5천만원 미만인 경우에는 5년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제3조(알선수재)</strong></span> 공무원의 직무에 속한 사항의 알선에 관하여 금품이나 이익을 수수·요구 또는 약속한 사람은 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 특가법 <span class=\"cs-stat\">제2조</span> 가중처벌 규정</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[규정]</span> <span class=\"cs-stat\"><strong>§129</strong></span>(수뢰, 사전수뢰), <span class=\"cs-stat\"><strong>§130</strong></span>(제삼자뇌물제공), <span class=\"cs-stat\"><strong>§132</strong></span>(알선수뢰)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">인정자료: 특가법상 뇌물죄 수뢰액은 '범죄구성요건' → '엄격한 증명' 대상 <span class=\"cs-fact-tag\">[수수·요구·약속한 수뢰액이 3,000만원 이상인 경우]</span><span class=\"cs-exam\">【변26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[수뢰후부정처사죄O]</span> <span class=\"cs-stat\"><strong>§131</strong></span>① 공무원 등이 <span class=\"cs-stat\"><strong>§129</strong></span>·<span class=\"cs-stat\"><strong>§130</strong></span> 죄 범한 후 부정행위한 때 가중처벌 규정 → 수뢰후부정처사죄 범한 자에게 특가법 <span class=\"cs-stat\"><strong>§2</strong></span>① 적용<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변사21, 모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-neg-tag\">[뇌물공여X]</span> 뇌물공여죄·증뢰물전달죄에는 특가법 적용<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·18】</span></div><div class=\"cs-h\">Ⅱ. 특가법위반(알선수재)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 특가법 <span class=\"cs-stat\"><strong>§3</strong></span> '알선' = 일정 사항 관하여 어떤 사람과 상대방 사이에 서서 중개·편의 도모하는 것 → 공무원 직무 속하는 일정 사항 관하여 당사자 의사를 공무원 측에 전달/편의 도모하는 행위, 또는 공무원 직무 관하여 부탁·영향력 행사해 당사자 원하는 방향으로 결정되도록 돕는 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 알선수재죄의 공무원 직무는 정당한 직무행위인 경우도 포함, 알선 상대방 공무원·직무내용 구체적 특정 不要 알선 명목으로 금품 받으면 실제 어떤 구체적 알선행위 하였는지 상관없이 성립 특가법 <span class=\"cs-stat\"><strong>§3</strong></span>은 행위주체를 비공무원으로 제한 안 함 → '공무원이 그 직위 이용해' 다른 공무원 직무 속한 사항 알선 관해 뇌물 수수·요구·약속시, <span class=\"cs-stat\"><strong>§2</strong></span> 가중처벌 경우 이외에는 <span class=\"cs-stat\"><strong>§3</strong></span> 적용 <span class=\"cs-fact-tag\">[3,000만원 이상: 특가법 </span><span class=\"cs-stat\">§2</span><span class=\"cs-fact-tag\">·형법 </span><span class=\"cs-stat\">§132</span><span class=\"cs-fact-tag\">(알선수뢰) 적용 / 3,000만원 미만: 특가법 </span><span class=\"cs-stat\">§3</span><span class=\"cs-fact-tag\">(알선수재) 적용]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 공무원 직무 속하는 사항 알선과 수수 금품 사이 '전체적·포괄적 대가관계' 있으면 족함 알선수재죄 성립은 당사자 붙인 계약 명칭·형식에 구애 X, 계약 '실질'에 따라 신중 판단</div>", ["§129", "§130", "§132", "§131", "§2", "§3", "제2조", "제129조"], 2, "gak_국가공무원"], ["국가007", "뇌물수수죄와 제3자뇌물수수죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] A군 군수 甲·사채업자 乙 공모, 건설업자 丙에 지원요구</strong></u> <span class=\"cs-exam\">【변사22】 </span><span class=\"cs-o\">(22)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">A군(郡) 군수 甲, 사채업자 乙과 공모해 관내 건설업자 丙에게 금전적 지원을 요구하기로 함. 甲은 丙을 군수집무실로 불러 A군이 둘레길 조성사업을 계획 중이고 丙에게 좋은 기회가 될 것이라며 乙이 향후 그 사업에 관여할 것이니 업무용 차량과 필요 비품을 지원해 주라고 부탁 → 丙이 乙에게 자기 소유 시가 3,000만 원 K5 승용차를 주고 시가 1,000만 원 비품을 구매해 줌. 소유권이전 등록은 해 주지 않았으나 丙은 반환받을 마음이 없었고 乙도 반환할 생각이 없었음.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲, 乙, 丙의 죄책은? (22점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [뇌물수수죄와 제3자뇌물수수죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 뇌물 = 직무에 관한 부당한 이익 내지 불법한 보수</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공무원 甲이 乙과 '공모'하고 甲이 丙에게 지원을 부탁, 乙이 이를 받음 → 공동정범(<span class=\"cs-stat\"><strong>제30조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 공무원과 공동정범 관계에 있는 비공무원은 제3자뇌물수수죄의 '제3자'(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲 = 제3자뇌물수수죄(<span class=\"cs-stat\"><strong>제130조</strong></span>)(X) → 뇌물수수죄(<span class=\"cs-stat\"><strong>제129조</strong></span> 제1항)의 공동정범</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [특가법의 적용여부]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 수수 = 뇌물에 대한 사실상의 처분권 획득</div><div class=\"cs-li\" style=\"margin-left:0px\">② 법률상 소유권 취득 요건을 갖추지 않았어도 점유를 취득하고 공여자에게서 반환을 요구받지 않는 관계에 이르면 실질적 사용·처분권한을 가져 물건 자체를 뇌물로 받은 것</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 소유권이전등록은 없었으나 丙·乙 모두 반환 의사(X) → 甲·乙은 시가 3,000만 원 K5 승용차의 사실상 처분권 획득</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 시가 3,000만 원 자동차 + 1,000만 원 비품 → 수수한 뇌물 가액(이득액) 4,000만 원</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [결론] 甲 = 특가법위반(뇌물)죄(특가법 <span class=\"cs-stat\"><strong>제2조</strong></span> 제1항 제3호)의 공동정범</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [乙의 죄책]</strong> 비신분자가 진정신분범에 가담 → <span class=\"cs-stat\"><strong>제33조</strong></span> 본문 적용 → 乙도 특가법위반(뇌물)죄의 공동정범</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 뇌물공여죄에는 특가법 <span class=\"cs-stat\"><strong>제2조</strong></span> 제1항 적용(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙 = 뇌물공여죄(<span class=\"cs-stat\"><strong>제133조</strong></span> 제1항) <span class=\"cs-crime\">!-- 교정: 원문 '乙은 뇌물공여죄' → 문맥상 '丙은' --</span></div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲·乙 = 특가법위반(뇌물)죄의 공동정범, 丙 = 뇌물공여죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제133조(뇌물공여 등)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 제129조부터 제132조까지에 기재한 뇌물을 약속, 공여 또는 공여의 의사를 표시한 자는 5년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 행위에 제공할 목적으로 제3자에게 금품을 교부한 자 또는 그 사정을 알면서 금품을 교부받은 제3자도 제1항의 형에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 뇌물수수·요구·약속죄 (<span class=\"cs-stat\">§129</span>①)</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공무원이 직접 받은 것으로 평가되는 경우</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[사자·대리인 등]</span> 공무원이 증뢰자로 하여금 다른 사람에게 뇌물 공여하도록 한 경우라도, 그 다른 사람이 공무원의 사자·대리인으로서 받거나, 평소 공무원이 그 다른 사람 생활비 등 부담/그에 대해 채무 부담해 그 다른 사람이 뇌물 받음으로써 공무원이 그만큼 지출 면하는 등 사회통념상 공무원이 직접 받은 것과 같이 평가할 관계면 <span class=\"cs-stat\"><strong>§129</strong></span>① 단순수뢰죄 성립<span class=\"cs-exam\">【변18·12】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[실질 장악 컨설팅회사]</span> 공무원이 건설회사·컨설팅회사 간 용역계약 가장하여 건설회사들로부터 뇌물수수하는 과정에서 건설회사들이 형식적 용역계약 상대방 컨설팅회사 계좌로 뇌물 입금한 것은 사회통념상 피고인에게 직접 공여한 것과 동일 평가 <span class=\"cs-fact-tag\">[공무원이 실질적으로 장악한 컨설팅회사]</span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>뇌물수수죄의 공동정범</strong> 판단기준 (判例) : 공무원과 '공동정범' 관계 비공무원은 제3자뇌물수수죄 제3자 될 수 X, 공동정범 비공무원이 뇌물 받으면 공무원과 함께 뇌물수수죄 공동정범 성립 ·제3자뇌물수수죄 성립<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[비공무원에게 </span><span class=\"cs-stat\">§33</span><span class=\"cs-fact-tag\"> 본문 적용]</span><span class=\"cs-exam\">【변24·22】</span><span class=\"cs-exam\">【변사22】</span> 공무원·비공무원이 사전에 뇌물을 비공무원에게 귀속시키기로 모의 /성질상 비공무원이 사용·소비할 것이라 해도, 이는 공동정범 성립 후 뇌물처리에 관한 것 불과 → 뇌물수수죄 성립 영향 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[수뢰액 합산]</span> 수인이 공동으로 뇌물수수죄 범하면 공범자는 자기 수뢰액뿐 아니라 다른 공범자 수뢰액도 죄책 면할 수 없음 → 특가법 <span class=\"cs-stat\"><strong>§2</strong></span>① 적용 수뢰액은 공범 전원 수뢰액 합한 금액 기준, 각자 실제 취득/분배받기로 한 금액 기준 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공모공동정범]</span> 공모내용 따라 공범 중 1인이 금품·이익 수수시, 사전 특정금액 이하로만 받기로 약정/공모 과정에서 도저히 예상불가 고액 등 특별사정 없는 한 그 수수금품·이익 전부에 특가법위반(뇌물)죄 또는 뇌물수수죄 공모공동정범 성립, 규모·정도 사전 의사연락 있거나 구체적 금액 알아야 공모공동정범 성립하는 것 아님<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅱ. 제3자뇌물수수·요구·약속죄 (<span class=\"cs-stat\">§130</span>) – 부정한 청탁</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>제3자</strong> 적용범위: 제3자뇌물수수죄에서 뇌물 받는 제3자가 뇌물임을 인식할 것을 요건으로 하지 않음 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[교사·방조자 포함]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①'제3자' = 행위자와 공동정범 이외의 사람, 교사자·방조자도 포함</div><div class=\"cs-li\" style=\"margin-left:48px\">②공무원·중재인이 부정한 청탁 받고 제3자에게 뇌물 제공하게 하고 '제3자'가 그 범죄행위를 '알면서 방조'한 경우, 별도 처벌규정 없어도 방조범 형법총칙 규정 적용되어 제3자뇌물수수방조죄 인정 가능<span class=\"cs-exam\">【변25·22·20】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[지자체]</span> 공무원인 지자체장이 직무 관해 부정한 청탁 받고 지자체에 금품 제공하게 했다면 기부채납 재산 취득한 지자체는 '제3자뇌물제공죄'의 '제3자' 될 수 있음</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>부정한 청탁</strong> 개념: 제3자뇌물수수죄 뇌물 = 공무원 직무 관하여 '부정한 청탁' 매개로 제3자에게 교부되는 위법·부당한 이익, <span class=\"cs-stat\"><strong>§129</strong></span> 뇌물죄와 마찬가지로 직무관련성 있으면 인정 '부정한 청탁' = 청탁이 위법·부당한 직무집행을 내용으로 하는 경우는 물론, 청탁 대상 직무집행 자체는 '위법·부당하지 않더라도' 직무집행을 대가관계와 연결시켜 직무집행에 관한 대가 교부를 내용으로 하는 경우도 포함 판단기준 (判例) : 청탁 대상 직무행위 내용 구체적 특정 不要 부정한 청탁 내용은 공무원 직무와 제3자에게 제공되는 이익 사이 대가관계 인정할 정도로 특정하면 충분, 이미 발생한 현안뿐 아니라 장래 발생 예상 현안도 부정한 청탁 내용 될 수 있음</div>", ["§129", "§33", "§2", "§130", "제30조", "제130조", "제129조", "제2조"], 3, "gak_국가공무원"], ["국가008", "뇌물공여죄와 증뢰물전달죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 전달자가 교부금 중 일부만 전달·나머지 임의소비</strong></u> <span class=\"cs-exam\">【변사25】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">乙, 살인미수 사건으로 수사를 받게 되자 사법경찰관 P1에게 금품을 주어 형사처벌을 면하기로 하고, 자금 마련을 위해 친구 B에게 딸의 수술비 명목인 것처럼 말해 3천만 원 차용. P1과 친분이 있는 丙에게 사정을 말하고 그 3천만 원을 주며 P1에게 전해 달라 부탁 → 동의한 丙이 그중</div><div class=\"cs-li\" style=\"margin-left:0px\">2천만 원을 임의 소비하고 나머지만 P1에게 전달. 乙과 丙의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [사기죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 차용금의 '용도'를 사실대로 고지했다면 빌려주지 않았을 것이라면 용도를 기망한 경우에도 사기죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 실제는 뇌물 자금인데 딸 수술비 명목으로 기망해 3천만 원 차용, B가 알았다면 빌려주지 않았을 것 → 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [제3자뇌물교부죄 또는 뇌물공여죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 제3자가 실제로 공무원에게 전달한 경우 — 제3자뇌물교부죄만 성립설 / 뇌물공여죄에 흡수되어 뇌물공여죄만 성립설. 뇌물공여죄만 성립한다는 고등법원 판례만 있고 대법원 판례(X). 실제 전달했다면 증뢰자는 전달자에 대한 교부를 넘어 수뢰자에게 공여한 것 → 뇌물공여죄만 성립한다는 견해 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙 = 丙이 실제 전달한 1,000만 원 → 뇌물공여죄(<span class=\"cs-stat\"><strong>제133조</strong></span> 제1항), 전달하지 않은 2,000만 원 → 제3자뇌물교부죄(<span class=\"cs-stat\"><strong>제133조</strong></span> 제2항), 양죄는 상상적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [제3자뇌물취득죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 제3자가 교부받은 금품을 수뢰자에게 전달했는지와 관계없이 정을 알면서 교부받으면 제3자뇌물취득죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 전달했다고 해서 증뢰물전달죄 외에 별도로 뇌물공여죄가 성립하는 것(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 丙 = 3,000만 원에 대한 제3자뇌물취득죄(<span class=\"cs-stat\"><strong>제133조</strong></span> 제2항)만, 뇌물공여죄는 별도 성립(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [장물보관죄 또는 장물운반죄] 乙이 B에게서 편취한 장물임을 알면서 교부받아 보관하거나 뇌물로 전달 → 2,000만 원 장물보관죄 + 1,000만 원 장물운반죄의 상상적 경합(<span class=\"cs-stat\"><strong>제362조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [乙에 대한 횡령죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 불법원인급여물에도 횡령죄가 성립하는지 — 긍정설/부정설/절충설, 판례 = \"뇌물공여 목적으로 전달해 달라고 교부받은 금전은 민법 <span class=\"cs-stat\"><strong>제746조</strong></span>의 불법원인급여물로 소유권이 상대방에게 귀속 → 임의 소비해도 횡령죄(X)\" 원칙적 부정설</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙에게 乙에 대한 횡령죄(<span class=\"cs-stat\"><strong>제355조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(라) [B에 대한 횡령죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 장물보관죄가 성립하면 이미 소유물 추구권을 침해 → 이후 횡령행위는 불가벌적 사후행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 장물을 임의 소비해도 B에 대한 횡령죄는 별도 성립(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 乙 = 제3자뇌물교부죄(2,000만 원) + 뇌물공여죄(1,000만 원)의 상상적 경합, 이들과 사기죄는 실체적 경합</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙 = 제3자뇌물취득죄 + 장물보관죄 + 장물운반죄의 실체적 경합</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 뇌물공여죄와 뇌물수수죄의 관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공여의 성립요건]</span> 뇌물 공여행위+상대방 수령행위(부작위 포함)면 족, 반드시 상대방에 뇌물수수죄 성립 要 X<span class=\"cs-exam\">【변21·19·18·12】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[현금 든 굴비상자 제공]</span> 공여죄 성립해도, 뇌물성 인식 없던 상대방에 뇌물수수죄가 반드시 성립하는 것은 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[필요적 공범]</span> 공여죄·수수죄는 필요적 공범이나, 성립엔 행위 공동만 필요·협력자 전부 책임 있을 필요 X<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[함정교사로 공여]</span> 공무원이 직무관련 수수의사로 받아들이면 뇌물수수죄 성립, 공여자의 함정교사 사정은 면책사유 X<span class=\"cs-exam\">【변19】</span></div><div class=\"cs-h\">Ⅱ. 공여자 – 제3자뇌물'교부'죄<span class=\"cs-exam\">【변사25·21·19·12, 모사26·22·20·17·13】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>전달하지 않은 경우</strong> 적용범위: <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§133</span><span class=\"cs-fact-tag\">②]</span> 증뢰자가 뇌물 공할 목적으로 제3자에게 교부 or 그 정 알면서 교부받는 증뢰물전달행위 = 독립 구성요건, <span class=\"cs-stat\"><strong>§133</strong></span>①과 동일 형 처벌 <span class=\"cs-fact-tag\">[제3자가 실제 전달 안 해도 증뢰자에게 제3자뇌물교부죄 성립]</span> <span class=\"cs-fact-tag\">[이미 공무원에 공여 의사표시·약속 후 제3자에 교부]</span> 공여자에게 뇌물공여약속죄 등만 성립(흡수관계)</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>전달한 경우</strong> 判例(죄수관계): <span class=\"cs-fact-tag\">[제3자가 실제 전달]</span> 제3자뇌물교부 범행이 뇌물공여 범행에 흡수 → 뇌물공여죄만 성립 <span class=\"cs-issue\">《교부금 중 일부만 전달한 경우 교부자의 죄책》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>: <span class=\"cs-fact-tag\">[교부금 중 일부만 전달]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①교부자에 제3자뇌물교부죄만</div><div class=\"cs-li\" style=\"margin-left:16px\">②실제 전달분은 뇌물공여죄(<span class=\"cs-stat\"><strong>§133</strong></span>①)·미전달분은 제3자뇌물교부죄(<span class=\"cs-stat\"><strong>§133</strong></span>②) 각 성립+상상적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 실제 전달했다면 전달자 교부 넘어 수뢰자에 공여한 것 → 뇌물공여죄만 성립 타당</div></div><div class=\"cs-h\">Ⅲ. 전달자 – 제3자뇌물'취득'죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>제3자뇌물취득죄 (전달 무관)<span class=\"cs-exam\">【변사25·21·19·12, 모사25·22·20·17·13】</span></strong> 적용범위: <span class=\"cs-fact-tag\">[전달 여부 불문]</span> 증뢰자·수뢰자 아닌 제3자가 정 알면서 금품 교부받음으로써 성립<span class=\"cs-exam\">【변12】</span> <span class=\"cs-fact-tag\">[전달했어도]</span> 증뢰물전달죄 외 별도 뇌물공여죄 성립 X<span class=\"cs-exam\">【변16】</span> <span class=\"cs-fact-tag\">[</span><span class=\"cs-stat\">§133</span><span class=\"cs-fact-tag\">②의 제3자]</span> '공동정범 이외의 자' —</div><div class=\"cs-li\" style=\"margin-left:16px\">①공동정범이면 뇌물공여죄만</div><div class=\"cs-li\" style=\"margin-left:16px\">②공여죄 교사·방조로 볼 수 있어도 제3자뇌물취득죄만 성립</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>제3자가 전달할 의사로 받았으나 임의로 소비한 경우<span class=\"cs-exam\">【변사25·21, 모사25·22 등】</span></strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[불법원인급여와 횡령죄]</span> 뇌물공여·배임증재 목적 교부받은 금전 = 불법원인급여물, 소유권 상대방 귀속 → 전달 않고 임의소비해도 횡령죄<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변26·19·14·12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>제3자가 실제 전달할 의사 없이 기망하여 받은 경우</strong></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: <span class=\"cs-fact-tag\">[사견]</span> 사기죄와 제3자뇌물취득죄 상상적 경합 <span class=\"cs-fact-tag\">[불법원인급여라도 사기죄 성립]</span></div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-fact-tag\">[사기죄 성립 시]</span> 제3자가 임의소비해도 별도 횡령죄 X <span class=\"cs-fact-tag\">[사기죄 실행행위에 불과]</span></div>", ["§133", "제347조", "제133조", "제362조", "제746조", "제355조"], 3, "gak_국가공무원"], ["국가009", "사전수뢰죄, 사후수뢰죄, 수뢰후부정처사죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제131조(수뢰후부정처사, 사후수뢰)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 공무원 또는 중재인이 전2조의 죄를 범하여 부정한 행위를 한 때에는 1년 이상의 유기징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 공무원 또는 중재인이 그 직무상 부정한 행위를 한 후 뇌물을 수수, 요구 또는 약속하거나 제삼자에게 이를 공여하게 하거나 공여를 요구 또는 약속한 때에도 전항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 공무원 또는 중재인이었던 자가 그 재직 중에 청탁을 받고 직무상 부정한 행위를 한 후 뇌물을 수수, 요구 또는 약속한 때에는 5년 이하의 징역 또는 10년 이하의 자격정지에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 사전뇌물수수죄 (사전수뢰죄) (<span class=\"cs-stat\">§129</span>②)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[개념]</span> 공무원·중재인 될 자가 담당할 직무에 관해 청탁받고 뇌물 수수·요구·약속 후 '공무원·중재인이 된 때' 처벌 <span class=\"cs-fact-tag\">[became時=객관적 처벌조건, 고의 인식대상 X]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">성립요건: <span class=\"cs-fact-tag\">[청탁 요건]</span> 직무행위가 부정한 것인지 묻지 X, 청탁이 반드시 명시적일 필요도 X</div><div class=\"cs-h\">Ⅱ. 수뢰후부정처사죄 (<span class=\"cs-stat\">§131</span>①)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[부정행위 시점]</span> 뇌물수수 완료 이후일 필요 X, 수수 중 부정행위 한 경우도 포함 — 단일·계속된 범의로 반복된 일련의 수수·부정행위에 인과관계·피해법익 동일하면 최후 부정행위 이후 수수도 포괄일죄 처벌<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[도박장개설·범행 묵인 사례비 수수]</span> 경찰관 직무위배 부정행위<span class=\"cs-o\"><strong>(O)</strong></span>, 원주경찰서 교통계 근무·구체적 수사사무 미담당이라도 마찬가지 <span class=\"cs-fact-tag\">[직무유기죄와 상상적 경합]</span><span class=\"cs-exam\">【변14】</span></div>", ["§129", "§131", "제131조"], 1, "gak_국가공무원"], ["국가010", "알선뇌물수수(요구·약속)죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제132조(알선수뢰)</strong></span> 공무원이 그 지위를 이용하여 다른 공무원의 직무에 속한 사항의 알선에 관하여 뇌물을 수수, 요구 또는 약속한 때에는 3년 이하의 징역 또는 7년 이하의 자격정지에 처한다.</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">['지위를 이용하여']</span> 친구·친족 등 사적 관계 이용 or 단순 공무원 신분 이용은 해당 X, 다른 공무원 업무처리에 법률상·사실상 영향 줄 수 있는 공무원이 지위 이용하면 해당<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span> <span class=\"cs-fact-tag\">['지위 이용'의 범위]</span> 다른 공무원 사무처리에 영향 줄 관계면 족, 반드시 상하·협동·감독 등 특수 지위 要 X <span class=\"cs-fact-tag\">['알선행위']</span> 그 공무원 직무에 속하는 사항에 관한 것이면 족, 반드시 부정행위이거나 결재·최종결정권한 있어야 하는 것 X <span class=\"cs-fact-tag\">[특정 요부·기대감]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①알선 상대방·직무내용 구체적 특정 필요까지는 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②알선행위 장래의 것도 무방·현안 존재 不要하나, 뇌물수수 명목이 그 사항 알선 관련됨이 어느 정도 구체적으로 나타나야 함</div><div class=\"cs-li\" style=\"margin-left:16px\">③단순히 잘 보이면 도움·손해 없으리란 막연한 기대감 정도에 불과하면 알선뇌물수수죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22】</span></div>", ["제132조"], 1, "gak_국가공무원"], ["국가011", "뇌물죄의 죄수관계", "<details class=\"cs-case\"><summary><u><strong>[CASE(1)] 위반사실 없는데 발견됐다 속여 금품 수수 (사기+뇌물)</strong></u> <span class=\"cs-o\">(10)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">안남구청 건축과 공무원 甲, 빚이 많자 관할 구역 건축업자 乙에게 실제로는 위반사실이 발견되지 않았는데도 \"건축법 위반사실이 발견되어 확인 중이다. 3,000만 원을 주면 시장에게 위법이 확인되지 않았다고 보고해 아무 일 없게 해주겠다\"고 속여 3,000만 원 수령. 甲, 乙의 죄책은? (10점) [CASE(2)] 위반사실 이용 협박해 금품 수수·보고할 의사 없음 (공갈) 사채업자의 빚독촉에 시달리던 甲, 관할 구역에서 건축법을 위반한 건축업자 丙에게 \"위반사실이 발견되었는데 1,000만 원을 주지 않으면 시장에게 보고해 건축업을 못하게 하겠다\"고 겁을 주어 1,000만 원 수령. 그러나 甲은 애초에 시장에게 보고할 생각이 없었음.</div><div class=\"cs-li\" style=\"margin-left:0px\">甲, 丙의 죄책은? (10점) [직무유기의 점은 논외로 함]</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [사기죄] 위반사실이 없는데 발견되었다고 속여 乙에게서 3,000만 원 수령 → 사기죄(<span class=\"cs-stat\"><strong>제347조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [특가법위반(뇌물)]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원이 수수한 뇌물 가액이 3,000만 원 이상이면 특가법위반(뇌물)죄(특가법 <span class=\"cs-stat\"><strong>제2조</strong></span> 제1항 제3호, 형법 <span class=\"cs-stat\"><strong>제129조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 뇌물 수수 시 공여자를 기망한 점이 있어도 뇌물수수죄·뇌물공여죄 성립에 영향(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲은 직무에 관해 3,000만 원의 뇌물 수수 → 특가법위반(뇌물)죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [乙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 甲의 직무에 관해 3,000만 원 공여 → 뇌물공여죄(<span class=\"cs-stat\"><strong>제133조</strong></span> 제1항)(O). 甲이 기망했어도 마찬가지</div><div class=\"cs-li\" style=\"margin-left:0px\">② 뇌물공여죄에는 특가법 적용(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 특가법위반(뇌물)죄 + 사기죄의 상상적 경합, 乙 = 뇌물공여죄 (모범답안 - CASE(2))</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [甲의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [공갈죄] 丙의 건축법 위반사실을 이용해 건축업을 못하게 하겠다고 협박, 겁먹은 丙에게서 1,000만 원 수령 → 공갈죄(<span class=\"cs-stat\"><strong>제350조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [뇌물수수죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원이 상대방을 공갈해 재물을 교부받은 경우 공갈죄 외에 뇌물수수죄가 성립하는지 — 직무집행의사 + 직무집행의 대가관계가 모두 있어야 한다는 견해(다수설) / 대가관계만 있으면 직무집행의사와 무관하게 성립한다는 견해. 판례 = \"공무원이 직무집행의 의사 없이 또는 직무처리와 대가적 관계없이 타인을 공갈하여 재물을 교부하게 한 경우에는 공갈죄만 성립\". 직무집행의사가 없다면 단지 상대방을 공갈한 것에 불과 → 판례 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲은 보고할 생각이 없어 직무집행 의사(X) → 뇌물수수죄(<span class=\"cs-stat\"><strong>제129조</strong></span> 제1항)(X), 공갈죄만 성립</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무원에게 공갈죄만 성립하면 재물 교부자는 공갈죄의 피해자일 뿐 뇌물공여죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 甲에게 직무집행의사가 없어 공갈죄만 성립 → 丙은 공갈죄의 피해자에 불과, 뇌물공여죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲 = 공갈죄, 丙 = 아무런 죄책도 지지 않음 <span class=\"cs-crime\">!-- 교정: 원문 \"乙은 아무런 죄책\" → 丙 오기 --</span></div></div></details></div></details><div class=\"cs-h\">Ⅰ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[국가자금 횡령금을 공범끼리 분배 수수]</span> 공동정범 취득금 내부 분배에 지나지 않으면 그 수수에 별도 뇌물죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변22·23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[직무상 지득 구술시험 문제 유상 유출]</span> 공무상비밀누설인 동시에 <span class=\"cs-stat\"><strong>§131</strong></span>① 부정행위 <span class=\"cs-fact-tag\">[수뢰후부정처사죄와 공무상비밀누설죄 상상적 경합]</span><span class=\"cs-exam\">【변26·17】</span><span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공무원 의사가 부탁받고 허위진단서 작성·대가 수수]</span> 허위공문서작성죄와 부정처사후수뢰죄 실체적 경합</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공여 거절 후 수개월 뒤 다른 명목 공여]</span> 뇌물공여의사표시가 뇌물공여에 흡수<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[직무관련자에 제3자와 계약체결 요구]</span> 제3자뇌물수수죄와 직권남용권리행사방해죄 상상적 경합<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-h\">Ⅱ. 뇌물범죄와 사기죄 (상상적 경합)<span class=\"cs-exam\">【모사19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공여자 기망하여 수수]</span> 기망해도 뇌물수수죄·공여죄 성립 영향 X, 수수 공무원은 한 행위가 뇌물수수죄·사기죄 각 해당 → <span class=\"cs-stat\"><strong>§40</strong></span> 상상적 경합<span class=\"cs-exam\">【변24·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[청탁·알선 의사·능력 없이 기망 금품수수]</span> 사기죄와 변호사법위반죄 상상적 경합<span class=\"cs-exam\">【변21·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[알선수재]</span> 특가법위반(알선수재)죄(<span class=\"cs-stat\"><strong>§3</strong></span>), 특경법위반(알선수재)도 사기죄와 각 상상적 경합</div><div class=\"cs-h\">Ⅲ. 뇌물수수죄와 공갈죄<span class=\"cs-exam\">【모사21·19·16·14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공무원의 죄책</strong> <span class=\"cs-issue\">《공무원이 상대방 공갈하여 재물 교부받은 경우 공갈죄 외 뇌물수수죄 성립 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①직무집행의사+직무집행 대가관계 모두 있어야 뇌물수수죄 성립(다수설)</div><div class=\"cs-li\" style=\"margin-left:16px\">②직무행위 대가관계만 있으면 직무집행의사 무관하게 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[공갈죄만]</span> 공무원이 '직무집행 의사 없이' or '직무처리와 대가적 관계없이' 공갈하여 교부하게 한 경우 공갈죄만 성립<span class=\"cs-exam\">【변20·17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 직무집행의사 없으면 단지 공갈에 불과 → 공갈죄만 성립 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[TIP]</span> 양죄 모두 성립 시 — 형법상 뇌물수수죄가 공갈죄보다 형 낮으나 특가법 적용시 더 높고, 뇌물수수죄는 필요적 몰수·추징규정 있어 상상적 경합관계 견해 일반적</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[직무집행 '빙자'하여 갈취]</span> 공갈죄만 성립<span class=\"cs-exam\">【변12】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공여자의 죄책</strong> 가. <strong>공무원에게 '공갈죄만' 성립하는 경우 (뇌물공여죄 불성립)</strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[뇌물공여죄X]</span> 공무원이 직무집행 의사 없이·대가적 관계없이 공갈하여 교부하게 한 경우 공갈죄만 성립, 교부자가 해악 고지로 외포되어 금품 제공한 것이면 공갈죄 피해자 → 뇌물공여죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변17】</span> 나. <strong>공무원에게 뇌물수수죄와 공갈죄가 '모두' 성립하는 경우</strong></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①공갈죄 피해자로 마지못해 공여 → 뇌물공여죄 성립 X(부정설)</div><div class=\"cs-li\" style=\"margin-left:16px\">②피해자라도 공여 의사 있으면 뇌물공여죄 성립(긍정설)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 피해자이나 공무원 직무행위 매수 의사로 제공 → 뇌물공여죄 성립(긍정설) 타당</div></div>", ["§131", "§40", "§3", "제347조", "제2조", "제129조", "제133조", "제350조"], 3, "gak_국가공무원"], ["국가012", "공무집행방해죄", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <u><strong>[CASE1] 음주운전 발진조작 미완료·위법 현행범체포에 대한 상해</strong></u> <span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲, 술을 마신 뒤 귀가하려 술집 주차장에서 시동을 걸고 오토기어를 후진(R)으로 조작해 출발하려다 지나가던 A와 시비가 붙어 주브레이크에서 발을 떼지 못하고 기어를 (P)로 옮긴 뒤 시동을 끔. A가 30분 이상 지나 음주운전으로 신고 → 출동한 경찰관 P1이 적법하게 측정하니 혈중알코올농도 0.10% → P1이 음주운전 현행범으로 체포하려 하자(미란다원칙 고지 등 절차 위법</div><div class=\"cs-li\" style=\"margin-left:0px\">없음) 甲이 P1의 얼굴을 주먹으로 세게 때려 상해. 甲의 죄책은? (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [도교법위반(음주운전)죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 도교법 <span class=\"cs-stat\"><strong>§148의2</strong></span>③2호, <span class=\"cs-stat\"><strong>§44</strong></span>①</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자동차를 '그 본래의 사용방법'에 따라 사용했다고 하려면 엔진 시동만으로는 부족하고 발진조작의 완료 要</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 시동·기어 조작은 했으나 주브레이크에서 발을 떼는 등 제동장치 해제 조치(X) → 발진조작 완료(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 甲에게 도교법위반(음주운전)죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [공무집행방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무집행방해죄(<span class=\"cs-stat\"><strong>§136</strong></span>①)는 직무집행이 적법한 경우에 한해 성립 → 위법하면 '구성요건' 불충족</div><div class=\"cs-li\" style=\"margin-left:0px\">② 현행범인 = 범죄를 실행 중이거나 실행하고 난 직후의 사람, 누구든 영장 없이 체포 가능 (형소법 <span class=\"cs-stat\"><strong>§211</strong></span>, <span class=\"cs-stat\"><strong>§212</strong></span>). '실행하고 난 직후의 사람' = 실행행위를 종료한 직후의 범인임이 체포하는 자의 입장에서 명백한 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 체포 당시 운전 추정 시점에서 이미 30분 이상 경과 + 운전 여부도 불분명 → 현행범 체포 위법</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 공무집행이 위법 → 구성요건 해당(X) → 甲에게 공무집행방해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [상해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 위법한 현행범 체포에 저항해 경찰관에게 상해를 가함 → 정당방위로 위법성 조각</div><div class=\"cs-li\" style=\"margin-left:0px\">② 상해죄(<span class=\"cs-stat\"><strong>§257</strong></span>①) 구성요건 해당(O)이나 정당방위(<span class=\"cs-stat\"><strong>§21</strong></span>①)로 위법성 조각</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 甲에게 상해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [결론]</strong> 甲 = 어떠한 죄책도 지지 않음</div></div></details></div></details><details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <u><strong>[CASE2] 적법한 직무집행을 위법하다 오인·경찰관 폭행</strong></u> <span class=\"cs-exam\">【변사25】 </span><span class=\"cs-o\">(20)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">택시로 귀가하던 甲, 도착지에서 기사 丙과 과다 요금으로 시비 → 丙이 경찰 신고 → 출동한 경찰관 P가 당사자끼리 원만히 해결하라 조언 → 丙은 P가 편파적이라며 甲을 파출소로 연행하라 항의, 받아들여질 기미가 없자 P의 직무집행이 위법하다고 생각하며 P를 밀어 넘어뜨림. 공무집행방해죄의 성립요건 중 '직무집행의 적법성'의 범죄 체계상 지위에 관한 각 견해를 서술하고</div><div class=\"cs-li\" style=\"margin-left:0px\">그에 따른 丙의 죄책을 논하시오(단, P의 직무집행은 적법하다고 전제함). (20점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [문제점]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 공무집행방해죄(<span class=\"cs-stat\"><strong>§136</strong></span>①)는 공무원의 적법한 공무집행이 전제</div><div class=\"cs-li\" style=\"margin-left:0px\">② P는 '적법하게' 집행했으나 丙은 위법하다고 생각하고 밀었음 → 적법성 착오의 법적효과가 문제</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [직무집행의 적법성의 체계적 지위]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 구성요건요소설/위법성요소설/처벌조건설</div><div class=\"cs-li\" style=\"margin-left:0px\">② 판례 = 구성요건요소설</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 적법한 공무집행을 요건으로 하므로 구성요건요소설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [적법성 착오의 효과]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 적법한 공무집행을 위법하다고 착오한 경우 — 구성요건요소설에서 사실의 착오로 고의 조각설 / 구성요건요소설에서 적법성 자체의 착오는 법률의 착오이고 적법성의 기초사실(행위사정) 착오는 사실의 착오로 고의 조각설 / 위법성요소설에서 법률의 착오설 또는 위법성조각사유의 전제사실의 착오설 / 처벌조건설에서 범죄 성립과 무관설</div><div class=\"cs-li\" style=\"margin-left:0px\">② 판례 = 직무행위의 '적법성 자체에 관한 착오'는 법률의 착오</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 일률적으로 평가할 것이 아니라 구성요건요소설에서 적법성에 관한 착오는 법률의 착오 (정당한 이유 논점), 그 기초사실(행위사정)에 관한 착오는 사실의 착오로 봄이 타당</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(4) [법률의 착오와 정당한 이유]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 법령에 의해 죄가 되지 않는 것으로 오인한 행위는 그 오인에 정당한 이유가 있는 때에 한해 불벌(<span class=\"cs-stat\"><strong>§16</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">② '정당한 이유' = 위법 가능성에 대해 심사숙고·조회할 계기가 있어 지적능력을 다해 회피하려는 진지한 노력을 다했더라면 위법성을 인식할 가능성이 있었는지로 판단</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 丙은 단순히 위법하다고 생각했을 뿐 심사숙고나 진지한 노력(X) → 정당한 이유(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(5) [각 견해에 따른 결론]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 구성요건요소설 + '사실의 착오'설 → 고의 조각 → 공무집행방해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 구성요건요소설에서 적법성 자체는 법률의 착오·기초사실은 사실의 착오로 보는 견해, 위법성요소설에서 법률의 착오로 보는 견해, 적법성 자체의 착오를 법률의 착오로 보는 판례 → 적법성 자체를 착오했으나 정당한 이유(X) → 공무집행방해죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 위법성요소설에서 위법성조각사유의 전제사실의 착오로 보는 견해 + 그에 관한 판례 → 정당한 이유(X) → 위법성 조각(X) → 공무집행방해죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 처벌조건설 → 공무집행방해죄(O)</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제136조(공무집행방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 직무를 집행하는 공무원에 대하여 폭행 또는 협박한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제144조(특수공무방해)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 단체 또는 다중의 위력을 보이거나 위험한 물건을 휴대하여 제136조, 제138조와 제140조 내지 전조의 죄를 범한 때에는 각조에 정한 형의 2분의 1까지 가중한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 제1항의 죄를 범하여 공무원을 상해에 이르게 한 때에는 3년 이상의 유기징역에 처한다. 사망에 이르게 한 때에는 무기 또는 5년 이상의 징역에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 주체 – 직무를 집행하는 공무원</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>적법한 공무집행</strong> 성립요건: 공무집행방해죄는 적법한 공무집행이 전제 → 적법요건:</div><div class=\"cs-li\" style=\"margin-left:16px\">①행위가 당해 공무원의 추상적 직무권한에 속</div><div class=\"cs-li\" style=\"margin-left:16px\">②구체적으로도 권한 내</div><div class=\"cs-li\" style=\"margin-left:16px\">③직무행위로서 중요한 방식 갖춤 개념: 추상적 권한 반드시 법령에 명시될 필요 X '직무를 집행하는' = 직무수행에 직접 필요한 행위 현실적으로 행하는 때만이 아니라 직무수행 위해 근무 중 상태 포괄 <span class=\"cs-fact-tag\">[소란 피우는 민원인 제지·데리고 나가는 행위도 민원 담당 공무원 직무]</span> 판단기준 (判例) : 추상적 권한 속하는 공무집행의 적법성은 행위 당시 구체적 상황 기초 객관적·합리적 판단, 사후적 순수 객관적 기준 판단 X 공무원이 구체적 상황 비추어 인적·물적 능력 범위 내 적절한 조치라는 판단에 따라 직무수행 → 객관적 정당성 상실·현저히 불합리로 인정되지 않는 한 위법 X 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">[자정 음악 크게·소리 지름 = 경범죄처벌법 <span class=\"cs-stat\"><strong>§3</strong></span>①21호 인근소란, 112신고 출동했으나 문 안 열어주고 소란 안 멈춤→경찰이 집으로 통하는 전기 일시 차단] 집 밖 유도, 범죄 진압·예방·수사 위해 필요·적절, 경직법 <span class=\"cs-stat\"><strong>§6</strong></span> 즉시강제 요건 충족한 적법 직무집행 볼 여지<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>위법한 공무집행의 경우<span class=\"cs-exam\">【모사24·18·16】</span></strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공무집행방해죄]</span> 직무집행이 적법한 경우 한하여 성립, 적법하다 볼 수 없으면 공무집행방해죄 '구성요건' 충족<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[상해죄]</span> 경찰관 현행범 체포가 불법체포로 볼 수밖에 없으면, 현행범이 체포 면하려 반항 중 경찰관에 상해 = 불법체포로 인한 신체 현재 부당 침해 벗어나기 위한 정당방위 → 위법성 조각<span class=\"cs-exam\">【변25·21】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>공무집행방해죄의 적법성의 착오<span class=\"cs-exam\">【변사25, 모사20·14】</span></strong> 가. <strong>적법성의 체계적 지위</strong> <span class=\"cs-issue\">《직무집행 적법성의 체계적 지위》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①구성요건요소설(적법 공무집행에 대해서만 구성요건해당성 인정)</div><div class=\"cs-li\" style=\"margin-left:16px\">②위법성요소설(적법 공무집행에 대해서만 위법성 인정)</div><div class=\"cs-li\" style=\"margin-left:16px\">③처벌조건설(객관적 처벌조건으로 이해)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[구성요건요소설]</span> 적법한 공무집행 볼 수 없으면 구성요건 충족<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 공무집행방해죄는 적법한 공무집행을 요건으로 하므로 구성요건요소설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">나. <strong>적법성 착오의 효과</strong> <span class=\"cs-issue\">《'적법'한 공무집행을 '위법'으로 착오하고 공무원 폭행·협박한 경우의 효과》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①구성요건요소설(사실의 착오로 고의 조각)</div><div class=\"cs-li\" style=\"margin-left:16px\">②구성요건요소설(적법성 자체 착오는 법률의 착오, 적법성 기초 사실(행위사정) 착오는 사실의 착오로 고의 조각)</div><div class=\"cs-li\" style=\"margin-left:16px\">③위법성요소설(법률의 착오 또는 위법성조각사유 전제사실 착오)</div><div class=\"cs-li\" style=\"margin-left:16px\">④처벌조건설(착오는 범죄 성립과 무관)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: 공무집행 적법성에 관한 잘못된 법적 평가로 자신 행위가 금지되지 않는다 오인 → <span class=\"cs-stat\"><strong>§16</strong></span>에 따라 정당한 이유 살펴야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 일률 평가 X, 구성요건요소설 입장에서 직무행위 적법성 착오는 법률의 착오, 적법성 기초 사실(행위사정) 착오는 사실의 착오</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\"><span class=\"cs-fact-tag\">[TIP]</span> 이미 구속영장 제시했는데 아직 영장제시 없는 것으로 오인·저항 → 적법성 기초 사실의 착오 → 고의 조각</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">[甲이 경찰관 A(女)에게 고성·몸 들이밀자 경찰관 B(男)가 급히 밀쳐 분리, 甲이 B 행위 위법 오인하고 B를 밀침]</div><div class=\"cs-li\" style=\"margin-left:64px\">①경직법 <span class=\"cs-stat\"><strong>§6</strong></span> '범죄 예방·제지' 적법 공무</div><div class=\"cs-li\" style=\"margin-left:64px\">②위법성조각사유 전제사실 착오 없고 단지 B 직무집행 적법성에 대한 주관적 법적 평가 잘못 → <span class=\"cs-stat\"><strong>§16</strong></span> 적용</div><div class=\"cs-li\" style=\"margin-left:64px\">③B 행위 위법 오인할 만한 정당한 이유 없음</div><div class=\"cs-li\" style=\"margin-left:64px\">④甲에 공무집행방해죄 성립</div><div class=\"cs-h\">Ⅱ. 폭행 또는 협박</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[폭행(광의)]</span> 공무원에 대한 직접적 유형력 행사뿐 아니라 '간접적' 유형력 행사도 포함 <span class=\"cs-fact-tag\">[파출소 안 분뇨]</span> <span class=\"cs-fact-tag\">[협박]</span> 사람을 공포케 할 수 있는 해악 고지, 해악 고지 있으면 족하고 피해자에게 현실로 공포심 생겼음 필요 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 폭행·협박은 성질상 공무원 직무집행 방해할 만한 정도여야 → 경미하여 공무원이 개의치 않을 정도면 해당 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">윤활유·철판조각을 경찰관 면전에서 공무집행 방해 의도로 뿌린 특별한 사정 별론, 경찰관 부재 중 미리 바닥에 뿌려 놓은 것은 유형력 행사(폭행) 볼 수<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">차량 정차 후 경찰관 운전면허증 제시요구 불응·재출발, 경찰관이 잡은 운전석 열린 유리창 윗부분 놓지 않은 채 진행하다 차량속도 빨라지자 손 놓아버림 → 폭행 해당<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 공무집행방해의 결과와 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[추상적 위험범]</span> <span class=\"cs-stat\"><strong>§136</strong></span> 공무집행방해죄는 직무 집행 공무원에 폭행·협박한 경우 성립, 추상적 위험범으로서 구체적으로 직무집행 방해라는 결과발생 要하지 X<span class=\"cs-exam\">【변19】</span> <span class=\"cs-fact-tag\">[고의]</span> 상대방이 직무 집행 공무원이라는 사실 및 이에 대해 폭행·협박한다는 사실 인식, 불확정적(미필적) 고의로 족, 직무집행 방해할 의사 필요 X<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-h\">Ⅳ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계):</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">동일 공무 집행 여러 공무원에 폭행·협박 → 공무원 수에 따라 수개 공무집행방해죄, 폭행·협박이 동일 장소·동일 기회 사회관념상 1개 행위 평가 시 상상적 경합<span class=\"cs-exam\">【변25】</span> <span class=\"cs-fact-tag\">[피해 신고 출동 두 경찰관에 욕설하며 순차 폭행]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">공무집행방해죄와 그 공무원에 대한 상해죄 = 상상적 경합<span class=\"cs-exam\">【변20】</span></div>", ["§148", "§44", "§136", "§211", "§212", "§257", "§21", "§16"], 3, "gak_국가공무방해"], ["국가013", "위계공무집행방해죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 변호인의 접견 빙자 금지물품 반입·외부통화</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(12)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">구속된 甲의 변호인 戊, 변론 활동 의사가 없음에도 甲의 부탁에 따라 휴대전화 2대와 반입금지 물품인 진통제가 든 주사기 1개를 준비해 '사건 변론을 위해 접견하러 왔다'며 구치소에 접견 신청 → 교도관 Y가 반입금지 물품 소지 여부를 묻자 '없다'고 답했고 Y는 몸수색을 소홀히 한 채 출입 허락 → 戊는 휴대전화 2대 중 1대만 제출하며 모두 제출한 것처럼 행세한 뒤 접견실에서 甲에게 주사기를 건네고, 상담하는 척하며 甲이 휴대전화로 외부와 통화하게 함.</div><div class=\"cs-li\" style=\"margin-left:0px\">戊의 죄책을 논하시오. (12점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [건조물침입죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 출입이 통제되는 건조물에 관리자의 승낙을 받아 통상적 출입방법으로 들어갔다면 승낙의 의사표시에 하자가 있어도 건조물침입죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 출입 당시 객관적·외형적 행위태양상 사실상 평온상태를 해치는 모습으로 들어갔다고 평가할 수도(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 戊는 교도관 Y의 승낙을 받아 통상적 방법으로 입장 → 실제 목적을 알았다면 승낙하지 않았을 사정이 있어도 평온을 해치는 모습으로 들어갔다고 평가(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 戊에게 건조물침입죄(<span class=\"cs-stat\"><strong>§319</strong></span>①)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [위계공무집행방해죄]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [실제 변호를 할 의사 없이 접견신청을 한 행위]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 접견변호사가 미결수용자의 개인적 업무·심부름을 위해 접견신청을 해도 위계공무집행방해죄(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 변론 의사 없이 접견을 신청했다는 사정만으로는 위계공무집행방해죄(<span class=\"cs-stat\"><strong>§137</strong></span>)(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [감시·단속을 피하여 금지규정을 위반한 행위] (A) [금지물품(주사기) 반입행위]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 위계로 감시·단속 업무 공무원의 업무집행을 구체적·현실적으로 방해하면 성립하나, 단순히 감시·단속을 피해 금지규정을 위반한 데 지나지 않으면(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 휴대전화 1대와 주사기를 반입했어도 이는 몸수색을 소홀히 한 Y의 불충분한 심사에 기인한 것일 뿐 戊의 위계가 원인이라 볼 수(X) → 위계공무집행방해죄(X) (B) [외부통화행위]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 변호사가 접견을 핑계로 수용자를 위해 휴대전화·증권거래용 단말기를 구치소 내로 몰래 반입해 이용하게 한 행위 → 위계공무집행방해죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 상담하는 척하며 휴대전화로 외부와 통화하게 함 = 교도관들에 대해 사실상 적발이 어려운 위계를 구체적·현실적으로 사용해 직무집행에 지장을 주거나 곤란하게 함 → 위계공무집행방해죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 戊 = 외부통화하게 한 행위에 대해서만 위계공무집행방해죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제137조(위계에 의한 공무집행방해)</strong></span> 위계로써 공무원의 직무집행을 방해한 자는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div></div><div class=\"cs-h\">Ⅰ. 위계로써 공무원의 직무집행 방해</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>위계</strong> 개념: 위계란 행위자의 행위목적을 이루기 위하여 상대방에게 오인·착각·부지를 일으키게 하여 그 오인·착각·부지를 이용하는 것 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[담당 공무원 모두의 공모·양해 아래 부정한 행위]</span> 오인 등 일으킨 상대방 있다 할 수 X → 위계에 해당한다 볼 수<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공무원의 직무집행</strong> 적용범위: 위계에 의한 공무집행방해죄의 공무원 직무집행 = 법령 위임에 따른 적법한 직무집행인 이상 권력적 작용뿐 아니라 '사경제주체'로서의 활동 비롯한 비권력적 작용도 포함 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[몰수물 압수되어 있는 경우]</span> 검사의 집행지휘만으로 집행 종료 → 검사의 몰수판결 집행업무는 위계에 의해 방해당할 수 없는 성질의 업무</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>방해</strong> 성립요건:</div><div class=\"cs-li\" style=\"margin-left:16px\">①상대방이 위계에 따라 그릇된 행위·처분을 하여야만 이 죄 성립</div><div class=\"cs-li\" style=\"margin-left:16px\">②범죄행위가 구체적 공무집행을 저지하거나 '현실적으로' 곤란하게 하는 데까지 이르지 아니하고 미수에 그친 경우 처벌 X <span class=\"cs-fact-tag\">[위계공무집행방해죄는 미수범 처벌규정 없음]</span></div><div class=\"cs-h\">Ⅱ. 신청·출원에 대한 심사 업무</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>행정청에 대한 일방적 통고로 완성되는 신고</strong> 판단기준 (判例) : '일방적 통고로 효과가 완성되는 신고'는 신고인이 허위사실 기재·허위 소명자료 제출하더라도 그것만으로는 담당 공무원의 구체적·현실적 직무집행 방해받았다 볼 수 X → 특별한 사정 없는 한 위계공무집행방해죄 구성<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>출원심사 또는 신청에 따른 수용여부 결정</strong> 판단기준 (判例) : 행정관청이 출원·신청에 따라 자격요건 심사·수용 여부 결정하는 업무 = 신청서 기재 사유가 사실과 부합하지 않을 수 있음 전제로 심사·판단 → 업무담당자가 사실 충분히 확인 않고 허위 신청사유·소명자료 가볍게 믿고 수용 시, 업무담당자의 불충분한 심사에 기인 → 위계공무집행방해죄 구성<span class=\"cs-x\"><strong>(X)</strong></span> 그러나 '신고'와 달리, 출원자·신청인 제출 허위 소명자료에 대해 담당 공무원이 나름대로 충분히 심사했으나 발견 못해 인허가처분·수리하게 되면, 위계행위가 '원인이 되어' 그릇된 처분에 이른 것 → 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[등기신청]</span> 단순한 '신고'가 아니라 등기관의 심사·처분 예정 → 등기관이 나름대로 충분히 심사했음에도 발견 못해 등기 마쳐지면 위계공무집행방해죄 성립할 수<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[개인택시 운송사업 양도·양수 위해 허위 출원사유 주장, 의사로부터 허위 진단서 발급받아 소명자료로 제출하여 양도·양수 인가처분 받음]</span> 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>담당공무원의 경우</strong> 판단기준 (判例) : 출원 심사업무 담당 공무원이 출원인의 출원사유가 허위임을 알면서도 결재권자로 하여금 오인·착각·부지 일으키게 하고 이를 이용하여 인·허가처분 결재 받아낸 경우 → 허위 자료 제출한 경우와 달리 적정한 심사업무 기대할 수 없게 됨 → 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변13】</span></div><div class=\"cs-h\">Ⅲ. 수사기관에 대한 위계</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>수사기관에서의 허위진술 또는 허위증거 제출<span class=\"cs-exam\">【모사23】</span></strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①피의자 등이 수사기관에 '허위사실 진술'하거나 '증거 감추고 허위 증거 제출'하더라도, 수사기관이 충분한 수사 않은 채 허위 진술·증거만으로 증거 수집·조사 마쳤다면 수사기관의 불충분한 수사에 의한 것 → 위계공무집행방해죄 성립 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 '적극적으로 허위의 증거를 조작하여 제출'하고 수사기관이 '나름대로 충실한 수사'를 하더라도 허위임을 발견 못할 정도에 이르면 위계공무집행방해죄 성립 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[O]</span> 음주운전 중 교통사고 야기 후 타인의 혈액을 자신의 혈액인 것처럼 교통사고 조사 경찰관에게 제출·감정하도록 한 행위 = 적극적으로 피의사실에 관한 증거를 '조작'한 것 → 위계공무집행방해죄 성립</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X]</span> 수사기관에 대하여 피의자가 허위자백·참고인이 허위진술 한 사실만으로는 위계공무집행방해죄 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X]</span> 피의자·참고인 아닌 자가 자발적·계획적으로 피의자 가장하여 수사기관에 허위사실 진술하였다 하여 바로 위계공무집행방해죄 성립 X<span class=\"cs-exam\">【변22·19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X]</span> 자가용차 운전 중 교통사고 낸 사람이 가해차량이 자가용일 경우 피해자와 합의에 불리하다 생각하여 영업용택시 운전하다 사고 냈다고 허위신고하더라도 위계공무집행방해죄 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[X]</span> 피의자·참고인 등이 적극적으로 피의자 무고함 입증 등 목적으로 허위 증거 조작 제출한 것이 아니라 단순히 증거를 감추거나 없애 버린 것만으로는 위계공무집행방해죄 성립 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>거짓신고로 인한 공무원의 대응조치</strong> 판단기준 (判例) : 경범죄처벌법 <span class=\"cs-stat\"><strong>§3</strong></span>③2호 거짓신고로 경찰관이 진위 확인·검토 여유 없이 국민의 생명·신체 보호 위해 우선하여 긴급 출동하는 등 즉각적 대응조치 취해야 하는 상황에서 실제로 그 조치가 이루어졌다면, 특별한 사정 없는 한 위계공무집행방해죄 성립 判例(죄수관계): <span class=\"cs-fact-tag\">[법조경합]</span> 경범죄처벌법 <span class=\"cs-stat\"><strong>§3</strong></span>③2호 거짓신고가 '위계'의 수단·방법·태양의 하나가 된 경우 → 거짓신고로 인한 경범죄처벌법위반죄는 위계공무집행방해죄에 흡수 → 위계공무집행방해죄만 성립, 별도로 경범죄처벌법위반죄 성립 X</div><div class=\"cs-h\">Ⅳ. 법원에 대한 위계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 민사소송 제기 시 피고의 주소를 허위로 기재하여 법원공무원으로 하여금 변론기일소환장 등 허위주소로 송달케 한 사실만으로는 법원공무원의 구체적·현실적 직무집행 방해되었다 할 수 없어 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【모사21】</span> 법원은 당사자의 허위 주장·증거 제출에도 불구하고 진실 밝혀야 하는 것이 직무 → 가처분신청 시 당사자가 허위 주장·증거 제출하더라도 그것만으로 법원의 구체적·현실적 직무집행 방해되었다 볼 수 없어 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅴ. 감시·단속</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 법령에서 일정 행위 금지하며 위반행위에 벌칙 정하고 공무원으로 하여금 금지규정 위반 여부 감시·단속하도록 한 경우, 공무원에게 감시·확인·단속 권한과 의무 있으므로 구체적·현실적으로 감시·단속 업무 수행하는 공무원에 대해 위계 사용하여 업무집행 못하게 하면 위계공무집행방해죄 성립<span class=\"cs-exam\">【변사26】</span> 단순히 공무원의 감시·단속을 피하여 금지규정을 위반한 것에 지나지 않으면 위계공무집행방해죄 해당 X → 피고인이 금지규정 위반하여 감시·단속 피한 것을 공무원이 적발 못하였다면 공무원이 감시·단속이라는 '직무를 소홀히 한 결과'일 뿐 위계로 공무집행 방해한 것 볼 수 X<span class=\"cs-exam\">【변사26】</span> <span class=\"cs-fact-tag\">[교도소에 안경·명함지갑 모양 녹음·녹화장비 반입]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①미결수용자 형사사건에 관하여 변호인이 구체적으로 어떤 변호 활동을 하는지, 실제 변호 의사 있는지 여부 등은 교도관 심사대상 X → 접견변호사가 미결수용자의 개인적 업무·심부름 위해 접견신청행위 하였다는 이유만으로 위계 해당·직무집행 방해 볼 수 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②접견변호사가 피고인과 소송서류 이외 서류 주고받은 것이 위계 해당·직무집행 방해 볼 수 X<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[O]</span> 변호사가 접견을 핑계로 수용자 위해 휴대전화와 증권거래용 단말기를 구치소 내로 몰래 반입하여 이용하게 한 행위 = 위계공무집행방해죄 해당<span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">과속단속카메라에 촬영되더라도 불빛 반사시켜 차량 번호판 식별 안 되게 하는 기능 제품을 번호판에 뿌린 상태로 운행한 행위만으로는 위계공무집행방해죄 성립<span class=\"cs-o\"><strong>(X)</strong></span></div>", ["§319", "§137", "§3", "제137조"], 3, "gak_국가공무방해"], ["국가014", "범인도피죄", "<details class=\"cs-case\"><summary><u><strong>[CASE] 강도범에 대한 도피자금 제공·친족 특례</strong></u> <span class=\"cs-exam\">【변사21】 </span><span class=\"cs-o\">(5)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">(1) [기출] 乙이 특수강도미수죄(또는 강도예비죄)를 범함. 경찰의 검거지시가 내려지자 乙이 친구 丙에게 사정을 이야기하며 도피 자금을 구해달라 부탁 → 승낙한 丙이 자기 고가 골프채를 E에게 양도해 마련한 1,000만 원을 도피 자금으로 건넴. 乙과 丙의 죄책은? (10점)</div><div class=\"cs-li\" style=\"margin-left:0px\">(2) [추가] 만약 丙이 乙의 사촌동생이라면 어떠한가? (5점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [설문(1)]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [丙의 범인도피죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① '도피하게 하는 행위' = 은닉 이외의 방법으로 형사사법 작용을 곤란·불가능하게 하는 일체의 행위</div><div class=\"cs-li\" style=\"margin-left:0px\">② 乙이 특수강도미수의 죄를 범한 자임을 알면서 도피자금 1,000만 원을 건넴 → 범인도피죄(<span class=\"cs-stat\"><strong>§151</strong></span>①)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [乙의 범인도피교사죄]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 도피 범행의 결의가 없는 丙에게 부탁해 결의하게 함 → 일응 교사행위(<span class=\"cs-stat\"><strong>§31</strong></span>①)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 도피 교사 — 부정설/긍정설, 판례 = \"범인이 도피를 위해 타인에게 도움을 요청하는 행위도 도피행위의 범주에 속하는 한 불벌이나, 방어권의 남용으로 볼 수 있을 때에는 범인도피교사죄에 해당할 수 있다\"</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 도피자금 마련을 교사함은 형사사법에 중대한 장애를 초래할 위험이 있는 방어권 남용 → 범인도피교사죄(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(다) [소결] 乙 = 범인도피교사죄, 丙 = 범인도피죄</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [설문(2)]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [丙의 죄책]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 범인도피죄의 친족간 특례(<span class=\"cs-stat\"><strong>§151</strong></span>②) = 책임조각사유</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙은 乙의 사촌동생 → 책임 조각 → 범인도피죄(X)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [乙의 죄책]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 범인이 자신을 위해 처벌받지 않는 친족으로 하여금 범인도피죄를 범하게 함 → 방어권 남용 → 범인도피교사죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丙은 친족으로서 책임이 조각되어 죄책(X)이나, 제한적 종속형식에 의해 乙 = 범인도피교사죄 &lt;!-- 원문 (나)의 원숫자는 1,2,4 로 인쇄되어 3이 빠져 있음(원문 오기로 보임). 순서 그대로 보존함 --&gt;</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제151조(범인은닉과 친족간의 특례)</strong></span></div><div class=\"cs-li\" style=\"margin-left:16px\">① 벌금 이상의 형에 해당하는 죄를 범한 자를 은닉 또는 도피하게 한 자는 3년 이하의 징역 또는 500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 친족 또는 동거의 가족이 본인을 위하여 전항의 죄를 범한 때에는 처벌하지 아니한다.</div></div><div class=\"cs-h\">Ⅰ. 벌금 이상의 형에 해당하는 죄를 범한 자</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>죄를 범한 자</strong> 적용범위: 범인도피죄는 타인을 도피하게 하는 경우 성립 가능, 여기서 타인에는 공범도 포함되나 범인 스스로 도피하는 행위는 처벌 X <span class=\"cs-fact-tag\">[벌금 이상의 형에 대한 인식]</span> 범인도피죄에서 '벌금 이상의 형에 해당하는 자'에 대한 인식은 실제로 '벌금 이상의 형에 해당하는 범죄'를 범한 자라는 것 인식으로 족, 그 법정형이 벌금 이상이라는 것까지 알 필요 X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[수사 개시 전O]</span> '죄를 범한 자' = 범죄 혐의 받아 수사대상 된 자 포함, 나아가 당시에는 아직 수사대상 아니었더라도 범인도피죄 성립<span class=\"cs-exam\">【변26】</span> <span class=\"cs-fact-tag\">[입건 전 내사단계도 성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[교특법위반 한정·자동차종합보험 가입]</span> 범인에게 적용될 수 있는 죄가 교특법위반죄에 한정되더라도 자동차종합보험 가입사실만으로 형사소추·처벌 받을 가능성 없는 경우에 해당한다 단정 X → 수사기관은 교특법 <span class=\"cs-stat\"><strong>§3</strong></span>② 단서 적용 여부 가리기 위해 수사할 수 있으므로 범인도피죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[부정수표단속법 피의자 甲이 A에 노임채무 인수 지불각서 작성·교부, A가 甲의 수사당국 인계 포기 합의]</span> 甲이 인계되지 않은 경우 피고인들에 범인도피죄 성립 인정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>'진범' 요부<span class=\"cs-exam\">【변기16】</span></strong> <span class=\"cs-issue\">《범인도피죄의 객체가 '진범'이어야 하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①적극설(<span class=\"cs-stat\"><strong>§151</strong></span>① '죄를 범한 자'로 규정하므로 진범임을 要함)</div><div class=\"cs-li\" style=\"margin-left:16px\">②소극설(진범임 要하지 않고 수사대상 되어 있으면 족함)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[소극설]</span> <span class=\"cs-stat\"><strong>§151</strong></span>①의 죄를 범한 자는 범죄 혐의 받아 수사대상 된 사람이면 진범 여부 묻지 않고 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 범인도피죄는 '위험범'으로서 현실적으로 형사사법 작용 방해 결과 초래 必 X → 소극설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[구속수사 대상 된 소송외인이 그 후 무혐의 석방]</span> 범인도피죄 성립에 영향 X</div><div class=\"cs-h\">Ⅱ. 은닉·도피</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[위험범]</span> 범인도피죄는 위험범으로서 현실적으로 형사사법 작용 방해 결과 초래 必 X '도피하게 하는 행위' = 은닉 이외의 방법으로 범인에 대한 수사·재판·형의 집행 등 형사사법 작용을 곤란·불가능하게 하는 일체의 행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①'도피하게 하는 행위'는 은닉 이외 방법으로 형사사법 작용 곤란·불가능하게 하는 일체 행위로 수단·방법 제한 없으나,</div><div class=\"cs-li\" style=\"margin-left:16px\">②같은 조 은닉행위에 비견될 정도로 수사기관 발견·체포 곤란하게 하는 행위 즉 직접 범인 도피시키거나 도피를 직접적으로 용이하게 하는 행위에 한정</div><div class=\"cs-li\" style=\"margin-left:16px\">③그러나 그 자체로는 도피시키는 것 직접 목적으로 하였다 보기 어려운 행위의 결과 간접적으로 범인이 안심하고 도피할 수 있게 한 경우까지 포함 X<span class=\"cs-exam\">【변20】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①범인은닉죄는 죄를 범한 자임을 인식하면서 장소 제공하여 체포 면하게 함만으로 성립</div><div class=\"cs-li\" style=\"margin-left:16px\">②장소 제공 후 동인에게 일정 기간 경찰 출두 말라 권유하는 언동 하여야만 성립하는 것 아니며</div><div class=\"cs-li\" style=\"margin-left:16px\">③권유에 따르지 않을 경우 강제력 행사하여야만 하거나 죄를 범한 자가 은닉자 말에 복종 관계 있어야만 성립하는 것 더욱 아님</div><div class=\"cs-li\" style=\"margin-left:16px\">①수사기관은 진술 여하에 불구하고 피의자 확정·피의사실 인정할 객관적 증거 수집·조사할 권리·의무 있으므로, '참고인'이 수사기관에서 알고 있는 사실 묵비·허위 진술하였더라도 그것이 적극적으로 수사기관 기만하여 착오 빠지게 함으로써 범인 발견·체포 곤란·불가능하게 할 정도 아닌 한 범인도피죄 구성 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②'피의자'가 수사기관에서 '공범에 관하여 묵비·허위 진술'한 경우에도 그대로 적용</div><div class=\"cs-li\" style=\"margin-left:16px\">①참고인이 범인 아닌 '다른 자를 진범이라 내세우는 경우' 등 적극적으로 허위사실 진술하여 수사관 기만·착오 빠지게 하는 경우와 달리,</div><div class=\"cs-li\" style=\"margin-left:16px\">②참고인이 진술 함에 있어 단순히 범인으로 체포된 사람과 목격한 범인이 동일함에도 '동일한 사람이 아니라고 허위진술'한 정도만으로는 그 허위진술로 증거 불충분하게 되어 범인 석방하게 되었더라도 범인도피죄 성립 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[기소중지자임을 알고 범인 부탁으로 다른 사람 명의 대신 임대차계약 체결해 준 경우]</span> 범인도피죄 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[범인 아닌 자가 수사기관에 범인임을 자처하고 허위사실 진술하여 진범 체포·발견에 지장 초래한 행위]</span> 범인도피죄 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사회적 상당성]</span> 어떤 행위가 범인도피죄 해당하는 것처럼 보이더라도 사회적으로 상당성 있는 행위일 때는 처벌 X <span class=\"cs-fact-tag\">[구성요건해당성 제한]</span></div><div class=\"cs-h\">Ⅲ. 친족간 책임조각 특례</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>친족간 책임조각사유</strong> 적용범위: 범인은닉(<span class=\"cs-stat\"><strong>§151</strong></span>②), 증거인멸 및 증인은닉(<span class=\"cs-stat\"><strong>§155</strong></span>④)<span class=\"cs-exam\">【변22】</span> <span class=\"cs-issue\">《친족간 특례의 법적 성격》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①인적처벌조각사유설</div><div class=\"cs-li\" style=\"margin-left:16px\">②책임조각사유설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: <span class=\"cs-fact-tag\">[책임조각사유]</span> 특례는 친족관계로 인한 기대불가능성 이유로 책임 조각하는 취지 → 책임조각사유설 타당<span class=\"cs-exam\">【모사25·20, 변기25·16】</span></div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[법률상 친족 한정]</span> 친족은 민법이 정한 법률상의 친족</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[사실혼X]</span> 사실혼관계에 있는 자는 민법 소정의 친족이라 할 수 없어 <span class=\"cs-stat\"><strong>§151</strong></span>②·<span class=\"cs-stat\"><strong>§155</strong></span>④에서 말하는 친족에 해당<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24·19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[혼외자의 생부 도피X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①<span class=\"cs-fact-tag\">[직접적용X]</span> 혼인외 출생자가 벌금 이상의 형에 해당하는 죄를 범한 자신의 생부(生父)를 도피하게 하더라도 생부가 혼인외 출생자를 인지하지 않은 경우에는 생부와 혼인외 출생자 사이에 법률상 친자관계 발생하지 않으므로 <span class=\"cs-stat\"><strong>§151</strong></span>② 적용 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②<span class=\"cs-fact-tag\">[유추적용X]</span> 유추적용은 법적 규율 없는 사안에 유사 사안 법규범 적용하는 것인데, <span class=\"cs-stat\"><strong>§151</strong></span>② 적용범위에 법률의 흠결 있다 볼 수 없음 → 본인과 행위자 사이 구체적·개별적 관계·상황 따져 적법행위 기대불가능성 유무 따라 <span class=\"cs-stat\"><strong>§151</strong></span>② 유추적용하는 것 허용 X</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>범인의 친족이 친족 아닌 자에게 범인도피를 교사한 경우<span class=\"cs-exam\">【모사25】</span></strong> 판단기준 (判例) : <span class=\"cs-fact-tag\">[책임조각부정설]</span> 범인의 친족이 친족 아닌 자를 교사하여 범인을 도피하게 한 경우 범인의 친족은 범인도피교사범으로서의 죄책 면할 수 X</div><div class=\"cs-h\">Ⅳ. 자기 도피 교사의 성립여부<span class=\"cs-exam\">【변사21·15·14, 모사25·18·16·15, 변기25·16】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>범인의 범인도피교사죄 성립 여부</strong> <span class=\"cs-issue\">《범인이 타인을 교사하여 자신에 대한 범인도피행위를 하게 한 경우 범인도피교사죄 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(자기 방어권 연장에 불과하고 정범 될 수 없는 자는 교사범도 될 수 없음)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(새로운 범인을 창출한 것은 방어권 남용으로 허용 X)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①범인 스스로 도피하는 행위는 처벌되지 않으므로 범인이 도피를 위하여 '타인에게 도움 요청하는 행위 역시 (자기) 도피행위의 범주'에 속하는 한 처벌 X, 범인 요청에 응하여 범인 도운 타인의 행위가 범인도피죄 해당하더라도 마찬가지</div><div class=\"cs-li\" style=\"margin-left:16px\">②다만 범인이 타인으로 하여금 허위 자백 하게 하는 등으로 범인도피죄 범하게 하는 경우와 같이 그것이 '방어권 남용'으로 볼 수 있을 때에는 범인도피교사죄 해당할 수 O<span class=\"cs-exam\">【변26·23·22·20】</span> <span class=\"cs-fact-tag\">[책임조각 친족 교사]</span> 범인이 자신을 위하여 타인으로 하여금 허위 자백 하게 하여 범인도피죄 범하게 하는 행위는 방어권 남용으로 범인도피교사죄 해당, 그 타인이 <span class=\"cs-stat\"><strong>§151</strong></span>②에 의하여 처벌 받지 아니하는 친족 등에 해당한다 하여 달리 볼 것 X<span class=\"cs-exam\">【변26·23·22·20 등 빈출】</span> <span class=\"cs-fact-tag\">[책임조각사유, 제한적 종속형식]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 자기 도피는 처벌되지 않으므로 자기도피행위 범주 속하면 처벌 X, 방어권 남용 볼 수 있는 경우에는 공범종속성 원칙상(제한적 종속형식) 교사범 성립 인정할 수 있으므로 判例 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>구체적 판례</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[범인도피교사O]</span> 甲이 음주운전 혐의로 적발되자 A에게 전화 걸어 음주단속 현장으로 나오게 하고 '어떻게 좀 해 보라'고 계속 재촉하여, A로 하여금 단속경찰관이 甲에 대한 주취운전자 적발보고서 작성·재차 음주측정 못하도록 제지하게 하였다면, 甲의 행위는 범인도피교사죄 해당</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[범인도피교사X]</span> 후배 A(범인도피 정범 성립)에게 요청하여 대포폰 개설받고, A에게 전화 걸어 자신 있는 곳으로 오도록 한 다음 A 운전 자동차 타고 청주시 일대 이동한 행위 = 형사사법에 중대한 장애 초래한다 보기 어려운 '통상적 도피의 한 유형' 볼 여지 충분</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[범인도피교사X]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①甲은 피고인과 10년 이상 친분관계로 부탁에 응하여 도와준 것으로 보이고 도피 위한 인적·물적 시설 미리 구비하거나 조직적 범죄단체 구성한 것 아님, 요청 핵심은 은신처와 차명 휴대전화 제공으로 통상적 도피의 한 유형 볼 여지 충분</div><div class=\"cs-li\" style=\"margin-left:48px\">②암묵적으로 '검거 위험 있으면 소재 허위 진술하여 도피시켜 달라'는 취지 의사 있었고 도피생활 계속할 수 있었더라도 형사피의자로서의 방어권 남용이라 보기 어려움<span class=\"cs-exam\">【변기25, 모사25】</span></div><div class=\"cs-h\">Ⅴ. 공범의 범인도피죄</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공범을 위한 범인도피</strong> 판단기준 (判例) : 공동정범 중 1인이 다른 공동정범을 도피시키면 범인도피죄의 죄책 면치 못함<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①참고인이 수사기관에서 알고 있는 사실 묵비·허위 진술하였더라도 적극적으로 수사기관 기만하여 착오 빠지게 함으로써 범인 발견·체포 곤란·불가능하게 할 정도 아닌 한 범인도피죄 구성 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②이 법리는 피의자가 수사기관에서 공범에 관하여 묵비·허위 진술한 경우에도 그대로 적용</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공범이 '자신'의 범행에 관해 허위진술·허위자료 제출<span class=\"cs-exam\">【변사24, 모사25·23·21】</span></strong> 판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①범인도피죄는 타인 도피하게 하는 경우 성립, 타인에 공범 포함되나 범인 스스로 도피 처벌 X</div><div class=\"cs-li\" style=\"margin-left:16px\">②공범 중 1인이 그 범행에 관한 수사절차에서 참고인·피의자로 조사받으면서 '자기의 범행을 구성하는 사실관계'에 관하여 허위 진술·허위 자료 제출하는 것은 자신의 범행에 대한 방어권 행사 범위 벗어난 것 볼 수 X</div><div class=\"cs-li\" style=\"margin-left:16px\">③이러한 행위가 다른 공범 도피하게 하는 결과 되더라도 범인도피죄로 처벌 X <span class=\"cs-fact-tag\">[교사]</span> 공범이 이러한 행위 교사하였더라도 범죄 될 수 없는 행위 교사한 것에 불과 → 범인도피교사죄 성립 X<span class=\"cs-exam\">【변20】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">①A가 강제집행 피하기 위해 콜라텍을 B에게 허위 양도하여 강제집행 면탈, B가 허위양수인으로서 관여 정도 비추어 강제집행면탈죄 공동정범인 경우, B가 조사받으며 콜라텍 실제 양수 운영한다 허위 진술·허위 자료 제출하여 A 도피하게 하는 결과 되더라도 범인도피죄 성립 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②A가 B에게 이 행위 교사하였더라도 범죄 될 수 없는 행위 교사한 것에 불과 → 범인도피교사죄도 성립 X</div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>게임장 관련<span class=\"cs-exam\">【변사14】</span></strong> 판단기준 (判例) : 게임산업진흥법 위반·도박개장 등 혐의로 조사받는 피의자가 사실은 게임장·오락실·피씨방 등의 실제 업주 아니라 그 종업원임에도 자신이 실제 업주라 허위 진술하였더라도 그 자체만으로 범인도피죄 구성 X<span class=\"cs-exam\">【변12】</span> 다만 그 피의자가 실제 업주로부터 금전적 이익 등 제공받기로 하고 단속되면 실제 업주 숨기고 자신이 대신 처벌받기로 하는 역할(이른바 바지사장) 맡기로 하는 등 수사기관을 착오에 빠뜨리기로 하고, 단순히 실제 업주라 진술하는 것에서 나아가 게임장 운영 경위·자금 출처·게임기 구입 경위·점포 임대차계약 체결 경위 등에 관해서까지 적극적으로 허위 진술·허위 자료 제시하여 수사기관이 실제 업주 발견·체포 곤란·불가능하게 될 정도에까지 이른 것으로 평가되는 경우 등에는 범인도피죄 구성할 수 O<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅵ. 도주죄와 범인도피죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 도주죄는 즉시범으로서 범인이 간수자의 실력적 지배를 이탈한 상태에 이르렀을 때 기수 되어 도주행위 종료, 도주원조죄는 도주죄에 있어서의 범인의 도주행위 야기·용이하게 하는 등 공범관계 행위를 독립한 구성요건으로 하는 범죄 → 도주죄의 범인이 도주행위하여 기수 이른 이후에 범인 도피 도와주는 행위는 범인도피죄에 해당할 수 있을 뿐 도주원조죄에는 해당<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20·19】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">법원이 선고기일에 피고인에 실형 선고하면서 구속영장 발부하는 경우, 검사가 법정에 재정하여 법원으로부터 구속영장 전달받아 집행 지휘하고 그에 따라 피고인 대기실로 인치된 피고인은 도주죄의 주체인 '법률에 의하여 체포 또는 구금된 자'에 해당<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[구속 피고인 대기실 출입문 열고 법정으로 뛰어 들어가 도주하려다 교도관에 검거 → 도주미수죄]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">불법체포된 피고인은 <span class=\"cs-stat\"><strong>§145</strong></span>① 소정의 '법률에 의하여 체포 또는 구금된 자'가 아니어서 도주죄의 주체 될 수<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span></div>", ["§151", "§31", "§3", "§155", "§145", "제151조"], 3, "gak_국가공무방해"], ["국가015", "증거인멸 및 증인도피", "<details class=\"cs-case\"><summary><u><strong>[CASE] 공통증거(휴대폰) 인멸</strong></u> [모사 등] <span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">甲과 乙이 합동해 A회사 금고의 상품권을 절취. 이후 甲은 수사가 진행되면 서로 주고받은 문자메시지로 범행이 발각될 것을 우려해 乙에게 휴대폰을 한강에 버리라고 종용, 乙도 처벌이</div><div class=\"cs-li\" style=\"margin-left:0px\">두려워 자기 휴대폰을 한강에 몰래 버림. 휴대폰을 버린 것과 관련된 甲과 乙의 죄책은? (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [乙의 증거인멸죄]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① '타인의 형사사건 또는 징계사건' = 인멸행위 시 아직 수사절차 개시 전 이라도 장차 형사사건이 될 수 있는 것까지 포함</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자신과 공범자의 공통된 증거를 인멸한 경우 증거인멸죄 성부 — 위 학설 및 판례</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 판례에 의하면 乙은 자기 처벌이 두려워 자신의 이익을 위해 공통증거를 몰래 버림 → 공범 甲의 형사사건 증거를 인멸한 결과가 되어도 자기의 형사사건 증거를 인멸한 것에 불과</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 乙에게 증거인멸죄(<span class=\"cs-stat\"><strong>제155조</strong></span> 제1항)(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [甲의 증거인멸죄의 교사범 또는 간접정범]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 교사범은 정범의 행위가 구성요건에 해당하고 위법할 것 要(제한적 종속형식) → 乙에게 구성요건해당성(X) → 甲에게 교사범(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 간접정범도 정범의 일종인 이상 증거인멸죄의 정범으로 처벌되지 않는 甲을 간접정범으로 처벌할 수도(X)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 甲과 乙 = 아무런 죄책도 지지 않음</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제155조(증거인멸 등과 친족간의 특례)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 타인의 형사사건 또는 징계사건에 관한 증거를 인멸, 은닉, 위조 또는 변조하거나 위조 또는 변조한 증거를 사용한 자는 5년 이하의 징역 또는 700만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 타인의 형사사건 또는 징계사건에 관한 증인을 은닉 또는 도피하게 한 자도 제1항의 형과 같다.</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 피고인, 피의자 또는 징계혐의자를 모해할 목적으로 전2항의 죄를 범한 자는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">④ 친족 또는 동거의 가족이 본인을 위하여 본조의 죄를 범한 때에는 처벌하지 아니한다.</div></div><div class=\"cs-h\">Ⅰ. 타인의 형사사건 또는 징계사건에 관한 증거</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: <span class=\"cs-fact-tag\">[형사사건]</span> 인멸행위 시 아직 수사절차 개시 전이라도 장차 형사사건 될 수 있는 것까지 포함, 그 형사사건 불기소·무죄 선고돼도 증거인멸죄 성립에 영향 X<span class=\"cs-exam\">【변19】</span> <span class=\"cs-fact-tag\">[징계사건]</span> <span class=\"cs-stat\"><strong>§155</strong></span>① '징계사건'은 국가의 징계사건에 한정, 사인 간 징계사건 포함 X <span class=\"cs-fact-tag\">[증거]</span> 수사기관·법원·징계기관이 국가 형벌권·징계권 유무 확인에 관계있는 일체 자료, 타인에게 유리·불리 불문, 증거가치 유무·정도 불문</div><div class=\"cs-h\">Ⅱ. 공통증거를 인멸한 경우<span class=\"cs-exam\">【모사21·17·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《자신과 공범자의 공통된 증거 인멸 시 증거인멸죄 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①긍정설(공통증거는 공범인 타인의 형사사건 증거→성립)</div><div class=\"cs-li\" style=\"margin-left:16px\">②부정설(공범자 사건은 타인 사건 X→불성립)</div><div class=\"cs-li\" style=\"margin-left:16px\">③절충설(자신·자신+공범 위해 인멸 시 불성립, 공범 위한 의사로 인멸 시 성립)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[절충설 유사]</span> 피고인이 자기 이익 위해 증거자료 인멸 →동시에 다른 공범자 형사·징계사건 증거 인멸 결과 돼도 증거인멸죄로 다스릴 수 X, 공범자 아닌 자의 사건 증거 인멸 결과여도 마찬가지<span class=\"cs-exam\">【변26·25·19·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 자기 이익 위해 자기 형사사건 증거 인멸 →공통증거는 타인 형사사건 증거로 볼 수 X → 절충설 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[양벌규정 행위자]</span> '피고인 자신이 직접 형사처분 받을 것'에는 양벌규정 따라 처벌받는 법인 업무에 관해 행위자로서 처벌받을 수 있는 경우도 포함 <span class=\"cs-fact-tag\">[X회사 임원이 하도급법위반 증거 인멸→행위자로 직접 처벌 상황서 자기 이익 위해 인멸 시 불성립]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공범 교사]</span> 공범 甲이 공범 乙에게 증거인멸 교사, 乙이 자기 이익 위해 인멸 →乙 구성요건해당성 X, 제한적 종속형식상 甲도 증거인멸교사죄 불성립<span class=\"cs-exam\">【변26】</span></div><div class=\"cs-h\">Ⅲ. 자기 사건 증거은닉교사 및 공동정범 성립여부</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>자기 사건 증거인멸교사<span class=\"cs-exam\">【모사22·19·18·17·13】</span></strong> <span class=\"cs-issue\">《자기 사건 증거은닉 교사 시 증거은닉교사죄 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(자기 방어권 연장, 정범 될 수 없는 자는 교사범도 X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(새 범인 창출, 방어권 남용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 자기 형사사건 증거인멸은 방어권 인정 취지상 처벌 X, 타인에게 도움 요청도 원칙 불처벌이나 방어권 남용 시 증거인멸교사죄 처벌 가능<span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 타인에게 증거인멸 교사까지 기대가능성 없다 볼 수 X, 공범종속성 원칙(제한적 종속형식) → 긍정설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>타인과 공동으로 자기 증거를 인멸한 경우 (공동정범)</strong> 판단기준 (判例) : 범인 자신이 형사처분 두려워 자기 이익 위해 증거자료 은닉 →증거은닉죄 해당 X, 제3자와 공동으로 해도 마찬가지<span class=\"cs-exam\">【모기25】</span></div><div class=\"cs-h\">Ⅳ. 증인도피</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 증인도피죄는 타인 형사·징계사건 증인 은닉·도피 시 성립, 피고인 자신이 형사처분 두려워 '자기 이익 위해' 증인 될 사람 도피시킨 경우 동시에 다른 공범자 사건 증인 도피 결과 돼도 증인도피죄 처벌 X</div><div class=\"cs-h\">Ⅴ. 친족간 책임조각 특례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사실혼X]</span> 사실혼관계자는 민법 소정 친족 아니어서 <span class=\"cs-stat\"><strong>§151</strong></span>②·<span class=\"cs-stat\"><strong>§155</strong></span>④ 친족에 해당<span class=\"cs-o\"><strong>(X)</strong></span></div>", ["§155", "§151", "제155조"], 3, "gak_국가공무방해"], ["국가016", "증거위조·변조죄", "<div class=\"cs-h\">Ⅰ. '타인'의 형사사건 또는 징계사건에 관한 증거</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 증거위조죄의 '타인 형사사건'이란 위조행위 시 아직 수사절차 개시 전이라도 장차 형사사건 될 수 있는 것까지 포함<span class=\"cs-exam\">【변15】</span> 그 형사사건 불기소처분·무죄 선고돼도 증거위조죄 성립에 영향 X<span class=\"cs-exam\">【변15】</span> <span class=\"cs-fact-tag\">[증거 범위]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①범죄·징계사유 성립 여부뿐 아니라 형·징계 경중에 관계있는 정상 인정 자료도 증거에 포함</div><div class=\"cs-li\" style=\"margin-left:16px\">②타인에게 유리·불리 불문, 증거가치 유무·정도 불문<span class=\"cs-exam\">【변23】</span></div><div class=\"cs-h\">Ⅱ. 모해증거위조죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-stat\"><strong>§155</strong></span>③ '피의자'이려면 수사기관이 범죄 인지 등으로 수사 개시돼 있어야, 이전 단계선 장차 형사입건 가능성 커도 '피의자' 해당 X 사경이 절차 거치기 전 범죄혐의 있다고 보아 수사 착수 시 그때 인지한 것으로 보아야 하고, 그 뒤 범죄인지보고서 작성 시 인지한 것 아님</div><div class=\"cs-h\">Ⅲ. 위조 또는 변조</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>새로운 증거의 창조</strong> 개념: <span class=\"cs-stat\"><strong>§155</strong></span>① 증거위조죄의 '위조'란 문서죄 위조 개념과 달리 새로운 증거의 창조 의미 사실 증명 위해 작성된 문서가 내용·작성명의 등에 아무런 허위 없으면 증거위조 해당 X, 사실증명 문서가 형사·징계사건서 허위 주장 증거로 제출돼 뒷받침해도 마찬가지 판단기준 (判例) : '증거의 위조'란 '증거방법의 위조' 의미 →위조 여부는 증거방법 자체 기준, 증명하려는 사실의 허위·진실 여부로 위조 여부 결정돼선 안 됨<span class=\"cs-exam\">【변23】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[송금자료 양형자료]</span> 변호인·피고인이 대가 반환 자료로 양형 유리 판단 받고자 의뢰인 측 은행계좌↔A 은행계좌 간 송금·반환 반복 후 A 송금자료만 양형자료로 제출:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">①양형자료도 '형사·징계사건 증거'에 포함되어 위조 대상 '증거' 해당하나</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">②금융자료(입금확인증 등)는 실제 송금 내용 문서로 내용·작성명의에 허위 없어</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">증거위조 및 위조증거사용죄 불성립<span class=\"cs-exam\">【변24·23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[처분문서 소급작성]</span> '위조'는 새로운 증거의 창조 의미 →존재하지 않던 증거를 이전부터 존재한 것처럼 작출하는 행위도 위조 해당, 증거가 문서 형식 가져도 작성권한 유무·내용 진실성에 좌우 X<span class=\"cs-exam\">【변15】</span> 법률행위 당시 존재하지 않던 '처분문서'(외형·내용상 법률행위가 문서 자체에 의해 이루어진 외관)를 사후에 작성일 소급 작성: 작성권한 있고 법률행위가 당시 존재·내용 차이 없어도 증거위조죄 구성요건 충족</div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>증거 자체 위조 (허위 진술)</strong> 적용범위: 증거를 위조한다 함은 증거 자체를 위조함을 말함 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[녹음파일·녹취록O]</span> 참고인이 타인 형사사건 등에 관해 제3자와 대화하며 허위 진술하고 그 대화 녹음한 녹음파일·녹취록은 진술내용뿐 아니라 현장음향·제3자 진술 등 포함되어 일체가 증거자료→'증거' 해당, 녹음의 자연스러움 뒷받침하는 현장성 강해 증거가치 오도 위험 증대 →허위 증거를 새로 작출하는 행위로 '위조'에도 해당<span class=\"cs-exam\">【변23·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[증언X]</span> 선서무능력자로서 범죄현장 목격 못한 자로 하여금 형사법정서 목격한 양 허위 증언하게 하는 것은 증거위조죄 구성<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[진술X]</span> 참고인이 수사기관서 허위진술하는 것은 포함<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[진술서X]</span> 참고인이 허위 사실확인서·진술서 작성해 수사기관 제출도 새로운 증거 창조 아니고 참고인 수사기관 허위진술과 차이 없어 증거위조죄 구성<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span></div><div class=\"cs-h\">Ⅳ. 자기 증거 위조교사</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 자기 형사사건 증거 위조 위해 타인 교사해 죄 범하게 한 자는 증거위조교사죄 성립 <span class=\"cs-fact-tag\">[증거인멸과 동일 학설]</span></div><div class=\"cs-h\">Ⅴ. 공범에게 공통증거의 변조·사용을 교사한 경우</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[교사범X]</span> 자기 형사사건 증거 변조·사용 위해 타인 교사해 변조·사용하게 해도 피교사자인 타인이 같은 형사사건 공범 해당해 증거변조·변조증거사용죄로 처벌 안 된 이상 본죄 교사범 처벌<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[제한적 종속형식]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[간접정범X]</span> 간접정범도 정범 일종인 이상 증거변조·변조증거사용죄 정범으로 처벌 안 되는 자를 같은 죄 간접정범으로 처벌할 수<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변17】</span></div>", ["§155"], 3, "gak_국가공무방해"], ["국가017", "위증죄 일반", "<details class=\"cs-case\"><summary><u><strong>[CASE] 증언거부권 불고지·자기 사건 위증교사</strong></u> <span class=\"cs-exam\">【변사13】 </span><span class=\"cs-o\">(25)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">경찰관 P, 특수절도 피의자인 사촌동생 丙에게 전화해 빨리 도망가도록 종용 → 검사가 P를 직무유기죄로 불구속 기소 → 공판 중 P는 유죄판결이 확정되면 파면될 것이 두려워 丙에게 자신이 도망가라고 전화한 사실이 없다고 증언하도록 시킴 → 재판장은 丙이 P의 친척임을 간과하고 증언거부권을 고지하지 않은 채 증언하게 함 → 丙은 선서 후 \"P와 단 한 번도 전화통화를 한</div><div class=\"cs-li\" style=\"margin-left:0px\">사실이 없다\"고 허위 증언. 丙의 증언과 관련한 P와 丙의 죄책은? (25점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 丙 = P의 사촌동생 → 증언거부권(O)(형소법 <span class=\"cs-stat\"><strong>제148조</strong></span> 제1호)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 재판장은 신문 전에 증언을 거부할 수 있음을 설명해야 함(형소법 <span class=\"cs-stat\"><strong>제160조</strong></span>)</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 재판장이 증언거부권을 고지하지 않은 경우 위증죄 성부 — 성립설/불성립설, 판례 = \"증인이 증언거부권을 고지받지 못해 그 행사에 사실상 장애가 초래되었다고 볼 수 있는 경우에는 위증죄(X)\". 구체적 사안에서 성립 여부를 판단하는 판례 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">④ P가 적극적으로 위증을 교사했고 丙도 이에 따라 적극적으로 위증 → 고지받았어도 허위진술을 했을 것 → 증언거부권 행사에 사실상 장애(X) → 丙 = 위증죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [P의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 위증의 결의가 없는 丙에게 위증을 결의하게 함 → 일응 교사(<span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 자기 형사사건에 관한 위증교사 — 방어권의 연장에 불과하다는 부정설 / 새로운 범인을 창출한 방어권 남용이라는 긍정설, 판례 = \"자기의 형사사건에 관하여 타인을 교사하여 위증죄를 범하게 하는 것은 방어권 남용으로 위증교사죄 성립\" 긍정설. 타인에게 위증을 교사하는 것까지 기대가능성이 없다고 볼 수 없고 공범종속성의 원칙상 교사범 성립을 인정하는 긍정설 타당</div><div class=\"cs-li\" style=\"margin-left:0px\">③ P = 위증교사죄(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(3) [결론]</strong> 丙 = 위증죄, P = 위증교사죄</div></div></details></div></details><div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제152조(위증, 모해위증)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">① 법률에 의하여 선서한 증인이 허위의 진술을 한 때에는 5년 이하의 징역 또는 1천만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">② 형사사건 또는 징계사건에 관하여 피고인, 피의자 또는 징계혐의자를 모해할 목적으로 전항의 죄를 범한 때에는 10년 이하의 징역에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제153조(자백, 자수)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">전조의 죄를 범한 자가 그 공술한 사건의 재판 또는 징계처분이 확정되기 전에 자백 또는 자수한 때에는 그 형을 감경 또는 면제한다.</div></div><div class=\"cs-h\">Ⅰ. 법률에 의하여 선서한 증인</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[진정신분범·자수범]</span> 위증죄는 '선서한 증인'만 주체, 선서한 증인 이외의 자는 간접정범·공동정범 될 수 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[선서무능력자X]</span> 선서무능력자는 위증죄 주체 될 수<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[법정진술X]</span> 공범이 법정진술로 허위 진술해도 위증죄 성립<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변14】</span><span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[민사소송 당사자X]</span> 민사소송 당사자는 증인능력 없어 위증죄 주체 될 수 X, 민사소송 당사자인 법인 대표자도 위증죄 주체 될 수<span class=\"cs-o\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[가처분 심문절차X]</span> 제3자가 심문절차로 진행되는 가처분 신청사건서 증인으로 출석·선서·진술해 허위 공술해도 그 선서는 법률상 근거 없어 무효 →위증죄 성립<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[가처분사건 변론절차 진행 시엔 선서·증언 가능]</span></div><div class=\"cs-h\">Ⅱ. 허위 진술<span class=\"cs-exam\">【모사24】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>허위의 의미</strong> <span class=\"cs-issue\">《위증죄의 '허위'의 의미》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①객관설(증언 내용이 객관적 진실에 반하는 것)</div><div class=\"cs-li\" style=\"margin-left:16px\">②주관설(증인 자기 기억에 반하는 진술)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[주관설]</span> 허위의 공술이란 증인이 '자기 기억에 반하는 사실' 진술, 내용이 객관적 사실과 부합해도 위증죄 성립에 장애 X, 진술이 객관적 사실과 부합 안 해도 증인 기억에 반하는지 가려보기 전엔 위증 단정 X<span class=\"cs-exam\">【변13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 증인에게 기억과 관계없이 객관적 진실 말할 의무 없음 → 주관설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>허위의 진술</strong> 판단기준 (判例) : 증인 진술이 경험한 사실에 대한 법률적 평가·단순 의견에 지나지 않으면 위증죄 허위 공술<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변13】</span> 공술 내용이 요증사실에 관한 것인지·판결에 영향 미쳤는지 여부는 위증죄 성립과 관계 X<span class=\"cs-exam\">【변13】</span> 기억에 반하는 허위 진술인지 가릴 때 증언 단편적 구절에 구애될 것 아니라 신문 절차서 한 증언 전체를 일체로 파악해야 자기가 지득 안 한 '사실관계'를 단순히 법률적 표현 써서 진술한 것이면 객관적 사실 토대로 한 증인 나름의 법률적 견해 진술과 달라 위증죄 성립 부인 X 증인이 착오에 빠져 기억에 반한다는 인식 없이 증언했음이 밝혀진 경우 위증 범의 인정<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24】</span></div><div class=\"cs-h\">Ⅲ. 모해위증죄<span class=\"cs-exam\">【모사18】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: '모해할 목적'이란 피고인·피의자·징계혐의자를 불리하게 할 목적, 허위 진술로 피고인에게 불리하게 될 것이라는 인식 있으면 충분, 결과 발생까지 희망할 필요 X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[모해 목적 신분]</span> <span class=\"cs-stat\"><strong>§152</strong></span>①·②은 '모해 목적' 유무라는 범인의 특수 상태 차이 따라 형 경중 구별 →<span class=\"cs-stat\"><strong>§33</strong></span> 단서 '신분관계로 형 경중 있는 경우' 해당, 피고인이 모해 목적으로 위증 교사한 이상 정범에 모해 목적 없어도 <span class=\"cs-stat\"><strong>§33</strong></span> 단서로 모해위증교사죄 처단 가능</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[징계사건]</span> 모해위증죄 보호법익은 국가 사법작용·징계작용의 적정한 행사 →'징계'는 국가가 공법상 지위에 기초해 행하는 행정적 제재 학교법인 등과 사립학교 교원 관계는 원칙 사법상 법률관계(사법상 고용계약), 학교법인이 사립학교 교원에 징계권 행사한 사건은 <span class=\"cs-stat\"><strong>§152</strong></span>② '징계사건' 포함 X →해임된 교사 A가 학교법인 상대 해임무효확인 소송서 피고인이 한 증언은 징계사건 관한 진술 아니어서 모해위증죄 성립<span class=\"cs-o\"><strong>(X)</strong></span> <span class=\"cs-fact-tag\">[축소사실인 위증죄 유죄]</span></div><div class=\"cs-h\">Ⅳ. 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 하나의 사건에 한 번 선서한 증인이 같은 기일에 여러 사실에 관해 기억에 반하는 허위 진술한 경우 하나의 범죄의사로 계속 허위 진술한 것으로 포괄하여 1개 위증죄 구성, 각 진술마다 수 개 위증죄 구성 X<span class=\"cs-exam\">【변19·13】</span> 같은 심급에서 변론기일 달리해 수차 증인으로 나가 수개 허위진술해도 최초 한 선서 효력 유지시킨 후 증언한 이상 1개 위증죄 구성</div><div class=\"cs-h\">Ⅴ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 증인 증언은 전부를 일체로 관찰·판단 →선서한 증인이 기억에 반하는 허위 진술해도 신문 끝나기 전 철회·시정 시 위증 안 됨 증인이 1개 증인신문절차서 허위 진술하고 철회·시정 없이 '증인신문절차 종료'된 경우 위증죄 기수, 그 후 '별도 증인 신청·채택 절차' 거쳐 다시 신문받는 과정서 종전 진술 철회·시정해도 <span class=\"cs-stat\"><strong>§153</strong></span> 형 감면사유 해당할 뿐 이미 종결된 종전 위증죄 성립에 영향 X<span class=\"cs-exam\">【변24·23·19】</span> 위 법리는 증인이 '별도 증인신문절차'서 새로 선서한 경우뿐 아니라 종전 절차서 한 선서 효력 유지됨 고지받고 진술한 경우에도 적용</div><div class=\"cs-h\">Ⅵ. 자기 사건 위증교사<span class=\"cs-exam\">【변사13, 모사24·22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><span class=\"cs-issue\">《자기 형사사건에 관해 위증 교사한 경우 위증교사죄 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(자기 방어권 연장, 정범 될 수 없는 자는 교사범도 X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(새 범인 창출, 방어권 남용)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span> 자기 형사사건 허위진술은 방어권 인정 취지상 처벌 X이나, 선서한 증인이 타인 형사사건에 위증하면 <span class=\"cs-stat\"><strong>§152</strong></span>① 위증죄 성립하므로 자기 형사사건에 관해 타인 교사해 위증하게 하는 것은 방어권 남용 →교사범 죄책 부담<span class=\"cs-exam\">【변24·20·19·17·13】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 타인에게 위증 교사까지 기대가능성 없다 볼 수 X, 공범종속성 원칙상 교사범 성립 → 긍정설 타당</div></div><div class=\"cs-h\">Ⅶ. 자백 또는 자수 - 필요적 감면</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">효과: <span class=\"cs-fact-tag\">[필요적 감면]</span> 전조의 죄를 범한 자가 공술한 사건의 재판·징계처분 확정 전 자백·자수 시 형 감경·면제(<span class=\"cs-stat\"><strong>§153</strong></span>)<span class=\"cs-exam\">【변24·16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 위증죄에는 친족간 책임조각 특례 적용 X</div>", ["§152", "§33", "§153", "제148조", "제160조", "제31조", "제152조", "제153조"], 3, "gak_국가공무방해"], ["국가018", "공동피고인의 증인적격과 증언거부권", "<div class=\"cs-h\">Ⅰ. 공동피고인의 증인적격과 위증죄 성립여부</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>공범인 공동피고인</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[증인적격]</span> 공범인 공동피고인은 당해 소송절차선 피고인 지위에 있어 다른 공동피고인 공소사실에 증인 될 수 X, 소송절차 분리되어 피고인 지위서 벗어나면 다른 공동피고인 공소사실에 증인 될 수 있음<span class=\"cs-exam\">【모사25】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[병합심리]</span> 피고인과 공범 변론 분리 안 된 이상 피고인은 공범 공소사실에 증인 될 수 없어 위증죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[변론분리]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①증언거부권이 실질 보장되는 한 공범인 공동피고인에 소송절차 분리 후 증인적격 인정하고 자신 범죄사실 관련 질문해도 피고인으로서 진술거부권·자기부죄거부특권 침해 X</div><div class=\"cs-li\" style=\"margin-left:48px\">②증인적격 인정되는 피고인이 증인신문절차서 증언거부권 고지받고도 자신 범죄사실 관련 증언거부권 행사 안 한 채 허위 진술 시 위증죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변26·25·22·16】</span><span class=\"cs-exam\">【변사23, 모사25】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>공범이 아닌 공동피고인</strong> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[증인적격]</span> 피고인과 별개 범죄사실로 기소되어 병합심리중인 공동피고인은 피고인 범죄사실에 관하여는 증인 지위에 있음</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[병합·분리]</span> 공범 아닌 공동피고인은 변론 병합·분리 여부 관계없이 증인적격 인정 →증인으로 허위 진술 시 위증죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-h\">Ⅱ. 증언거부권을 고지하지 않은 경우 위증죄 성립여부</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>민사소송의 증인</strong> 판단기준 (判例) : 민사소송법은 증언거부권 고지 규정 별도로 두지 않음 →재판장이 증인에게 증언거부권 고지 안 했어도 절차위반 위법 X, 특별한 사정 없는 한 위증죄 성립<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong><span class=\"cs-fact-tag\">[형사]</span> 증언거부권을 고지받지 못하고 허위 진술한 경우<span class=\"cs-exam\">【모사22·14】</span></strong> 개념: 증인이 <span class=\"cs-stat\"><strong>§148</strong></span>·<span class=\"cs-stat\"><strong>§149</strong></span> 해당 시 재판장은 신문 전 증언 거부할 수 있음 설명해야 (형소법 <span class=\"cs-stat\"><strong>제160조</strong></span>) <span class=\"cs-issue\">《재판장이 증언거부권자에게 고지 안 했는데 증인이 허위 진술 시 위증죄 성립하는지》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①위증죄 성립설</div><div class=\"cs-li\" style=\"margin-left:16px\">②위증죄 불성립설</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①증인신문절차서 증인 보호 규정 지켜진 것 인정 안 되면 '법률에 의해 선서한 증인' 해당 X→위증죄 처벌 X 원칙</div><div class=\"cs-li\" style=\"margin-left:16px\">②재판장이 증언거부권 고지 안 한 경우에도 증인이 침묵 안 하고 진술한 것이 자신의 진정한 의사에 의한 것인지 여부 기준으로 위증죄 성립 판단</div><div class=\"cs-li\" style=\"margin-left:16px\">③헌법 <span class=\"cs-stat\"><strong>§12</strong></span>② 불이익진술 강요금지 구체화한 자기부죄거부특권에 관한 것이거나 기타 증언거부사유 있음에도 증언거부권 고지 못 받아 그 행사에 사실상 장애 초래됐다 볼 수 있는 경우 위증죄 성립 부정<span class=\"cs-exam\">【변16】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 일률적으로 성립 긍정·부정할 것 아니라 구체적 사안서 위증죄 성립여부 판단하는 판례 타당</div></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[쌍방폭행 자기부죄]</span> 쌍방폭행 기소되어 자신은 폭행한 적 없다 다투다가, 상대방 폭행 피해자로 증인 채택되어 증언거부권 고지 못 받은 채 종전 주장 되풀이해 거짓 진술에 이른 경우 위증죄 죄책 물을 수<span class=\"cs-x\"><strong>(X)</strong></span> <span class=\"cs-neg-tag\">[자기부죄거부특권]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[전 남편 음주운전]</span> 전 남편 음주운전 사건에 증인 출석해 증언거부권 고지 못 받은 상태서 자신이 전남편 태우고 운전했다 적극적으로 전남편 변명에 부합하는 증언 시 위증죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[사실상 장애 초래X]</span></div><div class=\"cs-h\">Ⅲ. 유죄확정 판결을 받은 자의 증언거부권</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) :</div><div class=\"cs-li\" style=\"margin-left:16px\">①이미 유죄확정판결 받은 경우 일사부재리 원칙에 의해 다시 처벌 안 됨 →피고인은 공범 형사사건서 그 범행에 증언 거부할 수 없을 뿐 아니라 사실대로 증언해야</div><div class=\"cs-li\" style=\"margin-left:16px\">②피고인이 자신 형사사건(강도상해)서 시종일관 범행 부인했어도 위증죄 양형참작사유로 볼 수 있음은 별론, 이를 이유로 사실대로 진술 기대가능성 없다 볼 수 X <span class=\"cs-fact-tag\">[위증죄 성립]</span><span class=\"cs-exam\">【변26·23·20·19·18·17·12】</span><span class=\"cs-exam\">【모사22·20·14, 변기24】</span> 자신에 대한 유죄판결 확정된 증인이 공범 피고사건서 증언 당시 앞으로 재심 청구할 예정이라 해도 이를 이유로 증인에게 형소법 <span class=\"cs-stat\"><strong>§148</strong></span> 증언거부권 인정 X</div>", ["§148", "§149", "§12", "제160조"], 3, "gak_국가공무방해"], ["국가019", "무고죄", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제156조(무고)</strong></span> 타인으로 하여금 형사처분 또는 징계처분을 받게 할 목적으로 공무소 또는 공무원에 대하여 허위의 사실을 신고한 자는 10년 이하의 징역 또는 1천500만원 이하의 벌금에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제157조(자백·자수)</strong></span> 제153조는 전조에 준용한다.</div></div><div class=\"cs-h\">Ⅰ. 형사처분 또는 징계처분을 받게 할 목적</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[목적의 정도]</span> 허위신고로 상대방이 형사·징계처분 받게 될 것이라는 인식 있으면 족, 결과발생 희망까지는 不要 → 고소인이 고소장을 수사기관 제출한 이상 그 인식 있었다고 봄<span class=\"cs-exam\">【변22】</span></div><div class=\"cs-h\">Ⅱ. 공무소 또는 공무원에 대하여</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-stat\"><strong>§156</strong></span> '징계처분' = 공법상 감독관계에서 질서유지 위해 과하는 신분적 제재<span class=\"cs-exam\">【변23·21】</span><span class=\"cs-exam\">【변기22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[변호사]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①변호사 징계처분은 <span class=\"cs-stat\"><strong>§156</strong></span> '징계처분' 포함</div><div class=\"cs-li\" style=\"margin-left:32px\">②피고인이 변호사인 피해자로 하여금 징계처분 받게 할 목적으로 서울지방변호사회에 회장 수취인 허위 진정서 제출 시 무고죄 성립<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사법적 법률행위]</span> 신고사실이 사법적 법률행위 성격의 징계처분 원인에 불과 → 그 사실 자체는 징계사유 구성X → 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[사립학교 교원]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①학교법인의 사립학교 교원 인사권 행사(징계 등 불리한 처분)는 사법적 법률행위 성격</div><div class=\"cs-li\" style=\"margin-left:32px\">②학교법인의 사립학교 교원 징계처분은 <span class=\"cs-stat\"><strong>§156</strong></span> '징계처분' 포함<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변23·21】</span><span class=\"cs-exam\">【변기22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[경찰인재개발원 무기계약근로자]</span> 인사권 행사로서의 징계는 사법적 법률행위 성격 → <span class=\"cs-stat\"><strong>§156</strong></span> 징계처분 포함<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-h\">Ⅲ. 허위사실의 신고</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>신고</strong> 개념: 당국 추문 없이 자진하여 허위사실 신고함으로써 성립 → 신고방식 구두·서면 불문, 신고가 자발적일 것만 요함 판단기준 (判例) : <span class=\"cs-fact-tag\">[자진 진술]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①신고는 자발적이어야, 수사기관 추문에 대한 허위진술은 무고X</div><div class=\"cs-li\" style=\"margin-left:16px\">②당초 고소장 미기재 사실을 고소보충조서 받을 때 자진 진술하면 이 진술부분까지 신고한 것으로 봄 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">수사관 만나 범죄혐의 인정 사실 말하고 뒤에 진술조서 작성하며 처벌 요구 진술 → 추문·요청에 의한 진술·정보제공 아니라 자진 허위신고에 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[고발 주도자]</span> 고발은 피해자 본인·고소권자 제외 누구나 가능(대리 불허), 고발의사 결정·고발행위 주재한 자가 고발인 → 타인명의 고소장 제출로 위증사실 신고돼도 피고인이 고소장 작성·제출하고 고발인 진술 등 주도 시 고발인은 피고인 <span class=\"cs-fact-tag\">[무고죄 주체 됨]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">수사기관 요청에 의한 단순 정보제공은 무고죄 신고에 해당<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공동피고인 진술]</span> 1인이 타범죄 조사받는 과정에서 사경·검사 심문에 따라 다른 공동피고인 범죄사실 진술 → 가사 허위라도 무고라 할 수<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>허위</strong> 판단기준 (判例) : 신고사실이 '객관적 진실에 반하는 허위사실'인 경우 성립 → 신고자가 허위로 믿었어도 객관적 진실에 부합하면 허위신고 해당X → 무고죄 성립X 허위 여부는 신고사실의 '핵심 또는 중요내용'이 허위인가로 판단 '객관적 진실 반하는 허위사실' 요건은 적극적 증명 必 → 진실성 인정 못한다는 소극적 증명만으로 허위 단정 불가<span class=\"cs-exam\">【변21】</span> 신고자가 객관적 사실관계 그대로 신고한 이상 주관적 법률평가 잘못하여 신고한 것만으로는 허위사실 신고 해당X 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[차용금 - 용도 속여 대여]</span> 실제 용도가 사기죄 성립에 영향 미치는 경우(용도 속인 바람에 대여) → 실제 용도는 고소사실 중요부분 → 용도 허위신고 시 그것만으로 허위사실 신고에 해당<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">['배달원이 가슴 만졌다'만 신고, 별도 폭행·협박 신고 안함]</span> 무고죄 성립<span class=\"cs-o\"><strong>(O)</strong></span> <span class=\"cs-fact-tag\">[취지]</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[성폭행 피해]</span> 신고사실에 불기소처분·무죄판결 내려져도 신고내용 허위라 단정<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공범 가담 숨김]</span> 고소내용이 상대방 범행 부분에 관해 진실 부합 → 허위로 볼 수 없고, 공범 가담 숨겨도 독립하여 형사처분 대상 안 되고 상대방 범죄성립에 직접 영향 없음 → 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[차용금 - 변제의사·능력 기망]</span> 단순히 차용인이 변제의사·능력 유무 기망했다는 내용 고소 시, 차용금 실제 '용도'를 사실과 달리 신고했다는 것만으로는 중요부분 허위신고<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span> <span class=\"cs-fact-tag\">[실제용도 도박자금인데 네비게이션 구입자금이라 허위기재]</span></div><div class=\"cs-li\" style=\"margin-left:0px\">3. <strong>신고 내용이 명백히 형사처분의 대상이 아닌 경우</strong> 판단기준 (判例) : 신고된 사실 자체가 형사처분 대상 될 수 있어야 → 신고 당시 그 사실 자체가 형사범죄 구성 안 하면 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span><span class=\"cs-exam\">【변사18】</span> 해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공소시효]</span></div><div class=\"cs-li\" style=\"margin-left:48px\">①공소시효 완성됨이 신고내용 자체로 분명 → 형사처분 대상 안 됨 → 무고죄 성립X</div><div class=\"cs-li\" style=\"margin-left:48px\">②객관적으로 완성됐어도 마치 미완성인 것처럼 고소 시 국가기관 직무 그르칠 염려 → 무고죄 구성<span class=\"cs-o\"><strong>(O)</strong></span><span class=\"cs-exam\">【변20·15】</span><span class=\"cs-exam\">【변기17】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[채권 이중양도·엄벌 요청]</span> 고소사실이 횡령·배임 기타 형사범죄 구성 안 하는 내용 신고에 불과 → 신고내용 허위라도 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[친고죄 고소기간 경과]</span> 친고죄로서 고소기간 경과하여 공소제기 불가함이 신고내용 자체로 분명 → 국가기관 직무 그르칠 위험 없음 → 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24·21·20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-neg-tag\">[사면]</span> 허위사실 신고라도 사면되어 공소권 소멸 분명 시 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\">특정되지 않은 성명불상자에 대한 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li\" style=\"margin-left:0px\">4. <strong>정황의 과장</strong> 판단기준 (判例) : '허위의 사실' = 신고사실로 상대방 형사·징계처분 받을 위험 있어야 → 일부 객관적 진실 반하는 내용 포함돼도 독립하여 형사처분 대상 안 되고 단지 '정황 과장'이거나 허위 일부사실이 범죄성립에 직접 영향 안 줄 정도면 무고죄 성립<span class=\"cs-x\"><strong>(X)</strong></span><span class=\"cs-exam\">【변기24】</span> <span class=\"cs-fact-tag\">[전체 성질 변경]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①일부 허위가 범죄 성부에 영향 미치는 중요부분 아니고 단지 과장이면 무고 해당X</div><div class=\"cs-li\" style=\"margin-left:16px\">②그 허위가 국가 심판작용 그르치거나 개인 법적 안정성 침해할 정도로 고소사실 전체 성질 변경 시 무고죄 성립 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[강간 상해 고소]</span> 강간당해 상해 입었다는 고소는 하나의 강간행위 고소사실 → 강간·상해 두 고소로 분리 불가 → 甲으로부터 강간당한 것 사실인 이상 상해사실 포함시켜도 정황 과장에 불과 → 무고죄 구성<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[폭행 요청 후 강취로 고소]</span> 피고인이 '먼저 때려주면 돈 주겠다' 요청하여 A가 폭행해 상해 입었는데 'A가 폭행하여 돈 빼앗았다' 취지 고소:</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">①피고인 요청은 사회상규 어긋나 피해자 승낙 해당X → A는 폭행 내지 상해죄</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">②신고사실은 A가 갈취·강취 범했다는 것 → 일부 허위 명백,</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">폭행 당한 것인지 여부는 갈취·강취 성부 중요부분</div><div class=\"cs-li cs-bul\" style=\"margin-left:48px\">→ 과장 아니라 고소사실 전체 성질 변경<span class=\"cs-exam\">【변25】</span></div><div class=\"cs-h\">Ⅳ. 기수시기</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: <span class=\"cs-fact-tag\">[수사기관 도달]</span> 최초 작성 허위 고소장을 경찰관에게 제출한 때 이미 허위신고가 수사기관 '도달'되어 무고죄 '기수' → 이후 고소장 되돌려 받아도 성립에 영향<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변15】</span><span class=\"cs-exam\">【모사22】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : <span class=\"cs-fact-tag\">[사후 판례변경]</span> 허위신고 사실이 무고행위 당시 형사처분 대상 될 수 있었으면 형사사법권 적정 행사 그르칠 위험·개인 법적 안정성 침해 위험 이미 발생 → 기수, 이후 형사범죄 안 되는 것으로 판례 변경돼도 특별한 사정 없는 한 이미 성립한 무고죄에 영향<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변24·21·20·19】</span><span class=\"cs-exam\">【모기21】</span> <span class=\"cs-fact-tag\">[대물변제예약 후 이중매도를 배임죄로 고소 후 배임죄 불성립으로 판례변경된 경우]</span></div><div class=\"cs-h\">Ⅴ. 고의</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 범의는 확정적 고의 不要, '미필적 고의'로 충분 → 허위 확신 사실 신고뿐 아니라 진실하다는 확신 없는 사실 신고에도 범의 인정<span class=\"cs-exam\">【변25·24·23】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 신고 = 신고사실 허위임 인식 or 진실 확신 없이 신고함 → 객관적 사실 불일치라도 신고자가 진실 확신하고 신고 시 무고죄 성립X 허위 알면서 신고한 이상 목적이 필요한 조사 해달라는 데 있다는 등 이유로 무고 범의 없다 할 수 X <span class=\"cs-fact-tag\">[인식 무시]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①아는 객관적 사실관계에 의하더라도 신고사실 허위·허위 가능성 인식 못했으면 무고 고의 부정 가능</div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 그 인식하면서도 무시한 채 무조건 자기주장 옳다고 생각하는 경우까지 포함X</div><div class=\"cs-h\">Ⅵ. 무고죄의 죄수관계</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">判例(죄수관계): 수개 혐의사실 고소 시 일부는 진실이나 다른 사실 허위면 허위사실 부분만 독립하여 무고죄 구성<span class=\"cs-exam\">【변15】</span> <span class=\"cs-fact-tag\">[3개 문서 위조·변조 허위고소]</span> 무고죄 단순일죄 <span class=\"cs-fact-tag\">[1인에 대한 수개 허위사실 신고해도 '단순일죄']</span> 1개 고소장으로 수인 무고 시 '피무고자 수'에 따라 무고죄 성립, 각 무고죄는 상상적 경합범 관계</div><div class=\"cs-h\">Ⅶ. 자수·자백특례</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">효과: <span class=\"cs-fact-tag\">[자백 개념]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①자수·자백 필요적 감경·면제 절차 제한 없음 → 사건 다루는 기관에 대한 고백, 그 사건 다루는 재판부에 증인으로 재출석하여 전 신고 허위였음 고백은 물론 무고사건 피고인·피의자로서 법원·수사기관 신문에 의한 고백도 자백 포함</div><div class=\"cs-li\" style=\"margin-left:16px\">②<span class=\"cs-stat\"><strong>§153</strong></span> '재판 확정 전'에는 피고인 고소사건 수사결과 무고혐의 밝혀져 공소제기되고 피고소인 불기소결정 내려져 재판절차 미개시된 경우도 포함<span class=\"cs-exam\">【변25·23·21·15】</span> <span class=\"cs-fact-tag\">[피고인 무고사건 불기소처분, 피고인이 무고사건 항소심에서 자백 시 </span><span class=\"cs-stat\">§157</span><span class=\"cs-fact-tag\">·</span><span class=\"cs-stat\">§153</span><span class=\"cs-fact-tag\"> 필요적 감면조치]</span> <span class=\"cs-fact-tag\">[자백의 의미]</span> 자신의 범죄사실 (타인 형사·징계처분 받게 할 목적으로 공무소·공무원에 허위사실 신고했음) 자인 → 단순히 신고내용이 객관적 사실 반한다 인정함에 지나지 않는 것은 해당X</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용범위: 무고죄에는 친족간 책임조각 특례 적용X</div>", ["§156", "§153", "§157", "제156조", "제157조", "제153조"], 3, "gak_국가공무방해"], ["국가020", "승낙무고와 자기무고", "<details class=\"cs-case\"><summary><u><strong>[CASE]</strong></u> <span class=\"cs-exam\">【변사26】 </span><span class=\"cs-o\">(15)</span></summary><div class=\"cs-case-in\"><div class=\"cs-fact\"><div class=\"cs-li\" style=\"margin-left:0px\">유명 아이돌 丁의 팬클럽 회장 丙, A(10세)가 절취한 丁의 신인가수상 트로피를 정을 알고 취득한 뒤 SNS에 자랑 → 이를 확인한 丁이 경찰에 丙을 고소 → 丙이 '팬클럽 회장을 어떻게 고소할 수가 있냐'고 하자 丁이 '그렇다면 사실 내가 너에게 트로피를 선물한 것이라면서 나에 대한 고소장을 경찰에 내라'고 함 → 丙이 경찰에 '丁이 트로피를 선물해 놓고 나를 고소한 것이니 처벌해 달라'는 취지의 허위 고소장 제출. 이와 관련하여 1) 丙의 죄책을 논하고, 2) 丁의 죄책에 대하여는 유죄와 무죄의 논거를 각각 제시하시오. (15점)</div></div><details class=\"cs-ans\" open><summary><span class=\"cs-o\"><strong>모범답안</strong></span></summary><div class=\"cs-ans-in\"><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(1) [丙의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:0px\">① 무고죄의 주된 보호법익 = 국가의 형사사법권·징계권의 적정한 행사 → 피무고자의 승낙이 있어도 무고죄 성립에 영향(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 피무고자 丁의 승낙을 받아 허위 고소장을 제출했어도 丙 = 무고죄(<span class=\"cs-stat\"><strong>제156조</strong></span>)(O)</div><div class=\"cs-li\" style=\"margin-left:0px\"><strong>(2) [丁의 죄책]</strong></div><div class=\"cs-li\" style=\"margin-left:16px\">(가) [유죄의 논거-무고교사죄 성립]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 타인에게 자신에 대한 무고를 교사·방조한 경우 — 공범종속성의 원칙상 성립한다는 긍정설 / 정범 형태의 자기무고가 구성요건해당성이 없어 교사범도 성립하지 않는다는 부정설. 판례 = \"피무고자가 제3자에게 피무고자에 대한 무고행위를 교사·방조한 경우 피무고자에게도 교사·방조범이 성립\" 긍정설</div><div class=\"cs-li\" style=\"margin-left:0px\">③ 긍정설·판례에 의하면 丁은 무고의 결의가 없는 丙에게 무고를 결의하게 함 → 무고교사죄(<span class=\"cs-stat\"><strong>제31조</strong></span> 제1항)(O)</div><div class=\"cs-li\" style=\"margin-left:16px\">(나) [무죄의 논거] (A) [무고교사죄의 불성립] 위 부정설에 의하면 丁의 자기무고는 구성요건해당성(X) → 丁에게 무고교사죄도(X) (B) [무고죄의 공동정범 불성립]</div><div class=\"cs-li\" style=\"margin-left:0px\">① 자기 자신을 무고하기로 제3자와 공모하고 무고행위에 가담했어도 무고죄의 공동정범으로 처벌(X)</div><div class=\"cs-li\" style=\"margin-left:0px\">② 丁이 丙의 무고행위를 공모하고 수사기관의 예상 질문에 대한 대답을 준비해 조사에 응하는 등 실행행위를 분담해 기능적 행위지배가 인정되더라도 丁에게 무고죄의 공동정범(X)</div></div></details></div></details><div class=\"cs-h\">Ⅰ. 승낙무고 (정범)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 무고죄는 국가 형사사법권·징계권 적정 행사가 주된 보호법익, 개인의 부당한 처벌·징계 안 받을 이익은 부수적 보호 → 피무고자 승낙 있어도 무고죄 성립에 영향<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변25】</span><span class=\"cs-exam\">【변사26, 모사20】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[피해자 행세 허위고소]</span> 피고인들이 합의 주선 위해 자신들도 피해자인 것처럼 행세하려 공소외인 승낙받고 공소외인으로부터 차용금 피해 당한 것처럼 허위사실 기재 고소장 제출 → 공소외인 형사처분 결과발생 의욕은 아니라도 최소한 미필적 인식 있었음<span class=\"cs-exam\">【변14·13】</span><span class=\"cs-exam\">【모사20】</span></div><div class=\"cs-h\">Ⅱ. 자기무고</div><div class=\"cs-li\" style=\"margin-left:0px\">1. <strong>교사·방조범<span class=\"cs-exam\">【변사26, 모사20】</span></strong> <span class=\"cs-issue\">《타인에게 자신에 대한 무고 교사 시 무고교사죄 성립 여부》</span></div><div class=\"cs-theory\"><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>학설</strong>:</div><div class=\"cs-li\" style=\"margin-left:16px\">①부정설(정범 형태 자기무고가 구성요건해당성 없어 교사범도 성립X)</div><div class=\"cs-li\" style=\"margin-left:16px\">②긍정설(타인에게 무고 교사한 이상 공범종속성 원칙상 무고교사죄 성립)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>판례</strong>: <span class=\"cs-fact-tag\">[긍정설]</span></div><div class=\"cs-li\" style=\"margin-left:16px\">①스스로 본인 무고하는 자기무고는 <span class=\"cs-stat\"><strong>§156</strong></span> 무고죄 구성요건 해당X → 무고죄 구성X</div><div class=\"cs-li\" style=\"margin-left:16px\">②그러나 피무고자 교사·방조 하에 제3자가 피무고자에 대한 허위사실 신고 시 제3자 행위는 무고죄 구성요건 해당 → 무고죄 구성, 제3자 교사·방조한 피무고자도 교사·방조범 죄책 부담<span class=\"cs-exam\">【변20·17·15】</span></div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\"><strong>검토</strong>: 자기무고는 구성요건해당성 없으나 정범에게 무고죄 성립하는 이상 공범종속성 원칙상 교사·방조범 성립 가능 → 긍정설 타당</div></div><div class=\"cs-li\" style=\"margin-left:0px\">2. <strong>자기무고의 공동정범</strong> 판단기준 (判例) : 공동의사 따라 다른 공범자 이용 실현하려는 행위가 자신에게 범죄 구성 안 하면 특별한 사정 없는 한 공동정범 죄책<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변사26】</span> 자기 자신 무고는 무고죄 구성요건 해당X → 자기 무고하기로 제3자와 공모하고 무고행위 가담해도 자신에게는 구성요건 해당X, 범죄성립 불가 행위 실현에 지나지 않아 무고죄 공동정범으로 처벌<span class=\"cs-o\"><strong>(X)</strong></span><span class=\"cs-exam\">【변20】</span> 적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:32px\"><span class=\"cs-fact-tag\">[공모·조사 대응 분담]</span> 피고인이 A와 '공모'하여 A가 피고인을 사문서위조 등으로 허위 고소하고, 피고인은 수사기관 예상질문 대답 준비 방식으로 자신을 무고하기로 하여 A가 피고인 처벌 달라는 허위 고소장 작성·제출한 경우, 피고인은 무고죄 공동정범 성립<span class=\"cs-o\"><strong>(X)</strong></span></div>", ["§156", "제156조", "제31조"], 3, "gak_국가공무방해"], ["국가021", "국가적 법익 기타", "<div class=\"cs-statute\"><div class=\"cs-li\" style=\"margin-left:0px\"><span class=\"cs-crime\"><strong>제123조의2(법왜곡)</strong></span> 형사사건의 재판에 관여하는 법관, 공소를 제기하거나 유지하는 검사 또는 범죄수사에 관한 직무를 수행하는 자가 타인에게 위법 또는 부당하게 이익을 주거나 권익을 해할 목적으로 재판 또는 수사 중인 형사사건에 관하여 다음 각 호의 어느 하나에 해당하는 행위를 한 경우에는 10년 이하의 징역과 10년 이하의 자격정지에 처한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">1<span>.</span> 법령의 적용 요건이 충족되지 아니함을 알면서도 이를 적용하거나, 적용되어야 할 법령임을 알면서도 이를 적용하지 아니하여 의도적으로 재판 및 수사의 결과에 영향을 미친 경우. 다만, 법령 해석의 합리적 범위에서 이루어진 재량적 판단은 이에 해당하지 아니한다.</div><div class=\"cs-li\" style=\"margin-left:0px\">2<span>.</span> 사건에 관한 증거를 인멸, 은닉, 위조 또는 변조하거나 위조 또는 변조된 증거를 그 사정을 알면서 재판 또는 수사에 사용한 경우</div><div class=\"cs-li\" style=\"margin-left:0px\">3<span>.</span> 폭행, 협박, 위계, 그 밖의 방법으로 위법하게 증거를 수집하거나, 적법한 증거가 존재하지 아니함을 알면서도 범죄사실을 인정한 경우</div></div><div class=\"cs-h\">Ⅰ. 내란죄 (<span class=\"cs-stat\">§87</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 다수인이 한 지방 평온 해할 정도 폭동 시 이미 내란 구성요건 완전 충족 → '상태범'으로 봄이 상당<span class=\"cs-exam\">【변19·14】</span> 내란죄 폭동 내용으로서의 폭행·협박 = 일체의 유형력 행사나 외포심 생기게 하는 해악 고지 의미하는 최광의의 폭행·협박</div><div class=\"cs-h\">Ⅱ. 공무상표시무효죄 (<span class=\"cs-stat\">§140</span>①)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 공무원이 직무 관해 실시한 봉인·압류 기타 강제처분 표시 손상·은닉 or 기타 방법으로 효용 해한 자 → 5년 이하 징역 또는 700만원 이하 벌금(<span class=\"cs-stat\"><strong>§140</strong></span>①)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">해당여부 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[취소 전 하자]</span> 절차상·실체상 '하자' 있어도 적법한 절차로 '취소되지 아니하는 한' 객체 됨</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[점유이전금지가처분 고시문]</span> 집행관이 '채무자는 점유를 이전하여서는 아니 된다' 등 집행취지 고시문 부착 후 가처분 채무자가 타인에게 부동산 점유 이전 시 특별한 사정 없는 한 고시문 효력 사실상 없애는 행위 → 공무상표시무효죄 해당<span class=\"cs-o\"><strong>(O)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[당연무효·부존재]</span> 직권남용하여 위법 실시한 표시임이 명백하여 법률상 '당연무효 또는 부존재'로 볼 수 있으면 객체 안 됨 → 성립<span class=\"cs-x\"><strong>(X)</strong></span></div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[권리 오신]</span> 민사소송법 기타 공법 해석 잘못하여 압류물 효력 없어진 것으로 착오 or 손상·효력 해할 권리 있다고 오신 → 형벌법규 부지와 구별되어 범의 조각</div><div class=\"cs-h\">Ⅲ. 공용서류손상죄 (<span class=\"cs-stat\">§141</span>①)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 공무소 사용 서류 기타 물건·전자기록등 특수매체기록 손상·은닉 or 기타 방법으로 효용 해한 자 → 7년 이하 징역 또는 1천만원 이하 벌금(<span class=\"cs-stat\"><strong>§141</strong></span>①) <span class=\"cs-fact-tag\">[진술조서 파쇄한 경우(O)]</span><span class=\"cs-exam\">【변사26】</span></div><div class=\"cs-h\">Ⅳ. 부동산강제집행효용침해죄 (<span class=\"cs-stat\">§140의2</span>)</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">개념: 강제집행으로 명도·인도된 부동산 침입 or 기타 방법으로 강제집행 효용 해한 자 → 5년 이하 징역 또는 700만원 이하 벌금(<span class=\"cs-stat\"><strong>§140의2</strong></span>) '기타 방법' = 강제집행 효용 해할 수 있는 수단·방법에 해당하는 일체의 방해행위 '강제집행 효용 해하는 것' = 명도·인도된 부동산을 권리자가 용도 따라 사용·수익하거나 권리행사하는 데 지장 초래하는 일체의 침해행위</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">판단기준 (判例) : 위법한 인도명령 집행으로 점유 취득한 경우에도 특별한 사정 없는 한 그 점유는 보호되어야</div><div class=\"cs-li cs-bul\" style=\"margin-left:0px\">적용 判例:</div><div class=\"cs-li cs-bul\" style=\"margin-left:16px\"><span class=\"cs-fact-tag\">[공동점유 주택 인도집행 후 침입]</span></div><div class=\"cs-li\" style=\"margin-left:32px\">①아버지가 아들(피고인)·딸이 공동 점유하는 주택에 대해 딸 상대로만 인도소송 제기해 승소, 집행관이 딸을 상대방으로 인도집행 종료했는데 피고인이 집행종료 6시간 후 시정된 출입문 열어 침입한 행위는 부동산강제집행효용침해 구성</div><div class=\"cs-li\" style=\"margin-left:32px\">②공동점유자 중 1인만 상대방으로 한 인도집행은 위법하나 그 집행으로 취득된 점유도 보호되어야 → 피고인 침입은 부동산강제집행효용침해죄 해당<span class=\"cs-o\"><strong>(O)</strong></span>, 정당행위 해당도<span class=\"cs-x\"><strong>(X)</strong></span></div>", ["§87", "§140", "§141", "제123조"], 1, "gak_국가공무방해"]];
